def _pe_utf16_len(s: str) -> int:
    return len(s.encode('utf-16-le')) // 2

def _pe_find_unescaped(text, ch, start):
    i = start
    n = len(text)
    while i < n:
        if text[i] == '\\':
            i += 2
            continue
        if text[i] == ch:
            return i
        i += 1
    return -1

def _pe_unescape(s):
    return _pe_re.sub(r'\\([_*`\[\\])', r'\1', s)

def _pe_parse_legacy_markdown(text):
    """Best-effort re-implementation of Telegram's legacy parse_mode='Markdown' grammar.
    Returns (plain_text, entities) where entities is a list of dicts with UTF-16 offsets."""
    entities = []
    out = []
    i = 0
    n = len(text)
    utf16_offset = 0

    def emit(s):
        nonlocal utf16_offset
        out.append(s)
        utf16_offset += _pe_utf16_len(s)

    while i < n:
        c = text[i]
        if c == '\\' and i + 1 < n and text[i + 1] in '_*`[\\':
            emit(text[i + 1])
            i += 2
            continue

        if text[i:i + 3] == '```':
            end = text.find('```', i + 3)
            if end == -1:
                emit(c); i += 1; continue
            content = text[i + 3:end]
            lang = ''
            nl = content.find('\n')
            if nl != -1 and ' ' not in content[:nl] and content[:nl]:
                lang = content[:nl]
                content = content[nl + 1:]
            start_off = utf16_offset
            emit(content)
            ent = {'type': 'pre', 'offset': start_off, 'length': utf16_offset - start_off}
            if lang:
                ent['language'] = lang
            entities.append(ent)
            i = end + 3
            continue

        if c == '`':
            end = text.find('`', i + 1)
            if end == -1:
                emit(c); i += 1; continue
            content = text[i + 1:end]
            start_off = utf16_offset
            emit(content)
            entities.append({'type': 'code', 'offset': start_off, 'length': utf16_offset - start_off})
            i = end + 1
            continue

        if c == '*':
            end = _pe_find_unescaped(text, '*', i + 1)
            if end == -1:
                emit(c); i += 1; continue
            content = _pe_unescape(text[i + 1:end])
            start_off = utf16_offset
            emit(content)
            entities.append({'type': 'bold', 'offset': start_off, 'length': utf16_offset - start_off})
            i = end + 1
            continue

        if c == '_':
            end = _pe_find_unescaped(text, '_', i + 1)
            if end == -1:
                emit(c); i += 1; continue
            content = _pe_unescape(text[i + 1:end])
            start_off = utf16_offset
            emit(content)
            entities.append({'type': 'italic', 'offset': start_off, 'length': utf16_offset - start_off})
            i = end + 1
            continue

        if c == '[':
            close_b = _pe_find_unescaped(text, ']', i + 1)
            if close_b != -1 and close_b + 1 < n and text[close_b + 1] == '(':
                close_p = text.find(')', close_b + 2)
                if close_p != -1:
                    link_text = _pe_unescape(text[i + 1:close_b])
                    url = text[close_b + 2:close_p]
                    start_off = utf16_offset
                    emit(link_text)
                    if url.startswith('tg://user?id='):
                        try:
                            uid = int(url.split('=', 1)[1])
                            entities.append({'type': 'text_mention', 'offset': start_off,
                                              'length': utf16_offset - start_off, 'user_id': uid})
                        except ValueError:
                            entities.append({'type': 'text_link', 'offset': start_off,
                                              'length': utf16_offset - start_off, 'url': url})
                    else:
                        entities.append({'type': 'text_link', 'offset': start_off,
                                          'length': utf16_offset - start_off, 'url': url})
                    i = close_p + 1
                    continue
            emit(c); i += 1; continue

        emit(c)
        i += 1

    return ''.join(out), entities


def _pe_inject_custom_emoji(plain_text, entities):
    """Add custom_emoji entities for every mapped emoji found in plain_text, skipping
    characters that already fall inside a 'code' or 'pre' entity."""
    if not PREMIUM_EMOJI_MAP:
        return entities

    protected = [(e['offset'], e['offset'] + e['length']) for e in entities if e['type'] in ('code', 'pre')]

    def is_protected(off):
        return any(a <= off < b for a, b in protected)

    new_entities = list(entities)
    utf16_offset = 0
    for ch in plain_text:
        ch_len = _pe_utf16_len(ch)
        cid = PREMIUM_EMOJI_MAP.get(ch)
        if cid and not is_protected(utf16_offset):
            new_entities.append({'type': 'custom_emoji', 'offset': utf16_offset,
                                  'length': ch_len, 'custom_emoji_id': cid})
        utf16_offset += ch_len
    return new_entities


def _pe_to_message_entities(entities):
    result = []
    for e in entities:
        kwargs = {'type': e['type'], 'offset': e['offset'], 'length': e['length']}
        if 'url' in e:
            kwargs['url'] = e['url']
        if 'user_id' in e:
            from telegram import User as _PE_User
            kwargs['user'] = _PE_User(id=e['user_id'], first_name='', is_bot=False)
        if 'language' in e:
            kwargs['language'] = e['language']
        if 'custom_emoji_id' in e:
            kwargs['custom_emoji_id'] = e['custom_emoji_id']
        result.append(_PE_MessageEntity(**kwargs))
    return result


def _pe_transform_kwargs(kwargs, text_key):
    """Mutates kwargs in place: converts text_key/parse_mode into text_key/entities (or
    caption/caption_entities) with premium emoji injected. No-op if there's no mapped emoji
    present and no formatting to preserve, to keep behaviour identical otherwise."""
    text = kwargs.get(text_key)
    if not text or not isinstance(text, str):
        return
    if not any(ch in PREMIUM_EMOJI_MAP for ch in text):
        return  # nothing to swap — leave the call completely untouched

    entities_key = 'caption_entities' if text_key == 'caption' else 'entities'
    if kwargs.get(entities_key):
        # caller already passed explicit entities — just layer emoji on top, don't touch parse_mode
        raw_entities = [{'type': e.type, 'offset': e.offset, 'length': e.length} for e in kwargs[entities_key]]
        new_entities = _pe_inject_custom_emoji(text, raw_entities)
        kwargs[entities_key] = _pe_to_message_entities(new_entities)
        return

    parse_mode = kwargs.get('parse_mode')
    if parse_mode == 'Markdown':
        plain_text, entities = _pe_parse_legacy_markdown(text)
    else:
        plain_text, entities = text, []

    entities = _pe_inject_custom_emoji(plain_text, entities)
    kwargs[text_key] = plain_text
    kwargs[entities_key] = _pe_to_message_entities(entities)
    kwargs['parse_mode'] = None


_PE_STATE = {"enabled": True}  # flips to False the first time a Premium-emoji send fails

def _pe_wrap(cls, method_name, text_key):
    original = getattr(cls, method_name, None)
    if original is None:
        return

    entities_key = 'caption_entities' if text_key == 'caption' else 'entities'

    async def wrapper(self, *args, **kwargs):
        if not _PE_STATE["enabled"]:
            return await original(self, *args, **kwargs)

        text = kwargs.get(text_key)
        has_target = isinstance(text, str) and any(ch in PREMIUM_EMOJI_MAP for ch in text)
        if not has_target:
            return await original(self, *args, **kwargs)

        # Snapshot the untouched call so we can retry with it if the
        # Premium-emoji version gets rejected by Telegram.
        _orig_text = kwargs.get(text_key)
        _orig_parse_mode = kwargs.get('parse_mode')
        _orig_had_entities = entities_key in kwargs
        _orig_entities = kwargs.get(entities_key)

        _pe_transform_kwargs(kwargs, text_key)
        try:
            return await original(self, *args, **kwargs)
        except Exception as e:
            # FIX (bug): this used to catch bare `Exception` and permanently
            # disable Premium Emoji for the REST OF THE PROCESS on the very
            # first failure of ANY kind — including a transient flood-control
            # hit (RetryAfter), a network timeout, or an unrelated bad-entity
            # error. Since flood-control errors are common in this bot's logs
            # ([NAV] ... Flood control exceeded ...) and can occur on *any*
            # send, one transient flood-control error hitting a
            # premium-emoji-wrapped call could permanently kill custom emoji
            # for the whole run even though the bot account IS Premium/has a
            # Fragment username and everything would have worked again a few
            # seconds later. This is the proven, code-level explanation for
            # "premium emoji works when the bot starts, then stops working
            # after a while" — it only has to fail once, for ANY reason.
            #
            # Fix: only ever permanently disable the swap when Telegram's
            # error text clearly indicates a PERMISSION problem (custom emoji
            # not usable by this bot account at all). Every other error
            # (RetryAfter/flood control, network hiccup, timeout, or an
            # unrelated "can't parse entities" problem in the caller's own
            # text) is treated as transient: fall back to the plain call for
            # THIS message only, log it, and leave Premium Emoji enabled so
            # the very next send can try again normally.
            err_text = str(e)
            is_permission_error = (
                "CUSTOM_EMOJI_INVALID" in err_text
                or "not enough rights" in err_text.lower()
                or "chat_send_custom_emoji_forbidden" in err_text.lower()
                or ("PREMIUM" in err_text.upper() and "REQUIRED" in err_text.upper())
            )

            fallback_kwargs = dict(kwargs)
            fallback_kwargs[text_key] = _orig_text
            fallback_kwargs['parse_mode'] = _orig_parse_mode
            if _orig_had_entities:
                fallback_kwargs[entities_key] = _orig_entities
            else:
                fallback_kwargs.pop(entities_key, None)

            if isinstance(e, RetryAfter):
                # Centralized flood-control handling: honor Telegram's own
                # requested delay once, then retry the ORIGINAL (premium
                # emoji) call — do not disable anything, this has nothing to
                # do with permissions.
                _delay = getattr(e, "retry_after", 3) + 1
                print(f"[PREMIUM EMOJI] Flood control on {method_name}, waiting {_delay}s "
                      f"then retrying (not disabling — this is not a permission error).")
                await asyncio.sleep(_delay)
                try:
                    return await original(self, *args, **kwargs)
                except Exception as e2:
                    print(f"[PREMIUM EMOJI] Retry after flood-control still failed on "
                          f"{method_name}: {e2}. Falling back to plain send for this message.")
                    return await original(self, *args, **fallback_kwargs)

            try:
                result = await original(self, *args, **fallback_kwargs)
            except Exception:
                raise e  # neither version worked — surface the original error

            if is_permission_error:
                if _PE_STATE["enabled"]:
                    _PE_STATE["enabled"] = False
                    print(f"[PREMIUM EMOJI] Custom emoji send failed with a permission error "
                          f"({e}); this bot account likely isn't Telegram Premium (and has no "
                          f"Fragment username). Disabled custom-emoji swapping for the rest of "
                          f"this run — falling back to normal emoji everywhere so all "
                          f"commands/buttons/media work again.")
            else:
                print(f"[PREMIUM EMOJI] Transient error on {method_name}, sent this one message "
                      f"without custom emoji and left Premium Emoji ENABLED for next time: {e}")
            return result

    setattr(cls, method_name, wrapper)


for _pe_cls, _pe_method, _pe_key in [
    (_PE_Bot, 'send_message', 'text'),
    (_PE_Bot, 'edit_message_text', 'text'),
    (_PE_Bot, 'send_photo', 'caption'),
    (_PE_Bot, 'send_video', 'caption'),
    (_PE_Bot, 'send_animation', 'caption'),
    (_PE_Bot, 'send_document', 'caption'),
    (_PE_Bot, 'edit_message_caption', 'caption'),
    (_PE_Message, 'reply_text', 'text'),
    (_PE_Message, 'reply_photo', 'caption'),
    (_PE_Message, 'reply_video', 'caption'),
    (_PE_Message, 'reply_animation', 'caption'),
    (_PE_Message, 'reply_document', 'caption'),
    (_PE_Message, 'edit_text', 'text'),
    (_PE_Message, 'edit_caption', 'caption'),
    (_PE_CallbackQuery, 'edit_message_text', 'text'),
    (_PE_CallbackQuery, 'edit_message_caption', 'caption'),
]:
    _pe_wrap(_pe_cls, _pe_method, _pe_key)
