def get_last_5_30_ist_reset_epoch(now: int = None) -> int:
    """Return the unix epoch of the most recent 5:30 AM IST boundary on/before `now`."""
    if now is None:
        now = int(time.time())
    RESET_SECONDS = 5 * 3600 + 30 * 60  # 19800 — 5:30 AM in seconds past IST midnight
    now_ist_seconds = now + IST_OFFSET_SEC
    seconds_since_midnight_ist = now_ist_seconds % 86400
    if seconds_since_midnight_ist >= RESET_SECONDS:
        return now - (seconds_since_midnight_ist - RESET_SECONDS)
    else:
        return now - (seconds_since_midnight_ist + 86400 - RESET_SECONDS)

