@app.route("/health")
def health_check():
    """Lightweight health/diagnostics endpoint for uptime monitors.
    NOTE: this only proves the Python process is alive and its Flask thread
    is responsive — it says nothing about whether the hosting platform has
    put the whole CONTAINER to sleep, since code inside a sleeping/stopped
    container cannot answer HTTP requests at all (see the docs note further
    down in this file about StackHost sleep vs. process crash vs. task
    death — they're different failure modes and this endpoint can only ever
    help distinguish the first two)."""
    try:
        uptime = int(time.time() - _heartbeat_start_time) if '_heartbeat_start_time' in globals() else -1
        ram = _get_memory_mb() if '_get_memory_mb' in globals() else -1
        last_update_age = (
            int(time.time() - _LAST_UPDATE_TS["ts"]) if '_LAST_UPDATE_TS' in globals() else -1
        )
        task_status = {}
        if '_SUPERVISOR_STATS' in globals():
            for name, stats in _SUPERVISOR_STATS.items():
                task_status[name] = {"restarts": stats["restarts"], "last_error": stats["last_error"]}
        _loop_age = (time.monotonic() - _LOOP_HEARTBEAT_TS) if "_LOOP_HEARTBEAT_TS" in globals() else 0
        _db_ok = True
        try:
            _hc = sqlite3.connect(DB_PATH, timeout=2)      # own short-lived connection: never touches the bot's shared cursor
            try:
                _hc.execute("SELECT 1").fetchone()
            finally:
                _hc.close()
        except Exception:
            _db_ok = False
        _unhealthy = (not _db_ok) or _loop_age > float(os.environ.get("HEALTH_MAX_LOOP_AGE_SEC", "120"))
        _http = 503 if _unhealthy else 200
        _le = globals().get("_LAST_ERROR") or {}
        return {
            "status": "degraded" if _unhealthy else "alive",
            "db_ok": _db_ok,
            "last_error_type": _le.get("type"),
            "last_error_seconds_ago": round(time.time() - _le["ts"]) if _le.get("ts") else None,
            "pid": os.getpid(),
            "loop_heartbeat_age_seconds": round(time.monotonic() - _LOOP_HEARTBEAT_TS, 1) if "_LOOP_HEARTBEAT_TS" in globals() else None,
            "db_background_pending": _DB_BG_PENDING if "_DB_BG_PENDING" in globals() else None,
            "uptime_seconds": uptime,
            "ram_mb": round(ram, 1) if ram >= 0 else None,
            "last_telegram_update_seconds_ago": last_update_age,
            "mongo_available": MONGO_AVAILABLE if 'MONGO_AVAILABLE' in globals() else None,
            "premium_emoji_enabled": _PE_STATE["enabled"] if '_PE_STATE' in globals() else None,
            "flood_control_stats": _FC_STATS if '_FC_STATS' in globals() else None,
            "background_tasks": task_status,
        }, _http
    except Exception as e:
        # Even the health check itself must never crash the Flask thread —
        # it's the one thing that should keep answering no matter what else
        # in the bot is broken.
        return {"status": "error", "error": str(e)}, 500

