# ── Airdrop DB helpers ────────────────────────────────────────────────────────
def _airdrop_db():
    # Always use same DB_PATH as main bot (already resolved safely at startup)
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA busy_timeout=1200")
    conn.row_factory = sqlite3.Row
    return conn

def _get_airdrop_row(user_id):
    with _airdrop_db() as db:
        row = db.execute(
            "SELECT last_free,last_ad,streak,total_opens,last_streak_day "
            "FROM airdrop_data WHERE user_id=?", (user_id,)
        ).fetchone()
    if not row:
        with _airdrop_db() as db:
            db.execute(
                "INSERT OR IGNORE INTO airdrop_data "
                "(user_id,last_free,last_ad,streak,total_opens,last_streak_day) "
                "VALUES (?,0,0,0,0,0)", (user_id,)
            )
            db.commit()
        return 0, 0, 0, 0, 0
    return tuple(row)

def _save_airdrop_row(user_id, last_free, last_ad, streak, total_opens, last_streak_day):
    with _airdrop_db() as db:
        db.execute("""
            INSERT OR REPLACE INTO airdrop_data
            (user_id,last_free,last_ad,streak,total_opens,last_streak_day)
            VALUES (?,?,?,?,?,?)
        """, (user_id, last_free, last_ad, streak, total_opens, last_streak_day))
        db.commit()

def _add_coins_web(user_id, amount):
    with _airdrop_db() as db:
        db.execute("INSERT OR IGNORE INTO shinobi_coins (user_id,coins,last_daily,last_weekly,last_monthly) VALUES (?,0,0,0,0)", (user_id,))
        db.execute("UPDATE shinobi_coins SET coins=coins+? WHERE user_id=?", (amount, user_id))
        db.commit()

def _add_vouchers_web(user_id, amount):
    with _airdrop_db() as db:
        db.execute("INSERT OR IGNORE INTO draft_vouchers (user_id,vouchers) VALUES (?,0)", (user_id,))
        db.execute("UPDATE draft_vouchers SET vouchers=vouchers+? WHERE user_id=?", (amount, user_id))
        db.commit()

def _get_spring_card_web():
    with _airdrop_db() as db:
        return db.execute(
            "SELECT name,rarity,file_id,COALESCE(file_type,'photo') as ft "
            "FROM cards WHERE rarity='Spring' ORDER BY RANDOM() LIMIT 1"
        ).fetchone()

def _insert_user_card_web(user_id, name, rarity, file_id, file_type="photo"):
    with _airdrop_db() as db:
        row = db.execute("SELECT id FROM cards WHERE name=? AND rarity=? LIMIT 1", (name, rarity)).fetchone()
        card_id = row["id"] if row else None
        db.execute(
            "INSERT INTO user_cards (user_id,card_name,rarity,file_id,card_id,file_type) VALUES (?,?,?,?,?,?)",
            (user_id, name, rarity, file_id, card_id, file_type)
        )
        db.commit()

def _validate_init_data(init_data_str):
    try:
        parsed = dict(urllib.parse.parse_qsl(init_data_str, keep_blank_values=True))
        hash_recv = parsed.pop("hash", "")
        data_check = "\n".join(f"{k}={v}" for k, v in sorted(parsed.items()))
        secret_key = hmac.new(b"WebAppData", BOT_TOKEN.encode(), hashlib.sha256).digest()
        expected = hmac.new(secret_key, data_check.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, hash_recv):
            return None
        if time.time() - int(parsed.get("auth_date", 0)) > 3600:
            return None
        return json.loads(parsed.get("user", "{}"))
    except Exception:
        return None

def _generate_reward_web(total_opens):
    if total_opens > 0 and total_opens % AIRDROP_SPRING_OPEN == 0:
        card = _get_spring_card_web()
        if card:
            return {"type": "spring", "value": dict(card), "display": f"🌸 {card['name'].title()}", "emoji": "🌸"}
    roll = random.random() * 100
    if roll < 5:
        card = _get_spring_card_web()
        if card:
            return {"type": "spring", "value": dict(card), "display": f"🌸 {card['name'].title()}", "emoji": "🌸"}
    if roll < 40:
        amount = random.randint(2, 20)
        return {"type": "voucher", "value": amount, "display": f"{amount} Draft Vouchers", "emoji": "🎟️"}
    amount = random.randint(500, 5000)
    return {"type": "coins", "value": amount, "display": f"{amount:,} Coins", "emoji": "💰"}

@app.route("/airdrop/state")
def airdrop_state():
    from flask import request as freq, jsonify
    user_data = _validate_init_data(freq.args.get("init_data", ""))
    if not user_data:
        return jsonify({"ok": False, "error": "Unauthorized"}), 403
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"ok": False, "error": "No user"}), 400
    now = int(time.time())
    last_free, last_ad, streak, total_opens, _ = _get_airdrop_row(user_id)
    free_rem = max(0, AIRDROP_FREE_COOLDOWN - (now - last_free))
    ad_rem   = max(0, AIRDROP_AD_COOLDOWN   - (now - last_ad))
    sp_left  = AIRDROP_SPRING_OPEN - (total_opens % AIRDROP_SPRING_OPEN) if total_opens % AIRDROP_SPRING_OPEN != 0 else AIRDROP_SPRING_OPEN
    return jsonify({"ok": True, "freeAvailable": free_rem==0, "adAvailable": ad_rem==0,
                    "freeRemaining": free_rem, "adRemaining": ad_rem,
                    "streak": streak, "totalOpens": total_opens, "springLeft": sp_left})

@app.route("/airdrop/open", methods=["POST"])
def airdrop_open():
    from flask import request as freq, jsonify
    import json as _json
    body      = freq.get_json(silent=True) or {}
    box_type  = body.get("type", "free")
    user_data = _validate_init_data(body.get("init_data", ""))
    if not user_data:
        return jsonify({"ok": False, "error": "Unauthorized"}), 403
    user_id   = user_data.get("id")
    user_name = user_data.get("first_name", "Shinobi")
    if not user_id:
        return jsonify({"ok": False, "error": "No user ID"}), 400
    now = int(time.time())
    last_free, last_ad, streak, total_opens, last_streak_day = _get_airdrop_row(user_id)
    if box_type == "free":
        if (now - last_free) < AIRDROP_FREE_COOLDOWN:
            rem = AIRDROP_FREE_COOLDOWN - (now - last_free)
            return jsonify({"ok": False, "error": f"⏳ Free box resets in {rem//3600}h {(rem%3600)//60}m!"})
        last_free = now
    elif box_type == "ad":
        if (now - last_ad) < AIRDROP_AD_COOLDOWN:
            rem = AIRDROP_AD_COOLDOWN - (now - last_ad)
            return jsonify({"ok": False, "error": f"⏳ Ad box resets in {rem//60}m {rem%60}s!"})
        last_ad = now
    else:
        return jsonify({"ok": False, "error": "Unknown box type"}), 400
    now_ist = now + IST_OFFSET_SEC
    today_ist_day = now_ist // 86400
    if today_ist_day == last_streak_day + 1:
        streak += 1
    elif today_ist_day > last_streak_day + 1:
        streak = 1
    total_opens += 1
    reward = _generate_reward_web(total_opens)
    streak_bonus = (total_opens % AIRDROP_STREAK_BONUS == 0)
    if streak_bonus:
        _add_coins_web(user_id, 500)
    is_spring = reward["type"] == "spring"
    if reward["type"] == "coins":
        _add_coins_web(user_id, reward["value"])
    elif reward["type"] == "voucher":
        _add_vouchers_web(user_id, reward["value"])
    elif is_spring:
        card = reward["value"]
        _insert_user_card_web(user_id, card["name"], card["rarity"], card["file_id"], card.get("ft","photo"))
    _save_airdrop_row(user_id, last_free, last_ad, streak, total_opens, today_ist_day)
    try:
        txt = f"🎁 *AIRDROP REWARD!*\n\n🥷 *{user_name}*\n\n{reward['emoji']} *YOU GOT: {reward['display']}!*\n\n⚔️ Keep opening boxes! /airdrop"
        http_requests.post(f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage",
                           json={"chat_id": user_id, "text": txt, "parse_mode": "Markdown"}, timeout=5)
        if is_spring:
            http_requests.post(f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage",
                               json={"chat_id": LOG_GROUP_ID, "text": f"🌍 *GLOBAL AIRDROP!*\n\n🔥 *{user_name}* pulled\n🌸 *SPRING: {reward['display']}!*\n\nUse /airdrop now!", "parse_mode": "Markdown"}, timeout=5)
    except Exception:
        pass
    sp_left = AIRDROP_SPRING_OPEN - (total_opens % AIRDROP_SPRING_OPEN) if total_opens % AIRDROP_SPRING_OPEN != 0 else AIRDROP_SPRING_OPEN
    return jsonify({"ok": True, "reward_type": reward["type"], "reward_display": reward["display"],
                    "streak": streak, "total_opens": total_opens, "spring_left": sp_left,
                    "streak_bonus": streak_bonus, "notify_bot": False})

