# Rarities whose canonical form is NOT simple Title Case (e.g. "FIFA" stays all-caps,
# not "Fifa"). Used by normalize_rarity() below so user input like "fifa"/"FIFA"/"Fifa"
# all resolve to the correct dict key. Add future non-Title-Case rarities here.
RARITY_CAPITALIZATION_OVERRIDES = {
    "FIFA": "FIFA",
}

# ===== RARITY REGISTRY START =====
# ONE place that defines the built-in "extra" rarities. Everything else in the bot
# (drop pool, /addcard validation, shop/collection/inventory/trade/gift displays,
# /rarity, top commands, draft weights, referral rewards ...) already reads
# RARITY_WEIGHTS / RARITY_EMOJI, so registering here makes them available
# everywhere without scattered `if rarity == "limited"` checks.
#   weight 0  -> never spawns randomly in groups (admin/event/shop/draft only)
#   coins/ryo -> payout values used by RARITY_COINS / RARITY_RYO (edit here)
#   order     -> position in RARITY_ORDER_DEFAULT (0 = rarest / shown first)
EXTRA_BUILTIN_RARITIES = {
    "Limited":         {"emoji": "⌛", "weight": 0, "coins": 800, "ryo": 2000, "order": "front"},
    "Draft Exclusive": {"emoji": "🎫", "weight": 0, "coins": 800, "ryo": 2000, "order": "front"},
    "Rainy":           {"emoji": "🌧️", "weight": 0, "coins": 700, "ryo": 1500, "order": "front"},
    "Customized":      {"emoji": "🎨", "weight": 0, "coins": 600, "ryo": 1500, "order": "front"},
    "Shop":            {"emoji": "🛒", "weight": 0, "coins": 300, "ryo": 500,  "order": "back"},
}


def _rarity_compact(s: str) -> str:
    """'Draft Exclusive' / 'draft_exclusive' / 'DRAFT-EXCLUSIVE' -> 'draftexclusive'."""
    return re.sub(r"[^a-z0-9]", "", str(s).lower())


def _register_builtin_rarities():
    for _name, _cfg in EXTRA_BUILTIN_RARITIES.items():
        RARITY_WEIGHTS.setdefault(_name, _cfg["weight"])
        RARITY_EMOJI.setdefault(_name, _cfg["emoji"])
        RARITY_CAPITALIZATION_OVERRIDES.setdefault(_name.upper(), _name)


_register_builtin_rarities()


def normalize_rarity(raw: str) -> str:
    """
    Normalise user-typed rarity text (any case, spaces/underscores/hyphens ignored)
    to the canonical rarity key used throughout the bot (RARITY_WEIGHTS /
    RARITY_EMOJI / SHOP_PRICES, etc).  "fifa" -> "FIFA", "draft_exclusive" /
    "Draft Exclusive" / "DRAFTEXCLUSIVE" -> "Draft Exclusive", "epic" -> "Epic".
    Unknown text falls back to plain Title-Case exactly as before.
    """
    if not raw:
        return raw
    stripped = raw.strip()
    override = RARITY_CAPITALIZATION_OVERRIDES.get(stripped.upper())
    if override:
        return override
    compact = _rarity_compact(stripped)
    if compact:
        for known in list(RARITY_WEIGHTS):
            if _rarity_compact(known) == compact:
                return known
    return stripped.capitalize()


def split_name_and_rarity(tokens):
    """Splits ["Itachi", "Draft", "Exclusive"] -> (["Itachi"], "Draft Exclusive"):
    the rarity is the longest trailing 1-3 word group that is a known rarity;
    otherwise the last word (previous behaviour)."""
    tokens = list(tokens)
    for n in (3, 2):
        if len(tokens) > n:
            cand = normalize_rarity(" ".join(tokens[-n:]))
            if cand in RARITY_WEIGHTS:
                return tokens[:-n], cand
    return tokens[:-1], normalize_rarity(tokens[-1])
# ===== RARITY REGISTRY END =====


