def _load_custom_rarities():
    """Merges every admin-added rarity into RARITY_WEIGHTS / RARITY_EMOJI at startup."""
    try:
        cursor.execute("SELECT name, emoji, weight FROM custom_rarities")
        for _name, _emoji, _weight in cursor.fetchall():
            RARITY_WEIGHTS[_name] = _weight
            RARITY_EMOJI[_name] = _emoji
            RARITY_CAPITALIZATION_OVERRIDES[_name.upper()] = _name
    except Exception as _e:
        print(f"[CUSTOM RARITIES] load error: {_e}")

_load_custom_rarities()


# ── DB thread-pool executor ───────────────────────────────────────────────────
# All async handler DB calls run here so they never block the asyncio event loop.
# MEMORY FIX: lowered 8 -> 4 workers. Each worker thread holds its own SQLite
# connection forever (see _get_thread_conn) — fewer threads means fewer
# permanently-resident connections. Combined with the cache_size cut above,
# worst case is now 4 x 4MB = 16MB instead of the previous 8 x 32MB = 256MB.
_db_executor = ThreadPoolExecutor(max_workers=4, thread_name_prefix="db_worker")

async def _db_run(fn, *args):
    """Run a synchronous DB function in the thread-pool executor.
    Usage: result = await _db_run(lambda: cursor.execute(...).fetchone())
    """
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(_db_executor, fn, *args)

# Fire-and-forget DB work must be bounded. ThreadPoolExecutor's internal queue
# is unbounded; scheduling one task for every message can therefore turn a
# slow SQLite/Mongo write path into an ever-growing RAM backlog after hours.
_DB_BG_MAX_PENDING = int(os.environ.get("DB_BG_MAX_PENDING", "120"))
_DB_BG_PENDING = 0
_DB_BG_PENDING_LOCK = threading.Lock()

def _schedule_db_background(fn, *args, label="db"):
    """Submit low-priority DB work only while the background queue is healthy.
    Dropping a diagnostic/log update is preferable to letting the queue consume
    the whole container and eventually make Telegram polling appear dead."""
    global _DB_BG_PENDING
    with _DB_BG_PENDING_LOCK:
        if _DB_BG_PENDING >= _DB_BG_MAX_PENDING:
            print(f"[DB BACKPRESSURE] dropping low-priority '{label}' write; pending={_DB_BG_PENDING}")
            return False
        _DB_BG_PENDING += 1

    async def _runner():
        global _DB_BG_PENDING
        try:
            await _db_run(fn, *args)
        except Exception as exc:
            print(f"[DB BG] '{label}' failed: {exc}")
        finally:
            with _DB_BG_PENDING_LOCK:
                _DB_BG_PENDING = max(0, _DB_BG_PENDING - 1)

    try:
        asyncio.create_task(_runner(), name=f"db-bg-{label}")
        return True
    except Exception:
        with _DB_BG_PENDING_LOCK:
            _DB_BG_PENDING = max(0, _DB_BG_PENDING - 1)
        return False

_MILESTONE_SAVE_PENDING = set()
_MILESTONE_SAVE_LOCK = threading.Lock()

def _schedule_milestone_save(chat_id):
    """Coalesce repeated milestone snapshots for the same chat."""
    with _MILESTONE_SAVE_LOCK:
        if chat_id in _MILESTONE_SAVE_PENDING:
            return
        _MILESTONE_SAVE_PENDING.add(chat_id)

    async def _runner():
        try:
            await _db_run(_save_milestone_state, chat_id)
        except Exception as exc:
            print(f"[MILESTONE] background save failed for chat {chat_id}: {exc}")
        finally:
            with _MILESTONE_SAVE_LOCK:
                _MILESTONE_SAVE_PENDING.discard(chat_id)
    try:
        asyncio.create_task(_runner(), name=f"milestone-save-{chat_id}")
    except Exception:
        with _MILESTONE_SAVE_LOCK:
            _MILESTONE_SAVE_PENDING.discard(chat_id)

