# ================= ADMIN & BAN HELPERS =================

def is_admin(user_id: int) -> bool:
    """Check if user is owner, co-owner, or added admin."""
    if user_id in (OWNER_ID, CO_OWNER_ID):
        return True
    cursor.execute("SELECT user_id FROM admins WHERE user_id=?", (user_id,))
    return cursor.fetchone() is not None

# ================= UPLOADER ROLE (limited admin) =================
# Uploaders can ONLY use /addcard, /editcard, /delcard. They cannot access
# any other admin command — is_admin() deliberately does NOT include them,
# so every other admin-gated command stays closed to them automatically.

def is_uploader(user_id: int) -> bool:
    """Check if user has the limited 'uploader' role (card management only)."""
    if user_id in (OWNER_ID, CO_OWNER_ID):
        return True
    cursor.execute("SELECT user_id FROM uploaders WHERE user_id=?", (user_id,))
    return cursor.fetchone() is not None

def can_manage_cards(user_id: int) -> bool:
    """True for full admins AND uploaders — used ONLY by /addcard, /editcard,
    /delcard. Every other admin command must keep using is_admin()."""
    return is_admin(user_id) or is_uploader(user_id)

# ================= FEATURE FREEZE (generic kill switch) =================

def is_feature_frozen(feature: str):
    """Returns (frozen: bool, reason: str|None) for a given feature key."""
    try:
        cursor.execute("SELECT reason FROM frozen_features WHERE feature=?", (feature,))
        row = cursor.fetchone()
        if row:
            return True, (row[0] or "No reason given.")
        return False, None
    except Exception:
        return False, None

def freeze_feature(feature: str, by_user_id: int, reason: str = ""):
    cursor.execute(
        "INSERT OR REPLACE INTO frozen_features (feature, frozen_by, frozen_at, reason) VALUES (?,?,?,?)",
        (feature, by_user_id, int(time.time()), reason or "No reason given.")
    )
    conn.commit()

def unfreeze_feature(feature: str) -> bool:
    cursor.execute("DELETE FROM frozen_features WHERE feature=?", (feature,))
    conn.commit()
    return cursor.rowcount > 0

def list_frozen_features():
    cursor.execute("SELECT feature, frozen_by, frozen_at, reason FROM frozen_features ORDER BY frozen_at DESC")
    return cursor.fetchall()

# Known/enforced feature keys — kept as a reference list for /freeze's usage
# text. /freeze technically accepts ANY key (so it's ready for future
# features too), but a feature only actually stops working if its handler
# calls is_feature_frozen() — these are the ones that already do:
FREEZABLE_FEATURES = {
    "shinobi_market": "/market — buy/sell characters for Shinobi Coins",
    "player_market":  "/sell, /list, buy button — peer-to-peer card market",
    "trade":          "/trade_cards, /trade — direct card-for-card trading",
    "gift":           "/gift — sending a card to another user",
}

# BUGFIX: /freeze <key> used to accept ANY typed string with no validation,
# so a natural-but-wrong key (e.g. "/freeze marketplace" or "/freeze market")
# was silently saved as its own frozen row that no handler ever reads —
# meanwhile the real key ("shinobi_market") stayed untouched and the
# feature kept working like nothing was frozen. FEATURE_ALIASES maps the
# common variants admins actually type to the real enforced key, and
# freeze_cmd/unfreeze_cmd now reject anything that still doesn't resolve to
# a key in FREEZABLE_FEATURES instead of silently "succeeding".
FEATURE_ALIASES = {
    "marketplace":     "shinobi_market",
    "market":          "shinobi_market",
    "shinobimarket":   "shinobi_market",
    "shinobi":         "shinobi_market",
    "playermarket":    "player_market",
    "player":          "player_market",
    "sell":            "player_market",
    "trading":         "trade",
    "trades":          "trade",
    "gifting":         "gift",
    "gifts":           "gift",
}

def resolve_feature_key(raw: str) -> str:
    """Normalizes a user-typed feature key: lowercase + strip, then apply
    known aliases. Returns the resolved key as-is if there's no alias for
    it (still gets validated against FREEZABLE_FEATURES by the caller)."""
    key = raw.strip().lower()
    return FEATURE_ALIASES.get(key, key)

# ================= BOT ON/OFF + DATABASE-READY LOCK =================
# Both flags are stored in bot_settings via panel_get/panel_set (defined
# further below as panel_get/panel_set — safe because these are only ever
# called at request time, long after that def has run at import time).

def is_bot_enabled() -> bool:
    return panel_get("bot_enabled", "ON") == "ON"

def is_db_ready() -> bool:
    """False right after a fresh/empty database (e.g. a redeploy on a host
    with an ephemeral filesystem, before /restore has been run). While this
    is False, the bot refuses all non-admin commands instead of letting
    users /start and get treated as brand-new — which is what was silently
    wiping real collections: a user could get registered with 0 cards in the
    empty post-deploy DB, and if /restore later brought their real data back
    they *should* have been fine, but this window is exactly when new/blank
    rows for them could be created and then fought over with the restored
    ones. Locking the bot until the owner explicitly confirms the DB is
    ready (/live) — or a successful /restore sets it automatically — removes
    that window entirely.
    """
    return panel_get("db_ready", "0") == "1"

BOT_OFF_MSG = (
    "🔴 *The bot is currently turned OFF by the owner.*\n\n"
    "No features are available right now — please check back later."
)

DB_NOT_READY_MSG = (
    "⏳ *The bot is starting up / syncing its database.*\n\n"
    "This only takes a moment after a fresh deploy or a backup restore. "
    "Please try again shortly."
)

# PERF: has_started_bot() is called by the DM-gate for EVERY command (64 call sites). It used to do a
# MongoDB network round-trip and open a brand-new SQLite connection each time, on the event loop.
# "has started" can only ever go False -> True, so POSITIVE results are cached for the process
# lifetime (bounded by the number of users); negatives are never cached.
_STARTED_USERS_CACHE = set()
_STARTED_USERS_CACHE_MAX = 200_000

def has_started_bot(user_id: int) -> bool:
    """Check if user has previously started the bot in DM."""
    if user_id in _STARTED_USERS_CACHE:
        return True
    # MongoDB first
    if MONGO_AVAILABLE:
        result = has_started_bot_mongo(user_id)
        if result:
            if len(_STARTED_USERS_CACHE) < _STARTED_USERS_CACHE_MAX:
                _STARTED_USERS_CACHE.add(user_id)
            return True
    # SQLite fallback
    try:
        _c = sqlite3.connect(DB_PATH, check_same_thread=False)
        _c.execute("PRAGMA busy_timeout=5000")
        try:
            row = _c.execute("SELECT user_id FROM bot_users WHERE user_id=?", (user_id,)).fetchone()
        finally:
            _c.close()
        if row is not None and len(_STARTED_USERS_CACHE) < _STARTED_USERS_CACHE_MAX:
            _STARTED_USERS_CACHE.add(user_id)
        return row is not None
    except Exception:
        return True  # fail open (not cached)

