# ================= DRAFT HELPERS =================

def get_draft_days_remaining():
    """Return days remaining in the draft event from DB, or 0 if ended/not set."""
    cursor.execute("SELECT value FROM bot_settings WHERE key='draft_end'")
    row = cursor.fetchone()
    if not row:
        return 0
    try:
        end_ts = int(row[0])
        now = int(time.time())
        remaining_secs = max(0, end_ts - now)
        return remaining_secs // 86400
    except:
        return 0

def is_draft_event_active():
    """Check if draft event is active based on DB settings."""
    cursor.execute("SELECT value FROM bot_settings WHERE key='draft_active'")
    row = cursor.fetchone()
    if not row or row[0] != "1":
        return False
    cursor.execute("SELECT value FROM bot_settings WHERE key='draft_end'")
    end_row = cursor.fetchone()
    if not end_row:
        return False
    try:
        end_ts = int(end_row[0])
        now = int(time.time())
        return now <= end_ts
    except:
        return False

def load_draft_rarity_weights():
    """Load draft rarity weights and event name from DB into globals."""
    global DRAFT_RARITY_WEIGHTS, DRAFT_EVENT_NAME
    cursor.execute("SELECT value FROM bot_settings WHERE key='draft_rarities'")
    row = cursor.fetchone()
    if row:
        try:
            import json
            weights = json.loads(row[0])
            # Migration: older saved configs may still have "Academy" — FIFA now
            # takes over that role in the draft pool, so convert it on load.
            if "Academy" in weights and "FIFA" not in weights:
                weights["FIFA"] = weights.pop("Academy")
            elif "Academy" in weights and "FIFA" in weights:
                weights.pop("Academy")
            # Migration: FIFA's special-pull role in draft_event is now Mermaid.
            if "FIFA" in weights and "Mermaid" not in weights:
                weights["Mermaid"] = weights.pop("FIFA")
            elif "FIFA" in weights and "Mermaid" in weights:
                weights.pop("FIFA")
            # Migration: the special-pull role in draft_event is now Rainy 🌧️.
            # Older saved configs may still carry the previous special rarity
            # (Mermaid / Tradition) — convert it so the displayed drop rates
            # match the Rainy pity guarantee. Done in memory only; the stored
            # JSON is untouched until an admin edits the weights.
            for _old_special in ("Mermaid", "Tradition"):
                if _old_special in weights and "Rainy" not in weights:
                    weights["Rainy"] = weights.pop(_old_special)
                elif _old_special in weights and "Rainy" in weights:
                    weights.pop(_old_special)
            DRAFT_RARITY_WEIGHTS = weights
        except:
            DRAFT_RARITY_WEIGHTS = dict(DRAFT_RARITY_WEIGHTS_DEFAULT)
    else:
        DRAFT_RARITY_WEIGHTS = dict(DRAFT_RARITY_WEIGHTS_DEFAULT)
    # Also restore event name
    name_row = cursor.execute("SELECT value FROM bot_settings WHERE key='draft_event_name'").fetchone()
    if name_row and name_row[0]:
        DRAFT_EVENT_NAME = name_row[0]

def get_draft_banner_file_id():
    """Get draft banner file_id from DB settings."""
    cursor.execute("SELECT value FROM bot_settings WHERE key='draft_banner'")
    row = cursor.fetchone()
    return row[0] if row else None


# ================= LEADERBOARD BANNERS (Feature) =================
# Lets an owner/admin attach a banner image/video/GIF to ANY leaderboard
# command (/top_shinobi_coins, /top_xo, /top_clans, etc.) via a single
# generic command: reply to the media with /set_leaderboard <key>. Stored as
# JSON ({"file_id":..., "file_type":...}) per key in bot_settings, the same
# table the existing single-banner features (draft/collab) already use —
# this just generalizes that pattern to many independent named banners
# instead of one fixed slot, and to photo/video/animation/gif instead of
# photo-only.
#
# LEADERBOARD_KEYS maps a short, stable key (what admins type after
# /set_leaderboard) to the human-readable label shown in confirmations and
# in /leaderboard_banners. Every top_* command below is wired to one of
# these keys. If a board doesn't have a banner set, it sends exactly the
# same plain-text message as before — nothing breaks for boards nobody has
# customised yet.
LEADERBOARD_KEYS = {
    "shinobi_coins":      "🏆 Top Shinobi Coins",
    "gems":                "💎 Top Gems",
    "xo":                  "⭕ Top XO (Tic-Tac-Toe)",
    "rps":                 "✊ Top Rock-Paper-Scissors",
    "clans":               "🏯 Top Clans",
    "collectors":          "🎴 Top Collectors (/leaderboard)",
    "onepiece_summer":     "☀️ Top One Piece Summer",
    "bleach":              "⚔️ Top Bleach",
    "demon_slayer":        "🗡️ Top Demon Slayer",
    "bleach_summer":       "☀️ Top Bleach Summer",
    "demon_slayer_summer": "☀️ Top Demon Slayer Summer",
    "naruto_summer":       "☀️ Top Naruto Summer",
}


def _leaderboard_banner_setting_key(key: str) -> str:
    return f"leaderboard_banner_{key}"


def get_leaderboard_banner(key: str):
    """Return (file_id, file_type) for a leaderboard key, or (None, None) if unset."""
    import json as _json_lb
    cursor.execute(
        "SELECT value FROM bot_settings WHERE key=?",
        (_leaderboard_banner_setting_key(key),)
    )
    row = cursor.fetchone()
    if not row or not row[0]:
        return None, None
    try:
        data = _json_lb.loads(row[0])
        return data.get("file_id"), data.get("file_type", "photo")
    except Exception:
        return None, None


def set_leaderboard_banner(key: str, file_id: str, file_type: str):
    import json as _json_lb
    cursor.execute(
        "INSERT OR REPLACE INTO bot_settings (key, value) VALUES (?, ?)",
        (_leaderboard_banner_setting_key(key), _json_lb.dumps({"file_id": file_id, "file_type": file_type}))
    )
    conn.commit()


def clear_leaderboard_banner(key: str):
    cursor.execute(
        "DELETE FROM bot_settings WHERE key=?",
        (_leaderboard_banner_setting_key(key),)
    )
    conn.commit()


async def send_leaderboard(message, key: str, caption: str, parse_mode: str = "Markdown"):
    """
    Send a leaderboard's text, decorated with its configured banner if one
    has been set via /set_leaderboard. Falls back to a plain reply_text with
    the exact same caption when no banner is set, or if sending the media
    fails for any reason (e.g. a stale/deleted file_id) — a leaderboard
    should never go silent just because its banner broke.
    """
    file_id, file_type = get_leaderboard_banner(key)
    if not file_id:
        await message.reply_text(caption, parse_mode=parse_mode)
        return
    try:
        await send_card_media(message, file_id, file_type=file_type, caption=caption, parse_mode=parse_mode)
    except Exception as e:
        print(f"[LEADERBOARD BANNER] Failed to send banner for '{key}' ({e}) — falling back to text")
        try:
            await message.reply_text(caption, parse_mode=parse_mode)
        except Exception:
            # FIX (Bug 12 — literal "<b>" tags): last-resort fallback sends
            # plain text with NO parse_mode, so any leftover Markdown/HTML
            # markup must be stripped here too, not just Markdown's "*"/"`".
            plain = caption.replace("*", "").replace("`", "")
            if parse_mode == "HTML":
                plain = re.sub(r"<[^>]+>", "", plain)
            await message.reply_text(plain)


async def set_leaderboard_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /set_leaderboard <key> — Admin: reply to a photo/video/animation/GIF with
    this command to set (or replace) that leaderboard's banner.
    /set_leaderboard <key> off — remove a previously set banner.

    See /leaderboard_banners for the full list of valid keys.
    """
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only.")
        return

    args = context.args or []
    if not args:
        keys_list = "\n".join(f"  • `{k}` — {label}" for k, label in LEADERBOARD_KEYS.items())
        await update.message.reply_text(
            "🖼️ *Set Leaderboard Banner*\n\n"
            "Reply to a photo, video, or GIF/animation with:\n"
            "`/set_leaderboard <key>`\n\n"
            "Remove a banner with:\n"
            "`/set_leaderboard <key> off`\n\n"
            f"*Valid keys:*\n{keys_list}",
            parse_mode="Markdown"
        )
        return

    key = args[0].lower()
    if key not in LEADERBOARD_KEYS:
        await update.message.reply_text(
            f"❌ Unknown leaderboard key '{key}'.\n\n"
            "Use /set_leaderboard with no arguments to see the full list of valid keys."
        )
        return

    if len(args) > 1 and args[1].lower() in ("off", "remove", "clear", "none"):
        clear_leaderboard_banner(key)
        await update.message.reply_text(f"✅ Banner removed for {LEADERBOARD_KEYS[key]}.")
        return

    replied = update.message.reply_to_message
    file_id = None
    file_type = "photo"
    if replied:
        if replied.photo:
            file_id = replied.photo[-1].file_id
            file_type = "photo"
        elif replied.video:
            file_id = replied.video.file_id
            file_type = "video"
        elif replied.animation:
            file_id = replied.animation.file_id
            file_type = "animation"
    # Also allow sending the media directly with the command as its caption,
    # same convenience /addcard already offers.
    if not file_id:
        if update.message.photo:
            file_id = update.message.photo[-1].file_id
            file_type = "photo"
        elif update.message.video:
            file_id = update.message.video.file_id
            file_type = "video"
        elif update.message.animation:
            file_id = update.message.animation.file_id
            file_type = "animation"

    if not file_id:
        await update.message.reply_text(
            "📸 Reply to a photo, video, or GIF/animation with "
            f"`/set_leaderboard {key}`\n\n"
            "(or send the media itself with that as the caption).",
            parse_mode="Markdown"
        )
        return

    set_leaderboard_banner(key, file_id, file_type)
    await update.message.reply_text(
        f"✅ Banner set for *{LEADERBOARD_KEYS[key]}*!\n"
        f"Run its command to preview.",
        parse_mode="Markdown"
    )


async def leaderboard_banners_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/leaderboard_banners — Admin: show every leaderboard key and whether it has a banner set."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only.")
        return
    lines = []
    for key, label in LEADERBOARD_KEYS.items():
        file_id, _ = get_leaderboard_banner(key)
        status = "✅ set" if file_id else "—"
        lines.append(f"  • `{key}` — {label}: {status}")
    await update.message.reply_text(
        "🖼️ *Leaderboard Banners*\n\n" + "\n".join(lines) +
        "\n\n💡 Use `/set_leaderboard <key>` (reply to media) to set one.",
        parse_mode="Markdown"
    )

def get_user_vouchers(user_id: int) -> int:
    cursor.execute("SELECT vouchers FROM draft_vouchers WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    return row[0] if row else 0

def add_vouchers(user_id: int, amount: int):
    """Add vouchers to user. Uses separate INSERT + UPDATE to avoid upsert bugs."""
    # Ensure row exists first
    cursor.execute("""
        INSERT OR IGNORE INTO draft_vouchers 
        (user_id, vouchers, total_spins, spins_since_legendary, spins_since_spring)
        VALUES (?, 0, 0, 0, 0)
    """, (user_id,))
    # Now add the amount
    cursor.execute(
        "UPDATE draft_vouchers SET vouchers = vouchers + ? WHERE user_id = ?",
        (amount, user_id)
    )
    conn.commit()

def deduct_vouchers(user_id: int, amount: int) -> bool:
    current = get_user_vouchers(user_id)
    if current < amount:
        return False
    cursor.execute("UPDATE draft_vouchers SET vouchers = vouchers - ? WHERE user_id=?", (amount, user_id))
    conn.commit()
    return True

