def grant_welcome_bonus_if_new(user_id: int) -> bool:
    """
    Grant the one-time welcome bonus (100 vouchers + 5000 coins) to a user,
    exactly once, ever — regardless of when/where they first show up in
    bot_users. Returns True if the bonus was just granted (caller may want to
    notify), False if the user already received it previously.

    This is intentionally decoupled from "is this user new in bot_users":
    start() registers users in bot_users BEFORE the join/verify gate runs,
    so checking bot_users for "new-ness" elsewhere is unreliable for DM users.
    welcome_bonus_given is the single source of truth instead.
    """
    cursor.execute("SELECT user_id FROM welcome_bonus_given WHERE user_id=?", (user_id,))
    if cursor.fetchone() is not None:
        return False
    try:
        add_vouchers(user_id, WELCOME_BONUS_VOUCHERS)
        add_coins(user_id, WELCOME_BONUS_COINS)
        cursor.execute(
            "INSERT OR IGNORE INTO welcome_bonus_given (user_id, given_at) VALUES (?,?)",
            (user_id, int(time.time()))
        )
        conn.commit()
        return True
    except Exception as e:
        print(f"[BONUS] Failed to grant welcome bonus to {user_id}: {e}")
        return False


def deduct_coins(user_id: int, amount: int) -> bool:
    current = get_coins(user_id)
    if current < amount:
        return False
    cursor.execute(
        "UPDATE shinobi_coins SET coins = coins - ? WHERE user_id=?",
        (amount, user_id)
    )
    conn.commit()
    return True


