RYO_RESET_AMOUNT   = 25000  # Given to every user whenever the owner resets Ryo
RYO_DAILY_AMOUNT   = 5000
RYO_WEEKLY_AMOUNT  = 10000
RYO_MONTHLY_AMOUNT = 20000

# Ryo awarded for catching a card, by rarity (Bug 8)
