def note_referral_rejection(referred_id: int, ref_code: str, reason: str):
    """Best-effort audit row for a refused attribution (deduplicated by UNIQUE, so spam can't grow it)."""
    try:
        cur = conn.cursor()
        cur.execute("SELECT user_id FROM referrals WHERE referral_code=?", (ref_code,))
        row = cur.fetchone()
        cur.execute("INSERT OR IGNORE INTO referral_rejections (referred_id, attempted_referrer_id, reason, created_at) "
                    "VALUES (?,?,?,?)", (referred_id, row[0] if row else None, reason, int(time.time())))
        conn.commit()
    except Exception as exc:
        print(f"[REFERRAL] could not record rejection: {exc}")


def consume_referral_pending_notice(user_id: int) -> bool:
    """True exactly once per pending referral (atomic), so the 'collect your first card' notice never repeats."""
    try:
        cur = conn.cursor()
        cur.execute("UPDATE referral_uses SET welcomed=1 WHERE referred_id=? AND status='pending' AND COALESCE(welcomed,0)=0",
                    (user_id,))
        conn.commit()
        return cur.rowcount == 1
    except Exception as exc:
        print(f"[REFERRAL] pending-notice check failed: {exc}")
        return False


def referral_stats(user_id: int) -> dict:
    cur = conn.cursor()
    cur.execute("SELECT status, COUNT(*) FROM referral_uses WHERE referrer_id=? GROUP BY status", (user_id,))
    by = {s: c for s, c in cur.fetchall()}
    cur.execute("SELECT total_referrals FROM referrals WHERE user_id=?", (user_id,))
    row = cur.fetchone()
    return {"valid": row[0] if row else 0, "pending": by.get("pending", 0), "invalid": by.get("invalid", 0),
            "attributed": sum(c for s, c in by.items() if s != "invalid")}


def qualify_pending_referral(referred_id: int, reason: str = "safety_sweep") -> str:
    """Python twin of the trigger, used only by the safety-net sweep (e.g. if the trigger could not be
    created). Re-checks real ownership, then flips pending -> qualified exactly once."""
    with _REFERRAL_LOCK:
        cur = conn.cursor()
        try:
            _sp_begin(cur, "ref_qual")
            src_list = ",".join(f"'{s}'" for s in REFERRAL_NON_QUALIFYING_SOURCES)
            cur.execute(f"SELECT id, card_id FROM user_cards WHERE user_id=? AND COALESCE(acq_source,'') NOT IN ({src_list}) "
                        f"ORDER BY id LIMIT 1", (referred_id,))
            card = cur.fetchone()
            if not card:
                _sp_release(cur, "ref_qual")
                return "no_card"
            cur.execute("SELECT referrer_id FROM referral_uses WHERE referred_id=? AND status='pending' LIMIT 1", (referred_id,))
            row = cur.fetchone()
            if not row:
                _sp_release(cur, "ref_qual")
                return "not_pending"
            now = int(time.time())
            cur.execute("UPDATE referral_uses SET status='qualified', qualified_at=?, qualified_card_id=?, qualification_reason=? "
                        "WHERE referred_id=? AND status='pending'", (now, card[1], reason, referred_id))
            if cur.rowcount != 1:
                _sp_release(cur, "ref_qual")
                return "not_pending"
            cur.execute("UPDATE referrals SET total_referrals = total_referrals + 1 WHERE user_id=?", (row[0],))
            cur.execute("INSERT OR IGNORE INTO referral_qualify_outbox (referrer_id, referred_id, card_id, created_at) "
                        "VALUES (?,?,?,?)", (row[0], referred_id, card[1], now))
            _sp_release(cur, "ref_qual")
            return "qualified"
        except Exception:
            _savepoint_rollback(cur, "ref_qual")
            print(f"[REFERRAL] safety-net qualification failed for {referred_id}:")
            traceback.print_exc()
            return "error"


def referral_safety_sweep(limit: int = 100) -> int:
    """Qualifies pending referrals whose referred user demonstrably owns a card but were missed (normally 0)."""
    n = 0
    cur = conn.cursor()
    src_list = ",".join(f"'{s}'" for s in REFERRAL_NON_QUALIFYING_SOURCES)
    cur.execute(f"SELECT ru.referred_id FROM referral_uses ru WHERE ru.status='pending' AND EXISTS "
                f"(SELECT 1 FROM user_cards uc WHERE uc.user_id = ru.referred_id AND COALESCE(uc.acq_source,'') NOT IN ({src_list})) "
                f"LIMIT ?", (limit,))
    for (rid,) in cur.fetchall():
        if qualify_pending_referral(rid) == "qualified":
            n += 1
            print(f"[REFERRAL] safety-net qualified referred user {rid} (trigger had not fired)")
    return n


# ── outbox processing (rewards) ──────────────────────────────────────────────
def process_referral_outbox_sync(limit: int = 50) -> list:
    """Pays out (idempotently) every qualified referral waiting in the outbox. DB only - no Telegram calls."""
    done = []
    with _REFERRAL_LOCK:
        cur = conn.cursor()
        cur.execute("SELECT id, referrer_id, referred_id, attempts FROM referral_qualify_outbox WHERE processed=0 "
                    "ORDER BY id LIMIT ?", (limit,))
        rows = cur.fetchall()
        for oid, referrer_id, referred_id, attempts in rows:
            try:
                results = recover_pending_referral_rewards(referrer_id)
            except Exception:
                traceback.print_exc()
                results = [{"status": "error", "count": 0, "lines": [], "skipped": [], "major": False}]
            if any(r["status"] == "error" for r in results):
                attempts += 1
                failed_for_good = attempts >= REFERRAL_OUTBOX_MAX_ATTEMPTS
                cur.execute("UPDATE referral_qualify_outbox SET attempts=?, processed=? WHERE id=?",
                            (attempts, 2 if failed_for_good else 0, oid))
                conn.commit()
                print(f"[REFERRAL] outbox {oid} reward attempt {attempts} failed for referrer={referrer_id}"
                      f"{' - GIVING UP (needs admin attention)' if failed_for_good else ' - will retry'}")
                if failed_for_good:
                    done.append({"referrer_id": referrer_id, "referred_id": referred_id, "results": results, "gave_up": True})
                continue
            now = int(time.time())
            cur.execute("UPDATE referral_qualify_outbox SET processed=1, processed_at=?, attempts=? WHERE id=?", (now, attempts, oid))
            cur.execute("UPDATE referral_uses SET status='rewarded', reward_processed_at=? WHERE referred_id=? AND status='qualified'",
                        (now, referred_id))
            conn.commit()
            done.append({"referrer_id": referrer_id, "referred_id": referred_id, "results": results, "gave_up": False})
    return done


async def referral_outbox_loop(bot):
    """Supervised background loop: pays qualified referrals, notifies the referrer, runs the safety sweep."""
    last_sweep = 0.0
    while True:
        try:
            if time.monotonic() - last_sweep >= REFERRAL_SAFETY_SWEEP_SEC:
                last_sweep = time.monotonic()
                referral_safety_sweep()
            for entry in process_referral_outbox_sync():
                if entry.get("gave_up"):
                    await log_to_group(bot, f"🚨 *Referral reward gave up after {REFERRAL_OUTBOX_MAX_ATTEMPTS} attempts*\n"
                                            f"👤 Referrer: `{entry['referrer_id']}` (referred `{entry['referred_id']}`)")
                    continue
                await give_referral_reward(bot, entry["referrer_id"], entry["results"], entry["referred_id"])
        except asyncio.CancelledError:
            raise
        except Exception:
            print("[REFERRAL] outbox loop iteration failed (loop continues):")
            traceback.print_exc()
        await asyncio.sleep(REFERRAL_OUTBOX_INTERVAL)


# ── admin tools ──────────────────────────────────────────────────────────────
def _fmt_ts(ts):
    return time.strftime("%Y-%m-%d %H:%M", time.localtime(ts)) if ts else "—"


async def referral_info_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/referral_info <user_id> — referral investigation (admin)."""
    if not update.effective_user or not update.message or not is_admin(update.effective_user.id):
        return
    try:
        uid = int(context.args[0]) if context.args else update.effective_user.id
    except ValueError:
        await update.message.reply_text("Usage: /referral_info <user_id>")
        return
    st = referral_stats(uid)
    cur = conn.cursor()
    lines = [f"🔎 *Referral info for* `{uid}`", "",
             f"🏆 Valid: *{st['valid']}*   ⏳ Pending: *{st['pending']}*   🚫 Invalid: *{st['invalid']}*",
             f"📎 Total attributed (valid+pending): *{st['attributed']}*"]
    cur.execute("SELECT referrer_id, status, timestamp, qualified_at, qualification_reason FROM referral_uses WHERE referred_id=?", (uid,))
    r = cur.fetchone()
    if r:
        lines += ["", f"👑 Referred by: `{r[0]}`", f"📌 Status: *{r[1]}* ({r[4] or '—'})",
                  f"🕒 Joined: {_fmt_ts(r[2])}   ✅ Qualified: {_fmt_ts(r[3])}"]
    cur.execute("SELECT ru.referred_id, ru.status, ru.timestamp, ru.qualified_at, bu.first_name FROM referral_uses ru "
                "LEFT JOIN bot_users bu ON bu.user_id=ru.referred_id WHERE ru.referrer_id=? "
                "ORDER BY ru.timestamp DESC LIMIT 15", (uid,))
    rows = cur.fetchall()
    if rows:
        lines += ["", "📋 *Latest referred users:*"]
        for rid, status, ts, qts, fn in rows:
            lines.append(f"• `{rid}` {escape_markdown(fn or '', version=1)} — {status} | joined {_fmt_ts(ts)} | qualified {_fmt_ts(qts)}")
    cur.execute("SELECT reason, attempted_referrer_id, created_at FROM referral_rejections WHERE referred_id=? ORDER BY id DESC LIMIT 5", (uid,))
    rej = cur.fetchall()
    cur.execute("SELECT reason, referred_id, created_at FROM referral_rejections WHERE attempted_referrer_id=? ORDER BY id DESC LIMIT 5", (uid,))
    rej2 = cur.fetchall()
    if rej or rej2:
        lines += ["", "🚫 *Rejected attempts:*"]
        lines += [f"• own attempt: {a} (link of `{b}`) {_fmt_ts(c)}" for a, b, c in rej]
        lines += [f"• via their link: {a} by `{b}` {_fmt_ts(c)}" for a, b, c in rej2]
    await update.message.reply_text("\n".join(lines)[:3900], parse_mode="Markdown")


async def referral_invalidate_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/referral_invalidate <referred_user_id> — mark a PENDING referral invalid (admin). Qualified ones are never touched."""
    if not update.effective_user or not update.message or not is_admin(update.effective_user.id):
        return
    try:
        rid = int(context.args[0])
    except (IndexError, ValueError):
        await update.message.reply_text("Usage: /referral_invalidate <referred_user_id>  (pending referrals only)")
        return
    cur = conn.cursor()
    cur.execute("UPDATE referral_uses SET status='invalid', qualification_reason='admin_invalidated' "
                "WHERE referred_id=? AND status='pending'", (rid,))
    conn.commit()
    await update.message.reply_text("✅ Pending referral marked invalid." if cur.rowcount else "ℹ️ No pending referral for that user.")


