# ================= UTILS =================

def insert_user_card(user_id: int, card_name: str, rarity: str, file_id: str,
                     file_type: str = "photo", card_id: int = None, source: str = None):
    """
    Insert a card into user_cards.
    Writes to MongoDB (primary) AND SQLite (backup/fallback).
    source: None for a normal acquisition (drop/daily/pack/shop/draft/admin grant ...). Peer-to-peer moves
    pass "transfer" (gift/trade) or "restore" (account restore): those rows do NOT qualify a pending
    referral (see trg_referral_qualify), so a referrer cannot "gift" a card to a throw-away account.
    """
    master = None

    # 1️⃣ Exact match by primary key
    if card_id is not None:
        cursor.execute(
            "SELECT id, file_type, COALESCE(series,'Naruto') FROM cards WHERE id=?",
            (card_id,)
        )
        master = cursor.fetchone()

    # 2️⃣ Match by name + rarity + file_id together (most specific, avoids
    # picking a different duplicate row that merely shares the same name+rarity
    # or the same file_id in isolation). FIX (Bug 1 - wrong card users in /find).
    if master is None and file_id:
        cursor.execute(
            "SELECT id, file_type, COALESCE(series,'Naruto') FROM cards "
            "WHERE name=? AND rarity=? AND file_id=? ORDER BY id ASC LIMIT 1",
            (card_name, rarity, file_id)
        )
        master = cursor.fetchone()

    # 3️⃣ Match by file_id alone (covers renamed/edited cards where file_id
    # is still the reliable identifier)
    if master is None and file_id:
        cursor.execute(
            "SELECT id, file_type, COALESCE(series,'Naruto') FROM cards WHERE file_id=? ORDER BY id ASC LIMIT 1",
            (file_id,)
        )
        master = cursor.fetchone()

    # 4️⃣ Last-resort fallback: name + rarity only (deterministic lowest id,
    # so at least it's consistent instead of arbitrary)
    if master is None:
        cursor.execute(
            "SELECT id, file_type, COALESCE(series,'Naruto') FROM cards WHERE name=? AND rarity=? ORDER BY id ASC LIMIT 1",
            (card_name, rarity)
        )
        master = cursor.fetchone()

    master_card_id = master[0] if master else card_id
    if master and master[1]:
        file_type = master[1]
    series = master[2] if master else "Naruto"

    # Write to MongoDB (primary storage)
    if MONGO_AVAILABLE:
        insert_user_card_mongo(
            user_id, card_name, rarity, file_id,
            file_type=file_type, card_id=master_card_id, series=series
        )

    # Write to SQLite (backup). The referral trigger fires here, inside this same transaction.
    if source is None:
        cursor.execute(
            "INSERT INTO user_cards (user_id, card_name, rarity, file_id, card_id, file_type, series) VALUES (?,?,?,?,?,?,?)",
            (user_id, card_name, rarity, file_id, master_card_id, file_type, series)
        )
    else:
        cursor.execute(
            "INSERT INTO user_cards (user_id, card_name, rarity, file_id, card_id, file_type, series, acq_source) VALUES (?,?,?,?,?,?,?,?)",
            (user_id, card_name, rarity, file_id, master_card_id, file_type, series, source)
        )


async def send_card_media(target, file_id: str, file_type: str = "photo", caption: str = "", parse_mode: str = "Markdown", reply_markup=None, chat_id=None):
    """
    Send a card as photo, video (with sound), or animation depending on file_type.
    target can be update.message (uses reply_*), or a bot object (uses send_*,
    in which case chat_id MUST be provided since bot.send_* has no implicit chat).
    Returns the sent Message object (callers needing message_id can use it).
    """
    kwargs = {"caption": caption, "parse_mode": parse_mode}
    if reply_markup:
        kwargs["reply_markup"] = reply_markup
    if chat_id is not None:
        kwargs["chat_id"] = chat_id

    ft = (file_type or "photo").lower()

    if ft == "video":
        if hasattr(target, "reply_video") and chat_id is None:
            return await target.reply_video(video=file_id, supports_streaming=True, **kwargs)
        else:
            return await target.send_video(video=file_id, supports_streaming=True, **kwargs)
    elif ft == "animation":
        if hasattr(target, "reply_animation") and chat_id is None:
            return await target.reply_animation(animation=file_id, **kwargs)
        else:
            return await target.send_animation(animation=file_id, **kwargs)
    else:
        if hasattr(target, "reply_photo") and chat_id is None:
            return await target.reply_photo(photo=file_id, **kwargs)
        else:
            return await target.send_photo(photo=file_id, **kwargs)


def weighted_random_card():
    # Never include Disc or Dragon in random/pack/daily draws — admin-only
    # FIX (Bug 1 - wrong card users showing in /find): this used to select only
    # (name, rarity, file_id) and let insert_user_card() re-derive the card's
    # database id afterwards by re-querying on those fields. Since multiple
    # card rows can legitimately share the same name+rarity (documented
    # elsewhere in this file, e.g. find_card's multi-match handling), that
    # re-lookup was ambiguous and could silently resolve to a DIFFERENT row
    # than the one actually drawn here — so /find <id> on the real card would
    # never show that user, while /find <id> on the wrong duplicate would show
    # someone who never actually got it. Selecting the row's own `id` here and
    # passing it straight through removes the ambiguity completely.
    cursor.execute(
        "SELECT id, name, rarity, file_id FROM cards WHERE rarity NOT IN ('Animation','LeaderBoard')"
    )
    cards = cursor.fetchall()
    if not cards:
        return None
    weighted = []
    for card in cards:
        rarity = card[2]
        weight = RARITY_WEIGHTS.get(rarity, 1)
        weighted.extend([card] * weight)
    if not weighted:
        return None
    return random.choice(weighted)


def get_spawn_range(chat_id):
    """Return (min, max) spawn range for a chat, using custom if set."""
    if chat_id in chat_spawn_settings:
        val = chat_spawn_settings[chat_id]
        low = max(1, val - 10)
        return (low, val)
    return (SPAWN_MIN_MESSAGES, SPAWN_MAX_MESSAGES)


def reset_spawn(chat_id):
    message_counter[chat_id] = 0
    mn, mx = get_spawn_range(chat_id)
    next_spawn[chat_id] = random.randint(mn, mx)
    current_card.pop(chat_id, None)
    spawn_time.pop(chat_id, None)
    print(f"[SPAWN] Next spawn in chat {chat_id} at message #{next_spawn[chat_id]}")

def _count_cards_rarity_sync(rarity):
    c = _get_thread_conn()
    row = c.execute("SELECT COUNT(*) FROM cards WHERE rarity=?", (rarity,)).fetchone()
    return int(row[0] if row else 0)


