# ================= SPAM =================

block_notified: dict = {}

def record_message(user_id: int):
    """Record a message timestamp for spam detection."""
    now = time.time()
    timestamps = user_messages[user_id]
    timestamps.append(now)
    while timestamps and now - timestamps[0] > SPAM_WINDOW:
        timestamps.popleft()
    if len(timestamps) > SPAM_LIMIT:
        blocked_users[user_id] = now + BLOCK_DURATION

def is_blocked(user_id: int) -> bool:
    """Check if user is currently muted."""
    now = time.time()
    if user_id in blocked_users:
        if now < blocked_users[user_id]:
            return True
        else:
            del blocked_users[user_id]
            block_notified.pop(user_id, None)
    return False

def is_spamming(user_id: int) -> bool:
    """Record message + check if blocked."""
    record_message(user_id)
    return is_blocked(user_id)


# ================= SPAWN =================

async def spawn_card(update, context, forced_rarity=None):
    chat_id = update.effective_chat.id

    # Pick rarity first so we can show its emoji immediately
    rarity = forced_rarity if forced_rarity else get_random_rarity()
    emoji = RARITY_EMOJI.get(rarity, "⭐")

    # Step 1: Send rarity emoji as a teaser
    try:
        msg = await context.bot.send_message(
            chat_id=chat_id,
            text=f"{emoji}"
        )
    except Exception as e:
        print(f"[SPAWN] Cannot send message (no permission?): {e}")
        msg = None

    if msg:
        try:
            await asyncio.sleep(0.8)
            await msg.edit_text(f"{emoji}\n🌫️ A strange presence is forming...")
            await asyncio.sleep(0.8)
            await msg.edit_text(f"{emoji}\n🔮 Summoning shinobi...")
            await asyncio.sleep(0.8)
        except Exception as e:
            print(f"[SPAWN] Edit error (non-fatal): {e}")

    cursor.execute(
        """
        SELECT id, name, rarity, file_id, COALESCE(series, 'Naruto'), COALESCE(file_type, 'photo')
        FROM cards
        WHERE rarity=?
          AND (series IS NULL OR series NOT IN ({}))
        ORDER BY RANDOM()
        LIMIT 1
        """.format(",".join("?" * len(COLLAB_ONLY_SERIES))),
        (rarity, *COLLAB_ONLY_SERIES)
    )
    card = cursor.fetchone()

    if not card:
        try:
            if msg:
                await msg.edit_text(f"❌ No shinobi found for rarity: {rarity}!")
            else:
                await context.bot.send_message(chat_id=chat_id, text=f"❌ No shinobi found for rarity: {rarity}!")
        except Exception:
            await context.bot.send_message(chat_id=chat_id, text=f"❌ No shinobi found for rarity: {rarity}!")
        return

    card_id, name, rarity_db, file_id, card_series, card_file_type = card
    emoji = RARITY_EMOJI.get(rarity_db, "⭐")

    # FIX (Bug 1 - wrong card users showing in /find): store the exact card
    # row id that was spawned, so catch() below can attribute the catch to
    # THIS row instead of re-searching by name+rarity+file_id afterwards
    # (which is ambiguous whenever duplicate name+rarity rows exist).
    current_card[chat_id] = (name, rarity_db, file_id, card_series, card_file_type, card_id)
    spawn_time[chat_id] = time.time()

    print(f"[SPAWN] '{name}' ({rarity_db}, {card_file_type}) spawned in chat {chat_id}")

    if msg:
        try:
            await msg.delete()
        except Exception:
            pass

    spawn_caption = (
        f"{emoji} ᴀ sʜɪɴᴏʙɪ ʜᴀs ᴀᴘᴘᴇᴀʀᴇᴅ!\n\n"
        f"{emoji} ʀᴀʀɪᴛʏ: {rarity_db}\n\n"
        "━━━━━━━━━━━━━━\n"
        "🎴 ᴀᴅᴅ ɪᴛ ᴛᴏ ʏᴏᴜʀ ᴄᴏʟʟᴇᴄᴛɪᴏɴ\n"
        "ʙʏ sᴇɴᴅɪɴɢ:\n"
        "/catch <shinobi name>"
    )

    # ── Send with the correct method based on the card's actual file type ────
    try:
        ft = (card_file_type or "photo").lower()
        if ft == "video":
            await context.bot.send_video(
                chat_id=chat_id, video=file_id, caption=spawn_caption, supports_streaming=True
            )
        elif ft == "animation":
            await context.bot.send_animation(
                chat_id=chat_id, animation=file_id, caption=spawn_caption
            )
        else:
            await context.bot.send_photo(
                chat_id=chat_id, photo=file_id, caption=spawn_caption
            )
    except Exception as e:
        print(f"[SPAWN] Failed to send media (file_type={card_file_type}) for '{name}': {e}")
        # Fallback: try each method in turn so a wrongly-tagged file_type still spawns
        sent_ok = False
        for fallback_method in (context.bot.send_photo, context.bot.send_animation, context.bot.send_video):
            try:
                kwarg_name = {
                    context.bot.send_photo: "photo",
                    context.bot.send_animation: "animation",
                    context.bot.send_video: "video",
                }[fallback_method]
                await fallback_method(chat_id=chat_id, **{kwarg_name: file_id}, caption=spawn_caption)
                sent_ok = True
                break
            except Exception:
                continue
        if not sent_ok:
            await context.bot.send_message(
                chat_id=chat_id,
                text=f"{spawn_caption}\n\n⚠️ _(media preview unavailable)_",
                parse_mode="Markdown"
            )


