async def list_cards(update, context):
    user_id = update.effective_user.id
    if not is_admin(user_id):
        await update.message.reply_text("❌ Only admins can use this command.")
        return

    cursor.execute("SELECT id, name, rarity FROM cards ORDER BY id")
    rows = cursor.fetchall()

    if not rows:
        await update.message.reply_text("📜 No cards in database yet!")
        return

    text = "📜 Available Shinobi Cards\n\n"
    for row in rows:
        card_id, name, rarity = row
        emoji = RARITY_EMOJI.get(rarity, "⭐")
        id_display = f"#{card_id}" if card_id is not None else "#NULL ⚠️"
        text += f"{id_display} | {emoji} | {name.title()} | {rarity}\n"

    await update.message.reply_text(text)


# ================= Redeem create =========
async def redeem_create(update, context):
    user_id = update.effective_user.id
    if not is_admin(user_id):
        await update.message.reply_text("❌ Only admins can create redeem codes.")
        return

    try:
        card_id = int(context.args[0])
        uses = int(context.args[1])
        if uses <= 0:
            raise ValueError
    except:
        await update.message.reply_text("Usage:\n/redeem_create <card_id> <uses>")
        return

    cursor.execute("SELECT name, rarity FROM cards WHERE id=?", (card_id,))
    card = cursor.fetchone()

    if not card:
        await update.message.reply_text("❌ Card not found.")
        return

    name, rarity = card
    code = "".join(random.choices(string.ascii_uppercase + string.digits, k=7))

    cursor.execute("""
        INSERT INTO redeem_codes (code, card_id, uses_left)
        VALUES (?, ?, ?)
    """, (code, card_id, uses))
    conn.commit()

    await update.message.reply_text(
        f"🎁 Redeem Code Created!\n\n"
        f"Code: {code}\n"
        f"Card: {name} ({rarity})\n"
        f"Uses: {uses}"
    )


# ================= Bug 3: Owner — view/remove active redeem codes =========
async def active_codes_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/activecodes — Owner-only. Lists every currently ACTIVE redeem code
    across all three redeem systems (coin codes, specific-card codes, and
    giveaway/rarity codes) so the owner can audit what's still redeemable."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not is_admin(user_id):
        await update.message.reply_text("❌ Only admins can use this command.")
        return

    lines = []

    # 1) Coin codes — active while uses_count < max_uses
    cursor.execute(
        "SELECT code, coins, COALESCE(max_uses,1), COALESCE(uses_count,0) "
        "FROM coin_redeem_codes WHERE COALESCE(uses_count,0) < COALESCE(max_uses,1)"
    )
    coin_rows = cursor.fetchall()
    if coin_rows:
        lines.append("🪙 *Coin Codes:*")
        for code, coins, max_uses, uses_count in coin_rows:
            lines.append(f"  • `{code}` — {coins} coins ({uses_count}/{max_uses} used)")

    # 2) Specific-card codes — active while uses_left > 0
    cursor.execute(
        "SELECT rc.code, rc.uses_left, c.name, c.rarity FROM redeem_codes rc "
        "LEFT JOIN cards c ON c.id = rc.card_id WHERE rc.uses_left > 0"
    )
    card_rows = cursor.fetchall()
    if card_rows:
        lines.append("\n🎴 *Card Codes:*")
        for code, uses_left, cname, crarity in card_rows:
            cname_disp = cname.title() if cname else "Unknown Card"
            lines.append(f"  • `{code}` — {cname_disp} [{crarity}] ({uses_left} uses left)")

    # 3) Giveaway/rarity codes — active flag + not exhausted
    cursor.execute(
        "SELECT code, rarity, series, max_uses, uses_count FROM giveaway_redeem_codes "
        "WHERE active=1 AND (max_uses IS NULL OR uses_count < max_uses)"
    )
    gv_rows = cursor.fetchall()
    if gv_rows:
        lines.append("\n🎉 *Giveaway Codes:*")
        for code, rarity, series, max_uses, uses_count in gv_rows:
            series_disp = f" ({series})" if series else ""
            uses_disp = f"{uses_count}/{max_uses}" if max_uses is not None else f"{uses_count}/∞"
            lines.append(f"  • `{code}` — {rarity}{series_disp} ({uses_disp} used)")

    if not lines:
        await update.message.reply_text("📭 There are no active redeem codes right now.")
        return

    text = "📋 *Active Redeem Codes*\n\n" + "\n".join(lines)
    text += "\n\n🗑️ Remove one with: `/delcode <code>`"

    # Telegram message limit safety — split if needed
    if len(text) <= 4000:
        await update.message.reply_text(text, parse_mode="Markdown")
    else:
        chunk = ""
        for part in text.split("\n"):
            if len(chunk) + len(part) + 1 > 3800:
                await update.message.reply_text(chunk, parse_mode="Markdown")
                chunk = ""
            chunk += part + "\n"
        if chunk:
            await update.message.reply_text(chunk, parse_mode="Markdown")


async def delete_code_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/delcode <code> — Owner-only. Deactivates/removes a redeem code from
    whichever of the three redeem systems it belongs to."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not is_admin(user_id):
        await update.message.reply_text("❌ Only admins can use this command.")
        return

    if not context.args:
        await update.message.reply_text("Usage:\n/delcode <code>")
        return

    code = context.args[0].strip().upper()
    removed_from = []

    cursor.execute("SELECT 1 FROM coin_redeem_codes WHERE code=?", (code,))
    if cursor.fetchone():
        cursor.execute("DELETE FROM coin_redeem_codes WHERE code=?", (code,))
        removed_from.append("Coin Code")

    cursor.execute("SELECT 1 FROM redeem_codes WHERE code=?", (code,))
    if cursor.fetchone():
        cursor.execute("DELETE FROM redeem_codes WHERE code=?", (code,))
        cursor.execute("DELETE FROM redeem_codes_user_log WHERE code=?", (code,))
        removed_from.append("Card Code")

    cursor.execute("SELECT 1 FROM giveaway_redeem_codes WHERE code=?", (code,))
    if cursor.fetchone():
        cursor.execute("UPDATE giveaway_redeem_codes SET active=0 WHERE code=?", (code,))
        removed_from.append("Giveaway Code")

    conn.commit()

    if not removed_from:
        await update.message.reply_text(f"❌ No active code found matching `{code}`.", parse_mode="Markdown")
        return

    await update.message.reply_text(
        f"✅ Code `{code}` removed/deactivated.\n📂 Type: {', '.join(removed_from)}",
        parse_mode="Markdown"
    )


# ── Giveaway redeem codes — random card from a specified rarity ──────────────
# Supports compound rarity tokens for collab series, e.g. ONEPIECE_SUMMER or
# BLEACH_SUMMER both mean rarity="Summer" with series filtered to that anime.
GIVEAWAY_RARITY_SERIES_MAP = {
    "ONEPIECE_SUMMER": ("Summer", "One Piece"),
    "ONE_PIECE_SUMMER": ("Summer", "One Piece"),
    "BLEACH_SUMMER": ("Summer", "Bleach"),
    "DEMONSLAYER_SUMMER": ("Summer", "Demon Slayer"),
    "DEMON_SLAYER_SUMMER": ("Summer", "Demon Slayer"),
}


def _parse_giveaway_rarity_token(token: str):
    """
    Parse a rarity token from /create_giveaway_code into (rarity, series).
    series is None for plain rarities (any series matches); a specific string
    for compound collab tokens like ONEPIECE_SUMMER.
    Returns (rarity, series) or (None, None) if the token isn't recognised.
    """
    upper = token.strip().upper().replace(" ", "_")
    if upper in GIVEAWAY_RARITY_SERIES_MAP:
        return GIVEAWAY_RARITY_SERIES_MAP[upper]
    # Plain rarity — normalise via the existing helper (handles FIFA etc.)
    plain = normalize_rarity(token.strip())
    if plain in RARITY_WEIGHTS:
        return (plain, None)
    return (None, None)


async def create_giveaway_code_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /create_giveaway_code <rarity> [code] [max_uses|unlimited] [message...]
    Owner-only. Creates a redeem code that gives a RANDOM card of the given
    rarity. Each user can redeem any given code exactly once, ever; the
    overall number of different users who can redeem it is unlimited unless
    you specify a max_uses number.

    Rarity can be a plain rarity name (FIFA, SPRING, SUMMER, MYTHIC, ...) or
    a collab-specific token: ONEPIECE_SUMMER, BLEACH_SUMMER, DEMONSLAYER_SUMMER.

    If [code] is omitted, a random 7-character code is generated.
    If [max_uses] is omitted or set to "unlimited", there is no cap on total
    redemptions across different users.
    Anything after that becomes an optional custom message shown to whoever
    redeems the code (omit it entirely for a plain copy-paste code with no
    extra message).

    Examples:
      /create_giveaway_code FIFA
      /create_giveaway_code FIFA SUMMERFEST2026
      /create_giveaway_code FIFA SUMMERFEST2026 unlimited
      /create_giveaway_code FIFA SUMMERFEST2026 500 Happy holidays from the team!
      /create_giveaway_code ONEPIECE_SUMMER STRAWHAT25 100
    """
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("❌ Only admins can create giveaway redeem codes.")
        return

    args = list(context.args or [])
    if not args:
        await update.message.reply_text(
            "📖 *Usage:*\n\n"
            "`/create_giveaway_code <rarity> [code] [max_uses|unlimited] [message...]`\n\n"
            "*Examples:*\n"
            "`/create_giveaway_code FIFA`\n"
            "`/create_giveaway_code FIFA SUMMERFEST2026`\n"
            "`/create_giveaway_code FIFA SUMMERFEST2026 unlimited`\n"
            "`/create_giveaway_code FIFA SUMMERFEST2026 500 Happy holidays!`\n"
            "`/create_giveaway_code ONEPIECE_SUMMER STRAWHAT25 100`\n\n"
            "*Collab tokens:* ONEPIECE_SUMMER, BLEACH_SUMMER, DEMONSLAYER_SUMMER\n"
            f"*Plain rarities:* {', '.join(RARITY_WEIGHTS.keys())}",
            parse_mode="Markdown"
        )
        return

    rarity, series = _parse_giveaway_rarity_token(args[0])
    if rarity is None:
        await update.message.reply_text(
            f"❌ Unknown rarity token: `{args[0]}`\n\n"
            f"*Collab tokens:* ONEPIECE_SUMMER, BLEACH_SUMMER, DEMONSLAYER_SUMMER\n"
            f"*Plain rarities:* {', '.join(RARITY_WEIGHTS.keys())}",
            parse_mode="Markdown"
        )
        return

    rest = args[1:]
    code = None
    max_uses = None
    message_parts = []

    if rest:
        # First remaining token is the code, UNLESS it looks like a number/"unlimited"
        # (covers the case where the owner skips the code and goes straight to max_uses).
        if rest[0].lower() == "unlimited" or rest[0].isdigit():
            pass  # no custom code given
        else:
            code = rest[0]
            rest = rest[1:]

    if rest:
        if rest[0].lower() == "unlimited":
            max_uses = None
            rest = rest[1:]
        elif rest[0].isdigit():
            max_uses = int(rest[0])
            if max_uses <= 0:
                await update.message.reply_text("❌ max_uses must be a positive number, or `unlimited`.")
                return
            rest = rest[1:]

    if rest:
        message_parts = rest

    if not code:
        code = "".join(random.choices(string.ascii_uppercase + string.digits, k=8))
    else:
        code = code.upper()

    custom_message = " ".join(message_parts) if message_parts else None

    cursor.execute("SELECT code FROM giveaway_redeem_codes WHERE code=?", (code,))
    if cursor.fetchone():
        await update.message.reply_text(f"❌ Code `{code}` already exists — pick a different one.", parse_mode="Markdown")
        return

    cursor.execute(
        "INSERT INTO giveaway_redeem_codes (code, rarity, series, message, max_uses, uses_count, created_by, created_at, active) "
        "VALUES (?,?,?,?,?,0,?,?,1)",
        (code, rarity, series, custom_message, max_uses, update.effective_user.id, int(time.time()))
    )
    conn.commit()

    rarity_display = f"{rarity} ({series})" if series else rarity
    uses_display = "Unlimited" if max_uses is None else str(max_uses)
    msg_display = custom_message if custom_message else "_(none — plain code)_"

    await update.message.reply_text(
        f"🎁 *Giveaway Redeem Code Created!*\n\n"
        f"Code: `{code}`\n"
        f"Rarity: *{rarity_display}*\n"
        f"Max Uses: *{uses_display}* _(per-user limit: 1 redemption, always)_\n"
        f"Message: {msg_display}\n\n"
        f"Players redeem with:\n`/redeem_code {code}`",
        parse_mode="Markdown"
    )


async def redeem_code_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /redeem_code <code> — Redeem a giveaway code for a random card of its
    configured rarity. Each user can redeem any given code exactly once.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    if not _redeem_allowed_here(update):
        await update.message.reply_text(REDEEM_WRONG_CHAT_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    if not context.args:
        await update.message.reply_text("Usage: `/redeem_code <code>`", parse_mode="Markdown")
        return

    code = context.args[0].strip().upper()

    cursor.execute(
        "SELECT rarity, series, message, max_uses, uses_count, active FROM giveaway_redeem_codes WHERE code=?",
        (code,)
    )
    row = cursor.fetchone()
    if not row:
        await update.message.reply_text(f"❌ Code `{code}` not found or invalid.", parse_mode="Markdown")
        return

    rarity, series, message, max_uses, uses_count, active = row
    if not active:
        await update.message.reply_text(f"❌ Code `{code}` has been deactivated.", parse_mode="Markdown")
        return
    if max_uses is not None and uses_count >= max_uses:
        await update.message.reply_text(f"❌ Code `{code}` has reached its maximum number of uses.", parse_mode="Markdown")
        return

    cursor.execute("SELECT 1 FROM giveaway_redeem_user_log WHERE code=? AND user_id=?", (code, user_id))
    if cursor.fetchone():
        await update.message.reply_text(f"❌ You've already redeemed `{code}` — each code can only be used once per account.", parse_mode="Markdown")
        return

    # ── Pick a random card matching the rarity (+series if specified) ─────────
    if series:
        cursor.execute(
            "SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards "
            "WHERE rarity=? AND series=? ORDER BY RANDOM() LIMIT 1",
            (rarity, series)
        )
    else:
        cursor.execute(
            "SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards "
            "WHERE rarity=? ORDER BY RANDOM() LIMIT 1",
            (rarity,)
        )
    card = cursor.fetchone()
    if not card:
        await update.message.reply_text(
            f"❌ No cards are currently available for this code's rarity. Please contact the owner.",
            parse_mode="Markdown"
        )
        return

    card_id, card_name, card_rarity, file_id, file_type = card

    # ── Grant the card and record the redemption ───────────────────────────────
    insert_user_card(user_id, card_name, card_rarity, file_id, file_type=file_type, card_id=card_id)
    cursor.execute(
        "INSERT OR IGNORE INTO giveaway_redeem_user_log (code, user_id, card_id, redeemed_at) VALUES (?,?,?,?)",
        (code, user_id, card_id, int(time.time()))
    )
    cursor.execute(
        "UPDATE giveaway_redeem_codes SET uses_count = uses_count + 1 WHERE code=?",
        (code,)
    )
    conn.commit()

    emoji = RARITY_EMOJI.get(card_rarity, "⭐")
    caption = (
        f"🎉 *Code Redeemed!*\n\n"
        f"{emoji} You received: *{card_name}* ({card_rarity})\n"
    )
    if message:
        caption += f"\n💬 _{message}_"

    try:
        await send_card_media(update.message, file_id, file_type=file_type, caption=caption, parse_mode="Markdown")
    except Exception:
        await update.message.reply_text(caption, parse_mode="Markdown")


def _redeem_allowed_here(update: Update) -> bool:
    """FIX (Issue 10): the Redeem feature (code/draft-code redemption) should
    only work in the bot's main chatting group — not in DMs, not in any other
    group, and not in channels. Admins are exempt so they can still test/
    troubleshoot codes anywhere."""
    if update.effective_user and is_admin(update.effective_user.id):
        return True
    return bool(update.effective_chat) and update.effective_chat.id == CHAT_GROUP_ID


REDEEM_WRONG_CHAT_MSG = (
    "🚫 *Redeem only works in the official chatting group!*\n\n"
    "Head over there to redeem your code. 👉 " + CHAT_GROUP_URL_FALLBACK
)


async def redeem_unified_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /redeem <code> — Unified redeem command. Transparently detects what kind
    of code was entered and handles it accordingly, so players only ever need
    to remember ONE command:
      1. Shinobi Coin codes      (coin_redeem_codes)       → /redeem_create
      2. Specific-card codes     (redeem_codes)             → /redeem_create (legacy)
      3. Giveaway rarity codes   (giveaway_redeem_codes)    → /create_giveaway_code

    This checks each code table in turn and dispatches to whichever one the
    code actually belongs to. The original per-type logic (redeem_cmd,
    redeem, redeem_code_cmd) is left fully intact and still directly callable
    — this just adds one shared entry point on top of them.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    if not _redeem_allowed_here(update):
        await update.message.reply_text(REDEEM_WRONG_CHAT_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    if not context.args:
        await update.message.reply_text(
            "❌ *Usage:* `/redeem <code>`\n\n"
            "Works for Coin codes, Card codes, and Giveaway codes — just enter the code!",
            parse_mode="Markdown"
        )
        return

    code = context.args[0].strip().upper()

    # ── 1. Giveaway rarity code? (most specific — check first) ────────────────
    cursor.execute("SELECT 1 FROM giveaway_redeem_codes WHERE code=?", (code,))
    if cursor.fetchone():
        await redeem_code_cmd(update, context)
        return

    # ── 2. Specific-card code? ──────────────────────────────────────────────────
    cursor.execute("SELECT 1 FROM redeem_codes WHERE code=?", (code,))
    if cursor.fetchone():
        await redeem(update, context)
        return

    # ── 3. Shinobi Coin code? ───────────────────────────────────────────────────
    cursor.execute("SELECT 1 FROM coin_redeem_codes WHERE code=?", (code,))
    if cursor.fetchone():
        await redeem_cmd(update, context)
        return

    # ── No match in any table ───────────────────────────────────────────────────
    await update.message.reply_text(
        "❌ *Invalid code!*\n\nDouble-check the code and try again.",
        parse_mode="Markdown"
    )


# ================== Redeem ================
async def redeem(update, context):
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    try:
        code = context.args[0].upper()
    except:
        await update.message.reply_text("Usage:\n/redeem <code>")
        return

    cursor.execute("SELECT card_id, uses_left FROM redeem_codes WHERE code=?", (code,))
    row = cursor.fetchone()

    if not row:
        await update.message.reply_text("❌ Invalid redeem code.")
        return

    card_id, uses_left = row

    if uses_left <= 0:
        await update.message.reply_text("❌ This code has expired.")
        return

    # FIX (Redeem Bug — per-user redemption check): the ONLY thing that used
    # to gate this code was the global uses_left counter, so the same user
    # could call /redeem repeatedly and use up a multi-use code entirely by
    # themselves. Each account may now redeem any given card code exactly once.
    cursor.execute(
        "SELECT 1 FROM redeem_codes_user_log WHERE code=? AND user_id=?",
        (code, user_id)
    )
    if cursor.fetchone():
        await update.message.reply_text(
            "⚠️ *You have already redeemed this code!*\n\nEach code can only be used once per account.",
            parse_mode="Markdown"
        )
        return

    cursor.execute("SELECT name, rarity, file_id, COALESCE(file_type,'photo') FROM cards WHERE id=?", (card_id,))
    card = cursor.fetchone()

    if not card:
        await update.message.reply_text("❌ Card not found.")
        return

    name, rarity, file_id, redeem_file_type = card

    insert_user_card(user_id, name, rarity, file_id, file_type=redeem_file_type, card_id=card_id)
    cursor.execute(
        "UPDATE redeem_codes SET uses_left=uses_left-1 WHERE code=?",
        (code,)
    )
    # Record that this user has now redeemed this code, so they can't do it again.
    cursor.execute(
        "INSERT OR IGNORE INTO redeem_codes_user_log (code, user_id, redeemed_at) VALUES (?,?,?)",
        (code, user_id, int(time.time()))
    )
    conn.commit()

    emoji = RARITY_EMOJI.get(rarity, "⭐")

    redeem_caption = (
        f"🎉 REDEEM SUCCESSFUL!\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🥷 Shinobi: {name.title()}\n"
        f"{emoji} Rarity: {rarity.title()}\n"
        f"🆔 Card ID: #{card_id}\n"
        f"📦 Added to your collection\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🔥 A new warrior joins your squad!"
    )

    redeem_ft = (redeem_file_type or "photo").lower()
    try:
        if redeem_ft == "video":
            await update.message.reply_video(video=file_id, caption=redeem_caption, supports_streaming=True)
        elif redeem_ft == "animation":
            await update.message.reply_animation(animation=file_id, caption=redeem_caption)
        else:
            await update.message.reply_photo(photo=file_id, caption=redeem_caption)
    except Exception as e:
        print(f"[REDEEM] Media send failed (file_type={redeem_file_type}): {e}")
        await update.message.reply_text(redeem_caption)


# ================= Favourite ==============
async def fav(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return

    user_id = update.effective_user.id

    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    if not context.args:
        await update.message.reply_text("Usage: /fav <card_id>")
        return

    try:
        card_id = int(context.args[0])
    except ValueError:
        await update.message.reply_text("❌ Invalid card ID")
        return

    # Look up by master card_id (the number shown in /collection), fallback to row id
    cursor.execute(
        "SELECT id, card_name, rarity, file_id, COALESCE(file_type,'photo') FROM user_cards WHERE card_id=? AND user_id=? LIMIT 1",
        (card_id, user_id),
    )
    row = cursor.fetchone()
    if not row:
        cursor.execute(
            "SELECT id, card_name, rarity, file_id, COALESCE(file_type,'photo') FROM user_cards WHERE id=? AND user_id=?",
            (card_id, user_id),
        )
        row = cursor.fetchone()

    if not row:
        await update.message.reply_text("❌ Card not found")
        return

    row_id, card_name, rarity, file_id, file_type = row

    fav_confirm[user_id] = row_id

    keyboard = [
        [
            InlineKeyboardButton("✅ Yes", callback_data=f"fav_yes_{row_id}_{user_id}"),
            InlineKeyboardButton("❌ No", callback_data=f"fav_no_{row_id}_{user_id}")
        ]
    ]
    await send_card_media(
        update.message, file_id, file_type,
        caption="⭐ Are you willing to set this as your favourite shinobi?",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )


# ================== Yes / No handler for fav =======
async def fav_button(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    data = query.data
    if not data.startswith("fav_"):
        return

    parts = data.split("_")
    action = parts[1]
    card_id = int(parts[2])
    user_id = int(parts[3])

    if query.from_user.id != user_id:
        await query.answer("❌ Not your action.", show_alert=True)
        return

    if action == "no":
        await query.edit_message_caption(caption="❌ Favourite selection cancelled.")
        return

    cursor.execute("UPDATE user_cards SET is_favorite=0 WHERE user_id=?", (user_id,))
    cursor.execute(
        "UPDATE user_cards SET is_favorite=1 WHERE id=? AND user_id=?",
        (card_id, user_id)
    )
    conn.commit()
    await query.edit_message_caption(caption="⭐ Favourite shinobi updated!")


# ================= GROUP-ADD VOUCHER REWARDS =================
# One-time reward (ever, per group) of Draft Vouchers to whoever adds the bot
# to a group, scaled by that group's member count. Re-adding the same group
# after removing the bot does NOT pay out again — instead it DMs the owner a
# warning naming the user and group, so repeated remove/re-add abuse is visible.

GROUP_ADD_REWARD_TIERS = [
    # FIX (Bug 4): lowered the first three tiers per owner request — everything
    # from the 31-50 tier upward is intentionally left exactly as it was.
    (1, 10, 5),
    (11, 20, 20),
    (21, 30, 30),
    (31, 50, 50),
    (51, 70, 70),
    (71, 100, 100),
    (101, 150, 150),
    (151, 250, 200),
    (251, float("inf"), 300),
]


def _group_add_voucher_amount(member_count: int) -> int:
    """Look up the voucher reward tier for a given member count."""
    for lo, hi, amount in GROUP_ADD_REWARD_TIERS:
        if lo <= member_count <= hi:
            return amount
    return GROUP_ADD_REWARD_TIERS[-1][2]  # fallback: top tier


async def handle_bot_added_to_group(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ChatMemberHandler (my_chat_member) — fires whenever THIS bot's own status
    changes in a chat (added, removed, promoted, etc). We only care about the
    transition into being a member/admin of a group/supergroup.
    """
    result = update.my_chat_member
    if not result or not result.chat:
        return
    chat = result.chat
    if chat.type not in ("group", "supergroup"):
        return

    old_status = result.old_chat_member.status if result.old_chat_member else None
    new_status = result.new_chat_member.status if result.new_chat_member else None

    # Only react to the bot actually JOINING (was not a member/admin before,
    # now is) — ignore promotions, demotions, and removals here entirely.
    was_in = old_status in ("member", "administrator")
    is_in_now = new_status in ("member", "administrator")
    if was_in or not is_in_now:
        return

    adder = result.from_user  # the user who performed the add action
    adder_id = adder.id if adder else None
    adder_name = (adder.first_name if adder else None) or "Unknown"
    adder_username = (adder.username if adder else None) or ""
    chat_id = chat.id
    chat_title = chat.title or "Unknown Group"

    # ── Already rewarded for this exact group before? ─────────────────────────
    cursor.execute("SELECT add_count, voucher_amount FROM group_add_rewards WHERE chat_id=?", (chat_id,))
    existing = cursor.fetchone()

    if existing:
        # This group has been added before — bump add_count, do NOT reward again,
        # and warn the owner this looks like remove/re-add farming.
        new_add_count = existing[0] + 1
        cursor.execute(
            "UPDATE group_add_rewards SET add_count=? WHERE chat_id=?",
            (new_add_count, chat_id)
        )
        conn.commit()
        try:
            adder_tag = f"@{adder_username}" if adder_username else f"`{adder_id}`"
            await context.bot.send_message(
                chat_id=OWNER_ID,
                text=(
                    f"⚠️ *Repeat Group Add Detected!*\n\n"
                    f"👤 User: *{adder_name}* ({adder_tag})\n"
                    f"🆔 User ID: `{adder_id}`\n"
                    f"👥 Group: *{chat_title}*\n"
                    f"🆔 Group ID: `{chat_id}`\n"
                    f"🔁 This group has now been added *{new_add_count}* times.\n\n"
                    f"No voucher reward was given — this group already received "
                    f"*{existing[1]} vouchers* previously. This may be remove/re-add farming."
                ),
                parse_mode="Markdown"
            )
        except Exception as e:
            print(f"[GROUP_ADD] Failed to notify owner of repeat add: {e}")
        return

    # ── First time this group has ever been added — log it (no reward) ────────
    # FIX (Bug 7): draft-voucher rewards for adding the bot to a group have
    # been removed per request. We still record the add (for /find-style
    # analytics and repeat-add detection above) and still notify the owner,
    # just without paying out any vouchers.
    try:
        member_count = await context.bot.get_chat_member_count(chat_id)
    except Exception as e:
        print(f"[GROUP_ADD] Could not get member count for {chat_id}: {e}")
        member_count = 1

    voucher_amount = 0

    cursor.execute(
        "INSERT OR IGNORE INTO group_add_rewards "
        "(chat_id, group_title, member_count, voucher_amount, added_by_user_id, added_by_name, rewarded_at, add_count) "
        "VALUES (?,?,?,?,?,?,?,1)",
        (chat_id, chat_title, member_count, voucher_amount, adder_id, adder_name, int(time.time()))
    )
    conn.commit()

    # Notify the owner for visibility (no DM/reward sent to the adder anymore)
    try:
        adder_tag = f"@{adder_username}" if adder_username else f"`{adder_id}`"
        await context.bot.send_message(
            chat_id=OWNER_ID,
            text=(
                f"🆕 *Bot Added to New Group!*\n\n"
                f"👤 Added by: *{adder_name}* ({adder_tag})\n"
                f"🆔 User ID: `{adder_id}`\n"
                f"👥 Group: *{chat_title}*\n"
                f"🆔 Group ID: `{chat_id}`\n"
                f"📊 Members: *{member_count}*"
            ),
            parse_mode="Markdown"
        )
    except Exception as e:
        print(f"[GROUP_ADD] Failed to notify owner of new add: {e}")


# ================= TRACKER =================

async def message_tracker(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_chat or not update.effective_user or not update.message:
        return

    # ── Guard against fake "users" that aren't real people ────────────────────
    # 1087968824 is Telegram's fixed system ID for "GroupAnonymousBot" — the
    # sender shown whenever a group admin posts anonymously. It is NOT a real
    # account and was previously slipping through here, getting registered in
    # bot_users and sometimes even granted the welcome bonus / "New User
    # Joined" notification, even though nobody actually joined.
    # update.effective_user.is_bot also catches any other bot account
    # (including this bot itself in odd edge cases, and other bots in the chat).
    if update.effective_user.id == 1087968824 or update.effective_user.is_bot:
        return

    # Bot-wide OFF / DB-not-ready lock: silently ignore plain-text activity
    # (catches, spawn counting, conv-log/bot_users registration) for
    # non-admins. No reply here (unlike commands) to avoid spamming a busy
    # group with "bot is off" on every single message.
    if not is_admin(update.effective_user.id) and (not is_bot_enabled() or not is_db_ready()):
        return

    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    user_name = update.effective_user.first_name or "Unknown"

    # Log conversation to DB
    # PERF FIX: this used to run cursor.execute()+conn.commit() directly on the
    # asyncio event loop for EVERY message (busy groups = 10s-100s commits/sec,
    # each one blocking every other update from being processed). Moved to the
    # existing _db_executor thread pool via _db_run() — fire-and-forget (not
    # awaited) so the event loop never waits on it. A failed/slow write here
    # only delays the log, it can no longer stall the whole bot.
    msg_text = update.message.text or update.message.caption or ""
    if msg_text and chat_id != LOG_GROUP_ID:
        _uname = update.effective_user.username or ""
        def _write_conv_log(_uid=user_id, _uname=_uname, _fname=user_name, _text=msg_text[:500], _ts=int(time.time())):
            try:
                _c = _get_thread_conn()
                _c.execute(
                    "INSERT INTO conv_logs (user_id, username, first_name, message_text, timestamp) VALUES (?,?,?,?,?)",
                    (_uid, _uname, _fname, _text, _ts)
                )
                _c.commit()
            except Exception:
                pass
        _schedule_db_background(_write_conv_log, label="conv-log")

    # Register user in bot_users for broadcast (silent, non-blocking)
    # PERF FIX: same issue as above — this ran a synchronous SQLite
    # INSERT/COMMIT plus an *unawaited synchronous* MongoDB network call
    # directly on the event loop for every single message. Both are now
    # offloaded to the DB thread pool so a slow/stuck Mongo connection can
    # no longer freeze Telegram update processing for everyone.
    try:
        # FIX (Bug 3): this used to be "ON CONFLICT(user_id) DO NOTHING", which
        # writes the row ONCE on a user's very first message and then never
        # touches first_name/username again. /start already refreshes these on
        # every run (DO UPDATE SET ...), but most users only ever run /start
        # once — every regular message after that went through THIS path,
        # which silently froze their name forever at whatever it was on day
        # one. That's exactly "user changes their Telegram name but the bot
        # still shows the old name everywhere" — everywhere being every
        # display that reads first_name from bot_users (e.g. /find holders,
        # leaderboards, admin lookups). Refreshing here too means a name
        # change shows up the moment the user sends their next message,
        # in a group or in DM, not only after they re-run /start.
        _uname2 = update.effective_user.username or ""
        def _write_bot_user(_uid=user_id, _fname=user_name, _uname=_uname2, _ts=int(time.time())):
            try:
                _c = _get_thread_conn()
                _c.execute("""
                    INSERT INTO bot_users (user_id, first_name, username, joined_at)
                    VALUES (?, ?, ?, ?)
                    ON CONFLICT(user_id) DO UPDATE SET
                        first_name = excluded.first_name,
                        username = excluded.username
                """, (_uid, _fname, _uname, _ts))
                _c.commit()
            except Exception:
                pass
            # Also register in MongoDB — this is a network call and must never
            # run on the asyncio event loop thread; it now runs here, in the
            # DB thread pool, alongside the SQLite write.
            if MONGO_AVAILABLE:
                try:
                    register_user_mongo(_uid, _fname, _uname)
                except Exception:
                    pass
        _schedule_db_background(_write_bot_user, label="bot-user")
    except Exception:
        pass

    # ── Feature 4 & 5: First-time user bonus + log notification ──────────
    # NOTE: this used to key off "is this user new in bot_users", but start()
    # already inserts the user into bot_users BEFORE the join/verify gate runs,
    # so by the time this handler ran for a DM user the row always already
    # existed and the bonus never fired. grant_welcome_bonus_if_new() tracks
    # eligibility separately (welcome_bonus_given table) so it works correctly
    # regardless of bot_users timing, and is safe to call from multiple places
    # since it only ever pays out once per user.
    # IMPORTANT: plain-text DM messages aren't covered by the command-only
    # verify gate (require_dm_start), so we must NOT grant the bonus here for
    # an unverified DM user — only for group messages (no gate there) or DM
    # messages from a user who is actually verified/admin already.
    _chat_type = update.effective_chat.type if update.effective_chat else "private"
    _is_group_msg = _chat_type in ("group", "supergroup")
    if _is_group_msg or is_verified_user(user_id):
        bonus_just_granted = grant_welcome_bonus_if_new(user_id)
    else:
        bonus_just_granted = False
    if bonus_just_granted:
        try:
            # Notify logs group
            cursor.execute("SELECT COUNT(*) FROM bot_users")
            total_users = cursor.fetchone()[0]
            uname_str = update.effective_user.username or "N/A"
            await log_to_group(
                context.bot,
                f"🆕 *New User Joined!*\n\n"
                f"👤 Name: *{user_name}*\n"
                f"🆔 User ID: `{user_id}`\n"
                f"📛 Username: @{uname_str}\n"
                f"👥 Total users: *{total_users}*\n\n"
                f"🎁 Welcome bonus sent: *{WELCOME_BONUS_VOUCHERS} vouchers + {WELCOME_BONUS_COINS:,} coins*"
            )
        except Exception:
            pass

    # Register group in bot_groups for group broadcast (silent, non-blocking)
    # PERF FIX: offloaded to the DB thread pool, same reasoning as above.
    try:
        chat_type = update.effective_chat.type if update.effective_chat else "private"
        if chat_type in ("group", "supergroup"):
            group_title = update.effective_chat.title or ""
            def _write_bot_group(_cid=chat_id, _title=group_title, _ts=int(time.time())):
                try:
                    _c = _get_thread_conn()
                    _c.execute("""
                        INSERT INTO bot_groups (chat_id, title, last_seen)
                        VALUES (?, ?, ?)
                        ON CONFLICT(chat_id) DO UPDATE SET title=excluded.title, last_seen=excluded.last_seen
                    """, (_cid, _title, _ts))
                    _c.commit()
                except Exception:
                    pass
            _schedule_db_background(_write_bot_group, label="bot-group")
    except Exception:
        pass

    # Ban check — show ban message once then ignore
    if is_banned(user_id):
        if user_id not in block_notified:
            block_notified[user_id] = True
            try:
                await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
            except Exception:
                pass
        return

    # Commands are already recorded by require_dm_start (group=-1, runs first);
    # only record plain-text messages here to avoid double-counting the same
    # message twice toward the spam threshold.
    _msg_is_command = bool(update.message.text and update.message.text.startswith("/"))
    if not _msg_is_command:
        record_message(user_id)

    if is_blocked(user_id):
        if user_id not in block_notified:
            block_notified[user_id] = True
            remaining = int(blocked_users[user_id] - time.time())
            mins = remaining // 60
            secs = remaining % 60
            await update.message.reply_text(
                f"🚫 *Spam Detected!*\n\n"
                f"⛔ You have been muted for sending too many messages.\n"
                f"⏳ Cooldown: *{mins}m {secs}s* remaining.\n\n"
                f"🧘 Take a breath, shinobi. Come back when you're ready.",
                parse_mode="Markdown"
            )
        return

    message_counter[chat_id] += 1
    total_message_counter[chat_id] += 1
    total = total_message_counter[chat_id]
    chat_last_active[chat_id] = time.time()  # for recurring-quiz activity gate
    _LAST_UPDATE_TS["ts"] = time.time()  # heartbeat diagnostic: last time we saw ANY update
    if total % 10 == 0:
        # PERF FIX: was a synchronous cursor.execute()+conn.commit() directly
        # on the event loop every 10th message. Offloaded to the DB thread pool.
        _schedule_milestone_save(chat_id)
    # PERF FIX: this printed one line to stdout for EVERY single message across
    # every group the bot is in. On a busy multi-group bot that's a lot of
    # blocking stdout I/O (see the flooded Stackhost log in the screenshots),
    # and it drowns out the log lines that actually matter ([SPAWN], [ERROR],
    # [NET], [BACKUP], etc). Gated behind DEBUG now — set DEBUG=1 in the env
    # to get this back for troubleshooting.
    if DEBUG:
        print(f"[MSG] Chat {chat_id} | User: {user_name}({user_id}) | {message_counter[chat_id]} / {next_spawn[chat_id]} | Total: {total}")

    if chat_id in current_card:
        if time.time() - spawn_time.get(chat_id, 0) > ENCOUNTER_DURATION:
            try:
                await update.message.reply_text("💨 The shinobi escaped!")
            except Exception:
                pass  # Bot may not have send rights — silently skip
            reset_spawn(chat_id)
            return

    if chat_id not in current_card:
        # Special 🔮 rarity — spawns every 500 messages per group (under 500 msg cycle)
        if total % 500 == 0 and total > 0:
            special_count = await _db_run(_count_cards_rarity_sync, "Special")
            if special_count > 0:
                print(f"[SPECIAL] 🔮 Special spawn at msg #{total} in chat {chat_id}!")
                message_counter[chat_id] = 0
                mn, mx = get_spawn_range(chat_id)
                next_spawn[chat_id] = random.randint(mn, mx)
                await spawn_card(update, context, forced_rarity="Special")
                return

        # Check milestone first — overrides normal spawn
        milestone = get_milestone_rarity(chat_id, total)
        if milestone:
            print(f"[MILESTONE] {milestone} guaranteed spawn at total msg #{total} in chat {chat_id}!")
            message_counter[chat_id] = 0
            mn, mx = get_spawn_range(chat_id)
            next_spawn[chat_id] = random.randint(mn, mx)
            await _db_run(_save_milestone_state, chat_id)
            await spawn_card(update, context, forced_rarity=milestone)
        elif message_counter[chat_id] >= next_spawn[chat_id]:
            print(f"[SPAWN] Threshold reached in chat {chat_id}! Spawning...")
            message_counter[chat_id] = 0
            mn, mx = get_spawn_range(chat_id)
            next_spawn[chat_id] = random.randint(mn, mx)
            print(f"[SPAWN] Next spawn at message #{next_spawn[chat_id]}")
            await spawn_card(update, context)


