# ================= CATCH =================

async def catch(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_chat or not update.effective_user or not update.message:
        return

    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    now = time.time()

    # ── Must have started bot in DM first ────────────────────────────────────
    if not has_started_bot(user_id) and not is_admin(user_id):
        try:
            await update.message.reply_text(
                NOT_STARTED_MSG,
                parse_mode="Markdown",
                disable_web_page_preview=True
            )
        except Exception:
            pass
        return

    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    # Block banned users (duplicate safety check removed below)

    # Block muted users from catching
    if is_blocked(user_id):
        remaining = int(blocked_users[user_id] - now)
        mins = remaining // 60
        secs = remaining % 60
        await update.message.reply_text(
            f"🚫 *You are muted!*\n\n"
            f"⛔ Spammers cannot catch shinobi.\n"
            f"⏳ Your mute expires in: *{mins}m {secs}s*\n\n"
            f"😤 Serve your time, then return to battle.",
            parse_mode="Markdown"
        )
        return

    if user_id in last_guess_time:
        if now - last_guess_time[user_id] < GUESS_COOLDOWN:
            await update.message.reply_text("⏳ Wait before guessing again.")
            return

    last_guess_time[user_id] = now

    card = current_card.get(chat_id)
    if not card:
        await update.message.reply_text("❌ No active encounter.")
        return

    if not context.args:
        await update.message.reply_text("Usage: /catch <n>")
        return

    guess = normalize(" ".join(context.args))
    name, rarity, file_id, card_series, card_file_type, master_card_id = card
    real_name = normalize(name)

    if (
        guess == real_name
        or guess in real_name.split()
        or real_name.split()[0] in guess
    ):
        # ══════════════════════════════════════════════════════════════════
        # FIX (Bugs 2 & 3 — duplicate catches / stale "you got it" replies):
        # Claim the encounter IMMEDIATELY and atomically, before doing any
        # DB writes or awaiting anything. Previously the card wasn't removed
        # from current_card until AFTER the reply_photo/video/animation call
        # further below — and that call is the FIRST `await` in this whole
        # branch. Since python-telegram-bot runs every incoming update as
        # its own asyncio task, as soon as this task hit that first await,
        # the event loop was free to run OTHER users' /catch calls for the
        # same chat. Those other calls still saw the card sitting in
        # current_card (it hadn't been popped yet), matched the same guess,
        # and also got awarded the card + coins + Ryo — the exact "many
        # people catch the same card" bug that was reported.
        #
        # dict.pop() is a single atomic operation with no `await` inside
        # it, so whichever /catch call reaches this line first is
        # guaranteed to be the ONLY one that can ever succeed for this
        # encounter — every later call (even one that also guessed
        # correctly) will find nothing left to claim and gets a clean
        # "no active encounter" reply instead of a false "you caught it!".
        # ══════════════════════════════════════════════════════════════════
        claimed_card = current_card.pop(chat_id, None)
        if claimed_card != card:
            # Someone else already claimed this exact encounter a moment
            # before us — nothing left here to catch.
            if claimed_card is not None:
                # Not ours to take — put back whatever the actual winner's
                # encounter left behind (defensive; should not normally
                # happen, but we must never silently eat someone else's
                # still-valid encounter).
                current_card[chat_id] = claimed_card
            await update.message.reply_text(
                "❌ No active encounter — someone already caught this shinobi!"
            )
            return
        # Capture the spawn timestamp BEFORE popping it, so "time taken"
        # below still reflects how long the encounter was actually up for
        # (it used to read this after reset_spawn() cleared it — now that
        # we clear it immediately as part of claiming, we must grab it here
        # first or it would always show ~0s).
        encounter_started_at = spawn_time.pop(chat_id, now)

        # FIX (Bug 1 - wrong card users showing in /find): master_card_id now
        # comes straight from the exact row spawn_card() picked, instead of
        # being re-derived here by searching name+rarity+file_id (which could
        # resolve to a different duplicate row and misattribute the catch).
        #
        # FIX (catch feels slow): the SQLite write itself is cheap, but when
        # MongoDB syncing is enabled, insert_user_card() also performs a
        # *blocking* network write to Mongo on the same thread as the bot's
        # event loop. That freezes EVERY chat/user in the entire bot for
        # however long that network round-trip takes — which is exactly
        # what made /catch (and everything else) feel slow. We already own
        # this encounter (claimed above), so it's safe to push that write to
        # a worker thread instead: the user still gets an instant reply and
        # nobody else's /catch, /daily, spawns, etc. are blocked waiting on
        # Mongo.
        try:
            await asyncio.to_thread(
                insert_user_card, user_id, name, rarity, file_id,
                file_type=card_file_type, card_id=master_card_id
            )
            conn.commit()
        except Exception as e:
            print(f"[CATCH] insert_user_card failed: {e}")

        # ── Award Shinobi Coins for catching ────────────────────────────────
        coin_reward = RARITY_COINS.get(rarity, 0)
        if coin_reward > 0:
            add_coins(user_id, coin_reward)
        new_coins = get_coins(user_id)

        # ── Award Ryo 🪙 for catching (Bug 8) ────────────────────────────────
        ryo_reward = RARITY_RYO.get(rarity, 0)
        if ryo_reward > 0:
            add_ryo(user_id, ryo_reward)

        taken_time = int(time.time() - encounter_started_at)
        emoji = RARITY_EMOJI.get(rarity, "⭐")
        user_name = update.effective_user.first_name or "Shinobi"
        # Note: this caption is sent WITHOUT parse_mode (plain text), so no
        # Markdown-escaping is needed here — unlike /ryo, /top_ryo, etc.
        # which explicitly set parse_mode="Markdown" and therefore do need
        # safe_name() (see Bug 5 fix above).

        coin_line = f"🪙 *+{coin_reward} Shinobi Coins!* (Total: {new_coins})\n" if coin_reward > 0 else ""
        ryo_line = f"🪙 *+{ryo_reward} Ryo!*\n" if ryo_reward > 0 else ""

        # Source label: show the card's real anime series instead of always "Naruto Classic"
        source_label = "Naruto Classic" if card_series == "Naruto" else card_series

        text = (
            f"✅ {user_name}, you got a new shinobi!\n\n"
            f"🌸 𝗡𝗔𝗠𝗘: {name.title()} [{emoji}]\n"
            f"🔮 𝗥𝗔𝗥𝗜𝗧𝗬: {rarity}\n"
            f"❇️ 𝗦𝗢𝗨𝗥𝗖𝗘: {source_label}\n\n"
            f"{coin_line}"
            f"{ryo_line}"
            f"⌛ 𝗧𝗜𝗠𝗘 𝗧𝗔𝗞𝗘𝗡: {taken_time}s"
        )

        # ── Send with the correct media type ────────────────────────────────
        ft = (card_file_type or "photo").lower()
        try:
            if ft == "video":
                await update.message.reply_video(video=file_id, caption=text, supports_streaming=True)
            elif ft == "animation":
                await update.message.reply_animation(animation=file_id, caption=text)
            else:
                await update.message.reply_photo(photo=file_id, caption=text)
        except Exception as e:
            print(f"[CATCH] Media send failed (file_type={card_file_type}): {e}")
            try:
                await update.message.reply_text(text)
            except Exception:
                pass
        reset_spawn(chat_id)

        # Log to catch channel
        await log_catch(
            context.bot,
            f"🎴 *Card Caught!*\n\n"
            f"👤 Shinobi: {user_name} (`{user_id}`)\n"
            f"🥷 Card: {name.title()}\n"
            f"{RARITY_EMOJI.get(rarity, '⭐')} Rarity: {rarity}\n"
            f"⌛ Time taken: {taken_time}s\n"
            f"💬 Chat: `{chat_id}`",
            photo_file_id=file_id
        )

    else:
        await update.message.reply_text("❌ Wrong guess! Try again.")


# ================= DAILY =================

async def daily(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    now = int(time.time())

    # ── Reset window: 5:30 AM IST = 00:00 UTC (IST is UTC+5:30) ──────────────
    # Calculate the most recent 5:30 AM IST in UTC epoch
    IST_OFFSET = 5 * 3600 + 30 * 60  # 19800 seconds
    now_ist_seconds = now + IST_OFFSET
    # Seconds since midnight IST today
    seconds_since_midnight_ist = now_ist_seconds % 86400
    # 5:30 AM IST in seconds = 5*3600 + 30*60 = 19800
    RESET_SECONDS = 5 * 3600 + 30 * 60
    if seconds_since_midnight_ist >= RESET_SECONDS:
        # Today's reset was at RESET_SECONDS past midnight IST
        today_reset_epoch = now - (seconds_since_midnight_ist - RESET_SECONDS)
    else:
        # Today's reset hasn't happened yet; use yesterday's
        today_reset_epoch = now - (seconds_since_midnight_ist + 86400 - RESET_SECONDS)

    cursor.execute("SELECT last_daily FROM users WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    last_daily = row[0] if row and row[0] else 0

    if last_daily >= today_reset_epoch:
        # Already claimed since today's 5:30 AM IST reset
        next_reset = today_reset_epoch + 86400
        remaining = next_reset - now
        hours = remaining // 3600
        minutes = (remaining % 3600) // 60
        await update.message.reply_text(
            f"⏳ *Daily Reward Already Claimed!*\n\n"
            f"🕐 Resets at *5:30 AM* daily.\n"
            f"⏱️ Next reset in: *{hours}h {minutes}m*\n\n"
            f"🍃 Rest now, shinobi. Your next reward awaits!",
            parse_mode="Markdown"
        )
        return

    card = weighted_random_card()
    if not card:
        await update.message.reply_text("❌ No cards available yet. Ask the admin to add some!")
        return

    card_id, name, rarity, file_id = card
    emoji = RARITY_EMOJI.get(rarity, "⭐")
    user_name = update.effective_user.first_name or "Shinobi"

    insert_user_card(user_id, name, rarity, file_id, card_id=card_id)
    cursor.execute(
        "INSERT OR REPLACE INTO users (user_id, last_daily, pack_today, last_pack_day) "
        "VALUES (?, ?, COALESCE((SELECT pack_today FROM users WHERE user_id=?), 0), "
        "COALESCE((SELECT last_pack_day FROM users WHERE user_id=?), 0))",
        (user_id, now, user_id, user_id),
    )
    conn.commit()

    # Give 5 draft vouchers with daily
    add_vouchers(user_id, 5)
    add_coins(user_id, COIN_DAILY_AMOUNT)
    add_ryo(user_id, RYO_DAILY_AMOUNT)  # Bug 8: +5000 Ryo daily
    conn.commit()
    current_vouchers = get_user_vouchers(user_id)
    current_coins = get_coins(user_id)
    current_ryo = get_ryo(user_id)

    await update.message.reply_photo(
        photo=file_id,
        caption=(
            f"🎁 𝗗𝗔𝗜𝗟𝗬 𝗥𝗘𝗪𝗔𝗥𝗗!\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"👤 Shinobi: {user_name}\n"
            f"🥷 𝗡𝗔𝗠𝗘: {name.title()}\n"
            f"{emoji} 𝗥𝗔𝗥𝗜𝗧𝗬: {rarity}\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🎟️ +5 Draft Vouchers! (Total: {current_vouchers})\n"
            f"🪙 +{COIN_DAILY_AMOUNT} Shinobi Coins! (Total: {current_coins})\n"
            f"🪙 +{RYO_DAILY_AMOUNT} Ryo! (Total: {current_ryo})\n"
            f"🔥 A new warrior joins your squad!\n"
            f"📅 Resets at *5:30 AM* daily!"
        )
    )


# ================= PACK =================

