# ================= DATABASE-READY LOCK =================

async def live_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner/admin confirms the live database is complete and correct (either
    a fresh setup with no restore needed, or right after a manual /restore).
    Opens the bot back up to everyone."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admins only.")
        return
    panel_set("db_ready", "1")
    await update.message.reply_text(
        "✅ Database marked as *ready*. The bot is now open to all users again.",
        parse_mode="Markdown"
    )
    await log_to_group(context.bot, f"✅ *DB marked live* by {update.effective_user.first_name} (`{update.effective_user.id}`)")


async def lock_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Manually re-lock the bot (e.g. right before taking the host down for
    a redeploy) so nobody can /start and get a fresh 0-collection row while
    the database is in flux. Run /live (or /restore) to reopen."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admins only.")
        return
    panel_set("db_ready", "0")
    await update.message.reply_text(
        "🔒 Database marked as *not ready*. The bot will refuse all non-admin commands "
        "until you run /live or /restore.",
        parse_mode="Markdown"
    )
    await log_to_group(context.bot, f"🔒 *DB locked* by {update.effective_user.first_name} (`{update.effective_user.id}`)")


async def broadcast(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admins only.")
        return

    # ── Determine message content ─────────────────────────────────────────────
    msg_text = ""
    photo_file_id = None

    # Check if replying to a photo (with or without caption)
    if update.message.reply_to_message:
        replied = update.message.reply_to_message
        if replied.photo:
            photo_file_id = replied.photo[-1].file_id
            # Caption from the reply or from args
            if context.args:
                msg_text = " ".join(context.args)
            elif replied.caption:
                msg_text = replied.caption
        elif replied.text:
            msg_text = replied.text
    else:
        # No reply — must have args as text
        if context.args:
            msg_text = " ".join(context.args)

    # If this message itself is a photo with caption /broadcast
    if not photo_file_id and update.message.photo:
        photo_file_id = update.message.photo[-1].file_id
        msg_text = update.message.caption or msg_text

    if not msg_text and not photo_file_id:
        await update.message.reply_text(
            "❌ Please provide a message or reply to an image.\n\n"
            "Usage:\n"
            "• `/broadcast <text>` — text broadcast\n"
            "• Reply to an image with `/broadcast <caption>` — image broadcast\n"
            "• Reply to an image with `/broadcast` — broadcast image with its caption",
            parse_mode="Markdown"
        )
        return

    # ── Collect ALL users: bot_users + user_cards (union so no one is missed) ──
    cursor.execute("SELECT DISTINCT user_id FROM bot_users")
    users_set = set(r[0] for r in cursor.fetchall())
    cursor.execute("SELECT DISTINCT user_id FROM user_cards")
    users_set.update(r[0] for r in cursor.fetchall())
    users = list(users_set)

    # ── Collect all registered groups ──────────────────────────────────────────
    cursor.execute("SELECT chat_id FROM bot_groups")
    groups = [r[0] for r in cursor.fetchall()]

    await update.message.reply_text(
        f"📢 *Broadcasting to {len(users)} users + {len(groups)} groups...*\n"
        f"{'🖼️ With image' if photo_file_id else '📝 Text only'}",
        parse_mode="Markdown"
    )

    sent = 0
    failed = 0
    blocked = 0
    groups_sent = 0
    groups_failed = 0

    broadcast_caption = f"📢 *Announcement*\n\n{msg_text}" if msg_text else "📢 *Announcement*"

    # ── Send to individual users ───────────────────────────────────────────────
    for uid in users:
        try:
            if photo_file_id:
                await context.bot.send_photo(
                    chat_id=uid,
                    photo=photo_file_id,
                    caption=broadcast_caption,
                    parse_mode="Markdown"
                )
            else:
                await context.bot.send_message(
                    chat_id=uid,
                    text=broadcast_caption,
                    parse_mode="Markdown"
                )
            sent += 1
            await asyncio.sleep(0.05)  # Avoid Telegram flood limit
        except Exception as e:
            err = str(e).lower()
            if "blocked" in err or "deactivated" in err or "not found" in err or "forbidden" in err:
                blocked += 1
                # Remove permanently blocked users from bot_users to keep list clean
                cursor.execute("DELETE FROM bot_users WHERE user_id=?", (uid,))
                conn.commit()
            elif "can't parse entities" in err or "parse" in err:
                # Markdown formatting broke on this message — retry as plain text, no parse_mode
                try:
                    if photo_file_id:
                        await context.bot.send_photo(chat_id=uid, photo=photo_file_id, caption=broadcast_caption)
                    else:
                        await context.bot.send_message(chat_id=uid, text=broadcast_caption)
                    sent += 1
                except Exception as e2:
                    failed += 1
                    print(f"[BROADCAST] Plain-text retry failed uid={uid}: {e2}")
                await asyncio.sleep(0.05)
            else:
                failed += 1
                print(f"[BROADCAST] Failed uid={uid}: {e}")

    # ── Send to groups ─────────────────────────────────────────────────────────
    for gid in groups:
        try:
            if photo_file_id:
                await context.bot.send_photo(
                    chat_id=gid,
                    photo=photo_file_id,
                    caption=broadcast_caption,
                    parse_mode="Markdown"
                )
            else:
                await context.bot.send_message(
                    chat_id=gid,
                    text=broadcast_caption,
                    parse_mode="Markdown"
                )
            groups_sent += 1
            await asyncio.sleep(0.05)
        except Exception as e:
            err = str(e).lower()
            if "kicked" in err or "not a member" in err or "chat not found" in err or "forbidden" in err or "deactivated" in err:
                groups_failed += 1
                # Remove groups where bot was kicked / no longer present
                cursor.execute("DELETE FROM bot_groups WHERE chat_id=?", (gid,))
                conn.commit()
            elif "can't parse entities" in err or "parse" in err:
                # Markdown formatting broke on this message — retry as plain text, no parse_mode
                try:
                    if photo_file_id:
                        await context.bot.send_photo(chat_id=gid, photo=photo_file_id, caption=broadcast_caption)
                    else:
                        await context.bot.send_message(chat_id=gid, text=broadcast_caption)
                    groups_sent += 1
                except Exception as e2:
                    groups_failed += 1
                    print(f"[BROADCAST] Plain-text retry failed group gid={gid}: {e2}")
                await asyncio.sleep(0.05)
            else:
                groups_failed += 1
                print(f"[BROADCAST] Failed group gid={gid}: {e}")

    await update.message.reply_text(
        f"✅ *Broadcast Complete!*\n\n"
        f"👤 *Users:* Sent: *{sent}* | 🚫 Blocked: *{blocked}* | ❌ Errors: *{failed}*\n"
        f"👥 *Groups:* Sent: *{groups_sent}* | ❌ Failed/Removed: *{groups_failed}*",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"📢 *Broadcast Sent*\n\n"
        f"📝 Message: {msg_text[:200] if msg_text else '(image only)'}\n"
        f"🖼️ Image: {'Yes' if photo_file_id else 'No'}\n"
        f"👤 Users: Sent {sent} | 🚫 Blocked {blocked} | ❌ Errors {failed}\n"
        f"👥 Groups: Sent {groups_sent} | ❌ Failed {groups_failed}\n"
        f"👤 By: {update.effective_user.first_name} (`{update.effective_user.id}`)"
    )


async def ban(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Permanent ban — no expiry. Use /tban for temporary ban."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admins only.")
        return
    target_id = None
    target_name = "Unknown"
    if update.message.reply_to_message:
        target_id = update.message.reply_to_message.from_user.id
        target_name = update.message.reply_to_message.from_user.first_name or str(target_id)
    elif context.args:
        try:
            target_id = int(context.args[0])
            target_name = str(target_id)
        except ValueError:
            await update.message.reply_text("❌ Invalid user ID.")
            return
    if not target_id:
        await update.message.reply_text("Usage: /ban <user_id> [reason] OR reply to a user.")
        return
    if target_id in (OWNER_ID, CO_OWNER_ID):
        await update.message.reply_text("❌ Cannot ban the owner/co-owner.")
        return
    reason = " ".join(context.args[1:]) if context.args and not update.message.reply_to_message else " ".join(context.args) if context.args else "No reason"
    now = int(time.time())
    # unban_at = NULL → permanent ban
    cursor.execute(
        "INSERT OR REPLACE INTO banned_users (user_id, banned_by, banned_at, unban_at, reason) VALUES (?,?,?,NULL,?)",
        (target_id, update.effective_user.id, now, reason)
    )
    conn.commit()
    _BAN_CACHE.pop(target_id, None)
    await update.message.reply_text(
        f"🔨 *Permanent Ban Issued!*\n\n"
        f"👤 User: {target_name} (`{target_id}`)\n"
        f"📝 Reason: {reason}\n"
        f"❌ This is a *lifetime ban* — does not expire.",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🔨 *PERMANENT BAN*\n\n"
        f"👤 User: {target_name} (`{target_id}`)\n"
        f"📝 Reason: {reason}\n"
        f"❌ No expiry\n"
        f"👮 By: {update.effective_user.first_name} (`{update.effective_user.id}`)"
    )


async def tban(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Temporary ban with day count. /tban <user_id> <days> [reason]"""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admins only.")
        return
    target_id = None
    target_name = "Unknown"
    args = list(context.args) if context.args else []
    if update.message.reply_to_message:
        target_id = update.message.reply_to_message.from_user.id
        target_name = update.message.reply_to_message.from_user.first_name or str(target_id)
    elif args:
        try:
            target_id = int(args[0])
            target_name = str(target_id)
            args = args[1:]
        except ValueError:
            await update.message.reply_text("❌ Invalid user ID.")
            return
    if not target_id:
        await update.message.reply_text(
            "Usage:\n"
            "/tban <user_id> <days> [reason]\n"
            "OR reply to user: /tban <days> [reason]"
        )
        return
    if target_id in (OWNER_ID, CO_OWNER_ID):
        await update.message.reply_text("❌ Cannot ban the owner/co-owner.")
        return
    try:
        days = int(args[0]) if args else 1
        reason = " ".join(args[1:]) if len(args) > 1 else "No reason"
    except (ValueError, IndexError):
        days = 1
        reason = "No reason"
    if days < 1:
        days = 1
    now = int(time.time())
    unban_at = now + (days * 86400)
    cursor.execute(
        "INSERT OR REPLACE INTO banned_users (user_id, banned_by, banned_at, unban_at, reason) VALUES (?,?,?,?,?)",
        (target_id, update.effective_user.id, now, unban_at, reason)
    )
    conn.commit()
    _BAN_CACHE.pop(target_id, None)
    await update.message.reply_text(
        f"⏳ *Temporary Ban Issued!*\n\n"
        f"👤 User: {target_name} (`{target_id}`)\n"
        f"📝 Reason: {reason}\n"
        f"⏰ Duration: *{days} day(s)*\n"
        f"🔓 Auto-unban in {days} days.",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"⏳ *TEMPORARY BAN*\n\n"
        f"👤 User: {target_name} (`{target_id}`)\n"
        f"📝 Reason: {reason}\n"
        f"⏰ Duration: {days} day(s)\n"
        f"👮 By: {update.effective_user.first_name} (`{update.effective_user.id}`)"
    )


