# ================= /ADD CARD TO COLLECTION (Admin/Owner) =================

async def add_to_collection(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Admin/Owner:
      /add <card_id>              — Add card to your own collection
      /add <card_id> <user_id>   — Add card to another user by ID
      Reply to user + /add <card_id> — Add card to the replied user
    """
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admins only.")
        return

    if not context.args:
        await update.message.reply_text(
            "📖 *Usage:*\n"
            "• `/add <card_id>` — add to your own vault\n"
            "• `/add <card_id> <user_id>` — add to another user\n"
            "• Reply to a user's message + `/add <card_id>`",
            parse_mode="Markdown"
        )
        return

    try:
        card_id = int(context.args[0].replace("#", ""))
    except ValueError:
        await update.message.reply_text("❌ Invalid card ID.")
        return

    # ── Determine target: reply > explicit id > self ──────────────────────────
    target_id = None
    target_name = None

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        replied_user = update.message.reply_to_message.from_user
        if not replied_user.is_bot:
            target_id = replied_user.id
            target_name = replied_user.first_name or str(target_id)

    if target_id is None and len(context.args) >= 2:
        try:
            target_id = int(context.args[1])
            try:
                tc = await context.bot.get_chat(target_id)
                target_name = tc.first_name or str(target_id)
            except Exception:
                target_name = str(target_id)
        except ValueError:
            await update.message.reply_text("❌ Invalid user ID.")
            return

    if target_id is None:
        target_id = update.effective_user.id
        target_name = update.effective_user.first_name or "Self"

    cursor.execute("SELECT name, rarity, file_id, COALESCE(file_type,'photo') FROM cards WHERE id=?", (card_id,))
    card = cursor.fetchone()
    if not card:
        await update.message.reply_text(f"❌ No card found with ID #{card_id}.")
        return

    name, rarity, file_id, file_type = card

    insert_user_card(target_id, name, rarity, file_id, file_type=file_type, card_id=card_id)
    conn.commit()

    emoji = RARITY_EMOJI.get(rarity, "⭐")
    series_val = "Naruto"
    cursor.execute("SELECT COALESCE(series,'Naruto') FROM cards WHERE id=?", (card_id,))
    sr = cursor.fetchone()
    if sr:
        series_val = sr[0]
    series_emoji = SERIES_EMOJI.get(series_val, "🎴")

    caption = (
        f"✅ *Card Added to Collection!*\n\n"
        f"🆔 Card ID: #{card_id}\n"
        f"🥷 Name: {name.title()}\n"
        f"{emoji} Rarity: {rarity}\n"
        f"{series_emoji} Series: {series_val}\n\n"
        f"👤 Added to: *{target_name}* (`{target_id}`)\n"
        f"🏆 Card is now in their vault!"
    )

    try:
        await send_card_media(
            update.message,
            file_id=file_id,
            file_type=file_type,
            caption=caption,
            parse_mode="Markdown"
        )
    except Exception:
        await update.message.reply_text(caption, parse_mode="Markdown")
    await log_to_group(
        context.bot,
        f"➕ *Admin Add Card*\n\n"
        f"👤 By: {update.effective_user.first_name} (`{update.effective_user.id}`)\n"
        f"🎯 To: {target_name} (`{target_id}`)\n"
        f"🆔 Card: #{card_id} {name} [{rarity}]"
    )


# ================= /REMOVE CARD (Admin) =================

async def remove_from_collection(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Admin: /remove <user_id> <card_entry_id>
       OR  Reply to user + /remove <card_entry_id>
    Removes a specific card entry from a user's collection.
    """
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admins only.")
        return

    # ── Determine target and card_entry_id ───────────────────────────────────
    target_id = None
    target_name = None
    card_entry_id = None

    replied = update.message.reply_to_message
    if replied and replied.from_user and not replied.from_user.is_bot:
        target_id = replied.from_user.id
        target_name = replied.from_user.first_name or str(target_id)
        # In reply mode first arg is the card entry id
        if context.args:
            try:
                card_entry_id = int(context.args[0].replace("#", ""))
            except ValueError:
                await update.message.reply_text("❌ Invalid card entry ID.")
                return
        else:
            await update.message.reply_text(
                "Usage (reply to user): /remove <card_entry_id>\n"
                "Example: reply to user + /remove 42"
            )
            return
    else:
        # Normal mode: /remove <user_id> <card_entry_id>
        if not context.args or len(context.args) < 2:
            await update.message.reply_text(
                "📖 *Usage:*\n"
                "• `/remove <user_id> <card_entry_id>`\n"
                "• Reply to user + `/remove <card_entry_id>`\n\n"
                "Example: `/remove 123456789 42`\n"
                "💡 Find card entry IDs from /collection.",
                parse_mode="Markdown"
            )
            return
        try:
            target_id = int(context.args[0])
            card_entry_id = int(context.args[1].replace("#", ""))
        except ValueError:
            await update.message.reply_text("❌ Invalid user ID or card entry ID.")
            return
        try:
            tc = await context.bot.get_chat(target_id)
            target_name = tc.first_name or str(target_id)
        except Exception:
            target_name = str(target_id)

    # Fetch the card entry — look up by master card_id first, then row id
    cursor.execute(
        "SELECT id, card_name, rarity, file_id FROM user_cards WHERE card_id=? AND user_id=? LIMIT 1",
        (card_entry_id, target_id)
    )
    card = cursor.fetchone()
    if not card:
        # Fallback: try by internal row id
        cursor.execute(
            "SELECT id, card_name, rarity, file_id FROM user_cards WHERE id=? AND user_id=?",
            (card_entry_id, target_id)
        )
        card = cursor.fetchone()

    if not card:
        await update.message.reply_text(
            f"❌ No card *#{card_entry_id}* found for user `{target_id}`.\n\n"
            f"Check the card ID from their `/collection`.",
            parse_mode="Markdown"
        )
        return

    row_id, card_name, rarity, file_id = card
    emoji = RARITY_EMOJI.get(rarity, "⭐")

    cursor.execute("DELETE FROM user_cards WHERE id=? AND user_id=?", (row_id, target_id))
    conn.commit()

    await update.message.reply_text(
        f"🗑️ *Card Removed Successfully!*\n\n"
        f"👤 User: {target_name} (`{target_id}`)\n"
        f"🥷 Card: {card_name.title()}\n"
        f"{emoji} Rarity: {rarity}\n"
        f"🆔 Card ID: #{card_entry_id}\n\n"
        f"✅ Removed from their collection.",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🗑️ *Admin Removed Card*\n\n"
        f"👮 By: {update.effective_user.first_name} (`{update.effective_user.id}`)\n"
        f"👤 From: {target_name} (`{target_id}`)\n"
        f"🥷 Card: {card_name.title()} [{rarity}]\n"
        f"🆔 Card ID: #{card_entry_id}"
    )


# ================= /TRANSFER COLLECTION (Admin only) =================

async def transfer_collection(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Admin only: /transfer <receiver_id> <sender_id>
    Transfers the entire collection from sender to receiver.
    Sender's collection becomes empty after transfer.
    """
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 This command is for admins only.")
        return

    if not context.args or len(context.args) < 2:
        await update.message.reply_text(
            "Usage: /transfer <receiver_id> <sender_id>\n\n"
            "📥 First ID = the user who RECEIVES the collection\n"
            "📤 Second ID = the user who SENDS (loses) the collection\n\n"
            "Example:\n/transfer 1234567890 9876543210\n\n"
            "⚠️ The sender's collection will be completely emptied!"
        )
        return

    try:
        receiver_id = int(context.args[0])
        sender_id = int(context.args[1])
    except ValueError:
        await update.message.reply_text("❌ Invalid user IDs. Both must be numbers.")
        return

    if receiver_id == sender_id:
        await update.message.reply_text("❌ Receiver and sender cannot be the same user.")
        return

    # Count sender's cards
    cursor.execute("SELECT COUNT(*) FROM user_cards WHERE user_id=?", (sender_id,))
    card_count = cursor.fetchone()[0]

    if card_count == 0:
        await update.message.reply_text(
            f"⚠️ User `{sender_id}` has no cards to transfer.",
            parse_mode="Markdown"
        )
        return

    # Get user names
    try:
        receiver_chat = await context.bot.get_chat(receiver_id)
        receiver_name = receiver_chat.first_name or str(receiver_id)
    except Exception:
        receiver_name = str(receiver_id)

    try:
        sender_chat = await context.bot.get_chat(sender_id)
        sender_name = sender_chat.first_name or str(sender_id)
    except Exception:
        sender_name = str(sender_id)

    # Perform the transfer — update all sender's cards to receiver
    cursor.execute(
        "UPDATE user_cards SET user_id=? WHERE user_id=?",
        (receiver_id, sender_id)
    )
    conn.commit()

    await update.message.reply_text(
        f"✅ *Collection Transfer Complete!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📤 *Sender:* {sender_name} (`{sender_id}`)\n"
        f"📥 *Receiver:* {receiver_name} (`{receiver_id}`)\n"
        f"🃏 *Cards Transferred:* {card_count}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"✅ {receiver_name}'s collection has been updated.\n"
        f"⚠️ {sender_name}'s collection is now empty.",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🔄 *Collection Transfer*\n\n"
        f"👮 By: {update.effective_user.first_name} (`{update.effective_user.id}`)\n"
        f"📤 From: {sender_name} (`{sender_id}`)\n"
        f"📥 To: {receiver_name} (`{receiver_id}`)\n"
        f"🃏 Cards: {card_count}"
    )

    # Notify both users
    try:
        await context.bot.send_message(
            chat_id=receiver_id,
            text=(
                f"📥 *Collection Received!*\n\n"
                f"🎉 An admin has transferred *{card_count} cards* to your collection!\n\n"
                f"📦 Use /collection to view your updated vault.\n"
                f"🍃 Welcome your new shinobis! ⚔️"
            ),
            parse_mode="Markdown"
        )
    except Exception:
        pass

    try:
        await context.bot.send_message(
            chat_id=sender_id,
            text=(
                f"📤 *Collection Transferred!*\n\n"
                f"⚠️ An admin has transferred all *{card_count} cards* from your collection.\n\n"
                f"💔 Your vault is now empty.\n"
                f"📞 Contact an admin if you think this was a mistake."
            ),
            parse_mode="Markdown"
        )
    except Exception:
        pass


# ================= /FIND CARD (Search who has a card) =================

# ===== FIND PAGINATION START =====
# /find pagination.  Design (no shared/global page state):
#   * Holder pages are STATELESS: callback_data = "fh:<card_id>:<page>:<owner_uid>".
#     The page is recomputed from the database with LIMIT/OFFSET on every tap,
#     so it survives bot restarts and can never mix two users/searches up.
#   * Name-search pickers need the query, which can be longer than Telegram's
#     64-byte callback limit, so it is stored per search in the find_sessions
#     table (token -> user_id, query) and referenced as "fm:<token>:<page>:<uid>".
#     Sessions are persisted (restart-safe), capped per user and purged by age.
#   * Buttons only work for the user who ran the search.
try:
    FIND_HOLDERS_PAGE_SIZE = max(1, min(50, int(os.environ.get("FIND_HOLDERS_PAGE_SIZE", "20"))))
except ValueError:
    FIND_HOLDERS_PAGE_SIZE = 20
try:
    FIND_MATCH_PAGE_SIZE = max(1, min(50, int(os.environ.get("FIND_MATCH_PAGE_SIZE", "15"))))
except ValueError:
    FIND_MATCH_PAGE_SIZE = 15
try:
    FIND_SESSION_TTL = max(300, int(os.environ.get("FIND_SESSION_TTL_SEC", "86400")))
except ValueError:
    FIND_SESSION_TTL = 86400
try:
    FIND_SESSIONS_PER_USER = max(1, int(os.environ.get("FIND_SESSIONS_PER_USER", "20")))
except ValueError:
    FIND_SESSIONS_PER_USER = 20

try:
    cursor.execute("CREATE TABLE IF NOT EXISTS find_sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, "
                   "query TEXT NOT NULL, created_at INTEGER NOT NULL)")
    cursor.execute("CREATE INDEX IF NOT EXISTS idx_find_sessions_user ON find_sessions(user_id, created_at)")
    conn.commit()
except Exception as _fse:
    print(f"[FIND] could not create find_sessions table: {_fse}")


def _find_safe_md(text) -> str:
    text = str(text)
    for ch in ("_", "*", "`", "["):
        text = text.replace(ch, "\\" + ch)
    return text


def _find_like_pattern(raw_query: str) -> str:
    q = raw_query.replace("#", "").replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    return f"%{q}%"


def _find_count_matches(like_pat: str) -> int:
    cur = conn.cursor()
    cur.execute("SELECT COUNT(*) FROM cards WHERE LOWER(name) LIKE LOWER(?) ESCAPE '\\'", (like_pat,))
    return cur.fetchone()[0]


def _find_match_page(like_pat: str, page: int, size: int):
    cur = conn.cursor()
    cur.execute("SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards "
                "WHERE LOWER(name) LIKE LOWER(?) ESCAPE '\\' ORDER BY id LIMIT ? OFFSET ?",
                (like_pat, size, (max(1, page) - 1) * size))
    return cur.fetchall()


def _find_pages(total: int, size: int) -> int:
    return max(1, -(-total // size))


def _find_nav_keyboard(prefix: str, ident, page: int, pages: int, owner_uid: int):
    """Prev | page/pages | Next. Prev hidden on page 1, Next hidden on the last page,
    nothing at all when there is only one page."""
    if pages <= 1:
        return None
    row = []
    if page > 1:
        row.append(InlineKeyboardButton("⬅️ Prev", callback_data=f"{prefix}:{ident}:{page - 1}:{owner_uid}"))
    row.append(InlineKeyboardButton(f"{page}/{pages}", callback_data="fnoop"))
    if page < pages:
        row.append(InlineKeyboardButton("Next ➡️", callback_data=f"{prefix}:{ident}:{page + 1}:{owner_uid}"))
    return InlineKeyboardMarkup([row])


def _find_session_create(user_id: int, query: str) -> str:
    token = "".join(random.choices(string.ascii_lowercase + string.digits, k=8))
    now = int(time.time())
    cur = conn.cursor()
    cur.execute("INSERT INTO find_sessions (token, user_id, query, created_at) VALUES (?,?,?,?)",
                (token, user_id, query, now))
    cur.execute("DELETE FROM find_sessions WHERE created_at < ?", (now - FIND_SESSION_TTL,))
    cur.execute("DELETE FROM find_sessions WHERE user_id=? AND token NOT IN "
                "(SELECT token FROM find_sessions WHERE user_id=? ORDER BY created_at DESC, rowid DESC LIMIT ?)",
                (user_id, user_id, FIND_SESSIONS_PER_USER))
    conn.commit()
    return token


def _find_session_get(token: str):
    cur = conn.cursor()
    cur.execute("SELECT user_id, query FROM find_sessions WHERE token=?", (token,))
    return cur.fetchone()


def _find_holders_page(db_id: int, card_name: str, rarity: str, page: int, size: int) -> dict:
    cur = conn.cursor()
    where, params = "card_id=?", (db_id,)
    cur.execute(f"SELECT COUNT(DISTINCT user_id), COUNT(*) FROM user_cards WHERE {where}", params)
    n_holders, total_copies = cur.fetchone()
    if not n_holders:   # legacy rows inserted without card_id
        where, params = "LOWER(card_name)=LOWER(?) AND rarity=?", (card_name, rarity)
        cur.execute(f"SELECT COUNT(DISTINCT user_id), COUNT(*) FROM user_cards WHERE {where}", params)
        n_holders, total_copies = cur.fetchone()
    pages = _find_pages(n_holders, size)
    page = max(1, min(page, pages))
    rows = []
    if n_holders:
        cur.execute(f"SELECT user_id, COUNT(*) AS c FROM user_cards WHERE {where} "
                    f"GROUP BY user_id ORDER BY c DESC, user_id ASC LIMIT ? OFFSET ?",
                    (*params, size, (page - 1) * size))
        rows = cur.fetchall()
    names = {}
    if rows:
        ids = [r[0] for r in rows]
        cur.execute(f"SELECT user_id, first_name FROM bot_users WHERE user_id IN ({','.join('?' * len(ids))})", ids)
        names = {uid: fn for uid, fn in cur.fetchall()}
    lines = "".join(f"• {_find_safe_md(names.get(uid) or uid)} (`{uid}`) — {c}x\n" for uid, c in rows)
    return {"n_holders": n_holders, "total_copies": total_copies, "page": page, "pages": pages, "lines": lines}


def _find_holders_text(db_id: int, card_name: str, hp: dict) -> str:
    page_note = f" (page {hp['page']}/{hp['pages']})" if hp["pages"] > 1 else ""
    return f"📋 *Holders of #{db_id} — {_find_safe_md(card_name.title())}*{page_note}:\n{hp['lines']}"


def _find_matches_text(raw_query: str, total: int, rows, page: int, pages: int) -> str:
    lines = []
    for m_id, m_name, m_rarity, *_ in rows:
        lines.append(f"  • #{m_id} — {m_name.title()} [{RARITY_EMOJI.get(m_rarity, '⭐')} {m_rarity}]")
    page_note = f" — page {page}/{pages}" if pages > 1 else ""
    return (f"🔍 *Multiple cards match \"{_find_safe_md(raw_query)}\"* ({total}){page_note}:\n\n"
            + "\n".join(lines)
            + "\n\n💡 Use the exact ID, e.g. `/find " + str(rows[0][0]) + "`")


async def find_page_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles the Prev/Next buttons of /find (callback_data fh:/fm:/fnoop)."""
    query = update.callback_query
    if not query or not query.data:
        return
    data = query.data
    if data == "fnoop":
        await query.answer()
        return
    try:
        kind, ident, page_s, owner_s = data.split(":", 3)
        page, owner = int(page_s), int(owner_s)
    except ValueError:
        await query.answer("⚠️ Invalid button.", show_alert=False)
        return
    if query.from_user.id != owner:
        await query.answer("🔒 This is another player's search — run /find yourself.", show_alert=True)
        return

    if kind == "fh":
        try:
            db_id = int(ident)
        except ValueError:
            await query.answer("⚠️ Invalid button.")
            return
        cur = conn.cursor()
        cur.execute("SELECT name, rarity FROM cards WHERE id=?", (db_id,))
        card_row = cur.fetchone()
        if not card_row:
            await query.answer("❌ That card no longer exists.", show_alert=True)
            return
        hp = _find_holders_page(db_id, card_row[0], card_row[1], page, FIND_HOLDERS_PAGE_SIZE)
        text = _find_holders_text(db_id, card_row[0], hp)
        kb = _find_nav_keyboard("fh", db_id, hp["page"], hp["pages"], owner)
    elif kind == "fm":
        sess = _find_session_get(ident)
        if not sess or sess[0] != owner:
            await query.answer("⌛ This search expired — run /find again.", show_alert=True)
            return
        raw_query = sess[1]
        like_pat = _find_like_pattern(raw_query)
        total = _find_count_matches(like_pat)
        if total == 0:
            await query.answer("No results any more — run /find again.", show_alert=True)
            return
        pages = _find_pages(total, FIND_MATCH_PAGE_SIZE)
        page = max(1, min(page, pages))
        rows = _find_match_page(like_pat, page, FIND_MATCH_PAGE_SIZE)
        text = _find_matches_text(raw_query, total, rows, page, pages)
        kb = _find_nav_keyboard("fm", ident, page, pages, owner)
    else:
        await query.answer("⚠️ Invalid button.")
        return

    try:
        await query.edit_message_text(text, parse_mode="Markdown", reply_markup=kb)
    except BadRequest as exc:
        if "not modified" not in str(exc).lower():
            raise
    await query.answer()
# ===== FIND PAGINATION END =====


async def _send_find_all_rarities(update: Update, exact_matches: list):
    """FIX (Issue 3): one character's name found at multiple rarities — show
    the full name plus holder info for every rarity variant in one message,
    instead of forcing a second /find <id> lookup per rarity."""
    full_name = exact_matches[0][1]
    lines = [f"🔍 *{full_name.title()}* — available in *{len(exact_matches)}* rarities:\n"]
    for db_id, m_name, m_rarity, _file_id, _file_type in exact_matches:
        emoji = RARITY_EMOJI.get(m_rarity, "⭐")
        cursor.execute(
            "SELECT user_id, COUNT(*) as copies FROM user_cards WHERE card_id=? GROUP BY user_id ORDER BY copies DESC LIMIT 1",
            (db_id,)
        )
        top_holder = cursor.fetchone()
        cursor.execute("SELECT COUNT(DISTINCT user_id) FROM user_cards WHERE card_id=?", (db_id,))
        holder_count = cursor.fetchone()[0]
        if top_holder:
            lines.append(f"{emoji} *{m_rarity}* (`#{db_id}`) — {holder_count} owner(s), top: `{top_holder[0]}` ({top_holder[1]}x)")
        else:
            lines.append(f"{emoji} *{m_rarity}* (`#{db_id}`) — nobody owns this yet")
    lines.append(f"\n💡 Use `/find <id>` for full holder details on a specific rarity.")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def find_card(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /find <card_id or name> — Show which users own a card.
    Accepts the exact DB ID (recommended) or a name search.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    if not context.args:
        await update.message.reply_text(
            "🔍 *Find a Card*\n\n"
            "Usage: /find <card\\_id>\n"
            "Example: /find 42\n\n"
            "💡 Use the *exact card number* from the database.\n"
            "Admins can see all card IDs with /list\\_cards.",
            parse_mode="Markdown"
        )
        return

    raw_query = " ".join(context.args).strip()
    card = None
    multi_total = 0
    multi_like = None

    try:
        card_id = int(raw_query.replace("#", ""))
        cursor.execute("SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards WHERE id=?", (card_id,))
        card = cursor.fetchone()
    except ValueError:
        pass

    # FIX (Issue 3): when the query is a plain character name, show that
    # character's FULL name across EVERY rarity it exists in, in one
    # response — instead of just a bare "pick an ID" disambiguation list.
    # We first try an exact (case-insensitive) name match; if that name
    # exists at more than one rarity, we resolve holders for all of them
    # right here. Only a genuinely ambiguous substring match (query could
    # mean several different characters) falls back to the picker list.
    if not card:
        cursor.execute(
            "SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards "
            "WHERE LOWER(name) = LOWER(?) ORDER BY id",
            (raw_query,)
        )
        exact_matches = cursor.fetchall()

        if len(exact_matches) == 1:
            card = exact_matches[0]
        elif len(exact_matches) > 1:
            await _send_find_all_rarities(update, exact_matches)
            return
        else:
            # No exact name hit — fall back to substring search across
            # possibly-different characters, and let the user disambiguate.
            like_pat = _find_like_pattern(raw_query)
            total_matches = _find_count_matches(like_pat)
            if total_matches == 1:
                card = _find_match_page(like_pat, 1, 1)[0]
            elif total_matches > 1:
                multi_total, multi_like = total_matches, like_pat

    if multi_total:
        # Several different characters match: paginated picker (Prev | n/N | Next).
        pages = _find_pages(multi_total, FIND_MATCH_PAGE_SIZE)
        rows = _find_match_page(multi_like, 1, FIND_MATCH_PAGE_SIZE)
        kb = None
        if pages > 1:
            token = _find_session_create(user_id, raw_query)
            kb = _find_nav_keyboard("fm", token, 1, pages, user_id)
        await update.message.reply_text(
            _find_matches_text(raw_query, multi_total, rows, 1, pages),
            parse_mode="Markdown", reply_markup=kb
        )
        return

    if not card:
        await update.message.reply_text(
            f"❌ *No card found matching \"{_find_safe_md(raw_query)}\"!*\n\n"
            f"• Check the number shown in your `/collection`\n"
            f"• The card's *#ID* is shown in the caption\n"
            f"• Admins can see all IDs with /list\\_cards",
            parse_mode="Markdown"
        )
        return

    db_id, card_name, rarity, file_id, file_type = card
    emoji = RARITY_EMOJI.get(rarity, "⭐")

    hp = _find_holders_page(db_id, card_name, rarity, 1, FIND_HOLDERS_PAGE_SIZE)

    if not hp["n_holders"]:
        _find_caption = (
            f"🔍 *Card Search Results*\n\n"
            f"🆔 Card ID: *#{db_id}*\n"
            f"🥷 Card: {_find_safe_md(card_name.title())}\n"
            f"{emoji} Rarity: {rarity}\n\n"
            f"😶 *Nobody owns this card yet!*\n"
            f"Be the first to get it! ⚔️"
        )
        try:
            await send_card_media(update.message, file_id, file_type=file_type, caption=_find_caption, parse_mode="Markdown")
        except Exception as e:
            print(f"[FIND] media send failed (no-holders branch), falling back to text: {e}")
            try:
                await update.message.reply_text(_find_caption, parse_mode="Markdown")
            except Exception:
                await update.message.reply_text(_find_caption.replace("*", "").replace("`", ""))
        return

    _find_header = (
        f"🔍 *Card Search Results*\n\n"
        f"🆔 Card ID: *#{db_id}*\n"
        f"🥷 Card: {_find_safe_md(card_name.title())}\n"
        f"{emoji} Rarity: {rarity}\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"👥 *Owned by {hp['n_holders']} player(s)*\n"
        f"📦 Total copies: {hp['total_copies']}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━"
    )
    _holders_text = _find_holders_text(db_id, card_name, hp)
    _kb = _find_nav_keyboard("fh", db_id, 1, hp["pages"], user_id)
    # Telegram caps media captions at 1024 chars. Single page + fits -> everything in the caption
    # (unchanged behaviour). Otherwise the media carries the header and the holder list (with
    # Prev/Next buttons when there is more than one page) follows as its own text message.
    _full_caption = _find_header + "\n\n📋 *Holders:*\n" + hp["lines"]
    if hp["pages"] == 1 and len(_full_caption) <= 1024:
        _media_caption, _followup = _full_caption, None
    else:
        _media_caption, _followup = _find_header, _holders_text

    try:
        await send_card_media(update.message, file_id, file_type=file_type, caption=_media_caption, parse_mode="Markdown")
        if _followup:
            await update.message.reply_text(_followup, parse_mode="Markdown", reply_markup=_kb)
    except Exception as e:
        print(f"[FIND] media send failed, falling back to text: {e}")
        _fallback = _find_header + "\n\n" + _holders_text
        try:
            await update.message.reply_text(_fallback, parse_mode="Markdown", reply_markup=_kb)
        except Exception:
            await update.message.reply_text(_fallback.replace("*", "").replace("`", ""), reply_markup=_kb)


# ================= /DELACC — Delete User Account/Collection (Admin only) =================

async def delacc(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Admin only: /delacc <user_id>
    Completely deletes a user's collection (all their cards).
    Also removes their vouchers and spin stats.
    """
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 This command is for admins only.")
        return

    if not context.args and not (update.message.reply_to_message and update.message.reply_to_message.from_user):
        await update.message.reply_text(
            "Usage:\n"
            "• /delacc <user_id>\n"
            "• Reply to a user's message with /delacc\n\n"
            "⚠️ Permanently wipes their collection (backed up for /rec_acc).\n"
            "Example: /delacc 123456789"
        )
        return

    # Determine target — reply takes priority
    target_id = None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        replied = update.message.reply_to_message.from_user
        if not replied.is_bot:
            target_id = replied.id
    if target_id is None and context.args:
        try:
            target_id = int(context.args[0])
        except ValueError:
            await update.message.reply_text("❌ Invalid user ID.")
            return
    if target_id is None:
        await update.message.reply_text("❌ Could not determine target user.")
        return

    if target_id in (OWNER_ID, CO_OWNER_ID):
        # Only the owner themselves can delete their own account
        if not is_admin(update.effective_user.id):
            await update.message.reply_text("❌ Only the owner can delete the owner/co-owner's account.")
            return

    # Get target name
    try:
        tc = await context.bot.get_chat(target_id)
        target_name = tc.first_name or str(target_id)
    except Exception:
        target_name = str(target_id)

    # Count their cards before deleting
    cursor.execute("SELECT COUNT(*) FROM user_cards WHERE user_id=?", (target_id,))
    card_count = cursor.fetchone()[0]

    cursor.execute("SELECT vouchers FROM draft_vouchers WHERE user_id=?", (target_id,))
    v_row = cursor.fetchone()
    voucher_count = v_row[0] if v_row else 0

    # ── Backup cards to deleted_cards_backup BEFORE deleting (fixes /rec_acc) ──
    now_ts = int(time.time())
    cursor.execute(
        "SELECT card_name, rarity, file_id FROM user_cards WHERE user_id=?",
        (target_id,)
    )
    cards_to_backup = cursor.fetchall()
    for card_name, rarity, file_id in cards_to_backup:
        cursor.execute(
            "INSERT INTO deleted_cards_backup (user_id, card_name, rarity, file_id, deleted_at) "
            "VALUES (?, ?, ?, ?, ?)",
            (target_id, card_name, rarity, file_id, now_ts)
        )

    # ── Backup vouchers + spin stats to deleted_vouchers_backup ──────────────
    cursor.execute(
        "SELECT vouchers, total_spins, spins_since_legendary, spins_since_spring "
        "FROM draft_vouchers WHERE user_id=?",
        (target_id,)
    )
    vrow = cursor.fetchone()
    if vrow:
        cursor.execute("""
            INSERT OR REPLACE INTO deleted_vouchers_backup
            (user_id, vouchers, total_spins, spins_since_legendary, spins_since_spring, deleted_at)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (target_id, vrow[0], vrow[1], vrow[2], vrow[3], now_ts))

    # Delete everything
    cursor.execute("DELETE FROM user_cards WHERE user_id=?", (target_id,))
    cursor.execute("DELETE FROM draft_vouchers WHERE user_id=?", (target_id,))
    cursor.execute("DELETE FROM weekly_claims WHERE user_id=?", (target_id,))
    cursor.execute("DELETE FROM monthly_claims WHERE user_id=?", (target_id,))
    conn.commit()

    await update.message.reply_text(
        f"🗑️ *Account Data Deleted!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"👤 User: {target_name} (`{target_id}`)\n"
        f"🃏 Cards Deleted: {card_count}\n"
        f"🎟️ Vouchers Cleared: {voucher_count}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"✅ Their collection has been completely wiped.",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🗑️ *User Account Deleted*\n\n"
        f"👮 By: {update.effective_user.first_name} (`{update.effective_user.id}`)\n"
        f"👤 User: {target_name} (`{target_id}`)\n"
        f"🃏 Cards: {card_count} deleted\n"
        f"🎟️ Vouchers: {voucher_count} cleared"
    )

    # Notify the affected user
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=(
                f"⚠️ *Account Reset Notice*\n\n"
                f"An admin has deleted your collection and account data.\n\n"
                f"🃏 Cards: {card_count} removed\n"
                f"🎟️ Vouchers: {voucher_count} cleared\n\n"
                f"📞 Contact an admin if you think this was a mistake."
            ),
            parse_mode="Markdown"
        )
    except Exception:
        pass


# ================= /SHINOBI_MODE — Set Favourite Rarity Display Order =================

RARITY_ORDER_DEFAULT = (
    [_n for _n, _c in EXTRA_BUILTIN_RARITIES.items() if _c["order"] == "front"]
    + ["Crossverse", "Tradition", "Mermaid", "FIFA", "Academy", "Summer", "Spring", "Mythic", "Legendary", "Epic", "Rare"]
    + [_n for _n, _c in EXTRA_BUILTIN_RARITIES.items() if _c["order"] == "back"]
    + ["Common"]
)

# ── Anime series supported by the bot ────────────────────────────────────────
KNOWN_SERIES = ["Naruto", "One Piece", "Bleach", "Demon Slayer"]
# KNOWN_SERIES is extended dynamically when admin uses | separator in /addcard
# e.g. /addcard The Angel Next Door | Mahiru Shiina Animation
# The part before | is the series name, after | is the card name + rarity
SERIES_EMOJI = {
    "Naruto":       "⚔️",
    "One Piece":    "🏴‍☠️",
    "Bleach":       "🌸",
    "Demon Slayer": "🔥",
}
# One Piece, Bleach and Demon Slayer cards are collab-only — they never spawn randomly in groups
COLLAB_ONLY_SERIES = ["One Piece", "Bleach", "Demon Slayer"]

def get_user_fav_rarity(user_id: int):
    """
    Return the user's preferred rarity (or None if not set).

    FIX (Bug: /c_mode <rarity> and /shinobi_mode <rarity> appearing to do
    nothing — "all anime FIFA cards" grouping in /collection never showed
    up even after running /c_mode FIFA): this used to check MongoDB FIRST
    and only fall back to SQLite if Mongo had no value. But /c_mode's write
    path (see shinobi_mode()) only ever updates the LOCAL `shinobi_mode`
    SQLite table — set_fav_rarity_mongo()/clear_fav_rarity_mongo() are
    imported but never called anywhere in the bot. So once a Mongo doc
    existed for a user (e.g. from the one-time migration), it permanently
    shadowed every later SQLite update, and the user's actual current
    preference was never honoured.

    SQLite is the live, always-up-to-date source here (every /c_mode call
    INSERT-OR-IGNOREs a row first, so a row always exists after first use) —
    trust it completely once it exists, even if fav_rarity is NULL (that's
    a real "no preference set" / reset state, not missing data). Mongo is
    only consulted for brand-new accounts that have a migrated doc but have
    never run /c_mode locally yet.
    """
    cursor.execute("SELECT fav_rarity FROM shinobi_mode WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    if row is not None:
        return row[0]
    if MONGO_AVAILABLE:
        try:
            result = get_fav_rarity_mongo(user_id)
            if result:
                return result
        except Exception:
            pass
    return None

def get_sorted_collection(user_id: int, fav_rarity: str = None, fav_series: str = None):
    """
    Return collection rows sorted by rarity/series.
    Uses SQLite as the single source of truth (always correct after sell/trade/gift).
    MongoDB is used only when SQLite has 0 rows (initial migration case).
    Returns: [(card_id, card_name, rarity, count, series), ...]
    """
    # ── ALWAYS read from SQLite first (it is always in sync after every operation) ──
    cursor.execute(
        "SELECT uc.card_id, uc.card_name, uc.rarity, COUNT(*), "
        "COALESCE(uc.series, c.series, 'Naruto') as resolved_series "
        "FROM user_cards uc "
        "LEFT JOIN cards c ON c.id = uc.card_id "
        "WHERE uc.user_id = ? "
        "GROUP BY uc.card_id, uc.card_name, uc.rarity, resolved_series",
        (user_id,)
    )
    rows = cursor.fetchall()

    # Only fall back to MongoDB if SQLite has zero rows (new account / migration)
    if not rows and MONGO_AVAILABLE:
        mongo_rows = get_user_cards_grouped_mongo(user_id)
        if mongo_rows:
            # Validate each MongoDB row against SQLite to avoid stale data
            valid_rows = []
            for r in mongo_rows:
                cid, cname, crarity, ccount, cseries = r[0], r[1], r[2], r[3], r[4]
                if cid:
                    cursor.execute(
                        "SELECT COUNT(*) FROM user_cards WHERE user_id=? AND card_id=?",
                        (user_id, cid)
                    )
                else:
                    cursor.execute(
                        "SELECT COUNT(*) FROM user_cards "
                        "WHERE user_id=? AND card_name=? AND rarity=?",
                        (user_id, cname, crarity)
                    )
                actual = cursor.fetchone()[0]
                if actual > 0:
                    valid_rows.append((cid, cname, crarity, actual, cseries))
            rows = valid_rows

    if not rows:
        return []

    # Apply anime series filter if set by /c_mode anime:<series>
    if fav_series:
        rows = [r for r in rows if (r[4] if len(r) > 4 else "Naruto") == fav_series]
    if not rows:
        return []

    rarity_order = {r: i for i, r in enumerate(RARITY_ORDER_DEFAULT)}
    series_order = {s: i for i, s in enumerate(KNOWN_SERIES)}

    if fav_rarity:
        fav_rows  = [r for r in rows if r[2] == fav_rarity]
        rest_rows = [r for r in rows if r[2] != fav_rarity]
        fav_rows.sort(key=lambda r: (series_order.get(r[4], 99), r[1]))
        rest_rows.sort(key=lambda r: (series_order.get(r[4], 99), rarity_order.get(r[2], 99)))
        return fav_rows + rest_rows

    return sorted(
        rows,
        key=lambda r: (series_order.get(r[4], 99), rarity_order.get(r[2], 99))
    )

async def shinobi_mode(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /shinobi_mode [rarity]         — Set favourite rarity shown first in /collection.
    /c_mode [rarity]               — Same command, shorter alias.
    /c_mode anime:<SeriesName>     — Filter collection to show only one anime.
    /c_mode anime:One Piece        — Show only One Piece cards.
    /c_mode reset                  — Clear all preferences.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    user_name = update.effective_user.first_name or "Shinobi"

    # Ensure table has fav_series column (migration-safe)
    try:
        cursor.execute("ALTER TABLE shinobi_mode ADD COLUMN fav_series TEXT DEFAULT NULL")
        conn.commit()
    except Exception:
        pass

    # Ensure row exists
    cursor.execute(
        "INSERT OR IGNORE INTO shinobi_mode (user_id, fav_rarity) VALUES (?, NULL)",
        (user_id,)
    )
    conn.commit()

    current = get_user_fav_rarity(user_id)
    cursor.execute("SELECT fav_series FROM shinobi_mode WHERE user_id=?", (user_id,))
    _srow = cursor.fetchone()
    current_series = _srow[0] if _srow else None

    # No args — show current setting + menu
    if not context.args:
        rarity_list = "\n".join(
            f"  {RARITY_EMOJI.get(r, '⭐')} `{r}`" for r in RARITY_ORDER_DEFAULT
        )
        series_list = "\n".join(f"  📺 `{s}`" for s in KNOWN_SERIES)
        current_display = (
            f"{RARITY_EMOJI.get(current, '⭐')} *{current}* (shown first)"
            if current else "🔀 Default order (no preference set)"
        )
        series_display = f"📺 *{current_series}* only" if current_series else "All animes shown"

        keyboard_rows = []
        row = []
        for r in RARITY_ORDER_DEFAULT:
            idx = RARITY_ORDER_DEFAULT.index(r)
            label = f"{RARITY_EMOJI.get(r, '⭐')} {r}"
            row.append(InlineKeyboardButton(label, callback_data=f"cmr_{idx}"))
            if len(row) == 3:
                keyboard_rows.append(row)
                row = []
        if row:
            keyboard_rows.append(row)

        row = []
        for s in KNOWN_SERIES:
            idx = KNOWN_SERIES.index(s)
            row.append(InlineKeyboardButton(f"📺 {s}", callback_data=f"cma_{idx}"))
            if len(row) == 2:
                keyboard_rows.append(row)
                row = []
        if row:
            keyboard_rows.append(row)

        keyboard_rows.append([InlineKeyboardButton("🔀 Reset to Default", callback_data="cmreset")])

        await update.message.reply_text(
            f"⚔️ *Collection Mode Settings*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"👤 Shinobi: *{user_name}*\n"
            f"🎯 Rarity: {current_display}\n"
            f"📺 Anime: {series_display}\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"Tap a rarity or anime below to set it instantly, or use text commands:\n"
            f"• `/c_mode Mythic` — show Mythic cards first\n"
            f"• `/c_mode anime:One Piece` — show only One Piece cards\n"
            f"• `/c_mode reset` — restore default order",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup(keyboard_rows)
        )
        return

    full_arg = " ".join(context.args).strip()
    arg = context.args[0].strip()

    # Reset
    if arg.lower() == "reset":
        cursor.execute("UPDATE shinobi_mode SET fav_rarity=NULL, fav_series=NULL WHERE user_id=?", (user_id,))
        conn.commit()
        # Keep Mongo in sync too (defensive — SQLite stays authoritative via
        # get_user_fav_rarity()'s read order, but this stops a stale Mongo
        # doc from ever existing for this user again).
        if MONGO_AVAILABLE:
            try:
                clear_fav_rarity_mongo(user_id)
            except Exception:
                pass
        await update.message.reply_text(
            f"🔀 *Collection Mode Reset!*\n\n"
            f"✅ Your collection will now display in the default order with all animes shown.\n\n"
            f"💡 Use `/c_mode <rarity>` or `/c_mode anime:<series>` anytime.",
            parse_mode="Markdown"
        )
        return

    # Anime filter: /c_mode anime:One Piece
    if full_arg.lower().startswith("anime:"):
        chosen_series = full_arg[6:].strip()
        # Find best match in KNOWN_SERIES (case-insensitive)
        matched = next(
            (s for s in KNOWN_SERIES if s.lower() == chosen_series.lower()),
            None
        )
        if not matched:
            # Partial match
            matched = next(
                (s for s in KNOWN_SERIES if chosen_series.lower() in s.lower()),
                None
            )
        if not matched:
            series_list_txt = ", ".join(f"`{s}`" for s in KNOWN_SERIES)
            await update.message.reply_text(
                f"❌ *Unknown anime:* `{chosen_series}`\n\n"
                f"Available: {series_list_txt}\n\n"
                f"Example: `/c_mode anime:One Piece`",
                parse_mode="Markdown"
            )
            return
        cursor.execute("UPDATE shinobi_mode SET fav_series=? WHERE user_id=?", (matched, user_id))
        conn.commit()
        await update.message.reply_text(
            f"📺 *Anime Filter Set!*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"✅ Your /collection will now show only *{matched}* cards!\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"🔀 Use `/c_mode reset` to show all animes again.",
            parse_mode="Markdown"
        )
        return

    # Set rarity
    chosen = normalize_rarity(arg)
    if chosen not in RARITY_WEIGHTS:
        rarity_list = ", ".join(f"`{r}`" for r in RARITY_ORDER_DEFAULT)
        await update.message.reply_text(
            f"❌ *Unknown rarity:* `{arg}`\n\n"
            f"✅ Available rarities:\n{rarity_list}\n\n"
            f"Or filter by anime: `/c_mode anime:One Piece`\n"
            f"Example: `/c_mode Mythic`",
            parse_mode="Markdown"
        )
        return

    cursor.execute("UPDATE shinobi_mode SET fav_rarity=? WHERE user_id=?", (chosen, user_id))
    conn.commit()
    # Keep Mongo in sync too (defensive — see get_user_fav_rarity() for why
    # SQLite is authoritative; this just stops the two stores from drifting).
    if MONGO_AVAILABLE:
        try:
            set_fav_rarity_mongo(user_id, chosen)
        except Exception:
            pass
    emoji = RARITY_EMOJI.get(chosen, "⭐")

    await update.message.reply_text(
        f"{emoji} *Collection Mode Activated!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🎯 Favourite Rarity: *{chosen}*\n"
        f"📋 Your *{chosen}* cards will now appear\n"
        f"   at the top of /collection!\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"✨ Head to /collection to see the change!\n"
        f"💡 Also try: `/c_mode anime:One Piece`\n"
        f"🔀 Use `/c_mode reset` to go back to default.",
        parse_mode="Markdown"
    )


async def cmode_button_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles cmr_<rarity_index>, cma_<series_index>, and cmreset button taps from /c_mode."""
    query = update.callback_query
    if not query or not query.data:
        return
    user_id = query.from_user.id

    if is_banned(user_id):
        await query.answer("🚫 You're banned from using this bot.", show_alert=True)
        return

    cursor.execute("INSERT OR IGNORE INTO shinobi_mode (user_id, fav_rarity) VALUES (?, NULL)", (user_id,))
    conn.commit()

    data = query.data
    alert = ""

    if data == "cmreset":
        cursor.execute("UPDATE shinobi_mode SET fav_rarity=NULL, fav_series=NULL WHERE user_id=?", (user_id,))
        conn.commit()
        if MONGO_AVAILABLE:
            try:
                clear_fav_rarity_mongo(user_id)
            except Exception:
                pass
        alert = "🔀 Collection mode reset to default!"

    elif data.startswith("cmr_"):
        try:
            idx = int(data.split("_", 1)[1])
            chosen = RARITY_ORDER_DEFAULT[idx]
        except Exception:
            await query.answer("❌ Malformed button.", show_alert=True)
            return
        cursor.execute("UPDATE shinobi_mode SET fav_rarity=? WHERE user_id=?", (chosen, user_id))
        conn.commit()
        if MONGO_AVAILABLE:
            try:
                set_fav_rarity_mongo(user_id, chosen)
            except Exception:
                pass
        emoji = RARITY_EMOJI.get(chosen, "⭐")
        alert = f"{emoji} {chosen} will now show first in /collection!"

    elif data.startswith("cma_"):
        try:
            idx = int(data.split("_", 1)[1])
            matched = KNOWN_SERIES[idx]
        except Exception:
            await query.answer("❌ Malformed button.", show_alert=True)
            return
        cursor.execute("UPDATE shinobi_mode SET fav_series=? WHERE user_id=?", (matched, user_id))
        conn.commit()
        alert = f"📺 /collection will now show only {matched} cards!"

    else:
        await query.answer()
        return

    await query.answer(alert, show_alert=True)

    # Refresh the settings card in place.
    user_name = query.from_user.first_name or "Shinobi"
    current = get_user_fav_rarity(user_id)
    cursor.execute("SELECT fav_series FROM shinobi_mode WHERE user_id=?", (user_id,))
    _srow = cursor.fetchone()
    current_series = _srow[0] if _srow else None
    current_display = (
        f"{RARITY_EMOJI.get(current, '⭐')} *{current}* (shown first)"
        if current else "🔀 Default order (no preference set)"
    )
    series_display = f"📺 *{current_series}* only" if current_series else "All animes shown"

    keyboard_rows = []
    row = []
    for r in RARITY_ORDER_DEFAULT:
        idx = RARITY_ORDER_DEFAULT.index(r)
        row.append(InlineKeyboardButton(f"{RARITY_EMOJI.get(r, '⭐')} {r}", callback_data=f"cmr_{idx}"))
        if len(row) == 3:
            keyboard_rows.append(row)
            row = []
    if row:
        keyboard_rows.append(row)
    row = []
    for s in KNOWN_SERIES:
        idx = KNOWN_SERIES.index(s)
        row.append(InlineKeyboardButton(f"📺 {s}", callback_data=f"cma_{idx}"))
        if len(row) == 2:
            keyboard_rows.append(row)
            row = []
    if row:
        keyboard_rows.append(row)
    keyboard_rows.append([InlineKeyboardButton("🔀 Reset to Default", callback_data="cmreset")])

    try:
        await query.edit_message_text(
            f"⚔️ *Collection Mode Settings*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"👤 Shinobi: *{user_name}*\n"
            f"🎯 Rarity: {current_display}\n"
            f"📺 Anime: {series_display}\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"Tap a rarity or anime below to set it instantly, or use text commands:\n"
            f"• `/c_mode Mythic` — show Mythic cards first\n"
            f"• `/c_mode anime:One Piece` — show only One Piece cards\n"
            f"• `/c_mode reset` — restore default order",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup(keyboard_rows)
        )
    except Exception:
        pass




# ================= /GIFT — Gift a card to another user =================
# Pending gifts awaiting confirmation: {gift_id: {sender_id, target_id, card details, expires}}
_pending_gifts: dict = {}

async def gift_card(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /gift <card_id> — reply to a user's message OR mention them
    /gift @username <card_id>
    /gift <user_id> <card_id>

    Gift one copy of a card from your collection to another user.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    user_name = update.effective_user.first_name or "Shinobi"

    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    _frozen, _frozen_reason = is_feature_frozen("gift")
    if _frozen and not is_admin(user_id):
        await update.message.reply_text(
            f"🔒 *Gifting is temporarily frozen.*\n\n{_frozen_reason}", parse_mode="Markdown"
        )
        return

    args = list(context.args or [])
    target_id = None
    target_name = None

    # Method 1: reply to a message
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        replied = update.message.reply_to_message.from_user
        if replied.is_bot:
            await update.message.reply_text("❌ You can't gift cards to bots!")
            return
        target_id   = replied.id
        target_name = replied.first_name or str(target_id)
        # card_id is first arg
        if not args:
            await update.message.reply_text(
                "❌ Please specify a card ID to gift.\n\n"
                "Example: Reply to a user and send `/gift 42`",
                parse_mode="Markdown"
            )
            return
        try:
            card_id_arg = int(args[0])
        except ValueError:
            await update.message.reply_text("❌ Card ID must be a number.")
            return

    elif args and (args[0].startswith("@") or args[0].isdigit()):
        # Method 2: /gift @username card_id OR /gift user_id card_id
        if len(args) < 2:
            await update.message.reply_text(
                "❌ Usage: `/gift @username <card_id>` or `/gift <user_id> <card_id>`",
                parse_mode="Markdown"
            )
            return
        try:
            card_id_arg = int(args[1])
        except ValueError:
            await update.message.reply_text("❌ Card ID must be a number.")
            return
        if args[0].isdigit():
            target_id = int(args[0])
        else:
            uname = args[0].lstrip("@").lower()
            cursor.execute(
                "SELECT user_id, first_name FROM bot_users WHERE LOWER(username)=? LIMIT 1",
                (uname,)
            )
            row = cursor.fetchone()
            if not row:
                await update.message.reply_text(
                    f"❌ User `{args[0]}` not found. They must have started the bot.",
                    parse_mode="Markdown"
                )
                return
            target_id, target_name = row
        if not target_name:
            cursor.execute("SELECT first_name FROM bot_users WHERE user_id=?", (target_id,))
            nrow = cursor.fetchone()
            target_name = nrow[0] if nrow else str(target_id)
    else:
        await update.message.reply_text(
            "🎁 *Gift a Card*\n\n"
            "Send one of your cards to a friend!\n\n"
            "📖 *How to use:*\n"
            "• Reply to their message: `/gift <card_id>`\n"
            "• By username: `/gift @username <card_id>`\n"
            "• By user ID: `/gift <user_id> <card_id>`\n\n"
            "💡 Find your card IDs with `/collection`",
            parse_mode="Markdown"
        )
        return

    if target_id == user_id:
        await update.message.reply_text("❌ You can't gift cards to yourself!")
        return

    if not has_started_bot(target_id):
        await update.message.reply_text(
            f"❌ *{target_name}* hasn't started the bot yet!\n"
            f"Ask them to send `/start` first.",
            parse_mode="Markdown"
        )
        return

    # Find the card in sender's collection (by master card_id)
    cursor.execute(
        "SELECT uc.id, uc.card_name, uc.rarity, uc.file_id, "
        "COALESCE(uc.file_type,'photo'), COALESCE(uc.series,'Naruto'), uc.card_id "
        "FROM user_cards uc WHERE uc.card_id=? AND uc.user_id=? LIMIT 1",
        (card_id_arg, user_id)
    )
    card_row = cursor.fetchone()
    if not card_row:
        await update.message.reply_text(
            f"❌ You don't own card *#{card_id_arg}*.\n"
            f"Check your `/collection` for card IDs.",
            parse_mode="Markdown"
        )
        return

    row_id, c_name, c_rarity, c_file_id, c_file_type, c_series, c_master_id = card_row
    c_emoji = RARITY_EMOJI.get(c_rarity, "⭐")

    _frozen, _frozen_reason = is_card_frozen(row_id)
    if _frozen:
        await update.message.reply_text(f"🔒 *This card is frozen!*\n\n{_frozen_reason}", parse_mode="Markdown")
        return

    # ── Store in pending_gifts and ask for confirmation ───────────────────
    import uuid as _uuid
    _gift_id = _uuid.uuid4().hex[:12]
    _pending_gifts[_gift_id] = {
        "sender_id":   user_id,
        "sender_name": user_name,
        "target_id":   target_id,
        "target_name": target_name,
        "row_id":      row_id,
        "c_name":      c_name,
        "c_rarity":    c_rarity,
        "c_file_id":   c_file_id,
        "c_file_type": c_file_type,
        "c_series":    c_series,
        "c_master_id": c_master_id,
        "expires":     int(time.time()) + 120,
    }
    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ Yes, Gift!", callback_data=f"gift_confirm_{_gift_id}"),
        InlineKeyboardButton("❌ Cancel",     callback_data=f"gift_cancel_{_gift_id}"),
    ]])
    await send_card_media(
        update.message, c_file_id, file_type=c_file_type,
        caption=(
            f"🎁 *Confirm Gift*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"{c_emoji} *{c_name.title()}* [{c_rarity}]\n"
            f"📺 {c_series}\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"➡️ Gift to: *{target_name}*\n\n"
            f"⚠️ This card will be *permanently removed* from your collection!\n"
            f"Are you sure?"
        ),
        parse_mode="Markdown",
        reply_markup=keyboard
    )


async def gift_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle gift confirm/cancel button presses."""
    query = update.callback_query
    await query.answer()
    data    = query.data
    user_id = query.from_user.id

    if data.startswith("gift_cancel_"):
        gift_id = data[len("gift_cancel_"):]
        _pending_gifts.pop(gift_id, None)
        await query.edit_message_caption(caption="❌ *Gift cancelled.* Your card is safe!", parse_mode="Markdown")
        return

    if data.startswith("gift_confirm_"):
        gift_id = data[len("gift_confirm_"):]
        gift = _pending_gifts.get(gift_id)
        if not gift:
            await query.edit_message_caption(caption="❌ Gift expired or already processed. Try again.", parse_mode="Markdown")
            return
        if gift["sender_id"] != user_id:
            await query.answer("❌ This is not your gift confirmation!", show_alert=True)
            return
        if int(time.time()) > gift["expires"]:
            _pending_gifts.pop(gift_id, None)
            await query.edit_message_caption(caption="❌ Gift confirmation expired (2 min). Please try again.", parse_mode="Markdown")
            return

        _pending_gifts.pop(gift_id, None)
        row_id      = gift["row_id"]
        target_id   = gift["target_id"]
        target_name = gift["target_name"]
        c_name      = gift["c_name"]
        c_rarity    = gift["c_rarity"]
        c_file_id   = gift["c_file_id"]
        c_file_type = gift["c_file_type"]
        c_series    = gift["c_series"]
        c_master_id = gift["c_master_id"]
        sender_name = gift["sender_name"]
        c_emoji     = RARITY_EMOJI.get(c_rarity, "⭐")

        # Verify card still in sender's collection
        cursor.execute("SELECT id FROM user_cards WHERE id=? AND user_id=?", (row_id, user_id))
        if not cursor.fetchone():
            await query.edit_message_caption(caption="❌ Card no longer in your collection!", parse_mode="Markdown")
            return

        # Delete from sender (SQLite)
        cursor.execute("DELETE FROM user_cards WHERE id=?", (row_id,))
        conn.commit()
        # ── Sync MongoDB: delete from sender ─────────────────────────────
        if MONGO_AVAILABLE:
            try:
                if c_master_id:
                    delete_user_card_by_id_mongo(user_id, c_master_id)
                else:
                    delete_user_card_mongo(user_id, c_name, c_rarity, count=1)
            except Exception:
                pass
        # Insert for receiver (SQLite)
        insert_user_card(target_id, c_name, c_rarity, c_file_id,
                         file_type=c_file_type, card_id=c_master_id, source="transfer")
        # ── Sync MongoDB: insert for receiver ────────────────────────────
        if MONGO_AVAILABLE:
            try:
                insert_user_card_mongo(target_id, c_name, c_rarity, c_file_id,
                                       file_type=c_file_type, card_id=c_master_id, series=c_series)
            except Exception:
                pass
        conn.commit()

        await query.edit_message_caption(
            caption=(
                f"🎁 *Gift Sent!*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"{c_emoji} *{c_name.title()}* [{c_rarity}]\n"
                f"📺 {c_series}\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"✅ Card gifted to *{target_name}*!"
            ),
            parse_mode="Markdown"
        )
        try:
            await send_card_media(
                context.bot, c_file_id, file_type=c_file_type,
                caption=(
                    f"🎁 *You received a gift!*\n\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"{c_emoji} *{c_name.title()}* [{c_rarity}]\n"
                    f"📺 {c_series}\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                    f"🎀 Gifted by *{sender_name}*!\n"
                    f"Check `/collection` to see it."
                ),
                parse_mode="Markdown",
                chat_id=target_id
            )
        except Exception:
            pass
        await log_to_group(
            context.bot,
            f"🎁 *Card Gifted*\n\n"
            f"From: *{sender_name}* (`{user_id}`)\n"
            f"To: *{target_name}* (`{target_id}`)\n"
            f"{c_emoji} *{c_name.title()}* [{c_rarity}] — {c_series}"
        )




# ================= OWNER: /remove_cards =================

async def remove_cards_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /remove_cards <user_id/@username> <rarity> <count>
    Owner command — manually remove N cards of a rarity from a user.

    Examples:
      /remove_cards 123456789 Summer 19
      /remove_cards @Sanjay Legendary 5
      /remove_cards 987654 all all       (wipe entire collection of a rarity)
    """
    if not update.effective_user or not update.message:
        return
    if update.effective_user.id not in (OWNER_ID, CO_OWNER_ID):
        return

    args = list(context.args or [])
    if len(args) < 3:
        await update.message.reply_text(
            "🛠️ *Remove Cards — Usage*\n\n"
            "`/remove_cards <user_id/@username> <rarity> <count>`\n\n"
            "*Examples:*\n"
            "`/remove_cards 123456789 Summer 19`\n"
            "`/remove_cards @Sanjay Legendary 5`\n"
            "`/remove_cards 123456789 Summer all` — remove ALL Summer cards\n\n"
            f"*Available rarities:* {', '.join(RARITY_WEIGHTS.keys())}",
            parse_mode="Markdown"
        )
        return

    # Resolve user
    target_arg = args[0]
    if target_arg.startswith("@"):
        uname = target_arg.lstrip("@").lower()
        cursor.execute("SELECT user_id, first_name FROM bot_users WHERE LOWER(username)=? LIMIT 1", (uname,))
        row = cursor.fetchone()
        if not row:
            await update.message.reply_text(f"❌ User `{target_arg}` not found.", parse_mode="Markdown")
            return
        target_id, target_name = row
    else:
        try:
            target_id = int(target_arg)
        except ValueError:
            await update.message.reply_text("❌ Invalid user ID.", parse_mode="Markdown")
            return
        cursor.execute("SELECT first_name FROM bot_users WHERE user_id=?", (target_id,))
        r = cursor.fetchone()
        target_name = r[0] if r else str(target_id)

    rarity_arg = normalize_rarity(args[1])
    count_arg  = args[2].lower()

    # Validate rarity
    if rarity_arg not in RARITY_WEIGHTS:
        await update.message.reply_text(
            f"❌ Unknown rarity: `{rarity_arg}`\n"
            f"Available: {', '.join(RARITY_WEIGHTS.keys())}",
            parse_mode="Markdown"
        )
        return

    # Get current count
    cursor.execute(
        "SELECT COUNT(*) FROM user_cards WHERE user_id=? AND rarity=?",
        (target_id, rarity_arg)
    )
    current_count = cursor.fetchone()[0]

    if current_count == 0:
        await update.message.reply_text(
            f"ℹ️ *{target_name}* has no *{rarity_arg}* cards to remove.",
            parse_mode="Markdown"
        )
        return

    # Resolve count
    if count_arg == "all":
        remove_count = current_count
    else:
        try:
            remove_count = int(count_arg)
        except ValueError:
            await update.message.reply_text("❌ Count must be a number or `all`.", parse_mode="Markdown")
            return
        remove_count = min(remove_count, current_count)

    # Fetch rows to delete (with metadata for MongoDB sync)
    cursor.execute(
        "SELECT id, card_name, rarity, card_id FROM user_cards "
        "WHERE user_id=? AND rarity=? LIMIT ?",
        (target_id, rarity_arg, remove_count)
    )
    rows_to_del = cursor.fetchall()

    # Delete from SQLite
    for rid, cname, crarity, ccid in rows_to_del:
        cursor.execute("DELETE FROM user_cards WHERE id=?", (rid,))
        # Sync MongoDB
        if MONGO_AVAILABLE:
            try:
                if ccid:
                    delete_user_card_by_id_mongo(target_id, ccid)
                else:
                    delete_user_card_mongo(target_id, cname, crarity, count=1)
            except Exception:
                pass
    conn.commit()

    rarity_emoji = RARITY_EMOJI.get(rarity_arg, "⭐")
    remaining = current_count - remove_count

    await update.message.reply_text(
        f"✅ *Cards Removed!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"👤 User: *{target_name}* (`{target_id}`)\n"
        f"{rarity_emoji} Rarity: *{rarity_arg}*\n"
        f"🗑️ Removed: *{remove_count}* cards\n"
        f"📦 Remaining: *{remaining}* cards\n"
        f"━━━━━━━━━━━━━━━━━━━━━━",
        parse_mode="Markdown"
    )

    await log_to_group(
        update.effective_user._bot if hasattr(update.effective_user, '_bot') else update.get_bot(),
        f"🗑️ *Manual Card Removal*\n\n"
        f"👮 By: Owner\n"
        f"👤 From: *{target_name}* (`{target_id}`)\n"
        f"{rarity_emoji} Rarity: *{rarity_arg}*\n"
        f"🗑️ Removed: *{remove_count}* | Remaining: *{remaining}*"
    )

# ================= REFERRAL COMMAND =================

async def _referral_cmd_impl(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    user_name = update.effective_user.first_name or "Shinobi"
    code = get_or_create_referral_code(user_id)
    count = get_referral_count(user_id)

    # Get bot username for the deep link
    try:
        bot_username = context.bot.username            # cached by PTB at start-up: no API call per /referral
    except Exception:
        try:
            bot_username = (await context.bot.get_me()).username
        except Exception:
            bot_username = "YourBot"

    link = f"https://t.me/{bot_username}?start={code}"

    dash = build_referral_dashboard(user_id, count)
    stats = referral_stats(user_id)

    # Names come from the local bot_users table (no Telegram API call per row)
    cursor.execute(
        "SELECT ru.referred_id, bu.first_name FROM referral_uses ru "
        "LEFT JOIN bot_users bu ON bu.user_id = ru.referred_id "
        "WHERE ru.referrer_id=? AND ru.status='pending' ORDER BY ru.timestamp DESC LIMIT ?",
        (user_id, REFERRAL_PENDING_LIST_SIZE)
    )
    pending_rows = cursor.fetchall()
    pending_text = "".join(f"  • {escape_markdown(fname or str(rid), version=1)} — Needs to collect 1 card\n"
                           for rid, fname in pending_rows)
    if stats["pending"] > len(pending_rows):
        pending_text += f"  … and {stats['pending'] - len(pending_rows)} more\n"

    cursor.execute(
        "SELECT ru.referred_id, ru.qualified_at, ru.timestamp, bu.first_name FROM referral_uses ru "
        "LEFT JOIN bot_users bu ON bu.user_id = ru.referred_id "
        "WHERE ru.referrer_id=? AND ru.status IN ('qualified','rewarded') "
        "ORDER BY COALESCE(ru.qualified_at, ru.timestamp) DESC LIMIT 5",
        (user_id,)
    )
    recent_text = ""
    for rid, qts, ts, fname in cursor.fetchall():
        try:
            t = time.strftime("%d/%m/%Y", time.localtime(qts or ts)) if (qts or ts) else "—"
        except Exception:
            t = "—"
        recent_text += f"  • {escape_markdown(fname or str(rid), version=1)} — {t}\n"

    parts = [
        f"🔗 *Your Referral Dashboard*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"👤 Shinobi: *{escape_markdown(user_name, version=1)}*\n"
        f"🏆 Valid Referrals: *{count}*\n"
        f"⏳ Pending Referrals: *{stats['pending']}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"🔗 *Your Referral Link:*\n`{link}`\n\n"
        f"📤 Share it! A referral becomes *valid* when the new user starts the bot through your link "
        f"*and collects their first card* — then you earn rewards!"
    ]
    if dash["next_regular"]:
        parts.append(dash["next_regular"])
    if dash["next_major"]:
        parts.append(dash["next_major"])
    if pending_text:
        parts.append("⏳ *Pending Referrals:*\n" + pending_text.rstrip("\n"))
    if recent_text:
        parts.append("📋 *Recent Valid Referrals:*\n" + recent_text.rstrip("\n"))
    if dash["recent_rewards"]:
        parts.append("🏅 *Recent Rewards:*\n" + dash["recent_rewards"])
    if dash["majors"]:
        parts.append("🏆 *Major Milestones:*\n" + dash["majors"])
    text = "\n\n".join(parts)
    if len(text) > 4000:
        text = text[:3990] + "…"
    try:
        await update.message.reply_text(text, parse_mode="Markdown", disable_web_page_preview=True)
    except BadRequest:
        # Markdown could not be parsed (odd characters in a name/label) -> send as plain text
        # instead of failing silently. The link is kept intact.
        await update.message.reply_text(text.replace("*", "").replace("`", ""), disable_web_page_preview=True)


async def referral_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Never fails silently: any internal error is logged with a traceback and the user still
    gets their referral link."""
    try:
        await _referral_cmd_impl(update, context)
    except Exception:
        print("[REFERRAL] /referral failed:")
        traceback.print_exc()
        try:
            uid = update.effective_user.id
            try:
                conn.rollback()
            except Exception:
                pass
            code = get_or_create_referral_code(uid)
            uname = getattr(context.bot, "username", None) or "Naruto_tcg_bot"
            await update.message.reply_text(
                "🔗 Your Referral Link:\n"
                f"https://t.me/{uname}?start={code}\n\n"
                "Share it! A referral becomes valid when the new user starts the bot through your link "
                "and collects their first card.",
                disable_web_page_preview=True
            )
        except Exception:
            print("[REFERRAL] /referral fallback failed:")
            traceback.print_exc()

# ================= START / STOP DRAFT EVENT (Owner only) =================

async def start_draft_event(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Owner command: /start_draft [days] [Rare:50,Epic:35,Legendary:10,Mythic:3,Spring:2]
    Starts the draft event for <days> days (default 30).
    Example: /start_draft 30 Rare:50,Epic:35,Legendary:10,Mythic:3,Spring:2
    """
    if not update.effective_user or not update.message:
        return
    if update.effective_user.id not in (OWNER_ID, CO_OWNER_ID):
        await update.message.reply_text("🚫 Admin only command.")
        return

    import json

    args = list(context.args or [])
    days = 30
    custom_weights = None
    event_name = None

    if args:
        try:
            days = int(args[0])
            args = args[1:]
        except ValueError:
            pass

    # Check if the next arg looks like a name (no colon) rather than rarity weights
    if args and ":" not in args[0]:
        event_name = args[0].replace("_", " ")
        args = args[1:]

    if args:
        weights_str = " ".join(args)
        try:
            pairs = [p.strip() for p in weights_str.replace(" ", "").split(",")]
            custom_weights = {}
            for pair in pairs:
                rarity, weight = pair.split(":")
                rarity = normalize_rarity(rarity)
                if rarity not in RARITY_EMOJI:
                    await update.message.reply_text(f"❌ Unknown rarity: {rarity}\nExample: /start_draft 30 Rare:50,Epic:35,Legendary:10,Mythic:3,Spring:2")
                    return
                custom_weights[rarity] = int(weight)
        except Exception:
            await update.message.reply_text(
                "❌ Invalid rarity format.\n"
                "Example: /start_draft 30 Rare:50,Epic:35,Legendary:10,Mythic:3,Spring:2"
            )
            return

    now = int(time.time())
    end_ts = now + days * 86400
    weights_to_save = custom_weights if custom_weights else dict(DRAFT_RARITY_WEIGHTS_DEFAULT)

    cursor.execute("INSERT OR REPLACE INTO bot_settings (key, value) VALUES ('draft_active', '1')")
    cursor.execute("INSERT OR REPLACE INTO bot_settings (key, value) VALUES ('draft_start', ?)", (str(now),))
    cursor.execute("INSERT OR REPLACE INTO bot_settings (key, value) VALUES ('draft_end', ?)", (str(end_ts),))
    cursor.execute("INSERT OR REPLACE INTO bot_settings (key, value) VALUES ('draft_rarities', ?)", (json.dumps(weights_to_save),))
    if event_name:
        cursor.execute("INSERT OR REPLACE INTO bot_settings (key, value) VALUES ('draft_event_name', ?)", (event_name,))
    conn.commit()

    load_draft_rarity_weights()
    # Reload event name into global
    global DRAFT_EVENT_NAME
    _name_row = cursor.execute("SELECT value FROM bot_settings WHERE key='draft_event_name'").fetchone()
    DRAFT_EVENT_NAME = _name_row[0] if _name_row else "Draft Event"

    end_str = time.strftime("%d %b %Y %H:%M UTC", time.gmtime(end_ts))
    weight_lines = "\n".join([f"  {RARITY_EMOJI.get(r, '⭐')} {r}: {w}%" for r, w in weights_to_save.items()])

    # Confirm to owner
    await update.message.reply_text(
        f"✅ *Draft Event Started!*\n\n"
        f"⏳ Duration: *{days} days*\n"
        f"🗓️ Ends: *{end_str}*\n\n"
        f"📊 *Drop Rates:*\n{weight_lines}\n\n"
        f"📢 Notifying all users now...",
        parse_mode="Markdown"
    )

    # Broadcast to all users who have interacted with the bot
    cursor.execute("SELECT DISTINCT user_id FROM bot_users")
    users_set = set(r[0] for r in cursor.fetchall())
    cursor.execute("SELECT DISTINCT user_id FROM user_cards")
    users_set.update(r[0] for r in cursor.fetchall())
    users = list(users_set)

    banner_file_id = get_draft_banner_file_id()
    announce_text = (
        f"✨ *{DRAFT_EVENT_NAME.upper()} IS LIVE!* ✨\n\n"
        f"{'━' * 24}\n"
        f"⏳ Event Duration: *{days} days*\n"
        f"🗓️ Ends: *{end_str}*\n"
        f"{'━' * 24}\n\n"
        f"🎰 *Pull rare shinobi cards from the gacha!*\n\n"
        f"📊 *Drop Rates:*\n{weight_lines}\n\n"
        f"🎟️ *How to get vouchers:*\n"
        f"• /daily → +5 vouchers\n"
        f"• /weekly → +5 vouchers\n"
        f"• /monthly → +10 vouchers\n\n"
        f"💎 *Pity System:*\n"
        f"• Every 10th spin → Guaranteed Legendary\n"
        f"• Every 100th spin → Guaranteed {DRAFT_EVENT_NAME} card!\n\n"
        f"👉 Use /draft_event to start spinning! 🔥"
    )

    sent = 0
    failed = 0
    for uid in users:
        try:
            if banner_file_id:
                await context.bot.send_photo(
                    chat_id=uid,
                    photo=banner_file_id,
                    caption=announce_text,
                    parse_mode="Markdown"
                )
            else:
                await context.bot.send_message(
                    chat_id=uid,
                    text=announce_text,
                    parse_mode="Markdown"
                )
            sent += 1
            await asyncio.sleep(0.05)
        except Exception:
            failed += 1

    await update.message.reply_text(
        f"📢 *Broadcast Complete!*\n\n"
        f"📨 Notified: *{sent}* users\n"
        f"❌ Failed: *{failed}* users",
        parse_mode="Markdown"
    )

    await log_to_group(
        context.bot,
        f"🌸 *Draft Event STARTED*\n\n"
        f"⏳ Duration: {days} days\n"
        f"🗓️ Ends: {end_str}\n"
        f"📊 Weights: {json.dumps(weights_to_save)}\n"
        f"📨 Notified: {sent} users\n"
        f"👑 By: {update.effective_user.first_name} (`{update.effective_user.id}`)"
    )


async def stop_draft_event(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner command: /stop_draft — Immediately stops the draft event."""
    if not update.effective_user or not update.message:
        return
    if update.effective_user.id not in (OWNER_ID, CO_OWNER_ID):
        await update.message.reply_text("🚫 Admin only command.")
        return

    cursor.execute("INSERT OR REPLACE INTO bot_settings (key, value) VALUES ('draft_active', '0')")
    conn.commit()

    await update.message.reply_text(
        "🛑 *Draft Event Stopped!*\n\n"
        "The draft event has been manually ended.\n"
        "📢 Notifying all users...\n\n"
        "Use /start_draft to start a new one anytime.",
        parse_mode="Markdown"
    )

    # Broadcast stop to all users
    cursor.execute("SELECT DISTINCT user_id FROM bot_users")
    users_set = set(r[0] for r in cursor.fetchall())
    cursor.execute("SELECT DISTINCT user_id FROM user_cards")
    users_set.update(r[0] for r in cursor.fetchall())
    users = list(users_set)

    announce_text = (
        "🛑 *The Spring Blossom Draft Event Has Ended!*\n\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        "🌸 Thank you for participating, shinobi!\n\n"
        "💼 Your collected cards and vouchers are safe in your vault.\n\n"
        "🔔 Stay tuned — the next event is coming soon!\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        "Keep grinding! ⚔️🔥"
    )

    sent = 0
    failed = 0
    for uid in users:
        try:
            await context.bot.send_message(
                chat_id=uid,
                text=announce_text,
                parse_mode="Markdown"
            )
            sent += 1
            await asyncio.sleep(0.05)
        except Exception:
            failed += 1

    await update.message.reply_text(
        f"📢 *Stop Broadcast Complete!*\n\n"
        f"📨 Notified: *{sent}* users\n"
        f"❌ Failed: *{failed}* users",
        parse_mode="Markdown"
    )

    await log_to_group(
        context.bot,
        f"🛑 *Draft Event STOPPED*\n"
        f"📨 Notified: {sent} users\n"
        f"👑 By: {update.effective_user.first_name} (`{update.effective_user.id}`)"
    )


# ================= /REC_ACC (Admin/Owner) — Restore deleted collection =================

async def rec_acc(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /rec_acc <user_id>  OR  reply to user's message with /rec_acc
    Restores ALL cards backed up by /delacc for a user.
    Supports: replying to the user's message (no args needed).
    """
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admins only.")
        return

    # Determine target user — reply takes priority over args
    target_id = None
    target_name = None

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        target_id = update.message.reply_to_message.from_user.id
        target_name = (
            update.message.reply_to_message.from_user.first_name or str(target_id)
        )
    elif context.args:
        try:
            target_id = int(context.args[0])
        except ValueError:
            await update.message.reply_text("❌ Usage: /rec_acc <user_id>")
            return
    else:
        await update.message.reply_text(
            "Usage:\n"
            "• /rec_acc <user_id>\n"
            "• Reply to the user's message with /rec_acc\n\n"
            "Restores the user's collection from the last /delacc backup."
        )
        return

    # Try to get name if we don't have it yet
    if not target_name:
        try:
            tc = await context.bot.get_chat(target_id)
            target_name = tc.first_name or str(target_id)
        except Exception:
            target_name = str(target_id)

    # Fetch all backup records for this user
    cursor.execute("""
        SELECT card_name, rarity, file_id FROM deleted_cards_backup
        WHERE user_id = ?
        ORDER BY deleted_at ASC
    """, (target_id,))
    backups = cursor.fetchall()

    # Fetch voucher backup
    cursor.execute("""
        SELECT vouchers, total_spins, spins_since_legendary, spins_since_spring
        FROM deleted_vouchers_backup WHERE user_id = ?
    """, (target_id,))
    voucher_backup = cursor.fetchone()

    if not backups and not voucher_backup:
        await update.message.reply_text(
            f"📭 *No backup found for {target_name}* (`{target_id}`).\n\n"
            f"Either their account was never deleted via /delacc,\n"
            f"or an older deletion didn't save a backup.",
            parse_mode="Markdown"
        )
        return

    # ── Restore cards ─────────────────────────────────────────────────────────
    restored = 0
    for card_name, rarity, file_id in backups:
        insert_user_card(target_id, card_name, rarity, file_id, source="restore")
        restored += 1

    # ── Restore vouchers & spin stats ─────────────────────────────────────────
    restored_vouchers = 0
    if voucher_backup:
        v, total_spins, since_leg, since_spring = voucher_backup
        restored_vouchers = v
        cursor.execute("""
            INSERT OR REPLACE INTO draft_vouchers
            (user_id, vouchers, total_spins, spins_since_legendary, spins_since_spring)
            VALUES (?, ?, ?, ?, ?)
        """, (target_id, v, total_spins, since_leg, since_spring))
        # Clear voucher backup
        cursor.execute("DELETE FROM deleted_vouchers_backup WHERE user_id=?", (target_id,))

    # Clear card backup records after restoring
    cursor.execute("DELETE FROM deleted_cards_backup WHERE user_id=?", (target_id,))
    conn.commit()

    await update.message.reply_text(
        f"✅ *Account Recovery Complete!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"👤 User: *{target_name}* (`{target_id}`)\n"
        f"🃏 Cards Restored: *{restored}*\n"
        f"🎟️ Vouchers Restored: *{restored_vouchers}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"🏆 Full account returned to their vault!",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🔄 *Account Recovery*\n\n"
        f"👤 For: {target_name} (`{target_id}`)\n"
        f"🃏 Cards Restored: {restored}\n"
        f"🎟️ Vouchers Restored: {restored_vouchers}\n"
        f"👑 By: {update.effective_user.first_name} (`{update.effective_user.id}`)"
    )

    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=(
                f"🎉 *Your account has been fully recovered!*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"🃏 Cards Restored: *{restored}*\n"
                f"🎟️ Draft Vouchers Restored: *{restored_vouchers}*\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"⚔️ Use /collection to view your cards!\n"
                f"🌸 Use /view\\_drafts to check your vouchers!"
            ),
            parse_mode="Markdown"
        )
    except Exception:
        pass


# ================= /GIVE_ALL — Give cards or vouchers to ALL users (Owner only) =================

async def give_all(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Owner only: /give_all <type> <value> <reason>

    Types:
      vouchers <amount> <reason>
        → Give X draft vouchers to every registered user
        → Example: /give_all vouchers 10 Event celebration reward!

      card <card_id> <reason>
        → Give a specific card to every registered user
        → Example: /give_all card 42 Anniversary gift for all shinobis!
    """
    if not update.effective_user or not update.message:
        return

    # Owner only
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 This command is for the *owner* only.", parse_mode="Markdown")
        return

    if not context.args or len(context.args) < 3:
        await update.message.reply_text(
            "📖 *Usage:*\n\n"
            "Give vouchers to all users:\n"
            "`/give_all vouchers <amount> <reason>`\n"
            "_Example: /give_all vouchers 10 Spring event reward!_\n\n"
            "Give a card to all users:\n"
            "`/give_all card <card_id> <reason>`\n"
            "_Example: /give_all card 42 Anniversary gift!_\n\n"
            "⚠️ This affects *every registered user* in the bot.",
            parse_mode="Markdown"
        )
        return

    give_type = context.args[0].lower()
    reason = " ".join(context.args[2:]).strip()

    if not reason:
        await update.message.reply_text("❌ Please provide a reason. Example:\n`/give_all vouchers 10 Happy new year!`", parse_mode="Markdown")
        return

    # ── Fetch all registered users ────────────────────────────────────────────
    cursor.execute("SELECT user_id, first_name FROM bot_users")
    all_users = cursor.fetchall()

    if not all_users:
        await update.message.reply_text("⚠️ No registered users found.")
        return

    owner_name = update.effective_user.first_name or "Owner"

    # ════════════════════════════════════════════════════════════
    # VOUCHERS
    # ════════════════════════════════════════════════════════════
    if give_type == "vouchers":
        try:
            amount = int(context.args[1])
            if amount <= 0:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ Amount must be a positive number.")
            return

        await update.message.reply_text(
            f"⏳ *Distributing {amount} vouchers to {len(all_users)} users...*\n\n"
            f"📋 Reason: _{reason}_\n\n"
            f"Please wait...",
            parse_mode="Markdown"
        )

        success = 0
        failed = 0
        for uid, fname in all_users:
            try:
                add_vouchers(uid, amount)
                success += 1
            except Exception as e:
                print(f"[GIVE_ALL] Voucher error for {uid}: {e}")
                failed += 1

        conn.commit()

        # Notify all users
        notified = 0
        notify_failed = 0
        for uid, fname in all_users:
            try:
                total_v = get_user_vouchers(uid)
                await context.bot.send_message(
                    chat_id=uid,
                    text=(
                        f"🎁 *Special Gift from the Owner!*\n\n"
                        f"━━━━━━━━━━━━━━━━━━━━━━\n"
                        f"🎟️ *+{amount} Draft Vouchers* have been added to your wallet!\n"
                        f"💼 Your total vouchers: *{total_v}*\n"
                        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                        f"📋 *Reason:* {reason}\n\n"
                        f"🌸 Use /draft\\_event to spin!\n"
                        f"⚔️ — {owner_name}"
                    ),
                    parse_mode="Markdown"
                )
                notified += 1
                await asyncio.sleep(0.05)
            except Exception:
                notify_failed += 1

        await update.message.reply_text(
            f"✅ *Voucher Distribution Complete!*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🎟️ Amount: *+{amount}* vouchers each\n"
            f"👥 Total Users: *{len(all_users)}*\n"
            f"✅ Credited: *{success}*\n"
            f"📨 Notified: *{notified}*\n"
            f"❌ Failed: *{notify_failed}*\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"📋 Reason: _{reason}_",
            parse_mode="Markdown"
        )
        await log_to_group(
            context.bot,
            f"🎁 *Give All — Vouchers*\n\n"
            f"👑 By: {owner_name} (`{update.effective_user.id}`)\n"
            f"🎟️ Amount: +{amount} each\n"
            f"👥 Users: {len(all_users)}\n"
            f"📋 Reason: {reason}"
        )

    # ════════════════════════════════════════════════════════════
    # CARD
    # ════════════════════════════════════════════════════════════
    elif give_type == "card":
        try:
            card_id = int(context.args[1].replace("#", ""))
        except ValueError:
            await update.message.reply_text("❌ Invalid card ID. Example:\n`/give_all card 42 Anniversary gift!`", parse_mode="Markdown")
            return

        cursor.execute("SELECT name, rarity, file_id FROM cards WHERE id=?", (card_id,))
        card = cursor.fetchone()
        if not card:
            await update.message.reply_text(f"❌ No card found with ID #{card_id}.")
            return

        card_name, rarity, file_id = card
        emoji = RARITY_EMOJI.get(rarity, "⭐")

        await update.message.reply_text(
            f"⏳ *Distributing card to {len(all_users)} users...*\n\n"
            f"🥷 Card: *{card_name.title()}* {emoji}\n"
            f"📋 Reason: _{reason}_\n\n"
            f"Please wait...",
            parse_mode="Markdown"
        )

        success = 0
        failed = 0
        for uid, fname in all_users:
            try:
                insert_user_card(uid, card_name, rarity, file_id)
                success += 1
            except Exception as e:
                print(f"[GIVE_ALL] Card error for {uid}: {e}")
                failed += 1

        conn.commit()

        # Notify all users
        notified = 0
        notify_failed = 0
        for uid, fname in all_users:
            try:
                await context.bot.send_photo(
                    chat_id=uid,
                    photo=file_id,
                    caption=(
                        f"🎁 *Special Gift from the Owner!*\n\n"
                        f"━━━━━━━━━━━━━━━━━━━━━━\n"
                        f"🥷 *{card_name.title()}* has been added to your collection!\n"
                        f"{emoji} Rarity: *{rarity}*\n"
                        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                        f"📋 *Reason:* {reason}\n\n"
                        f"⚔️ Use /collection to view your vault!\n"
                        f"🍃 — {owner_name}"
                    ),
                    parse_mode="Markdown"
                )
                notified += 1
                await asyncio.sleep(0.05)
            except Exception:
                notify_failed += 1

        await update.message.reply_text(
            f"✅ *Card Distribution Complete!*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🥷 Card: *{card_name.title()}* {emoji}\n"
            f"🔮 Rarity: *{rarity}*\n"
            f"👥 Total Users: *{len(all_users)}*\n"
            f"✅ Added to: *{success}*\n"
            f"📨 Notified: *{notified}*\n"
            f"❌ Failed: *{notify_failed}*\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"📋 Reason: _{reason}_",
            parse_mode="Markdown"
        )
        await log_to_group(
            context.bot,
            f"🎁 *Give All — Card*\n\n"
            f"👑 By: {owner_name} (`{update.effective_user.id}`)\n"
            f"🥷 Card: #{card_id} {card_name} [{rarity}]\n"
            f"👥 Users: {len(all_users)}\n"
            f"📋 Reason: {reason}"
        )

    else:
        await update.message.reply_text(
            "❌ Unknown type. Use:\n"
            "`/give_all vouchers <amount> <reason>`\n"
            "`/give_all card <card_id> <reason>`",
            parse_mode="Markdown"
        )


# =====================================================================
# 👑  OWNER PANEL — /owner_panel
# Complete interactive control panel for the bot owner.
# Controls: spawn, coins, rewards, shop, sell values, weights,
#           event management, bot stats, broadcast, maintenance.
# =====================================================================

# ── Helpers ───────────────────────────────────────────────────────────────────

def panel_get(key: str, default: str = None) -> str:
    try:
        cursor.execute("SELECT value FROM bot_settings WHERE key=?", (f"panel_{key}",))
        row = cursor.fetchone()
        return row[0] if row else default
    except Exception:
        return default

def panel_set(key: str, value: str):
    try:
        cursor.execute(
            "INSERT OR REPLACE INTO bot_settings (key, value) VALUES (?, ?)",
            (f"panel_{key}", str(value))
        )
        conn.commit()
    except Exception as e:
        print(f"[PANEL] set error: {e}")

# ── Apply saved settings on startup ──────────────────────────────────────────

def apply_panel_settings():
    global MILESTONE_CYCLE, COIN_DAILY_AMOUNT, COIN_WEEKLY_AMOUNT, COIN_MONTHLY_AMOUNT
    global PACK_LIMIT_PER_DAY, ENCOUNTER_DURATION, WEEKLY_PASS_COST
    global AIRDROP_FREE_COOLDOWN, AIRDROP_AD_COOLDOWN

    for key, gname, minv, maxv in [
        ("spawn_cycle",        "MILESTONE_CYCLE",       500,   10000),
        ("coin_daily",         "COIN_DAILY_AMOUNT",      50,   50000),
        ("coin_weekly",        "COIN_WEEKLY_AMOUNT",    100,  100000),
        ("coin_monthly",       "COIN_MONTHLY_AMOUNT",   200,  200000),
        ("pack_limit",         "PACK_LIMIT_PER_DAY",      1,      20),
        ("encounter_dur",      "ENCOUNTER_DURATION",     30,     600),
        ("weekly_pass_cost",   "WEEKLY_PASS_COST",      500,  100000),
        ("airdrop_free_cd",    "AIRDROP_FREE_COOLDOWN", 3600, 172800),
        ("airdrop_ad_cd",      "AIRDROP_AD_COOLDOWN",    60,   86400),
    ]:
        val = panel_get(key)
        if val and val.isdigit():
            v = max(minv, min(maxv, int(val)))
            globals()[gname] = v

    # Restore per-rarity coin/shop/sell values from JSON
    import json as _j
    for store_key, target_dict in [
        ("rarity_coins",    RARITY_COINS),
        ("shop_prices",     SHOP_PRICES),
        ("sell_values",     SELL_COIN_VALUES),
    ]:
        raw = panel_get(store_key)
        if raw:
            try:
                saved = _j.loads(raw)
                for k, v in saved.items():
                    if k in target_dict:
                        target_dict[k] = v
            except Exception:
                pass

    print(f"[PANEL] Settings loaded. Spawn cycle={MILESTONE_CYCLE}")

# ── Panel text ────────────────────────────────────────────────────────────────

def get_panel_text():
    cycle      = panel_get("spawn_cycle", str(MILESTONE_CYCLE))
    summer     = panel_get("summer_spawn", "OFF")
    fifa_spawn = panel_get("fifa_spawn", "OFF")
    op_shop    = panel_get("shop_onepiece",    "ON")
    bl_shop    = panel_get("shop_bleach",      "ON")
    ds_shop    = panel_get("shop_demonslayer", "ON")
    bot_on     = panel_get("bot_enabled",      "ON")
    spawn_w    = {k: v for k, v in RARITY_WEIGHTS.items()
                  if k not in ("Animation","LeaderBoard","Summer","Academy","FIFA","Crossverse","Spring")}
    sw_line    = " | ".join(f"{RARITY_EMOJI.get(r,'⭐')}{r}:{v}%" for r, v in spawn_w.items())
    dw_line    = " | ".join(f"{RARITY_EMOJI.get(r,'⭐')}{r}:{v}%" for r, v in DRAFT_RARITY_WEIGHTS.items() if v > 0)
    bot_icon   = "🟢" if bot_on == "ON" else "🔴"

    return (
        "👑 *OWNER CONTROL PANEL*\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"{bot_icon} *Bot Status:* `{bot_on}`\n"
        f"🌀 *Spawn Cycle:* every `{cycle}` msgs  |  ☀️ Summer: `{summer}`  |  ⚽ FIFA: `{fifa_spawn}`\n"
        f"🕐 *Card Timeout:* `{ENCOUNTER_DURATION}s`\n\n"
        "💰 *Coin Rewards:*\n"
        f"  📅 Daily `{COIN_DAILY_AMOUNT}` | 📆 Weekly `{COIN_WEEKLY_AMOUNT}` | 🗓️ Monthly `{COIN_MONTHLY_AMOUNT}`\n\n"
        "📦 *Packs & Pass:*\n"
        f"  Pack limit `{PACK_LIMIT_PER_DAY}/day` | Weekly Pass `{WEEKLY_PASS_COST:,}` 🪙\n\n"
        f"🛒 *Collab:* OP `{op_shop}` | Bleach `{bl_shop}` | DS `{ds_shop}`\n"
        f"🛒 *Naruto:* FIFA `{panel_get('shop_fifa','ON')}` | Summer `{panel_get('shop_summer_naruto','ON')}` | Spring `{panel_get('shop_spring','ON')}`\n\n"
        f"⚖️ *Spawn:* `{sw_line}`\n"
        f"🎴 *Draft:* `{dw_line}`\n"
        "━━━━━━━━━━━━━━━━━━━━━━"
    )

