# ── Weights keyboard ──────────────────────────────────────────────────────────

def build_weights_keyboard(weight_type: str):
    if weight_type == "spawn":
        weights = {k: v for k, v in RARITY_WEIGHTS.items()
                   if k not in ("Animation","LeaderBoard","Summer","Academy","FIFA","Crossverse","Spring")}
    elif weight_type == "draft":
        weights = DRAFT_RARITY_WEIGHTS
    else:
        weights = COLLAB_RARITY_WEIGHTS

    keyboard = []
    for rarity, weight in weights.items():
        emoji = RARITY_EMOJI.get(rarity, "⭐")
        keyboard.append([
            InlineKeyboardButton(f"{emoji} {rarity}: {weight}%", callback_data="op_noop"),
            InlineKeyboardButton("➖", callback_data=f"op_w_{weight_type}_{rarity}_minus"),
            InlineKeyboardButton("➕", callback_data=f"op_w_{weight_type}_{rarity}_plus"),
        ])
    keyboard.append([InlineKeyboardButton("🔙 Back", callback_data="op_back")])
    return InlineKeyboardMarkup(keyboard)

# ── Prices keyboard ───────────────────────────────────────────────────────────

def build_prices_keyboard(price_type: str):
    if price_type == "shop":
        prices = SHOP_PRICES
        label  = "💴 Shop Prices"
    elif price_type == "sell":
        prices = SELL_COIN_VALUES
        label  = "💸 Sell Values"
    else:
        prices = RARITY_COINS
        label  = "🪙 Catch Coin Values"

    keyboard = [[InlineKeyboardButton(f"[ {label} ]", callback_data="op_noop")]]
    for rarity, price in prices.items():
        emoji = RARITY_EMOJI.get(rarity, "⭐")
        keyboard.append([
            InlineKeyboardButton(f"{emoji} {rarity}: {price:,}", callback_data="op_noop"),
            InlineKeyboardButton("➖100", callback_data=f"op_p_{price_type}_{rarity}_minus_100"),
            InlineKeyboardButton("➕100", callback_data=f"op_p_{price_type}_{rarity}_plus_100"),
            InlineKeyboardButton("➕500", callback_data=f"op_p_{price_type}_{rarity}_plus_500"),
        ])
    keyboard.append([InlineKeyboardButton("🔙 Back", callback_data="op_back")])
    return InlineKeyboardMarkup(keyboard)

