# ── /owner_panel command ──────────────────────────────────────────────────────

async def owner_panel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user or not update.message:
        return
    if update.effective_user.id not in (OWNER_ID, CO_OWNER_ID):
        await update.message.reply_text("🚫 Owner only.")
        return
    await update.message.reply_text(
        get_panel_text(), parse_mode="Markdown",
        reply_markup=build_owner_panel_keyboard()
    )

# ── Callback handler ──────────────────────────────────────────────────────────

async def owner_panel_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query or not query.data:
        return
    if update.effective_user.id not in (OWNER_ID, CO_OWNER_ID):
        await query.answer("🚫 Owner only!", show_alert=True)
        return

    await query.answer()
    data = query.data
    global COIN_DAILY_AMOUNT, COIN_WEEKLY_AMOUNT, COIN_MONTHLY_AMOUNT
    global PACK_LIMIT_PER_DAY, ENCOUNTER_DURATION, WEEKLY_PASS_COST
    global AIRDROP_FREE_COOLDOWN, AIRDROP_AD_COOLDOWN

    async def refresh():
        try:
            await query.edit_message_text(
                get_panel_text(), parse_mode="Markdown",
                reply_markup=build_owner_panel_keyboard()
            )
        except Exception:
            pass

    # ── Noop / close / back ───────────────────────────────────────────────────
    if data == "op_noop":
        return
    if data == "op_close":
        try: await query.message.delete()
        except Exception: pass
        return
    if data == "op_back":
        await refresh(); return

    # ── Reload ────────────────────────────────────────────────────────────────
    if data == "op_reload":
        apply_panel_settings()
        load_draft_rarity_weights()
        await refresh(); return

    # ── Bot ON/OFF toggle ─────────────────────────────────────────────────────
    if data == "op_toggle_bot":
        cur = panel_get("bot_enabled", "ON")
        panel_set("bot_enabled", "OFF" if cur == "ON" else "ON")
        await refresh(); return

    # ── Bot stats ─────────────────────────────────────────────────────────────
    if data == "op_stats":
        cursor.execute("SELECT COUNT(DISTINCT user_id) FROM user_cards")
        active = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM user_cards")
        total_uc = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM bot_users")
        reg = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM cards")
        card_defs = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM bot_groups")
        groups = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM banned_users")
        banned = cursor.fetchone()[0]
        cursor.execute("SELECT SUM(vouchers) FROM draft_vouchers")
        row = cursor.fetchone(); total_v = row[0] or 0 if row else 0
        cursor.execute("SELECT SUM(coins) FROM shinobi_coins")
        row = cursor.fetchone(); total_coins = row[0] or 0 if row else 0
        try:
            await query.edit_message_text(
                "📊 *Bot Statistics*\n"
                "━━━━━━━━━━━━━━━━━━━━━━\n"
                f"👥 Registered users: `{reg}`\n"
                f"🃏 Users with cards: `{active}`\n"
                f"🎴 Total card entries: `{total_uc}`\n"
                f"📚 Card definitions: `{card_defs}`\n"
                f"🏘️ Active groups: `{groups}`\n"
                f"🚫 Banned users: `{banned}`\n"
                f"🎟️ Total vouchers in circulation: `{total_v}`\n"
                f"🪙 Total coins in circulation: `{total_coins:,}`\n"
                "━━━━━━━━━━━━━━━━━━━━━━",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="op_back")]]),
            )
        except Exception:
            pass
        return

    # ── Banned list ───────────────────────────────────────────────────────────
    if data == "op_banned_list":
        cursor.execute("SELECT user_id, reason FROM banned_users LIMIT 20")
        rows = cursor.fetchall()
        if rows:
            lines = "\n".join(f"• `{r[0]}` — {r[1] or 'no reason'}" for r in rows)
        else:
            lines = "_No banned users_"
        try:
            await query.edit_message_text(
                f"🚫 *Banned Users* (max 20 shown)\n\n{lines}",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="op_back")]]),
            )
        except Exception:
            pass
        return

    # ── Spawn cycle ───────────────────────────────────────────────────────────
    if data in ("op_cycle_plus500","op_cycle_minus500","op_cycle_plus100","op_cycle_minus100"):
        global MILESTONE_CYCLE
        cur = int(panel_get("spawn_cycle", str(MILESTONE_CYCLE)))
        delta = {"op_cycle_plus500":500,"op_cycle_minus500":-500,
                 "op_cycle_plus100":100,"op_cycle_minus100":-100}[data]
        MILESTONE_CYCLE = max(500, min(10000, cur + delta))
        panel_set("spawn_cycle", str(MILESTONE_CYCLE))
        await refresh(); return

    # ── Summer toggle ─────────────────────────────────────────────────────────
    if data == "op_toggle_summer":
        panel_set("summer_spawn", "ON" if panel_get("summer_spawn","OFF")=="OFF" else "OFF")
        await refresh(); return

    # ── FIFA toggle (Bug 4 fix) ───────────────────────────────────────────────
    if data == "op_toggle_fifa_spawn":
        panel_set("fifa_spawn", "ON" if panel_get("fifa_spawn","OFF")=="OFF" else "OFF")
        await refresh(); return

    # ── Shop toggles ──────────────────────────────────────────────────────────
    _shop_map = {"op_shop_onepiece":     "shop_onepiece",
                 "op_shop_bleach":       "shop_bleach",
                 "op_shop_demonslayer":  "shop_demonslayer",
                 "op_shop_fifa":         "shop_fifa",
                 "op_shop_summer_naruto":"shop_summer_naruto",
                 "op_shop_spring":       "shop_spring"}
    if data in _shop_map:
        k = _shop_map[data]
        panel_set(k, "OFF" if panel_get(k,"ON")=="ON" else "ON")
        await refresh(); return

    # ── Encounter duration quick view ─────────────────────────────────────────
    if data == "op_encounter_view":
        data = "op_int_encounter_dur_view"   # fall through to int editor below

    # ── Int editor — open ─────────────────────────────────────────────────────
    _int_cfg = {
        "coin_daily":        (COIN_DAILY_AMOUNT,    50,  500,  "📅 Daily Coins"),
        "coin_weekly":       (COIN_WEEKLY_AMOUNT,   100, 1000, "📆 Weekly Coins"),
        "coin_monthly":      (COIN_MONTHLY_AMOUNT,  200, 2000, "🗓️ Monthly Coins"),
        "pack_limit":        (PACK_LIMIT_PER_DAY,   1,   5,    "📦 Pack Limit/Day"),
        "encounter_dur":     (ENCOUNTER_DURATION,   10,  60,   "🕐 Card Timeout (s)"),
        "weekly_pass_cost":  (WEEKLY_PASS_COST,     500, 2000, "🎟️ Weekly Pass Cost"),
        "airdrop_free_cd":   (AIRDROP_FREE_COOLDOWN//3600, 1, 12, "⏳ Airdrop Free CD (hrs)"),
        "airdrop_ad_cd":     (AIRDROP_AD_COOLDOWN//60,     1, 60, "⏳ Airdrop Ad CD (mins)"),
    }
    if data.endswith("_view") and data.startswith("op_int_"):
        key = data[len("op_int_"):-len("_view")]
        if key in _int_cfg:
            default_val, ss, sb, label = _int_cfg[key]
            saved = panel_get(key)
            # for time-based keys stored as raw seconds, convert for display
            if key == "airdrop_free_cd":
                cur_val = int(panel_get("airdrop_free_cd", str(AIRDROP_FREE_COOLDOWN))) // 3600
            elif key == "airdrop_ad_cd":
                cur_val = int(panel_get("airdrop_ad_cd", str(AIRDROP_AD_COOLDOWN))) // 60
            else:
                cur_val = int(saved) if (saved and saved.isdigit()) else default_val
            try:
                await query.edit_message_text(
                    f"⚙️ *{label}*\n\nCurrent: `{cur_val:,}`",
                    parse_mode="Markdown",
                    reply_markup=build_int_editor_keyboard(key, cur_val, ss, sb, label),
                )
            except Exception:
                pass
        return

    # ── Int editor — adjust ───────────────────────────────────────────────────
    if data.startswith("op_int_") and ("_plus_" in data or "_minus_" in data):
        remainder = data[len("op_int_"):]
        if "_plus_" in remainder:
            key, step_s = remainder.rsplit("_plus_", 1)
            direction = 1
        else:
            key, step_s = remainder.rsplit("_minus_", 1)
            direction = -1
        step = int(step_s)

        # display limits (these are display units, raw stored)
        limits = {
            "coin_daily":       (50,   50000,  None),
            "coin_weekly":      (100,  100000, None),
            "coin_monthly":     (200,  200000, None),
            "pack_limit":       (1,    20,     None),
            "encounter_dur":    (30,   600,    None),
            "weekly_pass_cost": (500,  100000, None),
            "airdrop_free_cd":  (1,    48,     None),   # hours
            "airdrop_ad_cd":    (1,    120,    None),   # minutes
        }
        if key not in limits:
            return
        minv, maxv, _ = limits[key]

        # get current display value
        if key == "airdrop_free_cd":
            cur_disp = int(panel_get("airdrop_free_cd", str(AIRDROP_FREE_COOLDOWN))) // 3600
        elif key == "airdrop_ad_cd":
            cur_disp = int(panel_get("airdrop_ad_cd", str(AIRDROP_AD_COOLDOWN))) // 60
        else:
            saved = panel_get(key)
            g_map = {
                "coin_daily": COIN_DAILY_AMOUNT, "coin_weekly": COIN_WEEKLY_AMOUNT,
                "coin_monthly": COIN_MONTHLY_AMOUNT, "pack_limit": PACK_LIMIT_PER_DAY,
                "encounter_dur": ENCOUNTER_DURATION, "weekly_pass_cost": WEEKLY_PASS_COST,
            }
            cur_disp = int(saved) if (saved and saved.isdigit()) else g_map[key]

        new_disp = max(minv, min(maxv, cur_disp + direction * step))

        # store and apply
        if key == "airdrop_free_cd":
            raw = new_disp * 3600
            panel_set("airdrop_free_cd", str(raw)); AIRDROP_FREE_COOLDOWN = raw
        elif key == "airdrop_ad_cd":
            raw = new_disp * 60
            panel_set("airdrop_ad_cd", str(raw)); AIRDROP_AD_COOLDOWN = raw
        else:
            panel_set(key, str(new_disp))
            if key == "coin_daily":      COIN_DAILY_AMOUNT   = new_disp
            elif key == "coin_weekly":   COIN_WEEKLY_AMOUNT  = new_disp
            elif key == "coin_monthly":  COIN_MONTHLY_AMOUNT = new_disp
            elif key == "pack_limit":    PACK_LIMIT_PER_DAY  = new_disp
            elif key == "encounter_dur": ENCOUNTER_DURATION  = new_disp
            elif key == "weekly_pass_cost": WEEKLY_PASS_COST = new_disp

        labels_map = {
            "coin_daily":"📅 Daily Coins","coin_weekly":"📆 Weekly Coins",
            "coin_monthly":"🗓️ Monthly Coins","pack_limit":"📦 Pack Limit/Day",
            "encounter_dur":"🕐 Card Timeout (s)","weekly_pass_cost":"🎟️ Weekly Pass Cost",
            "airdrop_free_cd":"⏳ Airdrop Free CD (hrs)","airdrop_ad_cd":"⏳ Airdrop Ad CD (mins)",
        }
        steps_map = {
            "coin_daily":(50,500),"coin_weekly":(100,1000),"coin_monthly":(200,2000),
            "pack_limit":(1,5),"encounter_dur":(10,60),"weekly_pass_cost":(500,2000),
            "airdrop_free_cd":(1,12),"airdrop_ad_cd":(1,60),
        }
        ss, sb = steps_map[key]
        try:
            await query.edit_message_reply_markup(
                reply_markup=build_int_editor_keyboard(key, new_disp, ss, sb, labels_map[key])
            )
        except Exception:
            pass
        return

    # ── Weights editor — open ─────────────────────────────────────────────────
    if data in ("op_weights_spawn","op_weights_draft","op_weights_collab"):
        wtype = data.replace("op_weights_","")
        try:
            await query.edit_message_text(
                f"⚖️ *Edit {wtype.title()} Weights*\n\nUse ➕/➖ to adjust. Changes apply instantly.",
                parse_mode="Markdown",
                reply_markup=build_weights_keyboard(wtype),
            )
        except Exception:
            pass
        return

    # ── Weights — adjust ─────────────────────────────────────────────────────
    if data.startswith("op_w_"):
        parts     = data.split("_")
        wtype     = parts[2]
        direction = parts[-1]
        rarity    = "_".join(parts[3:-1])

        global DRAFT_RARITY_WEIGHTS, COLLAB_RARITY_WEIGHTS
        wd = RARITY_WEIGHTS if wtype=="spawn" else (DRAFT_RARITY_WEIGHTS if wtype=="draft" else COLLAB_RARITY_WEIGHTS)

        if rarity in wd:
            wd[rarity] = min(99, wd[rarity]+1) if direction=="plus" else max(0, wd[rarity]-1)
            import json as _j
            if wtype == "draft":
                cursor.execute("INSERT OR REPLACE INTO bot_settings (key,value) VALUES ('draft_rarities',?)",
                               (_j.dumps(DRAFT_RARITY_WEIGHTS),))
            elif wtype == "collab":
                cursor.execute("INSERT OR REPLACE INTO bot_settings (key,value) VALUES ('collab_draft_rarities',?)",
                               (_j.dumps(COLLAB_RARITY_WEIGHTS),))
            conn.commit()
        try:
            await query.edit_message_reply_markup(reply_markup=build_weights_keyboard(wtype))
        except Exception:
            pass
        return

    # ── Prices — open ─────────────────────────────────────────────────────────
    if data in ("op_prices_shop","op_prices_sell","op_prices_rarity_coins"):
        ptype = {"op_prices_shop":"shop","op_prices_sell":"sell","op_prices_rarity_coins":"rarity_coins"}[data]
        try:
            await query.edit_message_text(
                f"💴 *Edit Prices — {ptype.replace('_',' ').title()}*\n\nUse ➕/➖ to adjust.",
                parse_mode="Markdown",
                reply_markup=build_prices_keyboard(ptype),
            )
        except Exception:
            pass
        return

    # ── Prices — adjust ───────────────────────────────────────────────────────
    if data.startswith("op_p_"):
        # format: op_p_{type}_{rarity}_{dir}_{step}
        parts  = data[5:].split("_")
        ptype  = parts[0]
        step   = int(parts[-1])
        dirstr = parts[-2]
        rarity = "_".join(parts[1:-2])
        delta  = step if dirstr=="plus" else -step

        import json as _j
        pd = SHOP_PRICES if ptype=="shop" else (SELL_COIN_VALUES if ptype=="sell" else RARITY_COINS)
        if rarity in pd:
            pd[rarity] = max(0, pd[rarity] + delta)
            # persist
            store_key = "shop_prices" if ptype=="shop" else ("sell_values" if ptype=="sell" else "rarity_coins")
            panel_set(store_key, _j.dumps(pd))
        try:
            await query.edit_message_reply_markup(reply_markup=build_prices_keyboard(ptype))
        except Exception:
            pass
        return

    # ── Event status ──────────────────────────────────────────────────────────
    if data == "op_event_status":
        active = is_draft_event_active()
        name   = DRAFT_EVENT_NAME
        import datetime
        try:
            end_dt = datetime.datetime.fromisoformat(panel_get("draft_end","")).strftime("%Y-%m-%d %H:%M") if panel_get("draft_end") else "not set"
        except Exception:
            end_dt = "not set"
        dw = " | ".join(f"{RARITY_EMOJI.get(r,'⭐')}{r}:{v}%" for r,v in DRAFT_RARITY_WEIGHTS.items() if v>0)
        try:
            await query.edit_message_text(
                f"🎉 *Event Status*\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"Name: `{name}`\n"
                f"Active: `{'✅ YES' if active else '❌ NO'}`\n"
                f"Ends: `{end_dt}`\n\n"
                f"🎴 Draft weights:\n`{dw}`\n\n"
                f"Use `/start_draft` to start a new event.\nUse `/end_draft` to end it.",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("🔚 End Event Now", callback_data="op_event_end")],
                    [InlineKeyboardButton("🔙 Back", callback_data="op_back")],
                ]),
            )
        except Exception:
            pass
        return

    if data == "op_event_end":
        panel_set("draft_active","OFF")
        await query.answer("✅ Event ended.", show_alert=True)
        await refresh(); return

    # ── Info screens ──────────────────────────────────────────────────────────
    if data == "op_broadcast_info":
        try:
            await query.edit_message_text(
                "📣 *Broadcast*\n\nSend a message to ALL registered users:\n"
                "`/broadcast <your message>`\n\n"
                "Supports text and photos (reply to a photo with the command).",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="op_back")]]),
            )
        except Exception:
            pass
        return

    if data == "op_backup_info":
        try:
            await query.edit_message_text(
                "💾 *Backup*\n\n`/backup` — sends `cards.db` to your DM.\n\n"
                "Your user data is also safely stored in MongoDB Atlas.",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back", callback_data="op_back")]]),
            )
        except Exception:
            pass
        return




# ================= GIVE ALL ONE PIECE (Compensation) =================

async def give_all_onepiece(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Owner only: /give_all_onepiece <reason>
    Gives every registered user ONE copy of every One Piece card in the database.
    Designed as a compensation command after data loss.
    """
    if not update.effective_user or not update.message:
        return

    if update.effective_user.id not in (OWNER_ID, CO_OWNER_ID):
        await update.message.reply_text("🚫 This command is for the *owner* only.", parse_mode="Markdown")
        return

    reason = " ".join(context.args).strip() if context.args else "Compensation for data loss"

    # Fetch all One Piece cards — EXCLUDE Summer rarity (collab-exclusive, not compensation)
    cursor.execute(
        "SELECT id, name, rarity, file_id FROM cards "
        "WHERE LOWER(series) = 'one piece' AND LOWER(rarity) != 'summer' ORDER BY id"
    )
    op_cards = cursor.fetchall()

    if not op_cards:
        await update.message.reply_text(
            "❌ No One Piece cards found in the database.\n"
            "Add cards first with `/addcard One Piece <name> <rarity>`.",
            parse_mode="Markdown"
        )
        return

    # Fetch all registered users
    cursor.execute("SELECT user_id, first_name FROM bot_users")
    all_users = cursor.fetchall()

    if not all_users:
        await update.message.reply_text("⚠️ No registered users found.")
        return

    owner_name = update.effective_user.first_name or "Owner"

    await update.message.reply_text(
        f"⏳ *Distributing {len(op_cards)} One Piece cards to {len(all_users)} users...*\n\n"
        f"📋 Reason: _{reason}_\n\n"
        f"This may take a while. Please wait...",
        parse_mode="Markdown"
    )

    cards_added = 0
    users_done = 0
    notify_failed = 0

    for uid, fname in all_users:
        # BUG FIX: Pre-load existing One Piece card names to prevent duplicates
        cursor.execute(
            "SELECT card_name FROM user_cards WHERE user_id=? AND series=\'One Piece\'",
            (uid,)
        )
        existing_names = {row[0] for row in cursor.fetchall()}

        # Give every One Piece card to this user — skip if already owned
        for card_id, card_name, rarity, file_id in op_cards:
            if card_name in existing_names:
                continue  # skip duplicate to prevent collection inflation
            try:
                insert_user_card(uid, card_name, rarity, file_id, card_id=card_id)
                existing_names.add(card_name)
                cards_added += 1
            except Exception as e:
                print(f"[GIVE_OP] Error uid={uid} card={card_id}: {e}")
        users_done += 1

    conn.commit()

    # Notify all users (send a summary message with the first card as preview)
    preview_card = op_cards[0]  # use first card's image as preview
    preview_file_id = preview_card[3]
    preview_name = preview_card[1]

    for uid, fname in all_users:
        try:
            caption = (
                f"🎁 *Compensation Gift from the Owner!*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"🏴‍☠️ *{len(op_cards)} One Piece Cards* have been added to your collection!\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"📋 *Reason:* {reason}\n\n"
                f"⚔️ Use /collection to view your vault!\n"
                f"🍃 — {owner_name}"
            )
            if preview_file_id:
                await context.bot.send_photo(
                    chat_id=uid,
                    photo=preview_file_id,
                    caption=caption,
                    parse_mode="Markdown"
                )
            else:
                await context.bot.send_message(
                    chat_id=uid,
                    text=caption,
                    parse_mode="Markdown"
                )
            await asyncio.sleep(0.05)
        except Exception:
            notify_failed += 1

    await update.message.reply_text(
        f"✅ *One Piece Compensation Complete!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🏴‍☠️ Cards distributed: *{len(op_cards)}* per user\n"
        f"👥 Total users: *{len(all_users)}*\n"
        f"🃏 Total cards added: *{cards_added}*\n"
        f"📨 Notify failed: *{notify_failed}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"📋 Reason: _{reason}_",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🎁 *Give All — One Piece Compensation*\n\n"
        f"👑 By: {owner_name} (`{update.effective_user.id}`)\n"
        f"🏴‍☠️ Cards: {len(op_cards)} per user\n"
        f"👥 Users: {len(all_users)}\n"
        f"🃏 Total added: {cards_added}\n"
        f"📋 Reason: {reason}"
    )


# ================= GIVE RANDOM ONE PIECE SUMMER =================

async def give_random_onepiece_summer(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Admin only: /give_random_onepiece_summer <user_id or @username> <count>

    Gives <count> random One Piece Summer cards to the specified user.
    Cards are picked randomly (with repetition allowed) from all ☀️ Summer
    One Piece cards in the database.

    Examples:
      /give_random_onepiece_summer 123456789 5
      /give_random_onepiece_summer @username 3
    """
    if not update.effective_user or not update.message:
        return

    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only command.")
        return

    # ── Parse arguments ────────────────────────────────────────────────────────
    args = context.args or []

    if len(args) < 2:
        await update.message.reply_text(
            "📖 *Usage:*\n\n"
            "`/give_random_onepiece_summer <user_id or @username> <count>`\n\n"
            "Examples:\n"
            "`/give_random_onepiece_summer 123456789 5`\n"
            "`/give_random_onepiece_summer @nakama 3`\n\n"
            "☀️ Picks random One Piece Summer cards from the database and gives them to the user.",
            parse_mode="Markdown"
        )
        return

    target_arg = args[0]
    count_arg  = args[1]

    # Validate count
    try:
        count = int(count_arg)
        if count <= 0:
            raise ValueError
        if count > 100:
            await update.message.reply_text("❌ Maximum 100 cards at a time.")
            return
    except ValueError:
        await update.message.reply_text("❌ Count must be a positive number (max 100).")
        return

    # ── Resolve target user ────────────────────────────────────────────────────
    target_id   = None
    target_name = None

    if target_arg.startswith("@"):
        # Username lookup
        uname = target_arg.lstrip("@")
        cursor.execute(
            "SELECT user_id, first_name FROM bot_users WHERE LOWER(username)=LOWER(?) LIMIT 1",
            (uname,)
        )
        row = cursor.fetchone()
        if row:
            target_id   = row[0]
            target_name = row[1] or uname
        else:
            await update.message.reply_text(
                f"❌ User `@{uname}` not found.\n"
                "They must have used the bot at least once.",
                parse_mode="Markdown"
            )
            return
    else:
        # Numeric user_id
        try:
            target_id = int(target_arg)
        except ValueError:
            await update.message.reply_text(
                "❌ Invalid target. Use a numeric user ID or @username.",
                parse_mode="Markdown"
            )
            return
        cursor.execute(
            "SELECT first_name FROM bot_users WHERE user_id=? LIMIT 1", (target_id,)
        )
        row = cursor.fetchone()
        target_name = row[0] if row else f"User {target_id}"

    # ── Fetch all One Piece Summer cards ───────────────────────────────────────
    cursor.execute(
        "SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') "
        "FROM cards "
        "WHERE rarity='Summer' AND LOWER(COALESCE(series,'')) = 'one piece' "
        "ORDER BY id"
    )
    summer_cards = cursor.fetchall()

    if not summer_cards:
        await update.message.reply_text(
            "❌ No One Piece Summer cards found in the database.\n"
            "Add some first with `/addcard One Piece <name> Summer`.",
            parse_mode="Markdown"
        )
        return

    # ── Pick <count> random cards (with replacement) ──────────────────────────
    import random as _random
    chosen = _random.choices(summer_cards, k=count)

    # ── Insert into user's collection ─────────────────────────────────────────
    added = 0
    for card_id, card_name, rarity, file_id, file_type in chosen:
        try:
            insert_user_card(target_id, card_name, rarity, file_id,
                             file_type=file_type, card_id=card_id)
            added += 1
        except Exception as e:
            print(f"[GIVE_OP_SUMMER] Error uid={target_id} card={card_id}: {e}")

    conn.commit()

    emoji = RARITY_EMOJI.get("Summer", "☀️")
    admin_name = update.effective_user.first_name or "Admin"

    # ── Summary for admin ──────────────────────────────────────────────────────
    card_lines = ""
    for _, card_name, _, _, _ in chosen:
        card_lines += f"  • {card_name.title()}\n"

    await update.message.reply_text(
        f"✅ *One Piece Summer Gift Sent!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🏴‍☠️ Recipient: *{target_name}* (`{target_id}`)\n"
        f"{emoji} Rarity: *Summer*\n"
        f"🎴 Cards given: *{added}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"*Cards:*\n{card_lines}",
        parse_mode="Markdown"
    )

    # ── Notify the recipient ───────────────────────────────────────────────────
    # Use the last card's image as the notification preview
    preview = chosen[-1]
    preview_file_id   = preview[3]
    preview_file_type = preview[4]
    preview_name      = preview[1]

    try:
        notif_caption = (
            f"🎁 *You received a special gift!*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"{emoji} *{count} One Piece Summer Card{'s' if count > 1 else ''}* added to your collection!\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"⚔️ Use /collection to view your vault!\n"
            f"🍃 — {admin_name}"
        )
        if preview_file_id:
            await send_card_media(
                context.bot, preview_file_id, file_type=preview_file_type, caption=notif_caption,
                parse_mode="Markdown", chat_id=target_id
            )
        else:
            await context.bot.send_message(
                chat_id=target_id,
                text=notif_caption,
                parse_mode="Markdown"
            )
    except Exception as e:
        print(f"[GIVE_OP_SUMMER] Could not notify user {target_id}: {e}")
        await update.message.reply_text(
            f"⚠️ Cards added but couldn't notify the user (they may not have started the bot in DM).",
            parse_mode="Markdown"
        )

    # ── Log to admin group ─────────────────────────────────────────────────────
    await log_to_group(
        context.bot,
        f"🎁 *Give Random One Piece Summer*\n\n"
        f"👑 By: {admin_name} (`{update.effective_user.id}`)\n"
        f"🏴‍☠️ To: {target_name} (`{target_id}`)\n"
        f"{emoji} Cards: {added} Summer\n"
        f"🃏 {card_lines.strip()}"
    )


# ================= OWNER: /give_random — bulk random cards by rarity =================

async def give_random_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Owner/admin only — give random cards of one or more rarities to a user.

    Usage (any of these forms):
      /give_random common,rare,epic,legendary 500          (reply to user's message)
      /give_random common 500 @username                    (tag, no reply needed)
      /give_random common 500 123456789                     (numeric user id)
      /give_random common,rare 200                          (reply to user's message)

    When multiple rarities are given (comma-separated), the total count is split
    evenly across them (remainder goes to the first rarities listed).
    """
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only command.")
        return

    args = list(context.args or [])
    if len(args) < 2:
        await update.message.reply_text(
            "📖 *Usage:*\n\n"
            "`/give_random <rarity[,rarity2,...]> <count> [user_id/@username]`\n\n"
            "*Examples:*\n"
            "`/give_random common,rare,epic,legendary 500` _(reply to a user)_\n"
            "`/give_random common 500 @username`\n"
            "`/give_random common 500 123456789`\n\n"
            f"*Valid rarities:* {', '.join(RARITY_WEIGHTS.keys())}",
            parse_mode="Markdown"
        )
        return

    rarity_arg_raw = args[0]
    count_arg = args[1]
    user_arg  = args[2] if len(args) > 2 else None

    # ── Parse rarities (comma-separated, case-insensitive) ────────────────────
    requested_rarities = [normalize_rarity(r.strip()) for r in rarity_arg_raw.split(",") if r.strip()]
    invalid = [r for r in requested_rarities if r not in RARITY_WEIGHTS]
    if invalid:
        await update.message.reply_text(
            f"❌ Unknown rarity: {', '.join(invalid)}\n\n"
            f"*Valid rarities:* {', '.join(RARITY_WEIGHTS.keys())}",
            parse_mode="Markdown"
        )
        return
    if not requested_rarities:
        await update.message.reply_text("❌ Please specify at least one rarity.")
        return

    # ── Parse count ─────────────────────────────────────────────────────────────
    try:
        total_count = int(count_arg)
        if total_count <= 0:
            raise ValueError
        if total_count > 5000:
            await update.message.reply_text("❌ Maximum 5000 cards at a time.")
            return
    except ValueError:
        await update.message.reply_text("❌ Count must be a positive number (max 5000).")
        return

    # ── Resolve target user: reply > @username/user_id arg ────────────────────
    target_id   = None
    target_name = None

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        replied = update.message.reply_to_message.from_user
        target_id   = replied.id
        target_name = replied.first_name or str(target_id)
    elif user_arg:
        if user_arg.startswith("@"):
            uname = user_arg.lstrip("@")
            cursor.execute(
                "SELECT user_id, first_name FROM bot_users WHERE LOWER(username)=LOWER(?) LIMIT 1",
                (uname,)
            )
            row = cursor.fetchone()
            if row:
                target_id, target_name = row[0], (row[1] or uname)
            else:
                await update.message.reply_text(
                    f"❌ User `@{uname}` not found. They must have used the bot at least once.",
                    parse_mode="Markdown"
                )
                return
        else:
            try:
                target_id = int(user_arg)
            except ValueError:
                await update.message.reply_text(
                    "❌ Invalid target. Use a numeric user ID or @username.",
                    parse_mode="Markdown"
                )
                return
            cursor.execute("SELECT first_name FROM bot_users WHERE user_id=? LIMIT 1", (target_id,))
            row = cursor.fetchone()
            target_name = row[0] if row else f"User {target_id}"
    else:
        await update.message.reply_text(
            "❌ No target specified.\n\n"
            "Either reply to the user's message, or add `@username`/`user_id` as the last argument.",
            parse_mode="Markdown"
        )
        return

    # ── Split count across requested rarities ──────────────────────────────────
    n = len(requested_rarities)
    base_share = total_count // n
    remainder  = total_count % n
    shares = {}
    for i, r in enumerate(requested_rarities):
        shares[r] = base_share + (1 if i < remainder else 0)

    # ── Fetch card pools per rarity (exclude collab-only series like One Piece/Bleach) ──
    import random as _random
    added_total = 0
    breakdown_lines = []

    for rarity, share_count in shares.items():
        if share_count <= 0:
            continue
        cursor.execute(
            "SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards "
            "WHERE rarity=? AND (series IS NULL OR series NOT IN ({}))".format(
                ",".join("?" * len(COLLAB_ONLY_SERIES))
            ),
            (rarity, *COLLAB_ONLY_SERIES)
        )
        pool = cursor.fetchall()
        if not pool:
            breakdown_lines.append(f"  ⚠️ {rarity}: no cards in database — skipped")
            continue

        chosen = _random.choices(pool, k=share_count)
        rarity_added = 0
        for card_id, card_name, card_rarity, file_id, file_type in chosen:
            try:
                insert_user_card(target_id, card_name, card_rarity, file_id,
                                 file_type=file_type, card_id=card_id)
                rarity_added += 1
            except Exception as e:
                print(f"[GIVE_RANDOM] Error uid={target_id} card={card_id}: {e}")
        added_total += rarity_added
        emoji = RARITY_EMOJI.get(rarity, "⭐")
        breakdown_lines.append(f"  {emoji} {rarity}: {rarity_added} card(s)")

    conn.commit()
    admin_name = update.effective_user.first_name or "Admin"

    await update.message.reply_text(
        f"✅ *Random Cards Given!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"👤 Recipient: *{target_name}* (`{target_id}`)\n"
        f"🎴 Total cards: *{added_total}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"*Breakdown:*\n" + "\n".join(breakdown_lines),
        parse_mode="Markdown"
    )

    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=(
                f"🎁 *You received a special gift!*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"🎴 *{added_total} random card(s)* added to your collection!\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"⚔️ Use /collection to view your vault!\n"
                f"🍃 — {admin_name}"
            ),
            parse_mode="Markdown"
        )
    except Exception as e:
        print(f"[GIVE_RANDOM] Could not notify user {target_id}: {e}")
        await update.message.reply_text(
            "⚠️ Cards added but couldn't notify the user (they may not have started the bot in DM).",
            parse_mode="Markdown"
        )

    await log_to_group(
        context.bot,
        f"🎁 *Give Random Cards*\n\n"
        f"👑 By: {admin_name} (`{update.effective_user.id}`)\n"
        f"👤 To: {target_name} (`{target_id}`)\n"
        f"🎴 Total: {added_total} card(s)\n"
        + "\n".join(breakdown_lines)
    )


# ================= AUTO BACKUP SCHEDULER =================

# Serializes the group (30min) and owner (60min) backup jobs so they never
# build a DB snapshot + gzip a ~20MB file at the same time — see
# _send_scheduled_backup for why. asyncio.Lock, not threading.Lock: both
# schedulers run as asyncio tasks on the same event loop.
_backup_lock = asyncio.Lock()

def _make_db_backup_gz():
    """
    Creates a safe, WAL-consistent, gzip-compressed snapshot of the live
    database and returns (gz_path, file_size_mb). Raises on failure.
    Caller is responsible for deleting the returned file afterwards.
    Shared by every scheduled/manual backup sender below.
    """
    import gzip
    import shutil
    import tempfile
    import sqlite3 as _sqlite3

    db_path = DB_PATH
    if not os.path.exists(db_path):
        raise FileNotFoundError("DB file not found")

    backup_tmp = tempfile.NamedTemporaryFile(suffix=".db", delete=False)
    backup_tmp.close()
    backup_gz = backup_tmp.name + ".gz"

    try:
        # Safe WAL-consistent snapshot via SQLite backup API
        src_conn = _sqlite3.connect(db_path)
        src_conn.execute("PRAGMA busy_timeout=5000")
        dst_conn = _sqlite3.connect(backup_tmp.name)
        src_conn.backup(dst_conn)
        dst_conn.close()
        src_conn.close()

        # Gzip compress
        with open(backup_tmp.name, "rb") as f_in, gzip.open(backup_gz, "wb", compresslevel=6) as f_out:
            shutil.copyfileobj(f_in, f_out)
    finally:
        if os.path.exists(backup_tmp.name):
            os.unlink(backup_tmp.name)

    file_size_mb = os.path.getsize(backup_gz) / (1024 * 1024)
    return backup_gz, file_size_mb


async def _send_scheduled_backup(bot, chat_id, label: str):
    """
    Builds a fresh backup snapshot and sends it to a single chat_id.
    Used by both the group scheduler (every 3 min) and the owner DM
    scheduler (every 5 min).

    SERIALIZED via _backup_lock (see below): group backup runs every 3 min
    and owner backup every 5 min, so every 15 min they land in the same
    window and — before this fix — both fired their own DB snapshot +
    gzip pass into the SAME container at once. Neither job is dropped; the
    second one just waits for the first to finish instead of doubling the
    memory/CPU spike. Also now logs elapsed time + RAM before/after so a
    memory spike during backup shows up directly in the heartbeat-adjacent
    log instead of only being visible as a heartbeat RAM jump a few lines
    away.
    """
    import datetime as _dt

    async with _backup_lock:
        backup_gz = None
        _t0 = time.time()
        _ram0 = _get_memory_mb()
        print(f"[BACKUP] START type={label} RAM={_ram0:.1f}MB" if _ram0 >= 0 else f"[BACKUP] START type={label}")
        try:
            backup_gz, file_size_mb = await asyncio.to_thread(_make_db_backup_gz)
            _ram1 = _get_memory_mb()
            if _ram1 >= 0:
                print(f"[BACKUP] SNAPSHOT+GZIP done type={label} RAM={_ram1:.1f}MB size={file_size_mb:.1f}MB")

            # Routes through the SAME split-or-single logic /backup uses (see
            # _send_backup_file_split's docstring) — this is what was missing
            # before, which is why scheduled backups kept going out as a single
            # un-restorable ~20MB file even after /backup itself got fixed.
            await _send_backup_file_split(bot, chat_id, backup_gz, file_size_mb, label=label, is_manual=False)

            _elapsed = time.time() - _t0
            _ram2 = _get_memory_mb()
            _ram2_str = f"{_ram2:.1f}MB" if _ram2 >= 0 else "n/a"
            print(f"[BACKUP] END type={label} elapsed={_elapsed:.1f}s RAM={_ram2_str}")

        except Exception as e:
            print(f"[AUTO-BACKUP] ❌ ({label}) Error sending to {chat_id}: {e}")
            try:
                await bot.send_message(
                    chat_id=BACKUP_OWNER_ID,
                    text=f"❌ *Auto Backup Failed* ({label})\n\nError: `{str(e)[:300]}`",
                    parse_mode="Markdown"
                )
            except Exception:
                pass
        finally:
            if backup_gz and os.path.exists(backup_gz):
                try:
                    os.unlink(backup_gz)
                except Exception:
                    pass


# ── Heartbeat ────────────────────────────────────────────────────────────────
# NEW (diagnostic): logs a single line every 30s so a future "the bot went
# quiet" incident can be told apart at a glance:
#   - log just stops entirely, no [SHUTDOWN]  -> process died / host killed it
#   - log continues but pending_tasks keeps climbing -> event loop is
#     backed up (too much sync work queued, e.g. the old message_tracker path)
#   - log continues with normal pending_tasks but the bot doesn't respond
#     -> Telegram connection/polling itself is the problem, not our code
_heartbeat_start_time = time.time()

def _get_memory_mb():
    """Resident memory of this process, in MB. Linux-only (/proc), returns
    -1 if unavailable (e.g. different OS) — heartbeat just omits it then."""
    try:
        with open("/proc/self/status", "r") as f:
            for line in f:
                if line.startswith("VmRSS:"):
                    return int(line.split()[1]) / 1024
    except Exception:
        return -1
    return -1

# ── Background task supervisor ────────────────────────────────────────────────
# Every scheduler below (backup/quiz/auction/heartbeat) already catches its
# own per-item exceptions internally, so this is a second, outer safety net:
# if one of them ever DOES exit unexpectedly (an exception that escapes its
# own try/except, or — bugs aside — simply returning), asyncio.create_task()
# by itself would just let that task die silently; nothing would ever
# restart it, and the only sign would be that scheduler's log lines quietly
# stopping forever while the rest of the bot kept running. This wraps each
# scheduler so a death is: logged with a full traceback and subsystem name,
# counted (visible in the heartbeat), backed off, and the scheduler is
# restarted automatically — matching exactly what was asked for ("if the
# Quiz scheduler dies, restart the Quiz scheduler", etc.) without changing
# any of the scheduler functions themselves.
_SUPERVISOR_STATS = {}  # {task_name: {"restarts": int, "last_error": str, "last_restart": float}}

async def _supervise_task(name: str, coro_factory):
    """Runs coro_factory() forever. If it raises or returns, logs the failure
    under `name`, waits with a growing backoff (capped), then restarts it.
    coro_factory is a zero-arg callable returning a fresh coroutine each time
    (e.g. `lambda: backup_group_scheduler(bot)`), since a coroutine object
    can only be awaited once."""
    _SUPERVISOR_STATS[name] = {"restarts": 0, "last_error": None, "last_restart": None}
    backoff = 5
    while True:
        try:
            await coro_factory()
            # A scheduler returning normally is itself unexpected (they're
            # all `while True`) — treat it the same as a crash so it gets
            # restarted instead of silently vanishing.
            print(f"[SUPERVISOR] '{name}' exited normally (unexpected — schedulers should "
                  f"run forever). Restarting in {backoff}s.")
        except asyncio.CancelledError:
            print(f"[SUPERVISOR] '{name}' cancelled (shutdown) — not restarting.")
            raise
        except Exception as e:
            print("=" * 70)
            print(f"[SUPERVISOR] Background task '{name}' died with an unhandled exception:")
            traceback.print_exc()
            print(f"[SUPERVISOR] Restarting '{name}' in {backoff}s. This does NOT affect "
                  f"any other part of the bot — only '{name}' was down.")
            print("=" * 70)
        _SUPERVISOR_STATS[name]["restarts"] += 1
        _SUPERVISOR_STATS[name]["last_error"] = str(sys.exc_info()[1]) if sys.exc_info()[1] else None
        _SUPERVISOR_STATS[name]["last_restart"] = time.time()
        await asyncio.sleep(backoff)
        backoff = min(backoff * 2, 120)  # cap at 2 min so we don't hammer on a persistent bug


_LAST_UPDATE_TS = {"ts": time.time()}  # updated in message_tracker (first thing most updates hit)
_LAST_API_SUCCESS_TS = {"ts": None}    # best-effort; set at the top of the heartbeat loop as a floor

async def _heartbeat_loop():
    global _LOOP_HEARTBEAT_TS
    while True:
        try:
            await asyncio.sleep(15)
            _LOOP_HEARTBEAT_TS = time.monotonic()
            uptime = int(time.time() - _heartbeat_start_time)
            try:
                all_tasks = asyncio.all_tasks()
                pending = len(all_tasks)
                pending_by_name = defaultdict(int)
                for t in all_tasks:
                    nm = t.get_name() if hasattr(t, "get_name") else "task"
                    pending_by_name[nm.split('-')[0]] += 1
            except Exception:
                pending = -1
                pending_by_name = {}
            total_msgs = sum(total_message_counter.values()) if total_message_counter else 0
            ram = _get_memory_mb()
            ram_str = f"{ram:.1f}MB" if ram >= 0 else "n/a"
            pid = os.getpid()

            # CPU% since process start (best-effort, Linux-only, cheap — no extra deps)
            cpu_str = "n/a"
            try:
                with open("/proc/self/stat", "r") as _sf:
                    _fields = _sf.read().split()
                utime, stime = int(_fields[13]), int(_fields[14])
                clk = os.sysconf("SC_CLK_TCK")
                cpu_secs = (utime + stime) / clk
                cpu_str = f"{(cpu_secs / max(uptime, 1)) * 100:.1f}%"
            except Exception:
                pass

            last_update_age = f"{int(time.time() - _LAST_UPDATE_TS['ts'])}s ago"
            mongo_status = "connected" if MONGO_AVAILABLE else "unavailable"
            restarts_summary = ",".join(
                f"{name}={stats['restarts']}" for name, stats in _SUPERVISOR_STATS.items()
            ) or "none"

            print(
                f"[HEARTBEAT] alive | pid={pid} | uptime={uptime}s | RAM={ram_str} | CPU={cpu_str} | "
                f"pending_tasks={pending} | total_msgs_seen={total_msgs} | "
                f"last_update={last_update_age} | mongo={mongo_status} | "
                f"flood_events={_FC_STATS['flood_events']} | retries={_FC_STATS['retries']} | "
                f"entity_fallbacks={_FC_STATS['entity_fallbacks']} | fc_exceptions={_FC_STATS['exceptions']} | "
                f"task_restarts=[{restarts_summary}] | db_bg_pending={_DB_BG_PENDING} | premium_emoji={'on' if _PE_STATE['enabled'] else 'off'}"
            )
        except asyncio.CancelledError:
            raise
        except Exception as _e:
            print(f"[HEARTBEAT] error (loop continues): {_e}")


async def backup_group_scheduler(bot):
    """
    Runs forever in the background. Every BACKUP_GROUP_INTERVAL seconds
    (default 30 minutes), sends a compressed database backup to
    BACKUP_GROUP_ID only.
    """
    print(f"[AUTO-BACKUP] Group scheduler started. Every {BACKUP_GROUP_INTERVAL}s → {BACKUP_GROUP_ID}")
    while True:
        await asyncio.sleep(BACKUP_GROUP_INTERVAL)
        await _send_scheduled_backup(bot, BACKUP_GROUP_ID, "Group")


async def backup_owner_scheduler(bot):
    """
    Runs forever in the background. Every BACKUP_OWNER_INTERVAL seconds
    (default 60 minutes), sends a compressed database backup to the
    owner's DM (BACKUP_OWNER_ID) only.
    """
    print(f"[AUTO-BACKUP] Owner DM scheduler started. Every {BACKUP_OWNER_INTERVAL}s → {BACKUP_OWNER_ID}")
    while True:
        await asyncio.sleep(BACKUP_OWNER_INTERVAL)
        await _send_scheduled_backup(bot, BACKUP_OWNER_ID, "Owner DM")


# ================= RECURRING ANIME QUIZ (Gems system) =================

def add_gems(user_id: int, amount: int = 1):
    cursor.execute("INSERT OR IGNORE INTO quiz_gems (user_id, gems) VALUES (?,0)", (user_id,))
    cursor.execute("UPDATE quiz_gems SET gems = gems + ? WHERE user_id=?", (amount, user_id))
    conn.commit()


def get_gems(user_id: int) -> int:
    cursor.execute("SELECT gems FROM quiz_gems WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    return row[0] if row else 0


def deduct_gems(user_id: int, amount: int) -> bool:
    """Deduct `amount` gems from user_id if they have enough. Returns True on success."""
    cursor.execute("INSERT OR IGNORE INTO quiz_gems (user_id, gems) VALUES (?,0)", (user_id,))
    conn.commit()
    current = get_gems(user_id)
    if current < amount:
        return False
    cursor.execute("UPDATE quiz_gems SET gems = gems - ? WHERE user_id=?", (amount, user_id))
    conn.commit()
    return True


async def give_gems_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /give_gems <amount> [@username/user_id] — Give some of YOUR OWN 💎 Gems to
    another user. Target can be a reply, @username, or numeric user ID (same
    resolution style as /give_random). This is a player-facing command, not
    admin-only — anyone with enough Gems can send them to another player.

    Usage:
      /give_gems 10                (reply to the user's message)
      /give_gems 10 @username
      /give_gems 10 123456789
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id

    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    args = list(context.args or [])
    if not args:
        await update.message.reply_text(
            "📖 *Usage:*\n\n"
            "`/give_gems <amount>` _(reply to a user)_\n"
            "`/give_gems <amount> @username`\n"
            "`/give_gems <amount> 123456789`\n\n"
            f"💎 Your current Gems: *{get_gems(user_id)}*",
            parse_mode="Markdown"
        )
        return

    try:
        amount = int(args[0])
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Amount must be a positive whole number.")
        return

    user_arg = args[1] if len(args) > 1 else None

    # ── Resolve target user: reply > @username/user_id arg ────────────────────
    target_id = None
    target_name = None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        replied = update.message.reply_to_message.from_user
        target_id = replied.id
        target_name = replied.first_name or str(target_id)
    elif user_arg:
        if user_arg.startswith("@"):
            uname = user_arg.lstrip("@")
            cursor.execute(
                "SELECT user_id, first_name FROM bot_users WHERE LOWER(username)=LOWER(?) LIMIT 1",
                (uname,)
            )
            row = cursor.fetchone()
            if row:
                target_id, target_name = row[0], (row[1] or uname)
            else:
                await update.message.reply_text(
                    f"❌ User `@{uname}` not found. They must have used the bot at least once.",
                    parse_mode="Markdown"
                )
                return
        else:
            try:
                target_id = int(user_arg)
            except ValueError:
                await update.message.reply_text(
                    "❌ Invalid target. Use a numeric user ID or @username.",
                    parse_mode="Markdown"
                )
                return
            cursor.execute("SELECT first_name FROM bot_users WHERE user_id=? LIMIT 1", (target_id,))
            row = cursor.fetchone()
            target_name = row[0] if row else f"User {target_id}"
    else:
        await update.message.reply_text(
            "❌ No target specified.\n\n"
            "Either reply to the user's message, or add `@username`/`user_id` as the last argument.",
            parse_mode="Markdown"
        )
        return

    if target_id == user_id:
        await update.message.reply_text("❌ You can't give Gems to yourself.")
        return

    current_gems = get_gems(user_id)
    if current_gems < amount:
        await update.message.reply_text(
            f"❌ You only have *{current_gems}* 💎 Gems — you can't give *{amount}*.",
            parse_mode="Markdown"
        )
        return

    # ── Transfer ────────────────────────────────────────────────────────────────
    add_gems(user_id, -amount)
    add_gems(target_id, amount)

    sender_name = update.effective_user.first_name or "A shinobi"
    await update.message.reply_text(
        f"💎 *Gems Sent!*\n\n"
        f"You gave *{amount}* 💎 Gems to *{target_name}*.\n"
        f"Your new balance: *{get_gems(user_id)}* 💎",
        parse_mode="Markdown"
    )
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=(
                f"🎁 *You received Gems!*\n\n"
                f"*{sender_name}* sent you *{amount}* 💎 Gems!\n"
                f"Your new balance: *{get_gems(target_id)}* 💎"
            ),
            parse_mode="Markdown"
        )
    except Exception:
        pass  # target may not have a DM-able chat with the bot yet


async def _post_quiz_to_chat(bot, chat_id: int):
    """Post a random quiz question as a Telegram poll to one chat."""
    q_idx = random.randrange(len(QUIZ_QUESTIONS))
    question, options, correct_idx = QUIZ_QUESTIONS[q_idx]
    # FIX (Bug 1): randomize where the correct answer lands before sending —
    # see shuffle_quiz_options() docstring for why this is needed.
    options, correct_idx = shuffle_quiz_options(options, correct_idx)

    try:
        msg = await bot.send_poll(
            chat_id=chat_id,
            question=f"🧠 Anime Quiz! {question}",
            options=options,
            type="quiz",
            correct_option_id=correct_idx,
            is_anonymous=False,
            open_period=300,   # 5-minute answer window (closed early on first vote anyway)
        )
        cursor.execute(
            "INSERT OR REPLACE INTO quiz_active (chat_id, message_id, question_idx, correct_option, answered, created_at) "
            "VALUES (?,?,?,?,0,?)",
            (chat_id, msg.message_id, q_idx, correct_idx, int(time.time()))
        )
        conn.commit()
        # Track poll_id -> chat_id so the answer handler knows where it came from
        _quiz_poll_to_chat[msg.poll.id] = chat_id
        _quiz_permission_cooldown.pop(chat_id, None)  # it worked — clear any earlier cooldown
    except Exception as e:
        print(f"[QUIZ] Failed to post quiz in chat {chat_id}: {e}")
        if "not enough rights" in str(e).lower() or "chat_admin_required" in str(e).lower():
            # FIX: this group's admins haven't given the bot poll permission.
            # That won't change from one 10-minute cycle to the next on its
            # own, so retrying every single cycle just spams the log and
            # wastes an API call. Back off from THIS chat for a while — the
            # scheduler itself, and every OTHER chat, are completely
            # unaffected (this is exactly the "mark that chat temporarily
            # unavailable, keep serving everyone else" behavior requested).
            _quiz_permission_cooldown[chat_id] = time.time() + QUIZ_PERMISSION_RECHECK_SECONDS


# Maps live poll_id -> chat_id (in-memory; quiz_active table is the durable record)
_quiz_poll_to_chat: dict[str, int] = {}

# chat_id -> unix timestamp before which we won't retry posting a quiz there,
# set after a "not enough rights to send polls" failure (see _post_quiz_to_chat)
_quiz_permission_cooldown: dict[int, float] = {}
QUIZ_PERMISSION_RECHECK_SECONDS = 60 * 60  # re-check an unavailable chat once an hour


async def recurring_quiz_scheduler(bot):
    """
    Runs forever. Every 10 minutes, posts a random anime-quiz poll to every
    group — but ONLY if that group has had a message within the last 10
    minutes (i.e. people are actively chatting). Inactive groups are skipped
    so the quiz doesn't spam a dead chat.
    The first correct answer in each poll earns 1 💎 Gem.
    """
    print("[QUIZ] Recurring quiz scheduler started (10-minute interval, activity-gated).")
    QUIZ_INTERVAL_SECONDS = 10 * 60       # fixed 10-minute cycle
    ACTIVITY_WINDOW_SECONDS = 10 * 60     # group must have a message within the last 10 min

    # Give the bot a moment to finish startup before the first quiz
    await asyncio.sleep(30)

    while True:
        try:
            cursor.execute("SELECT chat_id FROM bot_groups")
            group_ids = [r[0] for r in cursor.fetchall()]
            now = time.time()
            for gid in group_ids:
                cooldown_until = _quiz_permission_cooldown.get(gid)
                if cooldown_until and now < cooldown_until:
                    continue  # this chat recently failed with "not enough rights" — skip it for now
                last_active = chat_last_active.get(gid)
                if last_active is None or (now - last_active) > ACTIVITY_WINDOW_SECONDS:
                    # No one has spoken recently in this group — skip the quiz this round
                    continue
                await _post_quiz_to_chat(bot, gid)
                await asyncio.sleep(0.3)  # avoid flooding Telegram API
        except Exception as e:
            print(f"[QUIZ] Scheduler error: {e}")

        await asyncio.sleep(QUIZ_INTERVAL_SECONDS)


async def quiz_poll_answer_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Handle answers to recurring-quiz polls.
    Whoever votes FIRST — correct or not — ends the round immediately (the poll
    is closed via stop_poll so nobody else can vote). The Gem is only awarded
    if that first vote happened to be the correct answer.
    """
    answer = update.poll_answer
    if not answer or not answer.option_ids:
        return

    poll_id = answer.poll_id
    user = answer.user
    user_id = user.id if user else None
    if not user_id:
        return

    chat_id = _quiz_poll_to_chat.get(poll_id)
    if chat_id is None:
        return  # not a recurring-quiz poll we're tracking (could be giveaway poll)

    cursor.execute(
        "SELECT message_id, question_idx, correct_option, answered FROM quiz_active WHERE chat_id=?",
        (chat_id,)
    )
    row = cursor.fetchone()
    if not row:
        return
    message_id, q_idx, correct_option, already_answered = row

    if already_answered:
        return  # someone already voted first this round — ignore further votes

    # ── First vote received for this round — lock it immediately, regardless
    # of whether it's correct, so nobody else can vote after this point. ──────
    cursor.execute("UPDATE quiz_active SET answered=1 WHERE chat_id=?", (chat_id,))
    conn.commit()
    _quiz_poll_to_chat.pop(poll_id, None)

    try:
        await context.bot.stop_poll(chat_id=chat_id, message_id=message_id)
    except Exception as e:
        print(f"[QUIZ] Failed to stop poll early in chat {chat_id}: {e}")

    selected = answer.option_ids[0]
    user_name = user.first_name or "Shinobi"
    if selected == correct_option:
        add_gems(user_id, 1)
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=(
                    f"🎉 *{user_name}* answered correctly first!\n"
                    f"💎 +1 Gem awarded! Use /gems to check your total."
                ),
                parse_mode="Markdown"
            )
        except Exception:
            pass
    else:
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=(
                    f"⏱️ *{user_name}* answered first, but it wasn't correct — no Gem this round.\n"
                    f"Round closed. Next quiz coming soon!"
                ),
                parse_mode="Markdown"
            )
        except Exception:
            pass


# ================= USER FEEDBACK (Feature) — /feedback =================
# Lets any user send a bug report or feature suggestion straight to the
# owner's DM, complete with the sender's name/username/user ID so the owner
# can identify and reward (or politely decline) them without digging through
# chat logs. The owner gets two buttons right on the message: ✅ Accept
# (sends the user a congrats message + 20 draft vouchers) or ❌ Reject
# (sends a polite decline). Buttons are owner/admin-only so a random group
# member can't decide on someone else's feedback.
FEEDBACK_REWARD_VOUCHERS = 20


async def feedback_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /feedback <message> — Send a bug report or suggestion straight to the
    owner. Works in DM and in groups. The owner can Accept (rewards the
    sender with vouchers) or Reject (politely declines) right from the
    forwarded message.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    message_text = " ".join(context.args) if context.args else ""
    if not message_text.strip():
        await update.message.reply_text(
            "💬 *Send Feedback*\n\n"
            "Usage: `/feedback <your message>`\n\n"
            "Example: `/feedback The /find command should also show holder names!`\n\n"
            "Got a bug to report or an idea for the bot? This goes straight to the owner's DM.",
            parse_mode="Markdown"
        )
        return

    user_name = update.effective_user.first_name or "Unknown"
    username = update.effective_user.username or ""
    now = int(time.time())

    cursor.execute(
        "INSERT INTO user_feedback (user_id, user_name, username, message, status, submitted_at) "
        "VALUES (?, ?, ?, ?, 'pending', ?)",
        (user_id, user_name, username, message_text, now)
    )
    conn.commit()
    feedback_id = cursor.lastrowid

    usertag = f"@{username}" if username else "no username"
    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ ACCEPT", callback_data=f"fbdecide_accept_{feedback_id}"),
        InlineKeyboardButton("❌ REJECT", callback_data=f"fbdecide_reject_{feedback_id}"),
    ]])

    try:
        await context.bot.send_message(
            chat_id=OWNER_ID,
            text=(
                f"💬 *New Feedback Received!*\n\n"
                f"👤 From: *{_safe_md_global(user_name)}*\n"
                f"🔖 Username: {_safe_md_global(usertag)}\n"
                f"🆔 User ID: `{user_id}`\n\n"
                f"📝 *Message:*\n{message_text}\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"Choose below:"
            ),
            reply_markup=keyboard,
            parse_mode="Markdown"
        )
        await update.message.reply_text(
            "✅ *Feedback sent!*\n\n"
            "Thanks for helping improve the bot — the owner will review it soon.",
            parse_mode="Markdown"
        )
    except Exception as e:
        print(f"[FEEDBACK] Failed to deliver feedback #{feedback_id} to owner: {e}")
        await update.message.reply_text(
            "⚠️ Your feedback was saved, but I couldn't reach the owner's DM right now. "
            "It'll still be reviewed."
        )


def _safe_md_global(text: str) -> str:
    """Escape Telegram legacy-Markdown special characters in arbitrary text."""
    if not text:
        return text
    for ch in ("_", "*", "`", "["):
        text = text.replace(ch, "\\" + ch)
    return text


async def feedback_decide_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle the owner's ✅ Accept / ❌ Reject button press on a feedback message."""
    query = update.callback_query
    deciding_user_id = query.from_user.id

    if not is_admin(deciding_user_id):
        await query.answer("🚫 Only the owner/admins can decide on feedback.", show_alert=True)
        return

    parts = query.data.split("_")
    decision = parts[1]            # "accept" or "reject"
    feedback_id = int(parts[2])

    cursor.execute(
        "SELECT user_id, user_name, username, message, status FROM user_feedback WHERE id=?",
        (feedback_id,)
    )
    row = cursor.fetchone()
    if not row:
        await query.answer("❌ Feedback not found (may have been deleted).", show_alert=True)
        return
    sender_id, sender_name, sender_username, message_text, status = row

    if status != "pending":
        await query.answer(f"⚠️ Already {status}.", show_alert=True)
        return

    now = int(time.time())
    new_status = "accepted" if decision == "accept" else "rejected"
    cursor.execute(
        "UPDATE user_feedback SET status=?, decided_at=? WHERE id=?",
        (new_status, now, feedback_id)
    )
    conn.commit()
    await query.answer()

    usertag = f"@{sender_username}" if sender_username else "no username"

    if decision == "accept":
        add_vouchers(sender_id, FEEDBACK_REWARD_VOUCHERS)
        owner_update_text = (
            f"✅ *Feedback ACCEPTED*\n\n"
            f"👤 From: *{_safe_md_global(sender_name)}* ({_safe_md_global(usertag)} | `{sender_id}`)\n"
            f"📝 {message_text}\n\n"
            f"🎁 Rewarded *{FEEDBACK_REWARD_VOUCHERS}* draft vouchers."
        )
        user_text = (
            f"🎉 *Congratulations! Thank you for your suggestion!* 💚\n\n"
            f"Your feedback was accepted by the owner!\n"
            f"🎁 You've been rewarded *{FEEDBACK_REWARD_VOUCHERS}* draft vouchers!\n\n"
            f"Use /draft_event or /collaboration_draft to spin with your new vouchers!"
        )
    else:
        owner_update_text = (
            f"❌ *Feedback REJECTED*\n\n"
            f"👤 From: *{_safe_md_global(sender_name)}* ({_safe_md_global(usertag)} | `{sender_id}`)\n"
            f"📝 {message_text}"
        )
        user_text = (
            f"😔 *Sorry, that Your idea 💡 is not enough.*\n"
            f"Better luck next time! 🍀\n\n"
            f"Keep an eye out — feel free to send more ideas anytime with /feedback!"
        )

    try:
        await query.edit_message_text(owner_update_text, parse_mode="Markdown")
    except Exception:
        pass

    try:
        await context.bot.send_message(chat_id=sender_id, text=user_text, parse_mode="Markdown")
    except Exception as e:
        print(f"[FEEDBACK] Could not DM decision to user {sender_id}: {e}")


async def gems_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/Gems — show the user's quiz Gem total."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    user_name = update.effective_user.first_name or "Shinobi"
    gems = get_gems(user_id)

    cursor.execute(
        "SELECT COUNT(*)+1 FROM quiz_gems WHERE gems > (SELECT gems FROM quiz_gems WHERE user_id=?)",
        (user_id,)
    )
    rank_row = cursor.fetchone()
    rank = rank_row[0] if rank_row else None

    await update.message.reply_text(
        f"💎 *{user_name}'s Quiz Gems*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"💎 Gems: *{gems}*\n"
        f"🏆 Rank: *#{rank}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"🧠 Answer anime quizzes first & correctly to earn more Gems!",
        parse_mode="Markdown"
    )


async def top_gems_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/top_gems — leaderboard of quiz Gem collectors."""
    if not update.effective_user or not update.message:
        return
    cursor.execute(
        "SELECT qg.user_id, bu.first_name, qg.gems FROM quiz_gems qg "
        "LEFT JOIN bot_users bu ON bu.user_id = qg.user_id "
        "WHERE qg.gems > 0 ORDER BY qg.gems DESC LIMIT 10"
    )
    rows = cursor.fetchall()
    if not rows:
        await update.message.reply_text("💎 *No Gems earned yet!* Be the first to answer a quiz!", parse_mode="Markdown")
        return
    medals = ["🥇", "🥈", "🥉"]
    lines = ["💎 *TOP QUIZ GEM COLLECTORS* 🧠\n", "━━━━━━━━━━━━━━━━━━━━"]
    for i, (uid, fname, gems) in enumerate(rows):
        display = fname or str(uid)
        medal = medals[i] if i < 3 else f"{i+1}."
        lines.append(f"{medal} *{display}* — {gems} 💎")
    await send_leaderboard(update.message, "gems", "\n".join(lines), parse_mode="Markdown")


# ================= WORDLE — /wordle, /wordlestats, /wordletop, /wordlequit =====
# A polished daily Wordle-style mini-game. Each user gets up to 10 independent games
# per day (resets 5:30 AM IST). Win = +1 💎 Gem (shared quiz_gems economy). Board is
# rendered as a fresh PNG after every guess, dark Wordle-style theme.

WORDLE_DAILY_LIMIT = 10  # rewarded games per day (play itself is unlimited — see Bug 3 fix)
WORDLE_GEM_REWARD = 2    # Gems awarded per win, within the daily rewarded limit
WORDLE_MAX_ATTEMPTS = 6
WORDLE_EXPIRY_SECONDS = 10 * 60  # a game auto-expires 10 minutes after it started

WORDLE_FONT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "fonts")

_wordle_font_cache = {}

def _wordle_load_font(name: str, size: int):
    """Load a TTF font from the bundled fonts/ folder, with a safe fallback to
    PIL's built-in default font if the file is missing (so the bot never crashes
    if fonts weren't deployed alongside bot.py — board will just look plainer)."""
    key = (name, size)
    if key in _wordle_font_cache:
        return _wordle_font_cache[key]
    font = None
    try:
        font = ImageFont.truetype(os.path.join(WORDLE_FONT_DIR, name), size)
    except Exception:
        try:
            font = ImageFont.load_default()
        except Exception:
            font = None
    _wordle_font_cache[key] = font
    return font


# ── Palette — dark modern theme, distinct from the literal screenshot the user
# referenced, designed fresh for this bot rather than copied ──────────────────
_WORDLE_BG_TOP        = (18, 18, 24)
_WORDLE_BG_BOTTOM     = (10, 10, 14)
_WORDLE_TILE_EMPTY_BG = (32, 33, 41)
_WORDLE_TILE_EMPTY_BORDER = (58, 58, 68)
_WORDLE_TILE_CORRECT  = (83, 141, 78)
_WORDLE_TILE_PRESENT  = (181, 159, 59)
_WORDLE_TILE_ABSENT   = (58, 58, 62)
_WORDLE_TEXT_WHITE    = (255, 255, 255)
_WORDLE_TEXT_DIM      = (148, 148, 158)
_WORDLE_ACCENT_RED    = (255, 92, 92)
_WORDLE_W             = 1200


def _wordle_vertical_gradient(w, h, top, bottom):
    base = Image.new("RGB", (w, h), top)
    draw = ImageDraw.Draw(base)
    for y in range(h):
        t = y / max(h - 1, 1)
        r = int(top[0] + (bottom[0] - top[0]) * t)
        g = int(top[1] + (bottom[1] - top[1]) * t)
        b = int(top[2] + (bottom[2] - top[2]) * t)
        draw.line([(0, y), (w, y)], fill=(r, g, b))
    return base


def render_wordle_board(word_length: int, guesses_with_colors: list, game_num: int,
                         attempts_used: int, games_left: int, daily_limit: int,
                         status: str = "playing", answer: str = None, reward_gems: int = 0) -> io.BytesIO:
    """
    Render the current Wordle board as a PNG and return a BytesIO buffer ready
    for send_photo(). guesses_with_colors is a list of (letters[], colors[])
    tuples for each completed row; colors are 'correct' / 'present' / 'absent'.
    status: 'playing' | 'win' | 'lose'
    """
    if not PIL_AVAILABLE:
        return None

    f_title  = _wordle_load_font("BigShoulders-Bold.ttf", 72)
    f_sub    = _wordle_load_font("Outfit-Regular.ttf", 30)
    f_tile   = _wordle_load_font("BigShoulders-Bold.ttf", 64)
    f_footer = _wordle_load_font("Outfit-Bold.ttf", 34)
    f_footer_small = _wordle_load_font("Outfit-Regular.ttf", 28)
    f_banner = _wordle_load_font("BigShoulders-Bold.ttf", 84)
    f_banner_sub = _wordle_load_font("Outfit-Bold.ttf", 46)

    cols = word_length
    rows = WORDLE_MAX_ATTEMPTS
    tile_size = 150 if cols <= 5 else 130
    gap = 16
    board_w = cols * tile_size + (cols - 1) * gap
    board_h = rows * tile_size + (rows - 1) * gap
    start_x = (_WORDLE_W - board_w) // 2
    start_y = 260

    footer_y = start_y + board_h + 50
    total_h = footer_y + 100 if status == "playing" else footer_y + 290

    img = _wordle_vertical_gradient(_WORDLE_W, total_h, _WORDLE_BG_TOP, _WORDLE_BG_BOTTOM)
    draw = ImageDraw.Draw(img)

    title_plain = "WORDLE"
    bbox = draw.textbbox((0, 0), title_plain, font=f_title)
    tw = bbox[2] - bbox[0]
    draw.text(((_WORDLE_W - tw) // 2, 70), title_plain, font=f_title, fill=_WORDLE_TEXT_WHITE)

    sub = f"Game #{game_num}"
    bbox = draw.textbbox((0, 0), sub, font=f_sub)
    sw = bbox[2] - bbox[0]
    draw.text(((_WORDLE_W - sw) // 2, 160), sub, font=f_sub, fill=_WORDLE_TEXT_DIM)

    draw.line([(100, 215), (_WORDLE_W - 100, 215)], fill=(45, 45, 54), width=2)

    for r in range(rows):
        if r < len(guesses_with_colors):
            letters, colors = guesses_with_colors[r]
        else:
            letters, colors = [None] * cols, [None] * cols
        for c in range(cols):
            x0 = start_x + c * (tile_size + gap)
            y0 = start_y + r * (tile_size + gap)
            x1 = x0 + tile_size
            y1 = y0 + tile_size
            letter = letters[c] if c < len(letters) else None
            color = colors[c] if c < len(colors) else None
            if color == "correct":
                bg = border = _WORDLE_TILE_CORRECT
            elif color == "present":
                bg = border = _WORDLE_TILE_PRESENT
            elif color == "absent":
                bg = border = _WORDLE_TILE_ABSENT
            else:
                bg = _WORDLE_TILE_EMPTY_BG
                border = _WORDLE_TILE_EMPTY_BORDER
            draw.rounded_rectangle([x0, y0, x1, y1], radius=14, fill=bg, outline=border, width=3)
            if letter:
                bbox = draw.textbbox((0, 0), letter, font=f_tile)
                lw = bbox[2] - bbox[0]
                draw.text(
                    (x0 + (tile_size - lw) // 2, y0 + (tile_size - (bbox[3] - bbox[1])) // 2 - bbox[1]),
                    letter, font=f_tile, fill=_WORDLE_TEXT_WHITE
                )

    if status == "playing":
        draw.line([(100, footer_y), (_WORDLE_W - 100, footer_y)], fill=(45, 45, 54), width=2)
        ft_y = footer_y + 30
        att_text = f"Attempts: {attempts_used}/{WORDLE_MAX_ATTEMPTS}"
        draw.text((100, ft_y), att_text, font=f_footer, fill=_WORDLE_TEXT_WHITE)
        games_text = f"Games Left Today: {games_left}/{daily_limit}"
        bbox = draw.textbbox((0, 0), games_text, font=f_footer)
        gw = bbox[2] - bbox[0]
        draw.text((_WORDLE_W - 100 - gw, ft_y), games_text, font=f_footer, fill=_WORDLE_TEXT_DIM)

    elif status == "win":
        banner_y = footer_y + 10
        draw.rounded_rectangle([90, banner_y, _WORDLE_W - 90, banner_y + 260], radius=20,
                                fill=(20, 46, 24), outline=_WORDLE_TILE_CORRECT, width=3)
        win_text = "WORD CLEARED"
        bbox = draw.textbbox((0, 0), win_text, font=f_banner)
        ww = bbox[2] - bbox[0]
        draw.text(((_WORDLE_W - ww) // 2, banner_y + 25), win_text, font=f_banner, fill=(110, 210, 110))
        ans_text = f"Answer: {answer}"
        bbox = draw.textbbox((0, 0), ans_text, font=f_banner_sub)
        aw = bbox[2] - bbox[0]
        draw.text(((_WORDLE_W - aw) // 2, banner_y + 115), ans_text, font=f_banner_sub, fill=_WORDLE_TEXT_WHITE)
        reward_text = f"Attempts: {attempts_used}/{WORDLE_MAX_ATTEMPTS}   |   +{reward_gems} GEM REWARD"
        bbox = draw.textbbox((0, 0), reward_text, font=f_footer_small)
        rw = bbox[2] - bbox[0]
        draw.text(((_WORDLE_W - rw) // 2, banner_y + 185), reward_text, font=f_footer_small, fill=(200, 200, 160))

    elif status == "lose":
        banner_y = footer_y + 10
        draw.rounded_rectangle([90, banner_y, _WORDLE_W - 90, banner_y + 260], radius=20,
                                fill=(46, 20, 20), outline=_WORDLE_ACCENT_RED, width=3)
        lose_text = "GAME OVER"
        bbox = draw.textbbox((0, 0), lose_text, font=f_banner)
        lw = bbox[2] - bbox[0]
        draw.text(((_WORDLE_W - lw) // 2, banner_y + 25), lose_text, font=f_banner, fill=(230, 110, 110))
        ans_text = f"Answer: {answer}"
        bbox = draw.textbbox((0, 0), ans_text, font=f_banner_sub)
        aw = bbox[2] - bbox[0]
        draw.text(((_WORDLE_W - aw) // 2, banner_y + 115), ans_text, font=f_banner_sub, fill=_WORDLE_TEXT_WHITE)

    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    buf.name = "wordle.png"
    return buf


def _wordle_evaluate_guess(guess: str, answer: str) -> list:
    """Standard Wordle tile-coloring algorithm; correctly handles duplicate letters."""
    n = len(answer)
    colors = ["absent"] * n
    remaining = list(answer)
    for i in range(n):
        if guess[i] == answer[i]:
            colors[i] = "correct"
            remaining[i] = None
    for i in range(n):
        if colors[i] == "correct":
            continue
        if guess[i] in remaining:
            colors[i] = "present"
            remaining[remaining.index(guess[i])] = None
    return colors


def _wordle_next_game_num() -> int:
    """Atomically grab the next global Wordle game number (e.g. 'Game #47291')."""
    cursor.execute("UPDATE wordle_game_counter SET next_num = next_num + 1 WHERE id=1")
    cursor.execute("SELECT next_num FROM wordle_game_counter WHERE id=1")
    row = cursor.fetchone()
    conn.commit()
    return (row[0] - 1) if row else random.randint(10000, 99999)


def _wordle_get_daily_row(user_id: int):
    now = int(time.time())
    today_reset = get_last_5_30_ist_reset_epoch(now)
    cursor.execute(
        "INSERT OR IGNORE INTO wordle_daily (user_id, games_used, reset_epoch) VALUES (?,0,?)",
        (user_id, today_reset)
    )
    conn.commit()
    cursor.execute("SELECT games_used, reset_epoch FROM wordle_daily WHERE user_id=?", (user_id,))
    games_used, reset_epoch = cursor.fetchone()
    if reset_epoch < today_reset:
        games_used = 0
        cursor.execute(
            "UPDATE wordle_daily SET games_used=0, reset_epoch=? WHERE user_id=?",
            (today_reset, user_id)
        )
        conn.commit()
    return games_used, today_reset


def _wordle_ensure_stats_row(user_id: int):
    cursor.execute(
        "INSERT OR IGNORE INTO wordle_stats (user_id, games_played, wins, losses, gems_earned) VALUES (?,0,0,0,0)",
        (user_id,)
    )


def _wordle_expire_if_stale(user_id: int) -> bool:
    """
    If the user's active Wordle game has been running for longer than
    WORDLE_EXPIRY_SECONDS (10 minutes), mark it as expired (counts as a loss,
    no Gem) and return True. Returns False if there's no active game or it
    hasn't expired yet. Called before starting a new game and before
    processing any guess, so a forgotten/abandoned game never lingers forever
    intercepting the player's messages.
    """
    cursor.execute("SELECT status, created_at FROM wordle_games WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    if not row or row[0] != "playing":
        return False
    status, created_at = row
    if int(time.time()) - (created_at or 0) <= WORDLE_EXPIRY_SECONDS:
        return False
    cursor.execute("UPDATE wordle_games SET status='expired' WHERE user_id=?", (user_id,))
    _wordle_ensure_stats_row(user_id)
    cursor.execute(
        "UPDATE wordle_stats SET games_played = games_played + 1, losses = losses + 1 WHERE user_id=?",
        (user_id,)
    )
    conn.commit()
    return True


async def wordle_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /wordle — Start a new Wordle game. Works in DM and in groups.
    Up to 10 REWARDED games/day per user (resets 5:30 AM IST); after that,
    games can still be played but no Gems are awarded. Win = +2 💎 Gems
    (within the daily rewarded limit).
    """
    if not update.effective_user or not update.message:
        return

    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    if not PIL_AVAILABLE:
        await update.message.reply_text(
            "⚠️ Wordle image rendering isn't available right now (Pillow missing on server). "
            "Please contact the bot owner.",
            parse_mode="Markdown"
        )
        return

    # ── Already has an active game? (expire it first if it's >10 min old) ──────
    _wordle_expire_if_stale(user_id)
    cursor.execute("SELECT status FROM wordle_games WHERE user_id=?", (user_id,))
    existing = cursor.fetchone()
    if existing and existing[0] == "playing":
        await update.message.reply_text(
            "🎌 *You already have an active Wordle game!*\n\n"
            "Send your next guess as a normal message, or use /wordlequit to cancel it.",
            parse_mode="Markdown"
        )
        return

    # ── Daily REWARD eligibility (play is unlimited; only the first 10 games ──
    # of the day are reward-eligible — no hard block on starting more games) ──
    games_used, today_reset = _wordle_get_daily_row(user_id)
    is_rewarded = (games_used < WORDLE_DAILY_LIMIT) or is_admin(user_id)

    # ── Start a new game ────────────────────────────────────────────────────────
    word_length = 5  # Wordle is 5-letter-only now (per owner request)
    pool = WORDLE_WORDS_BY_LENGTH.get(word_length) or WORDLE_WORDS
    answer = random.choice(pool)
    game_num = _wordle_next_game_num()
    now = int(time.time())

    cursor.execute(
        "INSERT OR REPLACE INTO wordle_games "
        "(user_id, game_num, word, length, max_attempts, attempts, guesses, status, rewarded, created_at) "
        "VALUES (?,?,?,?,?,0,'[]','playing',?,?)",
        (user_id, game_num, answer, len(answer), WORDLE_MAX_ATTEMPTS, 1 if is_rewarded else 0, now)
    )
    if is_rewarded:
        cursor.execute(
            "UPDATE wordle_daily SET games_used = games_used + 1 WHERE user_id=?",
            (user_id,)
        )
    conn.commit()

    games_left = max(WORDLE_DAILY_LIMIT - (games_used + (1 if is_rewarded else 0)), 0)
    buf = render_wordle_board(len(answer), [], game_num, 0, games_left, WORDLE_DAILY_LIMIT, status="playing")
    reward_note = (
        f"Games Left Today (rewarded): *{games_left}/{WORDLE_DAILY_LIMIT}*"
        if is_rewarded else
        "⚠️ _Daily reward limit reached — this game is for fun only, no Gem on win._"
    )
    caption = (
        f"🎌 *Wordle #{game_num}*\n\n"
        f"Word Length: *{len(answer)}*\n"
        f"Attempts: *0/{WORDLE_MAX_ATTEMPTS}*\n"
        f"{reward_note}\n\n"
        f"Guess the word! Just send it as a message. 🍃\n"
        f"_Stuck? /wordlehint gives one free letter reveal per game._"
    )
    if buf:
        await update.message.reply_photo(photo=buf, caption=caption, parse_mode="Markdown")
    else:
        await update.message.reply_text(caption, parse_mode="Markdown")


async def wordlehint_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /wordlehint — Reveal one random letter's correct position in the answer,
    to help players who find the puzzle too tough. Limited to ONE hint per
    game so it stays helpful without trivializing the puzzle. Works in DM and
    group, same as the rest of Wordle.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id

    if _wordle_expire_if_stale(user_id):
        await update.message.reply_text(
            "⏳ Your last Wordle game already expired after 10 minutes of inactivity.\n\n"
            "Start a new one anytime with /wordle!",
            parse_mode="Markdown"
        )
        return

    cursor.execute(
        "SELECT word, length, status, hint_used, guesses FROM wordle_games WHERE user_id=?",
        (user_id,)
    )
    row = cursor.fetchone()
    if not row or row[2] != "playing":
        await update.message.reply_text(
            "🎌 You don't have an active Wordle game right now. Start one with /wordle!",
            parse_mode="Markdown"
        )
        return

    answer, length, status, hint_used, guesses_json = row
    if hint_used:
        await update.message.reply_text(
            "💡 You've already used your hint for this game — only one hint per game!\n\n"
            "Keep guessing, you've got this! 🍃",
            parse_mode="Markdown"
        )
        return

    # ── Figure out which positions are already correctly revealed, so the ────
    # hint doesn't waste itself on something the player already knows ───────
    import json as _json_hint
    try:
        guesses_list = _json_hint.loads(guesses_json) if guesses_json else []
    except Exception:
        guesses_list = []

    already_correct_positions = set()
    for g in guesses_list:
        for i, c in enumerate(g.get("colors", [])):
            if c == "correct":
                already_correct_positions.add(i)

    candidate_positions = [i for i in range(length) if i not in already_correct_positions]
    if not candidate_positions:
        # Every letter is already revealed via correct guesses — nothing left to hint.
        await update.message.reply_text(
            "💡 You've already revealed every letter through correct guesses — no hint needed!",
            parse_mode="Markdown"
        )
        return

    hint_pos = random.choice(candidate_positions)
    hint_letter = answer[hint_pos]

    cursor.execute("UPDATE wordle_games SET hint_used=1 WHERE user_id=?", (user_id,))
    conn.commit()

    await update.message.reply_text(
        f"💡 *Hint:* Letter *{hint_pos + 1}* of the word is *{hint_letter}*.\n\n"
        f"Use it wisely — only one hint per game! 🍃",
        parse_mode="Markdown"
    )


async def wordlequit_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/wordlequit — Cancel the user's active Wordle game, if any."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if _wordle_expire_if_stale(user_id):
        await update.message.reply_text(
            "⏳ Your last Wordle game already expired after 10 minutes of inactivity.\n\n"
            "Start a new one anytime with /wordle!",
            parse_mode="Markdown"
        )
        return
    cursor.execute("SELECT status, word FROM wordle_games WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    if not row or row[0] != "playing":
        await update.message.reply_text(
            "🎌 You don't have an active Wordle game right now. Start one with /wordle!",
            parse_mode="Markdown"
        )
        return
    answer = row[1]
    cursor.execute("UPDATE wordle_games SET status='cancelled' WHERE user_id=?", (user_id,))
    _wordle_ensure_stats_row(user_id)
    cursor.execute("UPDATE wordle_stats SET games_played = games_played + 1, losses = losses + 1 WHERE user_id=?", (user_id,))
    conn.commit()
    await update.message.reply_text(
        f"🚫 *Game Cancelled.*\n\nThe word was: *{answer}*\n\nStart a new one anytime with /wordle!",
        parse_mode="Markdown"
    )


async def wordlestats_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/wordlestats — Show the user's lifetime Wordle statistics."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    _wordle_ensure_stats_row(user_id)
    conn.commit()
    cursor.execute(
        "SELECT games_played, wins, losses, gems_earned FROM wordle_stats WHERE user_id=?",
        (user_id,)
    )
    games_played, wins, losses, gems_earned = cursor.fetchone()
