async def shinobi_coins_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/shinobi_coins — Show your current coin balance."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    coins = get_coins(user_id)
    user_name = safe_name(update.effective_user.first_name or "Shinobi")

    # Rank among all users
    cursor.execute("SELECT COUNT(*)+1 FROM shinobi_coins WHERE coins > ?", (coins,))
    rank = cursor.fetchone()[0]

    await update.message.reply_text(
        f"🪙 *SHINOBI COINS WALLET*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🥷 Shinobi: *{user_name}*\n"
        f"💰 Balance: *{coins:,} coins*\n"
        f"🏆 Global Rank: *#{rank}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"💡 *Earn coins by:*\n"
        f"  🎴 Catching cards (50–600 per rarity)\n"
        f"  📅 /daily → +{COIN_DAILY_AMOUNT} coins\n"
        f"  📆 /weekly → +{COIN_WEEKLY_AMOUNT} coins\n"
        f"  🗓️ /monthly → +{COIN_MONTHLY_AMOUNT} coins\n\n"
        f"🎲 Use /bet to gamble your coins!",
        parse_mode="Markdown"
    )


async def top_shinobi_coins(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/top_shinobi_coins — Top 10 coin holders."""
    if not update.effective_user or not update.message:
        return

    cursor.execute("""
        SELECT sc.user_id, sc.coins,
               COALESCE(bu.first_name, CAST(sc.user_id AS TEXT)) AS name
        FROM shinobi_coins sc
        LEFT JOIN bot_users bu ON bu.user_id = sc.user_id
        WHERE sc.coins > 0
        ORDER BY sc.coins DESC
        LIMIT 10
    """)
    rows = cursor.fetchall()

    if not rows:
        await update.message.reply_text("🪙 No coin data yet. Start catching shinobis!")
        return

    MEDALS = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]
    lines = []
    for i, (uid, coins, name) in enumerate(rows):
        lines.append(f"{MEDALS[i]} *{safe_name(name)}* — `{coins:,}` 🪙")

    board = "\n".join(lines)
    await send_leaderboard(
        update.message,
        "shinobi_coins",
        f"🏆 *TOP 10 SHINOBI COIN HOLDERS*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"{board}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"💡 Catch rare cards & claim daily rewards to climb the ranks!",
        parse_mode="Markdown"
    )


# ── /ryo — Bug 8: check your Ryo balance ─────────────────────────────────────

async def ryo_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/ryo — Show your current Ryo balance (the betting currency)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    # FIX (Bug 5 — /ryo completely not working): wrap the whole command in a
    # try/except. Previously any exception here (e.g. a Markdown parse
    # error from an unescaped display name — see safe_name() above) was
    # caught only by the global error_handler, which just prints to the
    # console for anything it doesn't specifically recognise. The user got
    # zero reply and zero indication anything went wrong. Now the user
    # always gets a response, and if something really does break, the
    # admin log group gets the traceback so it can actually be diagnosed.
    try:
        ryo = get_ryo(user_id)
        user_name = safe_name(update.effective_user.first_name or "Shinobi")

        cursor.execute("SELECT COUNT(*)+1 FROM ryo_balances WHERE ryo > ?", (ryo,))
        rank = cursor.fetchone()[0]

        bets_left = bets_remaining_today(user_id)

        await update.message.reply_text(
            f"🪙 *RYO WALLET*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🥷 Shinobi: *{user_name}*\n"
            f"💰 Balance: *{ryo:,} Ryo* 🪙\n"
            f"🏆 Global Rank: *#{rank}*\n"
            f"🎲 Bets left today: *{bets_left}/{MAX_BETS_PER_DAY}*\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"💡 *Earn Ryo by:*\n"
            f"  🎴 Catching cards (100–2000 per rarity)\n"
            f"  📅 /daily → +{RYO_DAILY_AMOUNT} Ryo\n"
            f"  📆 /weekly → +{RYO_WEEKLY_AMOUNT} Ryo\n"
            f"  🗓️ /monthly → +{RYO_MONTHLY_AMOUNT} Ryo\n\n"
            f"🎲 Use /bet, /bowl, /football, /basketball, /multiplier, "
            f"/roulette or /mines to gamble your Ryo!",
            parse_mode="Markdown"
        )
    except Exception as e:
        print(f"[RYO] /ryo failed for user {user_id}: {e}")
        try:
            await update.message.reply_text(
                "⚠️ Couldn't load your Ryo wallet right now. Please try again — "
                "the admins have been notified."
            )
        except Exception:
            pass
        try:
            await log_to_group(context.bot, f"🐞 *//ryo error*\nUser: `{user_id}`\n`{e}`")
        except Exception:
            pass


async def top_ryo_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/top_ryo — Top 10 Ryo holders (Bug 8)."""
    if not update.effective_user or not update.message:
        return

    # FIX (Bug 5 — /top_ryo completely not working): same try/except +
    # name-escaping fix as /ryo above. Leaderboards are especially exposed
    # to this because they render OTHER players' first_name values —
    # exactly the decorated, symbol-heavy names common in this group (see
    # safe_name() for the full explanation).
    try:
        cursor.execute("""
            SELECT rb.user_id, rb.ryo,
                   COALESCE(bu.first_name, CAST(rb.user_id AS TEXT)) AS name
            FROM ryo_balances rb
            LEFT JOIN bot_users bu ON bu.user_id = rb.user_id
            WHERE rb.ryo > 0
            ORDER BY rb.ryo DESC
            LIMIT 10
        """)
        rows = cursor.fetchall()

        if not rows:
            await update.message.reply_text("🪙 No Ryo data yet. Start catching shinobis or claim /daily!")
            return

        MEDALS = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]
        lines = []
        for i, (uid, ryo, name) in enumerate(rows):
            lines.append(f"{MEDALS[i]} *{safe_name(name)}* — `{ryo:,}` 🪙")

        board = "\n".join(lines)
        await send_leaderboard(
            update.message,
            "top_ryo",
            f"🏆 *TOP 10 RYO HOLDERS*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"{board}\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"💡 Catch rare cards & claim daily rewards to climb the ranks!",
            parse_mode="Markdown"
        )
    except Exception as e:
        print(f"[TOP_RYO] /top_ryo failed: {e}")
        try:
            await update.message.reply_text(
                "⚠️ Couldn't load the Ryo leaderboard right now. Please try again — "
                "the admins have been notified."
            )
        except Exception:
            pass
        try:
            await log_to_group(context.bot, f"🐞 *//top_ryo error*\n`{e}`")
        except Exception:
            pass


# ── /bet ─────────────────────────────────────────────────────────────────────

async def bet(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /bet <amount> h|t|heads|tails       — coin flip
    /bet <amount> o|odd|e|even          — dice odd/even
    /bet <amount> high|low              — dice high (4-6) / low (1-3)
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            "🎲 *HOW TO BET*\n\n"
            "━━━━━━━━━━━━━━━━━━━━━━\n"
            "🪙 *Coin Flip:*\n"
            "  `/bet <amount> h` — heads\n"
            "  `/bet <amount> t` — tails\n\n"
            "🎲 *Dice Odd/Even:*\n"
            "  `/bet <amount> o` or `odd`\n"
            "  `/bet <amount> e` or `even`\n\n"
            "🎲 *Dice High/Low:*\n"
            "  `/bet <amount> high` — rolls 4,5,6\n"
            "  `/bet <amount> low` — rolls 1,2,3\n"
            "━━━━━━━━━━━━━━━━━━━━━━\n"
            "💡 Win = double your bet | Lose = lose your bet\n"
            "🪙 Bets are placed in *Ryo* — check yours with /ryo\n"
            f"📊 Limit: *{MAX_BETS_PER_DAY} bets/day* across every betting game",
            parse_mode="Markdown"
        )
        return

    try:
        amount = int(args[0])
    except ValueError:
        await update.message.reply_text("❌ Bet amount must be a number.")
        return

    if amount <= 0:
        await update.message.reply_text("❌ Bet amount must be greater than 0.")
        return

    current = get_ryo(user_id)
    if current < amount:
        await update.message.reply_text(
            f"😔 *Not Enough Ryo!*\n\n"
            f"💰 You need: *{amount:,} Ryo*\n"
            f"💸 You have: *{current:,} Ryo*\n\n"
            f"💡 Catch cards, claim /daily, /weekly, /monthly to earn more!\n"
            f"🌟 Better luck next time, shinobi!",
            parse_mode="Markdown"
        )
        return

    cooldown_msg = check_bet_cooldown(user_id)
    if cooldown_msg:
        await update.message.reply_text(cooldown_msg, parse_mode="Markdown")
        return

    # FIX (Bug 8 — 30 bets/day cap): applies across every betting game combined,
    # win or lose, no matter what.
    if bets_remaining_today(user_id) <= 0:
        await update.message.reply_text(
            "🛑 *Daily Bet Limit Reached!*\n\n"
            f"You've used all *{MAX_BETS_PER_DAY}* bets for today (win or lose, they all count).\n"
            "⏰ Come back after the next 5:30 AM IST reset!",
            parse_mode="Markdown"
        )
        return
    mark_bet_placed(user_id)
    increment_bets_today(user_id)  # Bug 8: counts toward the 30/day cap

    bet_type = args[1].lower()
    user_name = update.effective_user.first_name or "Shinobi"
    bet_chat_id = update.effective_chat.id if update.effective_chat else None
    bet_chat_title = (update.effective_chat.title if update.effective_chat and update.effective_chat.title else None)

    # ── COIN FLIP ──────────────────────────────────────────────────────────────
    if bet_type in ("h", "heads", "t", "tails"):
        user_choice = "heads" if bet_type in ("h", "heads") else "tails"
        result = random.choice(["heads", "tails"])
        won = (user_choice == result)
        result_emoji = "🦅" if result == "heads" else "🦁"
        choice_emoji  = "🦅" if user_choice == "heads" else "🦁"

        if won:
            add_ryo(user_id, amount)
            new_bal = get_ryo(user_id)
            await update.message.reply_text(
                f"🪙 *COIN FLIP RESULT!*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"{choice_emoji} You chose: *{user_choice.title()}*\n"
                f"{result_emoji} Result: *{result.title()}*\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"🎉🏆 *CONGRATULATIONS, {user_name}!*\n\n"
                f"⚡ You crushed it, shinobi warrior!\n"
                f"💰 *+{amount:,} Ryo* added to your wallet!\n"
                f"💼 New Balance: *{new_bal:,} Ryo* 🪙\n\n"
                f"🔥 The ninja gods smile upon you today! 🌟",
                parse_mode="Markdown"
            )
            username_tag = f"@{update.effective_user.username}" if update.effective_user.username else f"ID: `{user_id}`"
            await log_bet(
                context.bot,
                f"🪙 *Bet Log — Coin Flip*\n\n"
                f"👤 *{user_name}* ({username_tag})\n"
                f"🎯 Bet: *{user_choice.title()}* | Result: *{result.title()}*\n"
                f"💰 Amount: *{amount:,}* Ryo\n"
                f"🏆 *Result: WIN* (+{amount:,} Ryo)",
                chat_id=bet_chat_id,
                chat_title=bet_chat_title
            )
        else:
            deduct_ryo(user_id, amount)
            new_bal = get_ryo(user_id)
            await update.message.reply_text(
                f"🪙 *COIN FLIP RESULT!*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"{choice_emoji} You chose: *{user_choice.title()}*\n"
                f"{result_emoji} Result: *{result.title()}*\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"😔💸 *Sorry, {user_name}... You Lost!*\n\n"
                f"🌪️ The coin didn't favor you this time!\n"
                f"💸 *-{amount:,} Ryo* deducted.\n"
                f"💼 Remaining: *{new_bal:,} Ryo* 🪙\n\n"
                f"💪 Don't give up! Give your best next time! 🌟",
                parse_mode="Markdown"
            )
            username_tag = f"@{update.effective_user.username}" if update.effective_user.username else f"ID: `{user_id}`"
            await log_bet(
                context.bot,
                f"🪙 *Bet Log — Coin Flip*\n\n"
                f"👤 *{user_name}* ({username_tag})\n"
                f"🎯 Bet: *{user_choice.title()}* | Result: *{result.title()}*\n"
                f"💰 Amount: *{amount:,}* Ryo\n"
                f"💀 *Result: LOSS* (-{amount:,} Ryo)",
                chat_id=bet_chat_id,
                chat_title=bet_chat_title
            )
        return

    # ── DICE BETS ──────────────────────────────────────────────────────────────
    if bet_type in ("o", "odd", "e", "even", "high", "low"):
        # Send the dice and wait for the result
        dice_msg = await update.message.reply_dice(emoji="🎲")
        dice_value = dice_msg.dice.value   # 1–6, already random from Telegram
        await asyncio.sleep(3)             # wait for animation

        if bet_type in ("o", "odd"):
            user_pred = "odd"
            won = (dice_value % 2 != 0)
            pred_emoji = "🔢"
        elif bet_type in ("e", "even"):
            user_pred = "even"
            won = (dice_value % 2 == 0)
            pred_emoji = "🔣"
        elif bet_type == "high":
            user_pred = "high (4–6)"
            won = (dice_value >= 4)
            pred_emoji = "⬆️"
        else:
            user_pred = "low (1–3)"
            won = (dice_value <= 3)
            pred_emoji = "⬇️"

        if won:
            add_ryo(user_id, amount)
            new_bal = get_ryo(user_id)
            await update.message.reply_text(
                f"🎲 *DICE RESULT: {dice_value}!*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"{pred_emoji} Your bet: *{user_pred}*\n"
                f"🎯 Result: *{dice_value}* ({'odd' if dice_value%2 else 'even'})\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"🎉🔥 *WINNER WINNER, {user_name}!*\n\n"
                f"⚔️ Your shinobi instincts were perfect!\n"
                f"💰 *+{amount:,} Ryo* added!\n"
                f"💼 New Balance: *{new_bal:,} Ryo* 🪙\n\n"
                f"🌟 The dice bow before a true ninja! 🥷",
                parse_mode="Markdown"
            )
            username_tag = f"@{update.effective_user.username}" if update.effective_user.username else f"ID: `{user_id}`"
            await log_bet(
                context.bot,
                f"🎲 *Bet Log — Dice*\n\n"
                f"👤 *{user_name}* ({username_tag})\n"
                f"🎯 Bet: *{user_pred}* | Dice: *{dice_value}*\n"
                f"💰 Amount: *{amount:,}* Ryo\n"
                f"🏆 *Result: WIN* (+{amount:,} Ryo)",
                chat_id=bet_chat_id,
                chat_title=bet_chat_title
            )
        else:
            deduct_ryo(user_id, amount)
            new_bal = get_ryo(user_id)
            await update.message.reply_text(
                f"🎲 *DICE RESULT: {dice_value}!*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n"
                f"{pred_emoji} Your bet: *{user_pred}*\n"
                f"🎯 Result: *{dice_value}* ({'odd' if dice_value%2 else 'even'})\n"
                f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
                f"😤💨 *So close, {user_name}... You Lost!*\n\n"
                f"🌪️ The dice were against you today!\n"
                f"💸 *-{amount:,} Ryo* deducted.\n"
                f"💼 Remaining: *{new_bal:,} Ryo* 🪙\n\n"
                f"🔥 Train harder and come back stronger! 💪",
                parse_mode="Markdown"
            )
            username_tag = f"@{update.effective_user.username}" if update.effective_user.username else f"ID: `{user_id}`"
            await log_bet(
                context.bot,
                f"🎲 *Bet Log — Dice*\n\n"
                f"👤 *{user_name}* ({username_tag})\n"
                f"🎯 Bet: *{user_pred}* | Dice: *{dice_value}*\n"
                f"💰 Amount: *{amount:,}* Ryo\n"
                f"💀 *Result: LOSS* (-{amount:,} Ryo)",
                chat_id=bet_chat_id,
                chat_title=bet_chat_title
            )
        return

    await update.message.reply_text(
        "❓ Unknown bet type.\n\n"
        "Valid options: `h` `t` `o` `e` `odd` `even` `high` `low`",
        parse_mode="Markdown"
    )


# ── /add_shinobi_coins (Owner only) ──────────────────────────────────────────

async def reset_shinobi_coins_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: /reset_shinobi_coins CONFIRM — wipe Shinobi Coins to 0 for
    EVERY user (Bug 9). Separate and independent from the Ryo reset below."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only command.")
        return

    args = context.args or []
    if not args or args[0].strip().upper() != "CONFIRM":
        cursor.execute("SELECT COUNT(*) FROM shinobi_coins WHERE coins > 0")
        affected = cursor.fetchone()[0]
        await update.message.reply_text(
            f"⚠️ *This will reset Shinobi Coins to 0 for ALL {affected} users with a balance.*\n\n"
            f"This does NOT touch Ryo, vouchers, or cards.\n\n"
            f"Type `/reset_shinobi_coins CONFIRM` to proceed.",
            parse_mode="Markdown"
        )
        return

    cursor.execute("UPDATE shinobi_coins SET coins = 0")
    conn.commit()

    await update.message.reply_text(
        "✅ *Shinobi Coins have been reset to 0 for every user.*",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🪙 *Shinobi Coins Reset*\n👤 By: {safe_name(update.effective_user.first_name)} (`{update.effective_user.id}`)"
    )


# ── /reset_all_currency (Owner only — Bug 6) ─────────────────────────────────
# Adds the fully comprehensive reset the owner asked for: wipes Shinobi
# Coins AND the clan vault (clan_deposits) completely, for every user, in
# one command. This is intentionally separate from /reset_shinobi_coins and
# /reset_ryo above — those two are kept exactly as they were (nothing
# removed), this is a new, stronger "wipe everything currency-related"
# command for when the owner wants a totally clean slate across the whole
# bot instead of resetting coins and the vault separately by hand.
async def reset_all_currency_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: /reset_all_currency CONFIRM — completely wipes Shinobi
    Coins AND every clan's vault (deposits) to 0, for every user, in a
    single command. Does NOT touch Ryo balances, draft vouchers, or cards —
    use /reset_ryo separately if you also want Ryo wiped."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only command.")
        return

    args = context.args or []
    if not args or args[0].strip().upper() != "CONFIRM":
        cursor.execute("SELECT COUNT(*) FROM shinobi_coins WHERE coins > 0")
        coin_affected = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM clan_deposits")
        vault_rows = cursor.fetchone()[0]
        cursor.execute("SELECT COALESCE(SUM(amount),0) FROM clan_deposits")
        vault_total = cursor.fetchone()[0]
        await update.message.reply_text(
            f"⚠️ *FULL CURRENCY RESET*\n\n"
            f"This will completely wipe, for EVERY user:\n"
            f"  🪙 Shinobi Coins → 0 (currently *{coin_affected}* users have a balance)\n"
            f"  🏯 Every clan's vault/treasury deposits → 0 "
            f"(*{vault_rows}* deposit entries totalling *{vault_total:,}*)\n\n"
            f"This does NOT touch Ryo, draft vouchers, or cards.\n\n"
            f"Type `/reset_all_currency CONFIRM` to proceed. This cannot be undone.",
            parse_mode="Markdown"
        )
        return

    cursor.execute("UPDATE shinobi_coins SET coins = 0")
    cursor.execute("DELETE FROM clan_deposits")
    conn.commit()

    await update.message.reply_text(
        "✅ *Full Currency Reset Complete!*\n\n"
        "🪙 Shinobi Coins reset to 0 for every user.\n"
        "🏯 Every clan's vault has been completely emptied.",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🪙 *FULL Currency Reset (coins + all clan vaults)*\n"
        f"👤 By: {safe_name(update.effective_user.first_name)} (`{update.effective_user.id}`)"
    )


# ── /full_shinobi_reset (Owner only — Bug 6) ─────────────────────────────────
# The definitive "totally fresh start" reset the owner asked for: wipes
# Shinobi Coins AND every clan's treasury completely, then gives EVERY
# registered user a starting balance of exactly 30,000 Shinobi Coins plus
# 1 random Mermaid-rarity card. This is intentionally separate from
# /reset_all_currency and /reset_all_shinobi_coins above (kept exactly as
# they were, nothing removed) — this is the new, single "reset + starter
# pack" command for a clean relaunch of the whole coin economy.
STARTER_RESET_COINS = 30000


async def full_shinobi_reset_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: /full_shinobi_reset CONFIRM — wipes Shinobi Coins AND every
    clan's treasury for every user, then sets every user's Shinobi Coins to
    exactly 30,000 and grants each of them 1 random Mermaid card."""
    if not update.effective_user or not update.message:
        return
    if not _is_owner(update.effective_user.id):
        await update.message.reply_text("🚫 Owner only.")
        return

    args = context.args or []
    if not args or args[0].strip().upper() != "CONFIRM":
        cursor.execute("SELECT COUNT(*) FROM bot_users")
        total_users = cursor.fetchone()[0]
        cursor.execute("SELECT COALESCE(SUM(amount),0) FROM clan_deposits")
        treasury_total = cursor.fetchone()[0]
        cursor.execute("SELECT COUNT(*) FROM cards WHERE rarity='Mermaid'")
        mermaid_pool = cursor.fetchone()[0]
        await update.message.reply_text(
            f"⚠️ *FULL SHINOBI COIN RESET*\n\n"
            f"This will, for EVERY registered user (~{total_users} users):\n"
            f"  🪙 Wipe Shinobi Coins and set the balance to exactly *{STARTER_RESET_COINS:,}*\n"
            f"  🏯 Completely empty every clan's treasury "
            f"(currently *{treasury_total:,}* total)\n"
            f"  🧜🏻 Grant *1 random Mermaid card* (pool has {mermaid_pool} Mermaid card(s))\n\n"
            f"This does NOT touch Ryo, draft vouchers, or existing cards other than the new Mermaid card.\n\n"
            f"Type `/full_shinobi_reset CONFIRM` to proceed. This cannot be undone.",
            parse_mode="Markdown"
        )
        return

    cursor.execute("SELECT COUNT(*) FROM cards WHERE rarity='Mermaid'")
    if cursor.fetchone()[0] == 0:
        await update.message.reply_text(
            "❌ There are no Mermaid-rarity cards in the catalog yet — add at least one with "
            "`/addcard` before running this reset.",
            parse_mode="Markdown"
        )
        return

    # 1) Wipe every clan's treasury completely.
    cursor.execute("DELETE FROM clan_deposits")

    # 2) Set every registered user's Shinobi Coins to exactly STARTER_RESET_COINS
    #    (a hard SET, not an add — per spec, everyone starts fresh at 30,000).
    cursor.execute("SELECT user_id FROM bot_users")
    all_users = [r[0] for r in cursor.fetchall()]
    for uid in all_users:
        cursor.execute(
            "INSERT INTO shinobi_coins (user_id, coins) VALUES (?, ?) "
            "ON CONFLICT(user_id) DO UPDATE SET coins=excluded.coins",
            (uid, STARTER_RESET_COINS)
        )
    conn.commit()

    # 3) Grant every user 1 random Mermaid card.
    granted = 0
    for uid in all_users:
        cursor.execute(
            "SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards "
            "WHERE rarity='Mermaid' ORDER BY RANDOM() LIMIT 1"
        )
        mcard = cursor.fetchone()
        if not mcard:
            continue
        mcid, mname, mrarity, mfile_id, mfile_type = mcard
        insert_user_card(uid, mname, mrarity, mfile_id, file_type=mfile_type, card_id=mcid)
        granted += 1
    conn.commit()

    await update.message.reply_text(
        f"✅ *Full Shinobi Reset Complete!*\n\n"
        f"🪙 Every user's Shinobi Coins reset to *{STARTER_RESET_COINS:,}*.\n"
        f"🏯 Every clan's treasury has been completely emptied.\n"
        f"🧜🏻 {granted}/{len(all_users)} users received 1 random Mermaid card.",
        parse_mode="Markdown"
    )

    notified = 0
    for uid in all_users:
        try:
            await context.bot.send_message(
                chat_id=uid,
                text=(
                    f"🔄 *Shinobi Coin Economy Reset!*\n\n"
                    f"🪙 Your balance is now *{STARTER_RESET_COINS:,} Shinobi Coins*.\n"
                    f"🧜🏻 You've also received a random Mermaid card — check `/collection`!"
                ),
                parse_mode="Markdown"
            )
            notified += 1
            await asyncio.sleep(0.05)
        except Exception:
            pass

    await log_to_group(
        context.bot,
        f"🪙 *FULL SHINOBI RESET*\n"
        f"👤 By: {safe_name(update.effective_user.first_name)} (`{update.effective_user.id}`)\n"
        f"All {len(all_users)} users set to {STARTER_RESET_COINS:,} coins, clan treasuries wiped, "
        f"{granted} Mermaid cards granted, {notified} users notified."
    )


async def reset_ryo_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: /reset_ryo CONFIRM — reinitialize Ryo (Bug 8). Every user's
    Ryo balance is set to RYO_RESET_AMOUNT (25000), and — per spec — clan
    treasury deposits are wiped too, since deposits going forward are made
    in Ryo and old deposits were made in the (now-separate) Shinobi Coins."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only command.")
        return

    args = context.args or []
    if not args or args[0].strip().upper() != "CONFIRM":
        cursor.execute("SELECT COUNT(*) FROM bot_users")
        total_users = cursor.fetchone()[0]
        cursor.execute("SELECT COALESCE(SUM(amount),0) FROM clan_deposits")
        treasury_total = cursor.fetchone()[0]
        await update.message.reply_text(
            f"⚠️ *This will:*\n"
            f"  🪙 Set Ryo to *{RYO_RESET_AMOUNT:,}* for every registered user (~{total_users} users)\n"
            f"  🏯 Wipe ALL clan treasury deposits (currently *{treasury_total:,}* total)\n\n"
            f"This does NOT touch Shinobi Coins, vouchers, or cards.\n\n"
            f"Type `/reset_ryo CONFIRM` to proceed.",
            parse_mode="Markdown"
        )
        return

    cursor.execute("SELECT user_id FROM bot_users")
    all_users = [r[0] for r in cursor.fetchall()]
    for uid in all_users:
        cursor.execute(
            "INSERT INTO ryo_balances (user_id, ryo, last_daily, last_weekly, last_monthly) "
            "VALUES (?,?,0,0,0) "
            "ON CONFLICT(user_id) DO UPDATE SET ryo=excluded.ryo",
            (uid, RYO_RESET_AMOUNT)
        )
    cursor.execute("DELETE FROM clan_deposits")
    conn.commit()

    await update.message.reply_text(
        f"✅ *Ryo Reset Complete!*\n\n"
        f"🪙 Every user now has *{RYO_RESET_AMOUNT:,} Ryo*.\n"
        f"🏯 All clan treasury deposits have been cleared — clans now deposit fresh using Ryo.",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🪙 *Ryo Reset*\n👤 By: {update.effective_user.first_name} (`{update.effective_user.id}`)\n"
        f"All users set to {RYO_RESET_AMOUNT:,} Ryo, clan deposits wiped."
    )


async def add_shinobi_coins_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Owner only: /add_shinobi_coins <amount> — add coins to self or reply/mention target."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only command.")
        return

    args = context.args or []
    target_id = None
    target_name = None
    amount = None

    replied = update.message.reply_to_message
    if replied and replied.from_user and not replied.from_user.is_bot:
        target_id   = replied.from_user.id
        target_name = replied.from_user.first_name or str(target_id)
        if not args:
            await update.message.reply_text("❌ Usage (reply): /add_shinobi_coins <amount>")
            return
        try:
            amount = int(args[0])
        except ValueError:
            await update.message.reply_text("❌ Amount must be a number.")
            return
    elif args:
        first = args[0]
        if first.startswith("@"):
            username = first.lstrip("@")
            cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (username,))
            row = cursor.fetchone()
            if not row:
                await update.message.reply_text(f"❌ User @{username} not found.")
                return
            target_id, target_name = row
            if len(args) < 2:
                await update.message.reply_text("❌ Usage: /add_shinobi_coins @username <amount>")
                return
            try:
                amount = int(args[1])
            except ValueError:
                await update.message.reply_text("❌ Amount must be a number.")
                return
        elif first.lstrip("-").isdigit() and len(first) > 5:
            try:
                target_id = int(first)
            except ValueError:
                await update.message.reply_text("❌ Invalid user ID.")
                return
            try:
                tc = await context.bot.get_chat(target_id)
                target_name = tc.first_name or str(target_id)
            except Exception:
                target_name = str(target_id)
            if len(args) < 2:
                await update.message.reply_text("❌ Usage: /add_shinobi_coins <user_id> <amount>")
                return
            try:
                amount = int(args[1])
            except ValueError:
                await update.message.reply_text("❌ Amount must be a number.")
                return
        else:
            try:
                amount = int(first)
                target_id   = update.effective_user.id
                target_name = update.effective_user.first_name or "Owner"
            except ValueError:
                await update.message.reply_text(
                    "❌ Usage:\n"
                    "• `/add_shinobi_coins <amount>` — add to yourself\n"
                    "• Reply + `/add_shinobi_coins <amount>`\n"
                    "• `/add_shinobi_coins @username <amount>`\n"
                    "• `/add_shinobi_coins <user_id> <amount>`",
                    parse_mode="Markdown"
                )
                return
    else:
        await update.message.reply_text(
            "❌ Usage:\n"
            "• `/add_shinobi_coins <amount>` — add to yourself\n"
            "• Reply + `/add_shinobi_coins <amount>`\n"
            "• `/add_shinobi_coins @username <amount>`\n"
            "• `/add_shinobi_coins <user_id> <amount>`",
            parse_mode="Markdown"
        )
        return

    if amount <= 0:
        await update.message.reply_text("❌ Amount must be greater than 0.")
        return

    add_coins(target_id, amount)
    new_total = get_coins(target_id)

    await update.message.reply_text(
        f"✅ *Shinobi Coins Added!*\n\n"
        f"👤 User: *{target_name}* (`{target_id}`)\n"
        f"🪙 Added: *+{amount:,}*\n"
        f"💰 New Total: *{new_total:,}*",
        parse_mode="Markdown"
    )


