# ── /give_shinobi_coins <amount> — Send coins to another user ────────────────
async def give_shinobi_coins(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    /give_shinobi_coins <amount> — reply to a user or tag @username
    Transfers coins from sender to target user.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    if not context.args:
        await update.message.reply_text(
            "💸 *Give Shinobi Coins*\n\n"
            "Usage:\n"
            "• Reply to a user's message: `/give_shinobi_coins <amount>`\n"
            "• Tag their username: `/give_shinobi_coins <amount> @username`\n\n"
            "Example: `/give_shinobi_coins 100`",
            parse_mode="Markdown"
        )
        return

    try:
        amount = int(context.args[0])
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Please enter a valid positive number.")
        return

    # ── Resolve target user ───────────────────────────────────────────────────
    target_id = None
    target_name = None

    # Priority 1: reply to message
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        target_user = update.message.reply_to_message.from_user
        if not target_user.is_bot:
            target_id = target_user.id
            target_name = target_user.first_name or str(target_id)

    # Priority 2: @username in args
    if target_id is None and len(context.args) >= 2:
        raw = context.args[1].lstrip("@")
        try:
            chat = await context.bot.get_chat(f"@{raw}")
            target_id = chat.id
            target_name = chat.first_name or raw
        except Exception:
            await update.message.reply_text(
                f"❌ Could not find user `@{raw}`. Make sure the username is correct.",
                parse_mode="Markdown"
            )
            return

    if target_id is None:
        await update.message.reply_text(
            "❌ Please reply to a user's message or provide their @username.\n\n"
            "Example: `/give_shinobi_coins 100 @username`",
            parse_mode="Markdown"
        )
        return

    if target_id == user_id:
        await update.message.reply_text("❌ You can't send coins to yourself!")
        return

    # ── Check sender balance ──────────────────────────────────────────────────
    sender_coins = get_coins(user_id)
    if sender_coins < amount:
        await update.message.reply_text(
            f"💔 *Insufficient Coins!*\n\n"
            f"🪙 You only have *{sender_coins}* Shinobi Coins.\n"
            f"You need *{amount}* to complete this transfer.\n\n"
            f"Earn more with /daily, /weekly, /monthly! 💪",
            parse_mode="Markdown"
        )
        return

    sender_name = update.effective_user.first_name or "Shinobi"

    # ── Transfer ──────────────────────────────────────────────────────────────
    deduct_coins(user_id, amount)
    add_coins(target_id, amount)

    sender_new = get_coins(user_id)
    target_new = get_coins(target_id)

    await update.message.reply_text(
        f"✅ *Shinobi Coins Transferred!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📤 From: *{sender_name}*\n"
        f"📥 To: *{target_name}*\n"
        f"🪙 Amount: *{amount} Shinobi Coins*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"💼 Your balance: *{sender_new}* coins",
        parse_mode="Markdown"
    )

    # Notify receiver in DM
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=(
                f"🎁 *You received Shinobi Coins!*\n\n"
                f"📤 From: *{sender_name}*\n"
                f"🪙 Amount: *+{amount} Shinobi Coins*\n"
                f"💼 Your balance: *{target_new}* coins\n\n"
                f"Use /shinobi\\_coins to check your wallet! 🔥"
            ),
            parse_mode="Markdown"
        )
    except Exception:
        pass  # User might not have DM'd the bot

    await log_to_group(
        context.bot,
        f"🪙 *Coin Transfer*\n\n"
        f"📤 {sender_name} (`{user_id}`)\n"
        f"📥 {target_name} (`{target_id}`)\n"
        f"💰 Amount: {amount} coins"
    )


# ================= SHOP SYSTEM =================

async def shop(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/shop — Open the Shinobi Card Shop."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    coins = get_coins(user_id)
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("🛒 Daily Deals", callback_data="shop_daily")],
        [InlineKeyboardButton("🎟️ Purchase Vouchers", callback_data="shop_vouchers")],
        [InlineKeyboardButton("🪙 My Coins", callback_data="shop_coins")],
    ])
    await update.message.reply_text(
        f"🏯 *SHINOBI CARD SHOP* 🏯\n\n"
        f"{'━' * 24}\n"
        f"🪙 Your Coins: *{coins}*\n"
        f"{'━' * 24}\n\n"
        f"✨ *Buy rare shinobi cards using your coins!*\n\n"
        f"🛒 *Daily Deals* — 6 new cards every day at 5:30 AM\n"
        f"Each user gets their own unique set of deals!\n"
        f"🛒 Limit: *3 card purchases per day*\n\n"
        f"🎟️ *Purchase Vouchers* — 500 coins each (up to 10/day)\n\n"
        f"👇 Choose a category:",
        reply_markup=keyboard,
        parse_mode="Markdown"
    )


async def shop_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle all shop inline button callbacks."""
    query = update.callback_query
    await query.answer()

    user_id = query.from_user.id
    user_name = query.from_user.first_name or "Shinobi"
    data = query.data

    # ── Purchase Vouchers ─────────────────────────────────────────────────────
    if data == "shop_vouchers":
        coins = get_coins(user_id)

        # Check daily voucher purchase limit (10 per day)
        reset_epoch = _get_reset_epoch_now()
        day_key = f"voucher_purchase_{user_id}_{reset_epoch}"
        cursor.execute("SELECT value FROM bot_settings WHERE key=?", (day_key,))
        row = cursor.fetchone()
        bought_today = int(row[0]) if row else 0
        can_buy = max(0, 10 - bought_today)

        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("🎟️ Buy 1 Voucher (500 🪙)", callback_data="shop_buy_voucher_1")],
            [InlineKeyboardButton("🎟️ Buy 5 Vouchers (2,500 🪙)", callback_data="shop_buy_voucher_5")],
            [InlineKeyboardButton("🎟️ Buy 10 Vouchers (5,000 🪙)", callback_data="shop_buy_voucher_10")],
            [InlineKeyboardButton("🔙 Back", callback_data="shop_main")],
        ])
        try:
            await query.edit_message_text(
                f"🎟️ *PURCHASE DRAFT VOUCHERS*\n\n"
                f"{'━' * 24}\n"
                f"🪙 Your Coins: *{coins:,}*\n"
                f"📦 Purchased today: *{bought_today}/10*\n"
                f"✅ Still available today: *{can_buy}*\n"
                f"💰 Price: *500 coins per voucher*\n"
                f"{'━' * 24}\n\n"
                f"📅 Limit resets daily at *5:30 AM IST*\n\n"
                f"👇 Choose how many to buy:",
                reply_markup=keyboard,
                parse_mode="Markdown"
            )
        except Exception:
            pass
        return

    if data.startswith("shop_buy_voucher_"):
        try:
            qty = int(data.split("_")[-1])
        except ValueError:
            return

        price_per = 500
        total_cost = qty * price_per

        # Check daily limit
        reset_epoch = _get_reset_epoch_now()
        day_key = f"voucher_purchase_{user_id}_{reset_epoch}"
        cursor.execute("SELECT value FROM bot_settings WHERE key=?", (day_key,))
        row = cursor.fetchone()
        bought_today = int(row[0]) if row else 0
        can_buy = max(0, 10 - bought_today)

        if qty > can_buy:
            await query.answer(
                f"❌ You can only buy {can_buy} more voucher(s) today (daily limit: 10).",
                show_alert=True
            )
            return

        coins = get_coins(user_id)
        if coins < total_cost:
            await query.answer(
                f"❌ Not enough coins! Need {total_cost:,} 🪙 but you have {coins:,} 🪙.",
                show_alert=True
            )
            return

        deduct_coins(user_id, total_cost)
        add_vouchers(user_id, qty)
        new_bought = bought_today + qty
        cursor.execute(
            "INSERT OR REPLACE INTO bot_settings (key, value) VALUES (?,?)",
            (day_key, str(new_bought))
        )
        conn.commit()

        new_coins = get_coins(user_id)
        new_vouchers = get_user_vouchers(user_id)
        remaining_today = 10 - new_bought

        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("🎟️ Buy More Vouchers", callback_data="shop_vouchers")],
            [InlineKeyboardButton("🏯 Back to Shop", callback_data="shop_main")],
        ])
        try:
            await query.edit_message_text(
                f"✅ *Vouchers Purchased!*\n\n"
                f"{'━' * 24}\n"
                f"🎟️ Bought: *{qty} voucher(s)*\n"
                f"💰 Paid: *{total_cost:,} coins*\n"
                f"{'━' * 24}\n\n"
                f"🪙 Coins left: *{new_coins:,}*\n"
                f"🎟️ Total vouchers: *{new_vouchers}*\n"
                f"📦 Remaining purchases today: *{remaining_today}*\n\n"
                f"🌀 Use /draft_event to spin!",
                reply_markup=keyboard,
                parse_mode="Markdown"
            )
        except Exception:
            pass
        return

    # ── My Coins ──────────────────────────────────────────────────────────────
    if data == "shop_coins":
        coins = get_coins(user_id)
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("🔙 Back to Shop", callback_data="shop_main")],
        ])
        try:
            await query.edit_message_text(
                f"🪙 *Your Shinobi Coin Balance*\n\n"
                f"💰 Coins: *{coins}*\n\n"
                f"Earn more with /daily, /weekly, /monthly!",
                reply_markup=keyboard,
                parse_mode="Markdown"
            )
        except Exception:
            pass
        return

    # ── Back to main shop ─────────────────────────────────────────────────────
    if data == "shop_main":
        coins = get_coins(user_id)
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("🛒 Daily Deals", callback_data="shop_daily")],
            [InlineKeyboardButton("🎟️ Purchase Vouchers", callback_data="shop_vouchers")],
            [InlineKeyboardButton("🪙 My Coins", callback_data="shop_coins")],
        ])
        shop_text = (
            f"🏯 *SHINOBI CARD SHOP* 🏯\n\n"
            f"{'━' * 24}\n"
            f"🪙 Your Coins: *{coins}*\n"
            f"{'━' * 24}\n\n"
            f"✨ *Buy rare shinobi cards using your coins!*\n\n"
            f"🛒 *Daily Deals* — 6 new cards every day at 5:30 AM\n"
            f"Each user gets their own unique set of deals!\n"
            f"🛒 Limit: *3 card purchases per day*\n\n"
            f"🎟️ *Purchase Vouchers* — 500 coins each (up to 10/day)\n\n"
            f"👇 Choose a category:"
        )
        # Try text edit first; if message is a photo/video, delete and resend
        edited = False
        try:
            await query.edit_message_text(shop_text, reply_markup=keyboard, parse_mode="Markdown")
            edited = True
        except Exception:
            pass
        if not edited:
            try:
                await query.message.delete()
            except Exception:
                pass
            try:
                await context.bot.send_message(
                    chat_id=query.message.chat_id,
                    text=shop_text,
                    reply_markup=keyboard,
                    parse_mode="Markdown"
                )
            except Exception:
                pass
        return

    # ── Daily Deals list ──────────────────────────────────────────────────────
    if data == "shop_daily":
        deals = _get_or_create_deals(user_id)
        coins = get_coins(user_id)
        reset_in = _time_until_next_reset()

        _shop_reset_epoch = _get_reset_epoch_now()
        _shop_buy_key = f"shop_card_purchase_{user_id}_{_shop_reset_epoch}"
        cursor.execute("SELECT value FROM bot_settings WHERE key=?", (_shop_buy_key,))
        _srow = cursor.fetchone()
        _bought_today = int(_srow[0]) if _srow else 0
        _purchases_left = max(0, SHOP_PURCHASE_LIMIT_PER_DAY - _bought_today)

        # FIX (Bug 2): pull the set of cards already bought this shop cycle
        # so the listing can mark them SOLD instead of letting the user try
        # (and fail) to buy them again.
        _bought_cards_row = cursor.execute(
            "SELECT value FROM bot_settings WHERE key=?",
            (f"shop_bought_cards_{user_id}_{_shop_reset_epoch}",)
        ).fetchone()
        _already_bought_ids = set(_bought_cards_row[0].split(",")) if _bought_cards_row and _bought_cards_row[0] else set()

        lines = ""
        buttons = []
        # Build rarity order based on panel settings
        rarity_order = ["Common", "Rare", "Epic", "Legendary", "Mythic"]
        if panel_get("shop_fifa", "ON") == "ON":
            rarity_order.append("FIFA")
        if panel_get("shop_summer_naruto", "ON") == "ON":
            rarity_order.append("Summer")
        if panel_get("shop_spring", "ON") == "ON":
            rarity_order.append("Spring")

        for rarity in rarity_order:
            card = deals.get(rarity)
            if not card:
                continue
            cid, cname, crarity, cfile_id, cfile_type = card
            circle = SHOP_RARITY_CIRCLES.get(rarity, "⭐")
            emoji = RARITY_EMOJI.get(rarity, "⭐")
            price = SHOP_PRICES.get(rarity)
            if price is None:
                continue  # skip rarities not available for purchase (e.g. Spring)
            already_bought = str(cid) in _already_bought_ids
            if already_bought:
                lines += f"{circle} {cname.title()} {emoji} — ✅ *SOLD (already bought)*\n"
                buttons.append([
                    InlineKeyboardButton(
                        f"✅ {cname.title()} [SOLD]",
                        callback_data="shop_daily"
                    )
                ])
            else:
                lines += f"{circle} {cname.title()} {emoji} — *{price}* 🪙\n"
                buttons.append([
                    InlineKeyboardButton(
                        f"{circle} {cname.title()} [{emoji}]",
                        callback_data=f"shop_buy_{cid}"
                    )
                ])

        buttons.append([InlineKeyboardButton("🔙 Back", callback_data="shop_main")])

        text = (
            f"🥷 *DAILY SHINOBI DEALS!* 🥷\n\n"
            f"{'━' * 24}\n"
            f"{lines}"
            f"{'━' * 24}\n\n"
            f"🪙 Your Coins: *{coins}*\n"
            f"🛒 Purchases left today: *{_purchases_left}/{SHOP_PURCHASE_LIMIT_PER_DAY}*\n"
            f"⏰ Next reset in: *{reset_in}*\n\n"
            f"👇 Tap a card to view & buy:"
        )
        edited = False
        try:
            await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(buttons), parse_mode="Markdown")
            edited = True
        except Exception:
            pass
        if not edited:
            try:
                await query.message.delete()
            except Exception:
                pass
            try:
                await context.bot.send_message(
                    chat_id=query.message.chat_id,
                    text=text,
                    reply_markup=InlineKeyboardMarkup(buttons),
                    parse_mode="Markdown"
                )
            except Exception:
                pass
        return

    # ── Buy card view ─────────────────────────────────────────────────────────
    if data.startswith("shop_buy_"):
        try:
            card_id = int(data.replace("shop_buy_", ""))
        except ValueError:
            return

        cursor.execute(
            "SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards WHERE id=?",
            (card_id,)
        )
        card = cursor.fetchone()
        if not card:
            await query.answer("❌ Card no longer available.", show_alert=True)
            return

        cid, cname, crarity, cfile_id, cfile_type = card

        # Spring cards are not available in the shop
        if crarity == "Spring":
            await query.answer("❌ This card is not available in the shop.", show_alert=True)
            return

        emoji = RARITY_EMOJI.get(crarity, "⭐")
        price = SHOP_PRICES.get(crarity, None)
        if price is None:
            await query.answer("❌ This card cannot be purchased.", show_alert=True)
            return

        # FIX (Bug 2): block viewing/re-buying a card already purchased this
        # shop cycle, same check used in shop_confirm_.
        _view_reset_epoch = _get_reset_epoch_now()
        _view_bought_key = f"shop_bought_cards_{user_id}_{_view_reset_epoch}"
        cursor.execute("SELECT value FROM bot_settings WHERE key=?", (_view_bought_key,))
        _view_row = cursor.fetchone()
        _view_bought_ids = set(_view_row[0].split(",")) if _view_row and _view_row[0] else set()
        if str(cid) in _view_bought_ids:
            reset_in = _time_until_next_reset()
            await query.answer(
                f"❌ You've already bought this card today! Resets in {reset_in}.",
                show_alert=True
            )
            return

        coins = get_coins(user_id)

        caption = (
            f"🛍️ *{cname.title()}*\n\n"
            f"{'━' * 24}\n"
            f"{emoji} Rarity: *{crarity}*\n"
            f"💰 Price: *{price} Shinobi Coins*\n"
            f"{'━' * 24}\n\n"
            f"🪙 Your Coins: *{coins}*\n\n"
            f"Do you want to buy this shinobi?"
        )

        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton(f"✅ Buy ({price} 🪙)", callback_data=f"shop_confirm_{cid}")],
            [InlineKeyboardButton("🔙 Back to Deals", callback_data="shop_daily")],
        ])

        # Delete old message and send new one with card image
        try:
            await query.message.delete()
        except Exception:
            pass

        try:
            if cfile_type == "video":
                await context.bot.send_video(
                    chat_id=query.message.chat_id,
                    video=cfile_id,
                    caption=caption,
                    reply_markup=keyboard,
                    parse_mode="Markdown",
                    supports_streaming=True
                )
            elif cfile_type == "animation":
                await context.bot.send_animation(
                    chat_id=query.message.chat_id,
                    animation=cfile_id,
                    caption=caption,
                    reply_markup=keyboard,
                    parse_mode="Markdown"
                )
            else:
                await context.bot.send_photo(
                    chat_id=query.message.chat_id,
                    photo=cfile_id,
                    caption=caption,
                    reply_markup=keyboard,
                    parse_mode="Markdown"
                )
        except Exception as e:
            print(f"[SHOP] Failed to send card media: {e}")
            await context.bot.send_message(
                chat_id=query.message.chat_id,
                text=caption,
                reply_markup=keyboard,
                parse_mode="Markdown"
            )
        return

    # ── Confirm purchase ──────────────────────────────────────────────────────
    if data.startswith("shop_confirm_"):
        try:
            card_id = int(data.replace("shop_confirm_", ""))
        except ValueError:
            return

        cursor.execute(
            "SELECT id, name, rarity, file_id, COALESCE(file_type,'photo') FROM cards WHERE id=?",
            (card_id,)
        )
        card = cursor.fetchone()
        if not card:
            await query.answer("❌ Card not found.", show_alert=True)
            return

        cid, cname, crarity, cfile_id, cfile_type = card

        # Block Spring cards from purchase
        if crarity == "Spring":
            await query.answer("❌ Spring cards cannot be purchased.", show_alert=True)
            return

        price = SHOP_PRICES.get(crarity, None)
        if price is None:
            await query.answer("❌ This card cannot be purchased.", show_alert=True)
            return

        # FIX (Bug 2 - unlimited shop buying): there was previously no cap at
        # all on shop_confirm_ purchases, so a user with enough coins could
        # tap "Buy" on the same (or any) deal repeatedly and receive
        # unlimited cards. Shop purchases are now capped at
        # SHOP_PURCHASE_LIMIT_PER_DAY (3) cards per user per day, tracked the
        # same way the voucher daily limit already is (bot_settings row keyed
        # by reset epoch).
        reset_epoch = _get_reset_epoch_now()
        shop_buy_key = f"shop_card_purchase_{user_id}_{reset_epoch}"
        cursor.execute("SELECT value FROM bot_settings WHERE key=?", (shop_buy_key,))
        _row = cursor.fetchone()
        bought_today = int(_row[0]) if _row else 0

        # FIX (Bug 2 - repeat purchase of the same card/rarity): the daily
        # purchase cap above only limits the TOTAL number of cards bought,
        # so a user could still spend all 3 of their daily purchases on the
        # exact same card. Once a specific card has been bought this shop
        # cycle, it is now off-limits to that user until the shop resets.
        shop_bought_cards_key = f"shop_bought_cards_{user_id}_{reset_epoch}"
        cursor.execute("SELECT value FROM bot_settings WHERE key=?", (shop_bought_cards_key,))
        _bought_row = cursor.fetchone()
        bought_card_ids = set(_bought_row[0].split(",")) if _bought_row and _bought_row[0] else set()

        if str(cid) in bought_card_ids:
            reset_in = _time_until_next_reset()
            await query.answer(
                "❌ You've already bought this card in today's shop! It'll be available again after the shop resets.",
                show_alert=True
            )
            keyboard = InlineKeyboardMarkup([
                [InlineKeyboardButton("🔙 Back to Deals", callback_data="shop_daily")],
            ])
            try:
                await query.edit_message_caption(
                    caption=(
                        f"🛑 *Already Purchased!*\n\n"
                        f"🥷 You already bought *{cname.title()}* this shop cycle.\n"
                        f"⏰ It'll be purchasable again after the shop resets in: *{reset_in}*"
                    ),
                    reply_markup=keyboard,
                    parse_mode="Markdown"
                )
            except Exception:
                pass
            return

        if bought_today >= SHOP_PURCHASE_LIMIT_PER_DAY:
            reset_in = _time_until_next_reset()
            await query.answer(
                f"❌ Daily shop limit reached! You can buy {SHOP_PURCHASE_LIMIT_PER_DAY} cards per day.",
                show_alert=True
            )
            keyboard = InlineKeyboardMarkup([
                [InlineKeyboardButton("🔙 Back to Deals", callback_data="shop_daily")],
            ])
            try:
                await query.edit_message_caption(
                    caption=(
                        f"🛑 *Daily Shop Limit Reached!*\n\n"
                        f"🛒 You've bought *{bought_today}/{SHOP_PURCHASE_LIMIT_PER_DAY}* cards today.\n"
                        f"⏰ Resets in: *{reset_in}*"
                    ),
                    reply_markup=keyboard,
                    parse_mode="Markdown"
                )
            except Exception:
                pass
            return

        coins = get_coins(user_id)

        if coins < price:
            await query.answer(
                f"❌ Not enough coins! You have {coins}, need {price}.",
                show_alert=True
            )
            # Also edit message to show error
            keyboard = InlineKeyboardMarkup([
                [InlineKeyboardButton("🔙 Back to Deals", callback_data="shop_daily")],
            ])
            try:
                await query.edit_message_caption(
                    caption=(
                        f"💔 *Not Enough Shinobi Coins!*\n\n"
                        f"🪙 You have: *{coins}* coins\n"
                        f"💰 You need: *{price}* coins\n\n"
                        f"Earn more with /daily, /weekly, /monthly! 💪"
                    ),
                    reply_markup=keyboard,
                    parse_mode="Markdown"
                )
            except Exception:
                pass
            return

        # Deduct and give card
        deduct_coins(user_id, price)
        insert_user_card(user_id, cname, crarity, cfile_id, cfile_type, card_id=cid)
        new_bought_today = bought_today + 1
        cursor.execute(
            "INSERT OR REPLACE INTO bot_settings (key, value) VALUES (?,?)",
            (shop_buy_key, str(new_bought_today))
        )
        # FIX (Bug 2): remember this card as bought for the current shop
        # cycle so this user can't purchase it again until the shop resets.
        bought_card_ids.add(str(cid))
        cursor.execute(
            "INSERT OR REPLACE INTO bot_settings (key, value) VALUES (?,?)",
            (shop_bought_cards_key, ",".join(bought_card_ids))
        )
        conn.commit()

        new_coins = get_coins(user_id)
        remaining_purchases = SHOP_PURCHASE_LIMIT_PER_DAY - new_bought_today
        emoji = RARITY_EMOJI.get(crarity, "⭐")

        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("🛒 Back to Deals", callback_data="shop_daily")],
            [InlineKeyboardButton("🏯 Back to Shop", callback_data="shop_main")],
        ])

        try:
            await query.edit_message_caption(
                caption=(
                    f"✅ *Purchase Successful!*\n\n"
                    f"{'━' * 24}\n"
                    f"🥷 Card: *{cname.title()}*\n"
                    f"{emoji} Rarity: *{crarity}*\n"
                    f"💰 Paid: *{price}* 🪙\n"
                    f"{'━' * 24}\n\n"
                    f"🪙 Remaining Coins: *{new_coins}*\n"
                    f"🛒 Shop purchases left today: *{remaining_purchases}/{SHOP_PURCHASE_LIMIT_PER_DAY}*\n\n"
                    f"⚔️ Card added to your vault! Use /collection to view it."
                ),
                reply_markup=keyboard,
                parse_mode="Markdown"
            )
        except Exception:
            await context.bot.send_message(
                chat_id=query.message.chat_id,
                text=(
                    f"✅ *Purchase Successful!*\n\n"
                    f"🥷 *{cname.title()}* [{emoji}] added to your vault!\n"
                    f"💰 Paid: *{price}* 🪙 | Remaining: *{new_coins}* 🪙"
                ),
                parse_mode="Markdown"
            )

        await log_to_group(
            context.bot,
            f"🛍️ *Shop Purchase*\n\n"
            f"👤 {user_name} (`{user_id}`)\n"
            f"🥷 Card: {cname.title()} [{crarity}]\n"
            f"💰 Paid: {price} coins\n"
            f"🪙 Balance: {new_coins} coins"
        )
        return


