#                     WEEKLY PASS SYSTEM
# ═══════════════════════════════════════════════════════════════════

cursor.execute("""
CREATE TABLE IF NOT EXISTS weekly_pass (
    user_id       INTEGER PRIMARY KEY,
    active        INTEGER DEFAULT 0,
    purchased_at  INTEGER DEFAULT 0,
    week_start    INTEGER DEFAULT 0,
    days_claimed  TEXT    DEFAULT '[]'
)
""")
conn.commit()

# ── Pass rework ────────────────────────────────────────────────────────────
# Cost: 10,000 coins. Total coin return across the 7 daily check-ins + the
# Day-7 Special Reward = 12,000 coins (11,000 from the week + 1,000 from the
# Special Reward), plus draft vouchers on every day and a bigger voucher
# grant in the Special Reward. Claiming works exactly like /claim_weekly_pass
# always has — one check-in per 5:30 AM IST reset window, same reset helper
# (_coin_reset_epoch) the bot's own /daily command uses.
WEEKLY_PASS_COST = 10000
WEEKLY_PASS_REWARDS = {
    1: {"coins": 800,  "vouchers": 2, "rarity": "Common"},
    2: {"coins": 1000, "vouchers": 2, "rarity": "Rare"},
    3: {"coins": 1200, "vouchers": 3, "rarity": "Rare"},
    4: {"coins": 1500, "vouchers": 3, "rarity": "Epic"},
    5: {"coins": 1800, "vouchers": 4, "rarity": "Legendary"},
    6: {"coins": 2200, "vouchers": 4, "rarity": "Legendary"},
    7: {"coins": 2500, "vouchers": 5, "rarity": "Epic"},
}

def _monday_reset_epoch(now: int) -> int:
    """Epoch of the most recent Monday 00:00 IST."""
    now_ist = now + IST_OFFSET_SEC
    dow = (now_ist // 86400 + 3) % 7   # 0=Mon
    return now - (dow * 86400 + (now_ist % 86400))

def get_weekly_pass_row(user_id: int):
    import json
    cursor.execute("SELECT active, purchased_at, week_start, days_claimed FROM weekly_pass WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    if not row:
        return None
    active, purchased_at, week_start, dc_raw = row
    try:
        days_claimed = json.loads(dc_raw or "[]")
    except Exception:
        days_claimed = []
    return active, purchased_at, week_start, days_claimed

def is_weekly_pass_active(user_id: int) -> bool:
    now = int(time.time())
    monday = _monday_reset_epoch(now)
    row = get_weekly_pass_row(user_id)
    if not row:
        return False
    active, _, week_start, _ = row
    if week_start < monday:
        cursor.execute("UPDATE weekly_pass SET active=0 WHERE user_id=?", (user_id,))
        conn.commit()
        return False
    return bool(active)

WEEKLY_PASS_GATED_MSG = (
    "🔒 *Weekly Pass Required!*\n\n"
    "This feature is exclusive to *Weekly Pass* holders.\n\n"
    f"💰 Activate for *{WEEKLY_PASS_COST:,} Shinobi Coins* with /weekly\\_pass\n"
    "🔄 Resets every *Monday* — try again next week! 💪"
)

async def weekly_pass_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/weekly_pass — Activate weekly pass for 5000 coins."""
    import json
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    now = int(time.time())
    monday = _monday_reset_epoch(now)

    row = get_weekly_pass_row(user_id)
    if row and row[0] and row[2] >= monday:
        days_claimed = row[3]
        next_day = max(days_claimed) + 1 if days_claimed else 1
        next_day = min(next_day, 7)
        await update.message.reply_text(
            f"✅ *Weekly Pass Already Active!*\n\n"
            f"📅 Days Claimed: *{len(days_claimed)}/7*\n"
            f"🎁 Next Reward: *Day {next_day}*\n\n"
            f"Use /claim\\_weekly\\_pass to collect today's reward!\n"
            f"🔄 Resets every *Monday*.",
            parse_mode="Markdown"
        )
        return

    coins = get_coins(user_id)
    if coins < WEEKLY_PASS_COST:
        await update.message.reply_text(
            f"💸 *Not Enough Shinobi Coins!*\n\n"
            f"Weekly Pass costs: *{WEEKLY_PASS_COST:,} 🪙*\n"
            f"Your balance: *{coins:,} 🪙*\n\n"
            f"Earn coins by catching cards, /daily, /weekly, /monthly!\n"
            f"🎲 Or try /bet to win big!",
            parse_mode="Markdown"
        )
        return

    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton(f"🏆 Activate Weekly Pass ({WEEKLY_PASS_COST:,} 🪙)", callback_data="activate_weekly_pass")
    ]])

    reward_lines = "\n".join([
        f"  {RARITY_EMOJI.get(r['rarity'],'⭐')} Day {d}: *{r['coins']:,}* coins + {r.get('vouchers',0)} 🎟️ + {r['rarity']} card"
        for d, r in WEEKLY_PASS_REWARDS.items()
    ])

    await update.message.reply_text(
        f"🏆 *WEEKLY PASS*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"💰 Cost: *{WEEKLY_PASS_COST:,} Shinobi Coins*\n"
        f"🪙 Your Balance: *{coins:,} coins*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"🎁 *7 Day Check-In Rewards* _(one claim per day, just like /daily)_:\n{reward_lines}\n\n"
        f"🌟 *Special Reward:* Claim all 7 days → *Mythic card + {WEEKLY_PASS_SPECIAL_REWARD_COINS:,} coins + {WEEKLY_PASS_SPECIAL_REWARD_VOUCHERS} 🎟️!*\n\n"
        f"📅 Use /claim\\_weekly\\_pass daily after activating!\n"
        f"🔄 Resets every *Monday 00:00 IST*.\n\n"
        f"👇 Tap below to purchase:",
        parse_mode="Markdown",
        reply_markup=keyboard
    )


async def claim_weekly_pass(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/claim_weekly_pass — Claim today's weekly pass reward."""
    import json
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    now = int(time.time())
    monday = _monday_reset_epoch(now)

    row = get_weekly_pass_row(user_id)
    if not row or not row[0] or row[2] < monday:
        await update.message.reply_text(WEEKLY_PASS_GATED_MSG, parse_mode="Markdown")
        return

    _, _, week_start, days_claimed = row

    next_day = (max(days_claimed) + 1) if days_claimed else 1
    if next_day > 7:
        await update.message.reply_text(
            f"🎊 *All 7 days claimed!*\n\n"
            f"Use /special\\_rewards to claim your *Mythic Special Reward*!\n"
            f"🔄 New pass resets next *Monday*.",
            parse_mode="Markdown"
        )
        return

    # 24h cooldown — one claim per 5:30 AM IST reset window.
    # IMPORTANT: this key must NOT include `next_day` — it tracks the reset window of the
    # user's *last claim on this pass*, not a specific day number. Keying it by next_day
    # meant every day had its own never-before-seen key, so the "already claimed" check
    # below was always comparing against 0 and never actually blocked a same-window claim,
    # letting users claim every day back-to-back instead of waiting for 5:30 AM IST.
    today_reset_epoch = _coin_reset_epoch(now)
    day_key = f"wp_last_claim_{user_id}_{week_start}"
    cursor.execute("SELECT value FROM bot_settings WHERE key=?", (day_key,))
    lrow = cursor.fetchone()
    last_claim_reset = int(lrow[0]) if lrow else 0

    if last_claim_reset >= today_reset_epoch:
        next_reset_epoch = today_reset_epoch + 86400
        rem = next_reset_epoch - now
        hrs, mins = rem // 3600, (rem % 3600) // 60
        await update.message.reply_text(
            f"⏳ *Already claimed today!*\n\n"
            f"📅 Come back *tomorrow after 5:30 AM IST* for Day {next_day + 1 if next_day < 7 else 7}'s reward!\n"
            f"⏱️ Next claim in: *{hrs}h {mins}m*\n\n"
            f"📅 Resets daily at *5:30 AM IST*.",
            parse_mode="Markdown"
        )
        return

    reward = WEEKLY_PASS_REWARDS[next_day]
    rarity, coins_reward, voucher_reward = reward["rarity"], reward["coins"], reward.get("vouchers", 0)

    cursor.execute(
        "SELECT name, rarity, file_id, COALESCE(file_type,'photo') FROM cards WHERE rarity=? ORDER BY RANDOM() LIMIT 1",
        (rarity,)
    )
    card = cursor.fetchone()
    if not card:
        await update.message.reply_text(f"❌ No *{rarity}* cards in database. Ask admin to add some!", parse_mode="Markdown")
        return

    cname, crarity, cfile, cfile_type = card
    insert_user_card(user_id, cname, crarity, cfile, file_type=cfile_type)
    add_coins(user_id, coins_reward)
    if voucher_reward:
        add_vouchers(user_id, voucher_reward)

    days_claimed.append(next_day)
    cursor.execute("UPDATE weekly_pass SET days_claimed=? WHERE user_id=?", (json.dumps(days_claimed), user_id))
    # Record the reset window this claim happened in, so the next /claim_weekly_pass call
    # is locked out until the following 5:30 AM IST reset (see cooldown check above).
    cursor.execute("INSERT OR REPLACE INTO bot_settings (key, value) VALUES (?,?)", (day_key, str(today_reset_epoch)))
    conn.commit()

    new_coins = get_coins(user_id)
    user_name = update.effective_user.first_name or "Shinobi"
    card_emoji = RARITY_EMOJI.get(crarity, "⭐")
    days_left = 7 - next_day

    voucher_line = f"🎟️ Vouchers: *+{voucher_reward}*\n" if voucher_reward else ""
    caption = (
        f"🎁 *WEEKLY PASS — DAY {next_day} REWARD!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🥷 Shinobi: *{user_name}*\n"
        f"🪙 Coins: *+{coins_reward:,}*\n"
        f"{voucher_line}"
        f"🃏 Card: *{cname.title()}* [{card_emoji} {crarity}]\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"💰 Total Coins: *{new_coins:,}*\n"
        f"📅 Days Claimed: *{next_day}/7*\n\n"
        + (f"🌟 *1 more day for your Special Reward!*" if next_day == 6 else
           f"🎊 *All done! Use /special\\_rewards for your Mythic Special Reward!*" if next_day == 7 else
           f"⏳ *{days_left} day(s) remaining!*")
    )

    await send_card_media(update.message, cfile, file_type=cfile_type, caption=caption, parse_mode="Markdown")


WEEKLY_PASS_SPECIAL_REWARD_COINS = 1000
WEEKLY_PASS_SPECIAL_REWARD_VOUCHERS = 5

async def weekly_pass_bonus(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/special_rewards (alias: /bonus) — Claim the Mythic Special Reward after all 7 days."""
    import json
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    now = int(time.time())
    monday = _monday_reset_epoch(now)
    row = get_weekly_pass_row(user_id)

    if not row or not row[0] or row[2] < monday:
        await update.message.reply_text(WEEKLY_PASS_GATED_MSG, parse_mode="Markdown")
        return

    _, _, week_start, days_claimed = row

    if set(days_claimed) < {1,2,3,4,5,6,7}:
        missing = sorted(set(range(1,8)) - set(days_claimed))
        await update.message.reply_text(
            f"⏳ *Complete all 7 days first!*\n\nMissing days: *{missing}*\n\nUse /claim\\_weekly\\_pass daily!",
            parse_mode="Markdown"
        )
        return

    bonus_key = f"wp_bonus_{user_id}_{week_start}"
    cursor.execute("SELECT value FROM bot_settings WHERE key=?", (bonus_key,))
    if cursor.fetchone():
        await update.message.reply_text("✅ *Special Reward already claimed this week!*\n\n🔄 New pass + Special Reward next Monday.", parse_mode="Markdown")
        return

    cursor.execute("SELECT name, rarity, file_id, COALESCE(file_type,'photo') FROM cards WHERE rarity='Mythic' ORDER BY RANDOM() LIMIT 1")
    card = cursor.fetchone()
    if not card:
        await update.message.reply_text("❌ No Mythic cards in the database yet!", parse_mode="Markdown")
        return

    cname, crarity, cfile, cfile_type = card
    insert_user_card(user_id, cname, crarity, cfile, file_type=cfile_type)
    bonus_coins = WEEKLY_PASS_SPECIAL_REWARD_COINS
    bonus_vouchers = WEEKLY_PASS_SPECIAL_REWARD_VOUCHERS
    add_coins(user_id, bonus_coins)
