COLLAB_RARITY_WEIGHTS_DEFAULT = {
    "Rare":       57,
    "Epic":       35,
    "Legendary":   5,
    "Mythic":      2,
    "Rainy":       1,   # 🌧️ collab-exclusive rarity (series set by /start_collaboration_draft)
}
COLLAB_RARITY_WEIGHTS: dict = dict(COLLAB_RARITY_WEIGHTS_DEFAULT)

# COLLAB_SERIES: which anime series each rarity pulls from.
# "Summer" defaults to "One Piece" but can be any collab series (e.g. "Bleach").
# All other rarities default to "Naruto" unless overridden.
# Set dynamically by /start_collaboration_draft via Summer(Bleach):1 syntax.
#
# Special sentinel: "Mixed" (case-insensitive) means "any series except Naruto" —
# used for FIFA collab events that pool cards from multiple non-Naruto anime
# series together rather than locking to one specific series, e.g.
# FIFA(Mixed):5 pulls a random FIFA card from One Piece, Bleach, Demon Slayer,
# or any other non-Naruto series that has FIFA cards uploaded.
COLLAB_SERIES_MIXED_SENTINEL = "Mixed"

COLLAB_SERIES: dict = {
    "Rare":      "Naruto",
    "Epic":      "Naruto",
    "Legendary": "Naruto",
    "Mythic":    "Naruto",
    "Summer":    "One Piece",  # default; overridden by e.g. Summer(Bleach)
    "Rainy":     "One Piece",  # default; overridden by e.g. Rainy(Bleach) / Rainy(Mixed)
}

# Migration: add collab pity columns to draft_vouchers
for _collab_col in ("collab_total", "collab_since_leg", "collab_since_spring"):
    try:
        cursor.execute(f"ALTER TABLE draft_vouchers ADD COLUMN {_collab_col} INTEGER DEFAULT 0")
        conn.commit()
    except Exception:
        pass


