#            🛒 PLAYER MARKET & AUCTION — shared config/helpers
# ═══════════════════════════════════════════════════════════════════
MARKET_GROUP_ID  = -1003985106223   # p2p sell listings post here
AUCTION_GROUP_ID = -1004412970582   # auctions post here (dedicated auction group)


def is_card_frozen(card_row_id: int) -> tuple[bool, str]:
    """Returns (frozen?, reason) — True if the card row is tied up in an
    active market listing, auction, or expedition and can't be sold/gifted/traded/re-listed."""
    cursor.execute(
        "SELECT id FROM market_listings WHERE card_row_id=? AND status='active' LIMIT 1",
        (card_row_id,)
    )
    if cursor.fetchone():
        return True, "It's currently listed on the /market. Cancel it with /list first."
    cursor.execute(
        "SELECT id FROM auction_listings WHERE card_row_id=? AND status='active' LIMIT 1",
        (card_row_id,)
    )
    if cursor.fetchone():
        return True, "It's currently up for /auction and can't be touched until it ends."
    cursor.execute(
        "SELECT id FROM shinobi_expeditions WHERE card_row_id=? AND status='active' LIMIT 1",
        (card_row_id,)
    )
    if cursor.fetchone():
        return True, "It's currently out on a /expedition and can't be touched until it returns."
    cursor.execute(
        "SELECT id FROM shinobi_contracts WHERE card_row_id=? AND status='active' LIMIT 1",
        (card_row_id,)
    )
    if cursor.fetchone():
        return True, "It's currently locked in a /contract and can't be touched until it resolves."
    return False, ""


