# ═══════════════════════════════════════════════════════════════════
#            🛒 PLAYER MARKET — sell cards to other users (Gems)
# ═══════════════════════════════════════════════════════════════════

async def market_sell_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/sell <card_id> <price> — list a card from your collection for sale to other players, paid in Gems."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    user_name = update.effective_user.first_name or "Shinobi"

    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    _frozen, _frozen_reason = is_feature_frozen("player_market")
    if _frozen and not is_admin(user_id):
        await update.message.reply_text(
            f"🔒 *The player market is temporarily frozen.*\n\n{_frozen_reason}", parse_mode="Markdown"
        )
        return

    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            "🛒 *SELL A CARD*\n\n"
            "Usage: `/sell <card_id> <price>`\n"
            "Example: `/sell 42 500`\n\n"
            "🪙 Price is in Shinobi Coins — other players can buy it straight from the market group.\n"
            "📋 Use `/list` anytime to view or cancel your active listings.",
            parse_mode="Markdown"
        )
        return

    try:
        card_id_arg = int(args[0])
        price = int(args[1])
    except ValueError:
        await update.message.reply_text("❌ Card ID and price must both be numbers.")
        return

    if price <= 0:
        await update.message.reply_text("❌ Price must be greater than 0 coins.")
        return

    cursor.execute(
        "SELECT id, card_name, rarity, file_id, COALESCE(file_type,'photo'), COALESCE(series,'Naruto') "
        "FROM user_cards WHERE card_id=? AND user_id=? LIMIT 1",
        (card_id_arg, user_id)
    )
    row = cursor.fetchone()
    if not row:
        await update.message.reply_text(
            f"❌ You don't own card *#{card_id_arg}*. Check `/collection` for your card IDs.",
            parse_mode="Markdown"
        )
        return

    row_id, card_name, rarity, file_id, file_type, series = row

    _frozen, _frozen_reason = is_card_frozen(row_id)
    if _frozen:
        await update.message.reply_text(f"🔒 *This card is frozen!*\n\n{_frozen_reason}", parse_mode="Markdown")
        return

    card_emoji = RARITY_EMOJI.get(rarity, "⭐")

    cursor.execute(
        "INSERT INTO market_listings (seller_id, card_row_id, card_id, card_name, rarity, file_id, file_type, "
        "series, price, status, created_at) VALUES (?,?,?,?,?,?,?,?,?, 'active', ?)",
        (user_id, row_id, card_id_arg, card_name, rarity, file_id, file_type, series, price, int(time.time()))
    )
    conn.commit()
    listing_id = cursor.lastrowid

    caption = (
        f"🛒 *PLAYER MARKET LISTING*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"{card_emoji} Card: *{card_name.title()}*\n"
        f"🏷️ Rarity: *{rarity}*\n"
        f"📺 {series}\n"
        f"🪙 Price: *{price:,} Shinobi Coins*\n"
        f"👤 Seller: *{user_name}*\n"
        f"🔢 Listing ID: `#{listing_id}`\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"Tap below to buy this card!"
    )
    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton(f"🪙 Buy for {price:,}", callback_data=f"mkt_buy_{listing_id}")
    ]])

    try:
        sent = await send_card_media(
            context.bot, file_id, file_type=file_type, caption=caption,
            parse_mode="Markdown", reply_markup=keyboard, chat_id=MARKET_GROUP_ID
        )
        msg_id = sent.message_id if sent else None
    except Exception as e:
        cursor.execute("DELETE FROM market_listings WHERE id=?", (listing_id,))
        conn.commit()
        await update.message.reply_text(f"❌ Couldn't post the listing to the market group. Error: `{str(e)[:200]}`", parse_mode="Markdown")
        return

    cursor.execute(
        "UPDATE market_listings SET listing_msg_id=?, listing_chat_id=? WHERE id=?",
        (msg_id, MARKET_GROUP_ID, listing_id)
    )
    conn.commit()

    await update.message.reply_text(
        f"✅ *Listed for sale!*\n\n"
        f"{card_emoji} *{card_name.title()}* — 🪙 {price:,} Shinobi Coins\n"
        f"🔢 Listing ID: `#{listing_id}`\n\n"
        f"📢 Your card is now visible in the market group.\n"
        f"🔒 It's frozen (can't be gifted/traded/sold elsewhere) until sold or cancelled.\n"
        f"📋 Use `/list` to view or cancel it anytime.",
        parse_mode="Markdown"
    )


async def market_list_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/list — show your own active market listings with a cancel button on each."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id

    cursor.execute(
        "SELECT id, card_name, rarity, price FROM market_listings WHERE seller_id=? AND status='active' ORDER BY id DESC",
        (user_id,)
    )
    rows = cursor.fetchall()
    if not rows:
        await update.message.reply_text("📋 *You have no active market listings.*\n\nUse `/sell <card_id> <price>` to list a card.", parse_mode="Markdown")
        return

    lines = ["📋 *YOUR ACTIVE LISTINGS*\n"]
    buttons = []
    for lid, card_name, rarity, price in rows:
        emoji = RARITY_EMOJI.get(rarity, "⭐")
        lines.append(f"{emoji} *{card_name.title()}* — 🪙 {price:,}  (`#{lid}`)")
        buttons.append([InlineKeyboardButton(f"❌ Cancel #{lid} — {card_name.title()}", callback_data=f"mkt_cancel_{lid}")])

    await update.message.reply_text(
        "\n".join(lines),
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup(buttons)
    )


async def market_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle mkt_buy_<id> and mkt_cancel_<id> button presses."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass

    user_id = query.from_user.id
    data = query.data

    if data.startswith("mkt_cancel_"):
        listing_id = int(data.split("_")[-1])
        cursor.execute(
            "SELECT seller_id, card_name, listing_msg_id, listing_chat_id, status FROM market_listings WHERE id=?",
            (listing_id,)
        )
        row = cursor.fetchone()
        if not row:
            await query.answer("Listing not found.", show_alert=True)
            return
        seller_id, card_name, listing_msg_id, listing_chat_id, status = row
        if seller_id != user_id:
            await query.answer("❌ This isn't your listing.", show_alert=True)
            return
        if status != "active":
            await query.answer("This listing is no longer active.", show_alert=True)
            return

        cursor.execute("UPDATE market_listings SET status='cancelled' WHERE id=?", (listing_id,))
        conn.commit()

        if listing_msg_id and listing_chat_id:
            try:
                await context.bot.delete_message(chat_id=listing_chat_id, message_id=listing_msg_id)
            except Exception:
                pass

        try:
            await query.edit_message_text(f"✅ Listing `#{listing_id}` ({card_name.title()}) cancelled. Your card is unfrozen.", parse_mode="Markdown")
        except Exception:
            pass
        return

    if data.startswith("mkt_buy_"):
        listing_id = int(data.split("_")[-1])
        cursor.execute(
            "SELECT seller_id, card_row_id, card_name, rarity, price, status FROM market_listings WHERE id=?",
            (listing_id,)
        )
        row = cursor.fetchone()
        if not row:
            await query.answer("Listing not found.", show_alert=True)
            return
        seller_id, card_row_id, card_name, rarity, price, status = row

        if status != "active":
            await query.answer("❌ This listing has already been sold or cancelled.", show_alert=True)
            return
        if seller_id == user_id:
            await query.answer("❌ You can't buy your own listing.", show_alert=True)
            return
        if not has_started_bot(user_id):
            await query.answer("Start the bot in DM first (/start).", show_alert=True)
            return
        if is_banned(user_id):
            await query.answer("You are banned from trading.", show_alert=True)
            return
        _frozen, _frozen_reason = is_feature_frozen("player_market")
        if _frozen and not is_admin(user_id):
            await query.answer(f"🔒 The player market is temporarily frozen. {_frozen_reason}", show_alert=True)
            return

        buyer_coins = get_coins(user_id)
        if buyer_coins < price:
            await query.answer(f"❌ Not enough Shinobi Coins! You have {buyer_coins:,}, need {price:,}.", show_alert=True)
            return

        # Re-check the card is still owned by the seller (defensive)
        cursor.execute("SELECT user_id FROM user_cards WHERE id=?", (card_row_id,))
        owner_row = cursor.fetchone()
        if not owner_row or owner_row[0] != seller_id:
            cursor.execute("UPDATE market_listings SET status='cancelled' WHERE id=?", (listing_id,))
            conn.commit()
            await query.answer("❌ This card is no longer available.", show_alert=True)
            return

        if not deduct_coins(user_id, price):
            await query.answer("❌ Purchase failed (insufficient Shinobi Coins).", show_alert=True)
            return

        add_coins(seller_id, price)
        cursor.execute("UPDATE user_cards SET user_id=? WHERE id=?", (user_id, card_row_id))
        cursor.execute("UPDATE market_listings SET status='sold' WHERE id=?", (listing_id,))
        conn.commit()

        buyer_name = query.from_user.first_name or str(user_id)
        card_emoji = RARITY_EMOJI.get(rarity, "⭐")

        try:
            await query.edit_message_caption(
                f"✅ *SOLD!*\n\n{card_emoji} *{card_name.title()}* [{rarity}]\n"
                f"🪙 Price: {price:,} Shinobi Coins\n"
                f"🛍️ Buyer: {buyer_name}",
                parse_mode="Markdown"
            )
        except Exception:
            try:
                await query.edit_message_text(f"✅ *SOLD* to {buyer_name} for {price:,} 🪙", parse_mode="Markdown")
            except Exception:
                pass

        try:
            await context.bot.send_message(
                chat_id=seller_id,
                text=f"💰 *Your card sold!*\n\n{card_emoji} *{card_name.title()}* [{rarity}]\n"
                     f"🪙 You received: {price:,} Shinobi Coins\n🛍️ Buyer: {buyer_name}",
                parse_mode="Markdown"
            )
        except Exception:
            pass
        try:
            await context.bot.send_message(
                chat_id=user_id,
                text=f"🎉 *Purchase complete!*\n\n{card_emoji} *{card_name.title()}* [{rarity}] is now in your `/collection`.\n"
                     f"🪙 Shinobi Coins spent: {price:,}",
                parse_mode="Markdown"
            )
        except Exception:
            pass


# ═══════════════════════════════════════════════════════════════════
#            🔨 AUCTION SYSTEM — timed bidding (Shinobi Coins, 2h)
# ═══════════════════════════════════════════════════════════════════
AUCTION_DURATION_SECONDS = 2 * 60 * 60


def _md_safe_name(name: str) -> str:
    """Strips Markdown-special characters from a user-supplied display name so it
    can't break `parse_mode='Markdown'` rendering when embedded in a caption."""
    if not name:
        return "Someone"
    for ch in ("_", "*", "`", "[", "]"):
        name = name.replace(ch, "")
    return name.strip() or "Someone"


def _auction_caption(row) -> str:
    (aid, seller_id, card_row_id, card_id, card_name, rarity, file_id, file_type,
     series, start_price, current_bid, current_bidder_id, status, listing_msg_id,
     listing_chat_id, created_at, ends_at, started_by_bot, current_bidder_name) = row
    emoji = RARITY_EMOJI.get(rarity, "⭐")
    remaining = max(0, ends_at - int(time.time()))
    hrs = remaining // 3600
    mins = (remaining % 3600) // 60
    if current_bid is None:
        bid_line = f"🪙 *No bids yet* — starting price *{start_price:,}* Shinobi Coins"
        bidder_line = ""
    else:
        bid_line = f"🪙 Highest Bid: *{current_bid:,}* Shinobi Coins"
        display_name = _md_safe_name(current_bidder_name) if current_bidder_name else "a bidder"
        mention = f"[{display_name}](tg://user?id={current_bidder_id})" if current_bidder_id else display_name
        bidder_line = f"🙋 Highest Bidder: {mention}\n"
    host = "🏛️ Hosted by: *the House*" if started_by_bot else "👤 Seller: *see /auction post*"
    return (
        f"🔨 *AUCTION{' — HOUSE ITEM' if started_by_bot else ''}*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"{emoji} Card: *{card_name.title()}*\n"
        f"🏷️ Rarity: *{rarity}*\n"
        f"📺 {series}\n"
        f"{bid_line}\n"
        f"{bidder_line}"
        f"{host}\n"
        f"⏳ Time Left: *{hrs}h {mins}m*\n"
        f"🔢 Auction ID: `#{aid}`\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"Reply to this message with `/bid <coins>` to bid!"
    )


async def _post_auction(context, aid: int):
    cursor.execute("SELECT * FROM auction_listings WHERE id=?", (aid,))
    row = cursor.fetchone()
    if not row:
        return
    file_id, file_type = row[6], row[7]
    caption = _auction_caption(row)
    sent = await send_card_media(
        context.bot, file_id, file_type=file_type, caption=caption,
        parse_mode="Markdown", chat_id=AUCTION_GROUP_ID
    )
    msg_id = sent.message_id if sent else None
    cursor.execute(
        "UPDATE auction_listings SET listing_msg_id=?, listing_chat_id=? WHERE id=?",
        (msg_id, AUCTION_GROUP_ID, aid)
    )
    conn.commit()

    if msg_id:
        try:
            await context.bot.pin_chat_message(chat_id=AUCTION_GROUP_ID, message_id=msg_id, disable_notification=True)
        except Exception:
            pass  # bot may lack pin permission in the auction group — auction still works fine


async def stauction_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/stauction <master_card_id> <starting_price> — OWNER ONLY. Bot hosts an auction
    for a card pulled straight from the card catalog (not from any player's collection)."""
    if not update.effective_user or not update.message:
        return
    if not _is_owner(update.effective_user.id):
        await update.message.reply_text("🚫 This command is for the owner only.")
        return

    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            "🔨 *START HOUSE AUCTION*\n\nUsage: `/stauction <card_id> <starting_price>`\n"
            "`card_id` is the master catalog card ID (from /addcard).",
            parse_mode="Markdown"
        )
        return

    try:
        card_id = int(args[0])
        start_price = int(args[1])
    except ValueError:
        await update.message.reply_text("❌ Card ID and starting price must be numbers.")
        return
    if start_price <= 0:
        await update.message.reply_text("❌ Starting price must be greater than 0.")
        return

    cursor.execute("SELECT id, name, rarity, file_id, COALESCE(file_type,'photo'), COALESCE(series,'Naruto') FROM cards WHERE id=?", (card_id,))
    card = cursor.fetchone()
    if not card:
        await update.message.reply_text(f"❌ No card with catalog ID #{card_id} exists.")
        return
    _, name, rarity, file_id, file_type, series = card

    now = int(time.time())
    cursor.execute(
        "INSERT INTO auction_listings (seller_id, card_row_id, card_id, card_name, rarity, file_id, file_type, "
        "series, start_price, status, created_at, ends_at, started_by_bot) "
        "VALUES (?,NULL,?,?,?,?,?,?,?, 'active', ?, ?, 1)",
        (OWNER_ID, card_id, name, rarity, file_id, file_type, series, start_price, now, now + AUCTION_DURATION_SECONDS)
    )
    conn.commit()
    aid = cursor.lastrowid
    await _post_auction(context, aid)
    await update.message.reply_text(f"✅ House auction `#{aid}` for *{name.title()}* started! Ends in 2h.", parse_mode="Markdown")


async def auction_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/auction <card_id> <base_price> — auction one of your own cards to other players."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            "🔨 *START AN AUCTION*\n\nUsage: `/auction <card_id> <base_price>`\n\n"
            "🪙 Base price is in Shinobi Coins. Bidding runs 2 hours.\n"
            "If nobody bids, your card is safely returned to you.",
            parse_mode="Markdown"
        )
        return

    try:
        card_id_arg = int(args[0])
        base_price = int(args[1])
    except ValueError:
        await update.message.reply_text("❌ Card ID and base price must be numbers.")
        return
    if base_price <= 0:
        await update.message.reply_text("❌ Base price must be greater than 0.")
        return

    cursor.execute(
        "SELECT id, card_name, rarity, file_id, COALESCE(file_type,'photo'), COALESCE(series,'Naruto') "
        "FROM user_cards WHERE card_id=? AND user_id=? LIMIT 1",
        (card_id_arg, user_id)
    )
    row = cursor.fetchone()
    if not row:
        await update.message.reply_text(f"❌ You don't own card *#{card_id_arg}*.", parse_mode="Markdown")
        return
    row_id, card_name, rarity, file_id, file_type, series = row

    _frozen, _frozen_reason = is_card_frozen(row_id)
    if _frozen:
        await update.message.reply_text(f"🔒 *This card is frozen!*\n\n{_frozen_reason}", parse_mode="Markdown")
        return

    now = int(time.time())
    cursor.execute(
        "INSERT INTO auction_listings (seller_id, card_row_id, card_id, card_name, rarity, file_id, file_type, "
        "series, start_price, status, created_at, ends_at, started_by_bot) "
        "VALUES (?,?,?,?,?,?,?,?,?, 'active', ?, ?, 0)",
        (user_id, row_id, card_id_arg, card_name, rarity, file_id, file_type, series, base_price, now, now + AUCTION_DURATION_SECONDS)
    )
    conn.commit()
    aid = cursor.lastrowid
    await _post_auction(context, aid)
    await update.message.reply_text(
        f"✅ Auction `#{aid}` started for *{card_name.title()}*!\n"
        f"🔒 Your card is frozen until the auction ends or is settled.",
        parse_mode="Markdown"
    )


async def bid_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/bid <coins> — reply to an auction post in the auction group to place a bid (Shinobi Coins)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    user_name = update.effective_user.first_name or "Bidder"

    if update.effective_chat and update.effective_chat.id != AUCTION_GROUP_ID:
        await update.message.reply_text("❌ Bidding only works inside the auction group.")
        return
    if not update.message.reply_to_message:
        await update.message.reply_text("❌ Reply to the auction post you want to bid on with `/bid <coins>`.", parse_mode="Markdown")
        return
    if not has_started_bot(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    args = context.args or []
    if not args:
        await update.message.reply_text("❌ Usage: `/bid <coins>`", parse_mode="Markdown")
        return
    try:
        amount = int(args[0])
    except ValueError:
        await update.message.reply_text("❌ Bid amount must be a number.")
        return

    replied_msg_id = update.message.reply_to_message.message_id
    cursor.execute(
        "SELECT * FROM auction_listings WHERE listing_msg_id=? AND listing_chat_id=? AND status='active'",
        (replied_msg_id, AUCTION_GROUP_ID)
    )
    row = cursor.fetchone()
    if not row:
        await update.message.reply_text("❌ That post isn't an active auction.")
        return

    (aid, seller_id, card_row_id, card_id, card_name, rarity, file_id, file_type,
     series, start_price, current_bid, current_bidder_id, status, listing_msg_id,
     listing_chat_id, created_at, ends_at, started_by_bot, current_bidder_name) = row

    if int(time.time()) >= ends_at:
        await update.message.reply_text("⏰ This auction has already ended.")
        return
    if seller_id == user_id and not started_by_bot:
        await update.message.reply_text("❌ You can't bid on your own auction.")
        return

    min_required = (current_bid + 1) if current_bid is not None else start_price
    if amount < min_required:
        await update.message.reply_text(f"❌ Bid too low! Minimum bid is *{min_required:,}* 🪙", parse_mode="Markdown")
        return
    if current_bidder_id == user_id:
        await update.message.reply_text("❌ You're already the highest bidder.")
        return

    if not deduct_coins(user_id, amount):
        await update.message.reply_text(f"❌ Not enough Shinobi Coins! You have {get_coins(user_id):,}, need {amount:,}.")
        return

    # Refund the previous highest bidder (their coins were escrowed/frozen)
    if current_bidder_id is not None and current_bid is not None:
        add_coins(current_bidder_id, current_bid)
        try:
            await context.bot.send_message(
                chat_id=current_bidder_id,
                text=f"🔔 You've been outbid on auction `#{aid}` ({card_name.title()})! Your {current_bid:,} 🪙 has been refunded.",
                parse_mode="Markdown"
            )
        except Exception:
            pass

    bidder_display_name = (
        f"@{update.effective_user.username}" if update.effective_user.username
        else (update.effective_user.first_name or "Bidder")
    )
    cursor.execute(
        "UPDATE auction_listings SET current_bid=?, current_bidder_id=?, current_bidder_name=? WHERE id=?",
        (amount, user_id, bidder_display_name, aid)
    )
    conn.commit()

    await update.message.reply_text(f"✅ Bid placed! *{amount:,}* 🪙 is now the highest bid on `#{aid}`.", parse_mode="Markdown")

    cursor.execute("SELECT * FROM auction_listings WHERE id=?", (aid,))
    updated_row = cursor.fetchone()
    if listing_msg_id:
        try:
            await context.bot.edit_message_caption(
                chat_id=AUCTION_GROUP_ID, message_id=listing_msg_id,
                caption=_auction_caption(updated_row), parse_mode="Markdown"
            )
        except Exception:
            pass


async def _finalize_auction(bot, row):
    (aid, seller_id, card_row_id, card_id, card_name, rarity, file_id, file_type,
     series, start_price, current_bid, current_bidder_id, status, listing_msg_id,
     listing_chat_id, created_at, ends_at, started_by_bot, current_bidder_name) = row

    emoji = RARITY_EMOJI.get(rarity, "⭐")
    winner_display = _md_safe_name(current_bidder_name) if current_bidder_name else "the winner"

    if current_bidder_id is None:
        # No bids — revert to seller, no coin movement needed
        cursor.execute("UPDATE auction_listings SET status='expired_no_bid' WHERE id=?", (aid,))
        conn.commit()
        result_text = f"⏰ *AUCTION ENDED — NO BIDS*\n\n{emoji} *{card_name.title()}* [{rarity}]\nCard reverted to the seller."
        if not started_by_bot and seller_id:
            try:
                await bot.send_message(chat_id=seller_id, text=f"⏰ Your auction `#{aid}` ({card_name.title()}) ended with no bids. The card is still yours.", parse_mode="Markdown")
            except Exception:
                pass
    else:
        cursor.execute("UPDATE auction_listings SET status='completed' WHERE id=?", (aid,))
        if started_by_bot:
            # Bot-hosted: winner's coins (already deducted at bid time) stay with the house.
            insert_user_card(current_bidder_id, card_name, rarity, file_id, file_type=file_type, card_id=card_id)
        else:
            cursor.execute("UPDATE user_cards SET user_id=? WHERE id=?", (current_bidder_id, card_row_id))
            add_coins(seller_id, current_bid)
        conn.commit()

        result_text = (
            f"🏆 *AUCTION ENDED — SOLD!*\n\n{emoji} *{card_name.title()}* [{rarity}]\n"
            f"🪙 Final Bid: *{current_bid:,}* Shinobi Coins\n"
            f"🎉 Winner: [{winner_display}](tg://user?id={current_bidder_id})"
        )
        try:
            await bot.send_message(
                chat_id=current_bidder_id,
                text=f"🏆 *You won auction* `#{aid}`!\n\n{emoji} *{card_name.title()}* [{rarity}] is now in your `/collection`.\n🪙 Paid: {current_bid:,} Shinobi Coins",
                parse_mode="Markdown"
            )
        except Exception:
            pass
        if not started_by_bot and seller_id:
            try:
                await bot.send_message(
                    chat_id=seller_id,
                    text=f"💰 *Your auction sold!*\n\n{emoji} *{card_name.title()}* [{rarity}]\n🪙 You received: {current_bid:,} Shinobi Coins",
                    parse_mode="Markdown"
                )
            except Exception:
                pass

    if listing_msg_id:
        try:
            await bot.edit_message_caption(chat_id=AUCTION_GROUP_ID, message_id=listing_msg_id, caption=result_text, parse_mode="Markdown")
        except Exception:
            pass
        try:
            await bot.unpin_chat_message(chat_id=AUCTION_GROUP_ID, message_id=listing_msg_id)
        except Exception:
            pass  # bot may lack pin permission, or it was already unpinned — not fatal


async def auction_scheduler(bot):
    """Runs forever. Every 60 seconds, settles any auction whose 2h timer has expired."""
    print("[AUCTION] Scheduler started (60s interval).")
    await asyncio.sleep(20)
    while True:
        try:
            now = int(time.time())
            cursor.execute("SELECT * FROM auction_listings WHERE status='active' AND ends_at<=?", (now,))
            due = cursor.fetchall()
            for row in due:
                try:
                    await _finalize_auction(bot, row)
                except Exception as e:
                    print(f"[AUCTION] Finalize error for auction {row[0]}: {e}")
        except Exception as e:
            print(f"[AUCTION] Scheduler error: {e}")
        await asyncio.sleep(60)


async def my_auctions_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/myauctions — list your own active player-hosted auctions (cards can't be cancelled once bidding starts)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    cursor.execute(
        "SELECT id, card_name, rarity, start_price, current_bid FROM auction_listings "
        "WHERE seller_id=? AND status='active' AND started_by_bot=0 ORDER BY id DESC",
        (user_id,)
    )
    rows = cursor.fetchall()
    if not rows:
        await update.message.reply_text("📋 *You have no active auctions.*\n\nUse `/auction <card_id> <base_price>` to start one.", parse_mode="Markdown")
        return
    lines = ["🔨 *YOUR ACTIVE AUCTIONS*\n"]
    for aid, name, rarity, start_price, current_bid in rows:
        emoji = RARITY_EMOJI.get(rarity, "⭐")
        bid_txt = f"{current_bid:,} 🪙 (highest)" if current_bid is not None else f"{start_price:,} 🪙 (starting, no bids)"
        lines.append(f"{emoji} *{name.title()}* — `#{aid}` — {bid_txt}")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


# ═══════════════════════════════════════════════════════════════════
#     📊 SHINOBI MARKET — dynamic, supply/demand-driven character prices
# ═══════════════════════════════════════════════════════════════════
# This is a SEPARATE system from the existing player-to-player /sell + /list
# marketplace (fixed price, seller sets it, other players buy that exact
# listing) and from /auction (timed bidding on one specific card copy).
#
# The Shinobi Market instead tracks a single, bot-computed "market value"
# PER CHARACTER (per master catalog card_id), which drifts up and down based
# on supply (how many copies are in circulation) and demand (recent buy
# activity), the same way the design doc's "Shinobi Market" system works.
# Users can /market a character to check its price, then trade directly
# against the market itself (mint a fresh copy by buying, or liquidate a
# copy by selling) at whatever the current computed value is.
#
# Nothing here touches /sell, /list, /auction, /stauction or their tables —
# those keep working exactly as before.

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_market_values (
    card_id           INTEGER PRIMARY KEY,
    base_value        INTEGER,
    min_value         INTEGER,
    max_value         INTEGER,
    current_value     INTEGER,
    supply            INTEGER DEFAULT 0,
    demand_6h         INTEGER DEFAULT 0,
    event_modifier    REAL DEFAULT 1.0,
    trades_total      INTEGER DEFAULT 0,
    value_24h_ago     INTEGER,
    value_24h_ago_at  INTEGER,
    last_recalc       INTEGER
)
""")
conn.commit()

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_market_trades (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    card_id   INTEGER,
    user_id   INTEGER,
    action    TEXT,
    price     INTEGER,
    ts        INTEGER
)
""")
conn.commit()

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_market_history (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    card_id      INTEGER,
    value        INTEGER,
    recorded_at  INTEGER
)
""")
conn.commit()

# FIX (Market bug): Buying on the Shinobi Market must give the user a STOCK
# POSITION in the character — not an actual physical card. Previously "Buy"
# minted a real row in user_cards, which was indistinguishable from pulling
# the character from a pack/draft. Holdings below are purely a number of
# "shares" per user per card_id; selling cashes them out at the current
# price. No user_cards rows are ever created or removed by this system.
cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_market_holdings (
    user_id   INTEGER,
    card_id   INTEGER,
    quantity  INTEGER DEFAULT 0,
    PRIMARY KEY (user_id, card_id)
)
""")
conn.commit()


def _market_get_holding(user_id: int, card_id: int) -> int:
    cursor.execute(
        "SELECT quantity FROM shinobi_market_holdings WHERE user_id=? AND card_id=?",
        (user_id, card_id)
    )
    row = cursor.fetchone()
    return row[0] if row else 0


def _market_add_holding(user_id: int, card_id: int, delta: int):
    """delta can be positive (buy) or negative (sell). Removes the row once
    quantity reaches 0 so empty positions don't linger."""
    current = _market_get_holding(user_id, card_id)
    new_qty = current + delta
    if new_qty <= 0:
        cursor.execute(
            "DELETE FROM shinobi_market_holdings WHERE user_id=? AND card_id=?",
            (user_id, card_id)
        )
    elif current == 0:
        cursor.execute(
            "INSERT INTO shinobi_market_holdings (user_id, card_id, quantity) VALUES (?,?,?)",
            (user_id, card_id, new_qty)
        )
    else:
        cursor.execute(
            "UPDATE shinobi_market_holdings SET quantity=? WHERE user_id=? AND card_id=?",
            (new_qty, user_id, card_id)
        )
    conn.commit()
    return max(0, new_qty)

# Base value per rarity tier — feel free to retune. Unlisted rarities (e.g. any
# custom rarity added later via /addrarity) fall back to MARKET_DEFAULT_BASE_VALUE.
MARKET_RARITY_BASE_VALUE = {
    "Common":       400,
    "Rare":         900,
    "Epic":         2000,
    "Legendary":    5000,
    "Mythic":       9000,
    "Spring":       1800,
    "Summer":       1800,
    "Academy":      700,
    "FIFA":         1500,
    "Crossverse":   3500,
    "Animation":    6000,
    "LeaderBoard":  12000,
    "Premium":      15000,
    "Special":      4500,
    "Mermaid":      2600,
    "Tradition":    2600,
}
MARKET_DEFAULT_BASE_VALUE = 800

# Cards whose rarity is in this set can be checked/valued on the market but
# cannot be minted via /market buy (owner can extend this for exclusive/
# event-only characters that should never be printable on demand).
MARKET_MINT_BLOCKED_RARITIES = set()

MARKET_TRADE_COOLDOWN_SECONDS = 5
_last_market_trade_time = {}  # user_id -> unix timestamp of last /market buy or sell


def _market_supply(card_id: int) -> int:
    """'Copies in circulation' for pricing purposes = total shares currently
    held by all users in shinobi_market_holdings (NOT physical cards — see
    the Market bug fix note above the holdings table)."""
    cursor.execute("SELECT COALESCE(SUM(quantity),0) FROM shinobi_market_holdings WHERE card_id=?", (card_id,))
    row = cursor.fetchone()
    return row[0] if row else 0


def _market_get_or_init(card_id: int):
    """Returns the shinobi_market_values row for card_id, creating it (seeded
    from the card's rarity and current circulation) the first time it's needed."""
    cursor.execute("SELECT * FROM shinobi_market_values WHERE card_id=?", (card_id,))
    row = cursor.fetchone()
    if row:
        return row

    cursor.execute("SELECT rarity FROM cards WHERE id=?", (card_id,))
    crow = cursor.fetchone()
    rarity = crow[0] if crow else None
    base = MARKET_RARITY_BASE_VALUE.get(rarity, MARKET_DEFAULT_BASE_VALUE)
    min_v = max(50, int(base * 0.4))
    max_v = int(base * 3.0)
    supply = _market_supply(card_id)
    now = int(time.time())

    cursor.execute(
        "INSERT INTO shinobi_market_values (card_id, base_value, min_value, max_value, current_value, "
        "supply, demand_6h, event_modifier, trades_total, value_24h_ago, value_24h_ago_at, last_recalc) "
        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
        (card_id, base, min_v, max_v, base, supply, 0, 1.0, 0, base, now, now)
    )
    conn.commit()
    cursor.execute("SELECT * FROM shinobi_market_values WHERE card_id=?", (card_id,))
    return cursor.fetchone()


def _market_recalc(card_id: int) -> int:
    """Recomputes and stores the current market value for one character based
    on live supply and recent (6h) buy/sell activity. Returns the new value."""
    row = _market_get_or_init(card_id)
    (_cid, base, min_v, max_v, current, _supply_old, _demand_old,
     mod, trades_total, v24, v24_at, _last_recalc) = row

    supply = _market_supply(card_id)
    now = int(time.time())

    cursor.execute(
        "SELECT action, COUNT(*) FROM shinobi_market_trades WHERE card_id=? AND ts>=? GROUP BY action",
        (card_id, now - 21600)  # last 6 hours
    )
    counts = dict(cursor.fetchall())
    buys6h = counts.get("buy", 0)
    sells6h = counts.get("sell", 0)
    demand_net = buys6h - sells6h

    # More copies in circulation → downward pressure. 40 copies ≈ neutral.
    supply_factor = max(-0.5, min(0.5, 0.5 - (supply / 40.0) * 0.15))
    # Recent net buying → upward pressure, ~3% per net trade, capped.
    demand_factor = max(-0.4, min(0.6, demand_net * 0.03))

    target = base * (1 + supply_factor + demand_factor) * (mod or 1.0)
    # Smooth movement toward target so a single trade can't spike the price.
    new_value = int(current + (target - current) * 0.35)
    new_value = max(min_v, min(max_v, new_value))

    if now - (v24_at or 0) >= 86400:
        v24 = current
        v24_at = now

    cursor.execute(
        "UPDATE shinobi_market_values SET current_value=?, supply=?, demand_6h=?, "
        "value_24h_ago=?, value_24h_ago_at=?, last_recalc=? WHERE card_id=?",
        (new_value, supply, demand_net, v24, v24_at, now, card_id)
    )
    conn.commit()
    cursor.execute(
        "INSERT INTO shinobi_market_history (card_id, value, recorded_at) VALUES (?,?,?)",
        (card_id, new_value, now)
    )
    conn.commit()
    return new_value


def _market_change_pct(card_id: int) -> float:
    cursor.execute("SELECT current_value, value_24h_ago FROM shinobi_market_values WHERE card_id=?", (card_id,))
    row = cursor.fetchone()
    if not row or not row[1]:
        return 0.0
    current, v24 = row
    if v24 <= 0:
        return 0.0
    return ((current - v24) / v24) * 100.0


def check_market_cooldown(user_id: int):
    now = time.time()
    elapsed = now - _last_market_trade_time.get(user_id, 0)
    if elapsed < MARKET_TRADE_COOLDOWN_SECONDS:
        remaining = MARKET_TRADE_COOLDOWN_SECONDS - elapsed
        return f"⏳ Slow down! Wait *{remaining:.1f}s* before your next market trade."
    return None


def mark_market_trade(user_id: int):
    _last_market_trade_time[user_id] = time.time()


def _market_detail_caption(card_id: int, name: str, rarity: str, series: str, user_id: int = None) -> str:
    _market_get_or_init(card_id)
    value = _market_recalc(card_id)
    change = _market_change_pct(card_id)
    supply = _market_supply(card_id)
    arrow = "📈" if change > 0 else ("📉" if change < 0 else "➖")
    emoji = RARITY_EMOJI.get(rarity, "⭐")
    cursor.execute("SELECT COUNT(*) FROM shinobi_market_trades WHERE card_id=?", (card_id,))
    total_trades = cursor.fetchone()[0]
    holding_line = ""
    if user_id is not None:
        held = _market_get_holding(user_id, card_id)
        holding_line = f"💼 Your shares: *{held}*\n"
    return (
        f"📊 *SHINOBI MARKET*\n\n"
        f"{emoji} *{name.title()}*  [{rarity}]\n"
        f"📺 {series}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🪙 Value: *{value:,}* Shinobi Coins / share\n"
        f"{arrow} 24h: *{change:+.1f}%*\n"
        f"👥 Shares in circulation: *{supply}*\n"
        f"{holding_line}"
        f"🔁 Trades: *{total_trades}*\n"
        f"🔢 Card ID: `#{card_id}`\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"Buy invests in *1 share* of this character at the current value (no physical card).\n"
        f"Sell cashes out 1 share from your position at the current value."
    )


async def market_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/market — dashboard of top movers, or /market <card_id> for one character's price + trade buttons."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    _frozen, _frozen_reason = is_feature_frozen("shinobi_market")
    if _frozen and not is_admin(user_id):
        await update.message.reply_text(
            f"🔒 *The Shinobi Market is temporarily frozen.*\n\n{_frozen_reason}",
            parse_mode="Markdown"
        )
        return

    args = context.args or []

    if not args:
        cursor.execute(
            "SELECT smv.card_id, c.name, c.rarity, smv.current_value, smv.value_24h_ago "
            "FROM shinobi_market_values smv JOIN cards c ON c.id = smv.card_id"
        )
        rows = cursor.fetchall()
        if not rows:
            await update.message.reply_text(
                "📊 *SHINOBI MARKET*\n\n"
                "No characters have been valued yet.\n"
                "Use `/market <card_id>` to look up any card and kick off its price tracking!",
                parse_mode="Markdown"
            )
            return

        scored = []
        for card_id, name, rarity, current, v24 in rows:
            pct = ((current - v24) / v24 * 100.0) if v24 else 0.0
            scored.append((pct, card_id, name, rarity, current))
        scored.sort(key=lambda x: x[0], reverse=True)

        gainers = scored[:5]
        losers = sorted(scored, key=lambda x: x[0])[:5]

        lines = ["📊 *SHINOBI MARKET — TOP MOVERS*\n"]
        lines.append("📈 *Gainers (24h)*")
        for pct, card_id, name, rarity, current in gainers:
            emoji = RARITY_EMOJI.get(rarity, "⭐")
            lines.append(f"{emoji} {name.title()} — 🪙{current:,} ({pct:+.1f}%) `#{card_id}`")
        lines.append("\n📉 *Losers (24h)*")
        for pct, card_id, name, rarity, current in losers:
            emoji = RARITY_EMOJI.get(rarity, "⭐")
            lines.append(f"{emoji} {name.title()} — 🪙{current:,} ({pct:+.1f}%) `#{card_id}`")
        lines.append("\nUse `/market <card_id>` to view and trade a specific character.")
        await update.message.reply_text("\n".join(lines), parse_mode="Markdown")
        return

    try:
        card_id = int(args[0])
    except ValueError:
        await update.message.reply_text("❌ Usage: `/market <card_id>`", parse_mode="Markdown")
        return

    cursor.execute("SELECT id, name, rarity, COALESCE(series,'Naruto') FROM cards WHERE id=?", (card_id,))
    card = cursor.fetchone()
    if not card:
        await update.message.reply_text(f"❌ No character with catalog ID #{card_id} exists.")
        return
    _, name, rarity, series = card

    caption = _market_detail_caption(card_id, name, rarity, series, user_id=user_id)
    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("🛒 Buy 1 Share", callback_data=f"mkval_buy_{card_id}"),
        InlineKeyboardButton("💰 Sell 1 Share", callback_data=f"mkval_sell_{card_id}"),
    ]])
    await update.message.reply_text(caption, parse_mode="Markdown", reply_markup=keyboard)


async def shinobi_market_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles mkval_buy_<card_id> / mkval_sell_<card_id> button taps."""
    query = update.callback_query
    if not query or not query.data:
        return
    user_id = query.from_user.id
    data = query.data

    if is_banned(user_id):
        await query.answer("🚫 You're banned from using this bot.", show_alert=True)
        return

    _frozen, _frozen_reason = is_feature_frozen("shinobi_market")
    if _frozen and not is_admin(user_id):
        await query.answer(f"🔒 The Shinobi Market is temporarily frozen. {_frozen_reason}", show_alert=True)
        return

    cd_msg = check_market_cooldown(user_id)
    if cd_msg:
        await query.answer(cd_msg, show_alert=True)
        return

    try:
        action, card_id_str = data.rsplit("_", 1)
        card_id = int(card_id_str)
    except Exception:
        await query.answer("❌ Malformed market button.", show_alert=True)
        return

    cursor.execute("SELECT id, name, rarity, COALESCE(series,'Naruto'), file_id, COALESCE(file_type,'photo') FROM cards WHERE id=?", (card_id,))
    card = cursor.fetchone()
    if not card:
        await query.answer("❌ This character no longer exists in the catalog.", show_alert=True)
        return
    _, name, rarity, series, master_file_id, master_file_type = card

    _market_get_or_init(card_id)
    cursor.execute("SELECT current_value FROM shinobi_market_values WHERE card_id=?", (card_id,))
    value = cursor.fetchone()[0]
    now = int(time.time())

    if data.startswith("mkval_buy_"):
        # FIX (Market bug): this used to INSERT a real row into user_cards,
        # handing the user an actual physical card. Buying on the Shinobi
        # Market should only open/add to a STOCK POSITION — see the
        # shinobi_market_holdings table + helpers defined above. No card is
        # created here anymore.
        if rarity in MARKET_MINT_BLOCKED_RARITIES:
            await query.answer("🚫 This character can't be traded on the market.", show_alert=True)
            return
        if not deduct_coins(user_id, value):
            await query.answer(f"❌ You need 🪙{value:,} coins to buy 1 share — check /balance.", show_alert=True)
            return
        new_qty = _market_add_holding(user_id, card_id, 1)
        cursor.execute("INSERT INTO shinobi_market_trades (card_id, user_id, action, price, ts) VALUES (?,?,?,?,?)",
                        (card_id, user_id, "buy", value, now))
        cursor.execute("UPDATE shinobi_market_values SET trades_total = trades_total + 1 WHERE card_id=?", (card_id,))
        conn.commit()
        mark_market_trade(user_id)
        new_value = _market_recalc(card_id)
        await query.answer(f"✅ Bought 1 share of {name.title()} for 🪙{value:,}! You now hold {new_qty}.", show_alert=True)
        try:
            caption = _market_detail_caption(card_id, name, rarity, series, user_id=user_id)
            keyboard = InlineKeyboardMarkup([[
                InlineKeyboardButton("🛒 Buy 1 Share", callback_data=f"mkval_buy_{card_id}"),
                InlineKeyboardButton("💰 Sell 1 Share", callback_data=f"mkval_sell_{card_id}"),
            ]])
            await query.edit_message_text(caption, parse_mode="Markdown", reply_markup=keyboard)
        except Exception:
            pass
        return

    if data.startswith("mkval_sell_"):
        held = _market_get_holding(user_id, card_id)
        if held <= 0:
            await query.answer("❌ You don't hold any shares of this character to sell.", show_alert=True)
            return

        new_qty = _market_add_holding(user_id, card_id, -1)
        add_coins(user_id, value)
        cursor.execute("INSERT INTO shinobi_market_trades (card_id, user_id, action, price, ts) VALUES (?,?,?,?,?)",
                        (card_id, user_id, "sell", value, now))
        cursor.execute("UPDATE shinobi_market_values SET trades_total = trades_total + 1 WHERE card_id=?", (card_id,))
        conn.commit()
        mark_market_trade(user_id)
        new_value = _market_recalc(card_id)
        await query.answer(f"✅ Sold 1 share of {name.title()} for 🪙{value:,}! You now hold {new_qty}.", show_alert=True)
        try:
            caption = _market_detail_caption(card_id, name, rarity, series, user_id=user_id)
            keyboard = InlineKeyboardMarkup([[
                InlineKeyboardButton("🛒 Buy 1 Share", callback_data=f"mkval_buy_{card_id}"),
                InlineKeyboardButton("💰 Sell 1 Share", callback_data=f"mkval_sell_{card_id}"),
            ]])
            await query.edit_message_text(caption, parse_mode="Markdown", reply_markup=keyboard)
        except Exception:
            pass
        return

    await query.answer()


async def market_price_scheduler(bot):
    """Runs forever. Every 5 minutes, recalculates the market value of every
    character that's currently being tracked (i.e. has been looked up or
    traded at least once)."""
    print("[SHINOBI MARKET] Price scheduler started (300s interval).")
    await asyncio.sleep(30)
    while True:
        try:
            cursor.execute("SELECT card_id FROM shinobi_market_values")
            tracked = [r[0] for r in cursor.fetchall()]
            for card_id in tracked:
                try:
                    _market_recalc(card_id)
                except Exception as e:
                    print(f"[SHINOBI MARKET] Recalc error for card {card_id}: {e}")
        except Exception as e:
            print(f"[SHINOBI MARKET] Scheduler error: {e}")
        await asyncio.sleep(300)



# ═══════════════════════════════════════════════════════════════════
#     🗺️ SHINOBI EXPEDITIONS — send a character out, come back later
# ═══════════════════════════════════════════════════════════════════
# Users pick one of their own (unfrozen) characters and send it on a 2-hour
# expedition. When it's done, they claim the result: usually a coin reward,
# occasionally a bigger "critical success" payout, and rarely a partial
# reward on failure. Different rarities have different reward size and
# success odds, so which character you send is a real decision.
#
# While a card is out on expedition it's frozen (via is_card_frozen, already
# updated above) so it can't also be sold/gifted/traded/auctioned/listed
# until it returns and the result is claimed.

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_expeditions (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id       INTEGER,
    card_row_id   INTEGER,
    card_id       INTEGER,
    card_name     TEXT,
    rarity        TEXT,
    file_id       TEXT,
    file_type     TEXT DEFAULT 'photo',
    series        TEXT DEFAULT 'Naruto',
    started_at    INTEGER,
    ends_at       INTEGER,
    status        TEXT DEFAULT 'active',
    success       INTEGER,
    coin_reward   INTEGER,
    notified      INTEGER DEFAULT 0
)
""")
conn.commit()

EXPEDITION_DURATION_SECONDS = 2 * 60 * 60  # 2 hours

# Per-rarity: base coin reward on success, success probability (0-1), and base
# voucher reward on success (FIX Issue 8: vouchers now drop from expeditions).
EXPEDITION_TRAITS = {
    "Common":      {"reward": 250,  "success": 0.95, "vouchers": 1},
    "Rare":        {"reward": 500,  "success": 0.90, "vouchers": 1},
    "Epic":        {"reward": 900,  "success": 0.85, "vouchers": 2},
    "Legendary":   {"reward": 1800, "success": 0.75, "vouchers": 2},
    "Mythic":      {"reward": 3000, "success": 0.65, "vouchers": 3},
    "Spring":      {"reward": 700,  "success": 0.88, "vouchers": 2},
    "Summer":      {"reward": 700,  "success": 0.88, "vouchers": 2},
    "Academy":     {"reward": 300,  "success": 0.93, "vouchers": 1},
    "FIFA":        {"reward": 600,  "success": 0.88, "vouchers": 1},
    "Crossverse":  {"reward": 1300, "success": 0.80, "vouchers": 2},
    "Animation":   {"reward": 2200, "success": 0.70, "vouchers": 3},
    "LeaderBoard": {"reward": 4000, "success": 0.60, "vouchers": 3},
    "Premium":     {"reward": 5000, "success": 0.55, "vouchers": 3},
    "Special":     {"reward": 1600, "success": 0.82, "vouchers": 2},
    "Mermaid":     {"reward": 950,  "success": 0.85, "vouchers": 2},
    "Tradition":   {"reward": 950,  "success": 0.85, "vouchers": 2},
}
EXPEDITION_DEFAULT_TRAIT = {"reward": 300, "success": 0.90, "vouchers": 1}
EXPEDITION_FAILURE_REWARD_PCT = 0.35   # consolation reward on failed expeditions
EXPEDITION_CRIT_CHANCE = 0.10          # chance of a 1.5x bonus on a successful expedition
EXPEDITION_CRIT_MULTIPLIER = 1.5

# FIX: without a cap, a user could send every single character they own on
# expedition at once — with a big enough collection that's dozens or hundreds
# of free coin payouts every 2 hours, which floods the Shinobi Coin economy.
# Capping concurrent expeditions per user keeps the reward loop meaningful
# (which character do I send now?) instead of a "send everything" macro.
MAX_CONCURRENT_EXPEDITIONS = 3

# ── Expedition rework (Issue 8) ─────────────────────────────────────────────
# - MAX_EXPEDITIONS_PER_DAY: separate from the concurrency cap above — this
#   limits how many expeditions a user can *start* in a rolling day, using
#   the same 5:30 AM IST reset the bot's /daily command uses.
# - Rewards scale with an "Expedition Level" that a user levels up by
#   completing expeditions (progression), on top of the existing village/
#   world-event multipliers.
# - Vouchers now drop from expeditions too, capped at 20/day.
# - A 7-consecutive-day usage streak grants a one-time 30 voucher bonus.
# - A rare (3%) "Rare Cache" jackpot grants +50 bonus vouchers on top of
#   the daily cap.
MAX_EXPEDITIONS_PER_DAY = 5
EXPEDITION_XP_PER_CLAIM = 15
EXPEDITION_XP_PER_LEVEL = 100
EXPEDITION_LEVEL_REWARD_BONUS_PCT = 0.04   # +4% coin/voucher reward per level
EXPEDITION_MAX_LEVEL_BONUS_PCT = 1.00      # cap the level bonus at +100%
EXPEDITION_DAILY_VOUCHER_CAP = 20
EXPEDITION_STREAK_BONUS_DAYS = 7
EXPEDITION_STREAK_BONUS_VOUCHERS = 30
EXPEDITION_JACKPOT_CHANCE = 0.03
EXPEDITION_JACKPOT_VOUCHERS = 50

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_expedition_progress (
    user_id             INTEGER PRIMARY KEY,
    xp                  INTEGER DEFAULT 0,
    level               INTEGER DEFAULT 1,
    total_completed     INTEGER DEFAULT 0,
    streak_days         INTEGER DEFAULT 0,
    last_active_day     INTEGER DEFAULT 0,
    vouchers_today       INTEGER DEFAULT 0,
    vouchers_day_epoch   INTEGER DEFAULT 0
)
""")
conn.commit()


def _expedition_get_progress(user_id: int):
    cursor.execute("SELECT xp, level, total_completed, streak_days, last_active_day, vouchers_today, vouchers_day_epoch "
                    "FROM shinobi_expedition_progress WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    if row:
        return row
    cursor.execute("INSERT INTO shinobi_expedition_progress (user_id) VALUES (?)", (user_id,))
    conn.commit()
    return (0, 1, 0, 0, 0, 0, 0)


def _expedition_level_bonus_pct(level: int) -> float:
    return min(EXPEDITION_LEVEL_REWARD_BONUS_PCT * (level - 1), EXPEDITION_MAX_LEVEL_BONUS_PCT)


def _expedition_daily_count(user_id: int, day_start: int) -> int:
    cursor.execute(
        "SELECT COUNT(*) FROM shinobi_expeditions WHERE user_id=? AND started_at>=?",
        (user_id, day_start)
    )
    return cursor.fetchone()[0]


def _expedition_traits(rarity: str) -> dict:
    return EXPEDITION_TRAITS.get(rarity, EXPEDITION_DEFAULT_TRAIT)


def _expedition_active_count(user_id: int) -> int:
    cursor.execute("SELECT COUNT(*) FROM shinobi_expeditions WHERE user_id=? AND status='active'", (user_id,))
    return cursor.fetchone()[0]


async def expedition_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/expedition — view your active/ready expeditions, or /expedition <card_id> to send a character out."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    args = context.args or []
    now = int(time.time())
    day_start = _coin_reset_epoch(now)

    if not args:
        cursor.execute(
            "SELECT id, card_name, rarity, ends_at FROM shinobi_expeditions "
            "WHERE user_id=? AND status='active' ORDER BY ends_at ASC",
            (user_id,)
        )
        rows = cursor.fetchall()
        daily_used = _expedition_daily_count(user_id, day_start)
        xp, level, total_completed, streak_days, last_active_day, vouchers_today, vouchers_day_epoch = _expedition_get_progress(user_id)
        if vouchers_day_epoch != day_start:
            vouchers_today = 0
        if not rows:
            await update.message.reply_text(
                "🗺️ *SHINOBI EXPEDITIONS*\n\n"
                "You have no characters out on expedition.\n\n"
                "Usage: `/expedition <card_id>` — send one of your characters out for 2 hours.\n"
                f"Max *{MAX_CONCURRENT_EXPEDITIONS}* characters out at once.\n"
                f"Max *{MAX_EXPEDITIONS_PER_DAY}* expeditions started per day (*{daily_used}/{MAX_EXPEDITIONS_PER_DAY}* used today).\n\n"
                f"📈 *Expedition Level {level}* (+{int(_expedition_level_bonus_pct(level)*100)}% rewards) — {xp % EXPEDITION_XP_PER_LEVEL}/{EXPEDITION_XP_PER_LEVEL} XP to next level\n"
                f"🎟️ Vouchers today: *{vouchers_today}/{EXPEDITION_DAILY_VOUCHER_CAP}*\n"
                f"🔥 Usage streak: *{streak_days}/{EXPEDITION_STREAK_BONUS_DAYS}* days (Day {EXPEDITION_STREAK_BONUS_DAYS} → +{EXPEDITION_STREAK_BONUS_VOUCHERS} 🎟️ bonus)\n"
                f"🍀 {int(EXPEDITION_JACKPOT_CHANCE*100)}% chance per claim for a +{EXPEDITION_JACKPOT_VOUCHERS} 🎟️ Rare Cache!\n\n"
                "Check `/collection` for your card IDs.",
                parse_mode="Markdown"
            )
            return

        lines = [f"🗺️ *YOUR EXPEDITIONS* ({len(rows)}/{MAX_CONCURRENT_EXPEDITIONS})  •  Today: {daily_used}/{MAX_EXPEDITIONS_PER_DAY}\n"]
        keyboard_rows = []
        for eid, name, rarity, ends_at in rows:
            emoji = RARITY_EMOJI.get(rarity, "⭐")
            remaining = ends_at - now
            if remaining <= 0:
                lines.append(f"{emoji} *{name.title()}* — ✅ Ready to claim! (`#{eid}`)")
                keyboard_rows.append([InlineKeyboardButton(f"🎒 Claim {name.title()}", callback_data=f"exp_claim_{eid}")])
            else:
                hrs, mins = remaining // 3600, (remaining % 3600) // 60
                lines.append(f"{emoji} *{name.title()}* — ⏳ {hrs}h {mins}m left (`#{eid}`)")
        keyboard = InlineKeyboardMarkup(keyboard_rows) if keyboard_rows else None
        await update.message.reply_text("\n".join(lines), parse_mode="Markdown", reply_markup=keyboard)
        return

    try:
        card_id_arg = int(args[0])
    except ValueError:
        await update.message.reply_text("❌ Usage: `/expedition <card_id>`", parse_mode="Markdown")
        return

    active_count = _expedition_active_count(user_id)
    if active_count >= MAX_CONCURRENT_EXPEDITIONS:
        await update.message.reply_text(
            f"🚫 *Expedition limit reached* — you already have *{active_count}/{MAX_CONCURRENT_EXPEDITIONS}* "
            f"characters out.\n\nWait for one to return (`/expedition`) before sending another.",
            parse_mode="Markdown"
        )
        return

    daily_used = _expedition_daily_count(user_id, day_start)
    if daily_used >= MAX_EXPEDITIONS_PER_DAY:
        await update.message.reply_text(
            f"🚫 *Daily expedition limit reached* — you've started *{daily_used}/{MAX_EXPEDITIONS_PER_DAY}* "
            f"expeditions today.\n\nCome back after the daily reset (5:30 AM IST)!",
            parse_mode="Markdown"
        )
        return

    cursor.execute(
        "SELECT id, card_name, rarity, file_id, COALESCE(file_type,'photo'), COALESCE(series,'Naruto') "
        "FROM user_cards WHERE card_id=? AND user_id=?",
        (card_id_arg, user_id)
    )
    owned_rows = cursor.fetchall()
    if not owned_rows:
        await update.message.reply_text(f"❌ You don't own card *#{card_id_arg}*.", parse_mode="Markdown")
        return

    target_row = None
    for row in owned_rows:
        frozen, _reason = is_card_frozen(row[0])
        if not frozen:
            target_row = row
            break
    if target_row is None:
        await update.message.reply_text(
            "🔒 *All your copies of this character are already tied up* (expedition, market, or auction).",
            parse_mode="Markdown"
        )
        return

    row_id, card_name, rarity, file_id, file_type, series = target_row
    trait = _expedition_traits(rarity)
    now = int(time.time())
    ends_at = now + EXPEDITION_DURATION_SECONDS

    cursor.execute(
        "INSERT INTO shinobi_expeditions (user_id, card_row_id, card_id, card_name, rarity, file_id, file_type, "
        "series, started_at, ends_at, status) VALUES (?,?,?,?,?,?,?,?,?,?, 'active')",
        (user_id, row_id, card_id_arg, card_name, rarity, file_id, file_type, series, now, ends_at)
    )
    conn.commit()
    eid = cursor.lastrowid
    emoji = RARITY_EMOJI.get(rarity, "⭐")

    await update.message.reply_text(
        f"🗺️ *EXPEDITION STARTED*\n\n"
        f"{emoji} *{card_name.title()}* has departed on a 2-hour expedition.\n"
        f"🎲 Success chance: *{int(trait['success']*100)}%*\n"
        f"🪙 Potential reward: up to *{int(trait['reward']*EXPEDITION_CRIT_MULTIPLIER):,}* coins\n"
        f"🎟️ Potential vouchers: up to *{trait.get('vouchers',1)}* (daily cap {EXPEDITION_DAILY_VOUCHER_CAP})\n"
        f"🔒 This card is frozen until it returns.\n"
        f"📊 Active expeditions: *{active_count+1}/{MAX_CONCURRENT_EXPEDITIONS}*\n"
        f"📅 Started today: *{daily_used+1}/{MAX_EXPEDITIONS_PER_DAY}*\n"
        f"🔢 Expedition ID: `#{eid}`\n\n"
        f"Use `/expedition` anytime to check on it.",
        parse_mode="Markdown"
    )


async def expedition_claim_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles exp_claim_<expedition_id> button taps."""
    query = update.callback_query
    if not query or not query.data:
        return
    user_id = query.from_user.id

    if is_banned(user_id):
        await query.answer("🚫 You're banned from using this bot.", show_alert=True)
        return

    try:
        eid = int(query.data.rsplit("_", 1)[1])
    except Exception:
        await query.answer("❌ Malformed expedition button.", show_alert=True)
        return

    cursor.execute(
        "SELECT id, user_id, card_row_id, card_id, card_name, rarity, ends_at, status FROM shinobi_expeditions WHERE id=?",
        (eid,)
    )
    row = cursor.fetchone()
    if not row:
        await query.answer("❌ This expedition no longer exists.", show_alert=True)
        return
    _id, owner_id, card_row_id, exp_card_id, card_name, rarity, ends_at, status = row

    if owner_id != user_id:
        await query.answer("❌ This isn't your expedition.", show_alert=True)
        return
    if status != "active":
        await query.answer("✅ Already claimed.", show_alert=True)
        return
    now = int(time.time())
    if ends_at > now:
        remaining = ends_at - now
        hrs, mins = remaining // 3600, (remaining % 3600) // 60
        await query.answer(f"⏳ Not back yet — {hrs}h {mins}m left.", show_alert=True)
        return

    trait = _expedition_traits(rarity)
    # Village level bonus + any active world event bonus for this character both
    # multiply the base reward. Neither system needs to know about the other.
    reward_multiplier = _village_expedition_multiplier(user_id) * _expedition_event_multiplier(exp_card_id)

    # ── Expedition Level progression (Issue 8) ──────────────────────────────
    xp, level, total_completed, streak_days, last_active_day, vouchers_today, vouchers_day_epoch = _expedition_get_progress(user_id)
    level_bonus_pct = _expedition_level_bonus_pct(level)
    reward_multiplier *= (1 + level_bonus_pct)

    success = random.random() < trait["success"]
    crit = False
    if success:
        reward = int(trait["reward"] * reward_multiplier)
        if random.random() < EXPEDITION_CRIT_CHANCE:
            crit = True
            reward = int(reward * EXPEDITION_CRIT_MULTIPLIER)
    else:
        reward = int(trait["reward"] * EXPEDITION_FAILURE_REWARD_PCT * reward_multiplier)

    add_coins(user_id, reward)
    cursor.execute(
        "UPDATE shinobi_expeditions SET status='claimed', success=?, coin_reward=? WHERE id=?",
        (1 if success else 0, reward, eid)
    )

    # ── Level up ─────────────────────────────────────────────────────────────
    new_xp = xp + EXPEDITION_XP_PER_CLAIM
    new_level = 1 + (new_xp // EXPEDITION_XP_PER_LEVEL)
    leveled_up = new_level > level

    # ── Voucher reward, capped at EXPEDITION_DAILY_VOUCHER_CAP/day ──────────
    now_day = _coin_reset_epoch(now)
    if vouchers_day_epoch != now_day:
        vouchers_today = 0  # new day, counter rolled over
    voucher_gain = 0
    if success:
        base_vouchers = trait.get("vouchers", 1)
        remaining_cap = max(0, EXPEDITION_DAILY_VOUCHER_CAP - vouchers_today)
        voucher_gain = min(base_vouchers, remaining_cap)
        if voucher_gain:
            add_vouchers(user_id, voucher_gain)
            vouchers_today += voucher_gain

    # ── 7-day usage streak bonus (Issue 8) ──────────────────────────────────
    streak_bonus_hit = False
    if last_active_day == 0:
        streak_days = 1
    elif now_day == last_active_day:
        pass  # already counted today
    elif now_day == last_active_day + 86400:
        streak_days += 1
    else:
        streak_days = 1  # streak broken

    if streak_days >= EXPEDITION_STREAK_BONUS_DAYS and now_day != last_active_day:
        add_vouchers(user_id, EXPEDITION_STREAK_BONUS_VOUCHERS)
        streak_bonus_hit = True
        streak_days = 0  # restart the streak after paying out

    # ── Rare 50-voucher jackpot (Issue 8), independent of the daily cap ─────
    jackpot_hit = success and (random.random() < EXPEDITION_JACKPOT_CHANCE)
    if jackpot_hit:
        add_vouchers(user_id, EXPEDITION_JACKPOT_VOUCHERS)

    cursor.execute(
        "UPDATE shinobi_expedition_progress SET xp=?, level=?, total_completed=total_completed+1, "
        "streak_days=?, last_active_day=?, vouchers_today=?, vouchers_day_epoch=? WHERE user_id=?",
        (new_xp, new_level, streak_days, now_day, vouchers_today, now_day, user_id)
    )
    conn.commit()

    emoji = RARITY_EMOJI.get(rarity, "⭐")
    if success and crit:
        header = "🌟 *CRITICAL SUCCESS!*"
    elif success:
        header = "🎉 *EXPEDITION COMPLETE!*"
    else:
        header = "💀 *Expedition had a rough time...*"

    extra_lines = ""
    if voucher_gain:
        extra_lines += f"🎟️ Vouchers: *+{voucher_gain}* ({vouchers_today}/{EXPEDITION_DAILY_VOUCHER_CAP} today)\n"
    if jackpot_hit:
        extra_lines += f"🍀 *RARE CACHE FOUND!* +{EXPEDITION_JACKPOT_VOUCHERS} 🎟️ bonus vouchers!\n"
    if streak_bonus_hit:
        extra_lines += f"🔥 *{EXPEDITION_STREAK_BONUS_DAYS}-Day Streak Bonus!* +{EXPEDITION_STREAK_BONUS_VOUCHERS} 🎟️ vouchers!\n"
    if leveled_up:
        extra_lines += f"📈 *Expedition Level Up!* Now Level *{new_level}* (+{int(_expedition_level_bonus_pct(new_level)*100)}% rewards)\n"

    result_text = (
        f"{header}\n\n"
        f"{emoji} *{card_name.title()}* has returned!\n"
        f"🪙 Reward: *+{reward:,}* Shinobi Coins\n"
        f"{extra_lines}"
        f"🔓 Your card is free to use again."
    )
    await query.answer("🎒 Claimed!")
    try:
        await query.edit_message_text(result_text, parse_mode="Markdown")
    except Exception:
        try:
            await context.bot.send_message(chat_id=user_id, text=result_text, parse_mode="Markdown")
        except Exception:
            pass


async def expedition_notify_scheduler(bot):
    """Runs forever. Every 60 seconds, DMs users a heads-up the first time we
    notice one of their expeditions has finished (doesn't auto-claim it —
    the user still taps Claim via /expedition to collect the reward)."""
    print("[EXPEDITION] Notify scheduler started (60s interval).")
    await asyncio.sleep(25)
    while True:
        try:
            now = int(time.time())
            cursor.execute(
                "SELECT id, user_id, card_name, rarity FROM shinobi_expeditions "
                "WHERE status='active' AND ends_at<=? AND notified=0",
                (now,)
            )
            due = cursor.fetchall()
            for eid, user_id, card_name, rarity in due:
                emoji = RARITY_EMOJI.get(rarity, "⭐")
                try:
                    await bot.send_message(
                        chat_id=user_id,
                        text=(
                            f"🗺️ *Expedition complete!*\n\n"
                            f"{emoji} *{card_name.title()}* is back and waiting for you.\n"
                            f"Use `/expedition` to claim your reward!"
                        ),
                        parse_mode="Markdown"
                    )
                except Exception:
                    pass  # user may have blocked the bot or never started a DM — safe to skip
                cursor.execute("UPDATE shinobi_expeditions SET notified=1 WHERE id=?", (eid,))
                conn.commit()
        except Exception as e:
            print(f"[EXPEDITION] Scheduler error: {e}")
        await asyncio.sleep(60)


# ═══════════════════════════════════════════════════════════════════
#     🔮 SHINOBI PREDICTIONS — bet coins on which character's market
#     value will rise the most over the next few hours
# ═══════════════════════════════════════════════════════════════════
# Every few hours the bot opens a round with a handful of candidate
# characters (pulled from the catalog, tracked on the Shinobi Market). Users
# stake coins on the one they think will gain the most by the time the round
# closes. When it resolves, whoever picked the biggest gainer gets paid out;
# everyone else's stake stays in the bot's economy (a genuine coin sink).
#
# This plugs directly into the Shinobi Market's price engine (_market_get_or_init
# / _market_recalc) added earlier — it doesn't duplicate pricing logic.

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_predictions (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at    INTEGER,
    closes_at     INTEGER,
    status        TEXT DEFAULT 'open',
    candidates    TEXT,
    winner_card_id INTEGER,
    winner_pct    REAL,
    resolved_at   INTEGER
)
""")
conn.commit()

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_prediction_entries (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    round_id      INTEGER,
    user_id       INTEGER,
    card_id       INTEGER,
    entry_amount  INTEGER,
    created_at    INTEGER,
    paid_out      INTEGER DEFAULT 0,
    payout        INTEGER DEFAULT 0
)
""")
conn.commit()

PREDICTION_ROUND_DURATION = 3 * 60 * 60   # 3 hours per round
PREDICTION_CANDIDATE_COUNT = 4
PREDICTION_MIN_ENTRY = 100
PREDICTION_MAX_ENTRY = 100000
PREDICTION_PAYOUT_MULTIPLIER = 3          # correct guess pays 3x stake (2x net profit)


def _prediction_get_open_round():
    cursor.execute("SELECT * FROM shinobi_predictions WHERE status='open' ORDER BY id DESC LIMIT 1")
    return cursor.fetchone()


def _prediction_create_round():
    """Picks PREDICTION_CANDIDATE_COUNT random distinct catalog characters,
    snapshots their current Shinobi Market value, and opens a new round."""
    cursor.execute(
        "SELECT id, name, rarity FROM cards ORDER BY RANDOM() LIMIT ?",
        (PREDICTION_CANDIDATE_COUNT,)
    )
    picks = cursor.fetchall()
    if len(picks) < 2:
        return None  # not enough distinct cards in the catalog yet

    candidates = []
    for card_id, name, rarity in picks:
        _market_get_or_init(card_id)
        start_value = _market_recalc(card_id)
        candidates.append({"card_id": card_id, "name": name, "rarity": rarity, "start_value": start_value})

    now = int(time.time())
    closes_at = now + PREDICTION_ROUND_DURATION
    cursor.execute(
        "INSERT INTO shinobi_predictions (created_at, closes_at, status, candidates) VALUES (?,?,?,?)",
        (now, closes_at, "open", json.dumps(candidates))
    )
    conn.commit()
    return cursor.lastrowid


def _prediction_round_caption(round_row) -> str:
    (rid, created_at, closes_at, status, candidates_json,
     winner_card_id, winner_pct, resolved_at) = round_row
    candidates = json.loads(candidates_json)
    now = int(time.time())
    remaining = max(0, closes_at - now)
    hrs, mins = remaining // 3600, (remaining % 3600) // 60

    lines = [f"🔮 *SHINOBI PREDICTION* — Round `#{rid}`\n", "Which character's market value will rise the most?\n"]
    for c in candidates:
        emoji = RARITY_EMOJI.get(c["rarity"], "⭐")
        lines.append(f"{emoji} *{c['name'].title()}* — `#{c['card_id']}`")
    lines.append(f"\n⏳ Closes in: *{hrs}h {mins}m*")
    lines.append(f"🪙 Entry: {PREDICTION_MIN_ENTRY:,}–{PREDICTION_MAX_ENTRY:,} coins")
    lines.append(f"🏆 Correct guess pays *{PREDICTION_PAYOUT_MULTIPLIER}x* your stake")
    lines.append("\nUsage: `/predict <card_id> <amount>`")
    return "\n".join(lines)


async def predict_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/predict — view the current round, or /predict <card_id> <amount> to enter it."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    round_row = _prediction_get_open_round()
    args = context.args or []

    if not args:
        if not round_row:
            await update.message.reply_text(
                "🔮 *SHINOBI PREDICTIONS*\n\nNo round is open right now — check back soon, a new one opens every few hours.",
                parse_mode="Markdown"
            )
            return
        await update.message.reply_text(_prediction_round_caption(round_row), parse_mode="Markdown")
        return

    if not round_row:
        await update.message.reply_text("❌ No round is open right now. Try `/predict` to check back later.", parse_mode="Markdown")
        return

    if len(args) < 2:
        await update.message.reply_text("❌ Usage: `/predict <card_id> <amount>`", parse_mode="Markdown")
        return

    try:
        card_id_arg = int(args[0])
        amount = int(args[1])
    except ValueError:
        await update.message.reply_text("❌ Card ID and amount must both be numbers.")
        return

    if amount < PREDICTION_MIN_ENTRY or amount > PREDICTION_MAX_ENTRY:
        await update.message.reply_text(
            f"❌ Entry must be between {PREDICTION_MIN_ENTRY:,} and {PREDICTION_MAX_ENTRY:,} coins.",
            parse_mode="Markdown"
        )
        return

    rid = round_row[0]
    candidates = json.loads(round_row[4])
    if not any(c["card_id"] == card_id_arg for c in candidates):
        await update.message.reply_text("❌ That character isn't in the current round. Check `/predict` for the candidates.", parse_mode="Markdown")
        return

    cursor.execute("SELECT id FROM shinobi_prediction_entries WHERE round_id=? AND user_id=?", (rid, user_id))
    if cursor.fetchone():
        await update.message.reply_text("❌ You've already entered this round — one prediction per round.", parse_mode="Markdown")
        return

    if not deduct_coins(user_id, amount):
        await update.message.reply_text(f"❌ You need 🪙{amount:,} coins to enter — check /balance.", parse_mode="Markdown")
        return

    cursor.execute(
        "INSERT INTO shinobi_prediction_entries (round_id, user_id, card_id, entry_amount, created_at) VALUES (?,?,?,?,?)",
        (rid, user_id, card_id_arg, amount, int(time.time()))
    )
    conn.commit()

    picked_name = next(c["name"] for c in candidates if c["card_id"] == card_id_arg)
    await update.message.reply_text(
        f"🔮 *PREDICTION LOCKED IN*\n\n"
        f"You staked 🪙{amount:,} on *{picked_name.title()}*.\n"
        f"If it's the biggest gainer when the round closes, you'll win 🪙{amount*PREDICTION_PAYOUT_MULTIPLIER:,}.",
        parse_mode="Markdown"
    )


async def _prediction_resolve_round(bot, round_row):
    (rid, created_at, closes_at, status, candidates_json,
     _winner_card_id, _winner_pct, _resolved_at) = round_row
    candidates = json.loads(candidates_json)

    best_card_id, best_pct = None, None
    for c in candidates:
        end_value = _market_recalc(c["card_id"])
        start_value = c["start_value"] or 1
        pct = ((end_value - start_value) / start_value) * 100.0
        c["end_value"] = end_value
        c["pct"] = pct
        if best_pct is None or pct > best_pct:
            best_pct = pct
            best_card_id = c["card_id"]

    now = int(time.time())
    cursor.execute(
        "UPDATE shinobi_predictions SET status='resolved', winner_card_id=?, winner_pct=?, resolved_at=?, candidates=? WHERE id=?",
        (best_card_id, best_pct, now, json.dumps(candidates), rid)
    )
    conn.commit()

    winner_name = next(c["name"] for c in candidates if c["card_id"] == best_card_id)

    cursor.execute("SELECT id, user_id, card_id, entry_amount FROM shinobi_prediction_entries WHERE round_id=?", (rid,))
    entries = cursor.fetchall()
    for entry_id, user_id, picked_card_id, entry_amount in entries:
        won = picked_card_id == best_card_id
        payout = entry_amount * PREDICTION_PAYOUT_MULTIPLIER if won else 0
        if payout:
            add_coins(user_id, payout)
        cursor.execute(
            "UPDATE shinobi_prediction_entries SET paid_out=1, payout=? WHERE id=?",
            (payout, entry_id)
        )
        conn.commit()
        try:
            if won:
                text = (
                    f"🔮 *PREDICTION COMPLETE*\n\n"
                    f"🏆 *{winner_name.title()}* was the biggest gainer ({best_pct:+.1f}%)!\n"
                    f"🪙 You staked {entry_amount:,} and won *{payout:,}* coins!"
                )
            else:
                text = (
                    f"🔮 *PREDICTION COMPLETE*\n\n"
                    f"🏆 *{winner_name.title()}* was the biggest gainer ({best_pct:+.1f}%).\n"
                    f"Your pick didn't win this round — better luck next time!"
                )
            await bot.send_message(chat_id=user_id, text=text, parse_mode="Markdown")
        except Exception:
            pass


async def prediction_scheduler(bot):
    """Runs forever. Opens a new prediction round whenever none is active,
    and resolves the open round once its window closes."""
    print("[PREDICTIONS] Scheduler started (60s interval).")
    await asyncio.sleep(40)
    while True:
        try:
            round_row = _prediction_get_open_round()
            now = int(time.time())
            if round_row and round_row[2] <= now:
                await _prediction_resolve_round(bot, round_row)
                round_row = None
            if not round_row:
                _prediction_create_round()
        except Exception as e:
            print(f"[PREDICTIONS] Scheduler error: {e}")
        await asyncio.sleep(60)


# ═══════════════════════════════════════════════════════════════════
#     📜 SHINOBI CONTRACTS — riskier, longer-term coin investment
# ═══════════════════════════════════════════════════════════════════
# Unlike Expeditions (short, mostly-safe, coin reward for free), a Contract
# costs coins up front and matures in 24 hours. The payout tier
# (Failure / Normal / Success / Critical) is randomly rolled at claim time
# against a flat probability table, so it stays a real gamble.
# FIX (Issue 7): contracts previously also required owning a character and
# freezing it as collateral for the duration — that requirement is removed.
# No card is needed or touched; it's purely a coins-in, coins-out gamble.

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_contracts (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id      INTEGER,
    card_row_id  INTEGER,
    card_id      INTEGER,
    card_name    TEXT,
    rarity       TEXT,
    cost         INTEGER,
    started_at   INTEGER,
    ends_at      INTEGER,
    status       TEXT DEFAULT 'active',
    tier         TEXT,
    payout       INTEGER,
    notified     INTEGER DEFAULT 0
)
""")
conn.commit()

CONTRACT_DURATION_SECONDS = 24 * 60 * 60  # 24 hours
CONTRACT_MIN_COST = 500
CONTRACT_MAX_COST = 200000

# Outcome payout = cost * multiplier
CONTRACT_MULTIPLIERS = {
    "fail": 0.7,
    "normal": 1.1,
    "success": 1.75,
    "critical": 2.5,
}

# Probability of each outcome tier, per rarity (must sum to 1.0 per rarity).
# Higher rarity → better odds at the top tiers, but Failure is never impossible.
CONTRACT_PROBS = {
    "Common":      {"fail": 0.30, "normal": 0.45, "success": 0.20, "critical": 0.05},
    "Rare":        {"fail": 0.26, "normal": 0.42, "success": 0.24, "critical": 0.08},
    "Epic":        {"fail": 0.22, "normal": 0.38, "success": 0.30, "critical": 0.10},
    "Legendary":   {"fail": 0.18, "normal": 0.34, "success": 0.35, "critical": 0.13},
    "Mythic":      {"fail": 0.15, "normal": 0.30, "success": 0.38, "critical": 0.17},
    "Spring":      {"fail": 0.24, "normal": 0.41, "success": 0.26, "critical": 0.09},
    "Summer":      {"fail": 0.24, "normal": 0.41, "success": 0.26, "critical": 0.09},
    "Academy":     {"fail": 0.32, "normal": 0.46, "success": 0.18, "critical": 0.04},
    "FIFA":        {"fail": 0.25, "normal": 0.42, "success": 0.25, "critical": 0.08},
    "Crossverse":  {"fail": 0.20, "normal": 0.36, "success": 0.32, "critical": 0.12},
    "Animation":   {"fail": 0.16, "normal": 0.31, "success": 0.37, "critical": 0.16},
    "LeaderBoard": {"fail": 0.14, "normal": 0.28, "success": 0.40, "critical": 0.18},
    "Premium":     {"fail": 0.12, "normal": 0.26, "success": 0.42, "critical": 0.20},
    "Special":     {"fail": 0.20, "normal": 0.36, "success": 0.32, "critical": 0.12},
    "Mermaid":     {"fail": 0.23, "normal": 0.40, "success": 0.27, "critical": 0.10},
    "Tradition":   {"fail": 0.23, "normal": 0.40, "success": 0.27, "critical": 0.10},
}
CONTRACT_DEFAULT_PROBS = {"fail": 0.28, "normal": 0.44, "success": 0.22, "critical": 0.06}

CONTRACT_TIER_LABEL = {
    "fail": "💀 Failure",
    "normal": "➖ Normal",
    "success": "🔥 Success",
    "critical": "⭐ Critical",
}


def _contract_roll_tier(rarity: str) -> str:
    probs = CONTRACT_PROBS.get(rarity, CONTRACT_DEFAULT_PROBS)
    r = random.random()
    cumulative = 0.0
    for tier in ("fail", "normal", "success", "critical"):
        cumulative += probs[tier]
        if r <= cumulative:
            return tier
    return "normal"  # float rounding fallback


async def contract_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/contract — view your active contracts, or /contract <card_id> <cost> to start one."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    args = context.args or []
    now = int(time.time())

    if not args:
        cursor.execute(
            "SELECT id, card_name, rarity, cost, ends_at FROM shinobi_contracts "
            "WHERE user_id=? AND status='active' ORDER BY ends_at ASC",
            (user_id,)
        )
        rows = cursor.fetchall()
        if not rows:
            await update.message.reply_text(
                "📜 *SHINOBI CONTRACTS*\n\n"
                "You have no active contracts.\n\n"
                "Usage: `/contract <cost>`\n"
                f"Cost must be {CONTRACT_MIN_COST:,}–{CONTRACT_MAX_COST:,} coins. Runs 24 hours.\n"
                f"Payout tiers: 💀 {CONTRACT_MULTIPLIERS['fail']}x · ➖ {CONTRACT_MULTIPLIERS['normal']}x · "
                f"🔥 {CONTRACT_MULTIPLIERS['success']}x · ⭐ {CONTRACT_MULTIPLIERS['critical']}x",
                parse_mode="Markdown"
            )
            return

        lines = ["📜 *YOUR CONTRACTS*\n"]
        keyboard_rows = []
        for cid, name, rarity, cost, ends_at in rows:
            remaining = ends_at - now
            if remaining <= 0:
                lines.append(f"🪙 Contract `#{cid}` ({cost:,} coins) — ✅ Ready to resolve!")
                keyboard_rows.append([InlineKeyboardButton(f"📜 Resolve #{cid}", callback_data=f"con_claim_{cid}")])
            else:
                hrs, mins = remaining // 3600, (remaining % 3600) // 60
                lines.append(f"🪙 Contract `#{cid}` ({cost:,} coins) — ⏳ {hrs}h {mins}m left")
        keyboard = InlineKeyboardMarkup(keyboard_rows) if keyboard_rows else None
        await update.message.reply_text("\n".join(lines), parse_mode="Markdown", reply_markup=keyboard)
        return

    # FIX (Issue 7): Contracts no longer require owning/freezing a character
    # card as collateral. Just pay coins up front — usage is now
    # `/contract <cost>` (previously `/contract <card_id> <cost>`).
    try:
        cost = int(args[0])
    except ValueError:
        await update.message.reply_text("❌ Usage: `/contract <cost>` — cost must be a number.", parse_mode="Markdown")
        return

    if cost < CONTRACT_MIN_COST or cost > CONTRACT_MAX_COST:
        await update.message.reply_text(
            f"❌ Cost must be between {CONTRACT_MIN_COST:,} and {CONTRACT_MAX_COST:,} coins.",
            parse_mode="Markdown"
        )
        return

    if not deduct_coins(user_id, cost):
        await update.message.reply_text(f"❌ You need 🪙{cost:,} coins to fund this contract — check /balance.", parse_mode="Markdown")
        return

    now = int(time.time())
    ends_at = now + CONTRACT_DURATION_SECONDS
    cursor.execute(
        "INSERT INTO shinobi_contracts (user_id, card_row_id, card_id, card_name, rarity, cost, started_at, ends_at, status) "
        "VALUES (?,NULL,NULL,NULL,NULL,?,?,?, 'active')",
        (user_id, cost, now, ends_at)
    )
    conn.commit()
    cid = cursor.lastrowid

    await update.message.reply_text(
        f"📜 *CONTRACT SIGNED*\n\n"
        f"🪙 Cost: *{cost:,}* coins\n"
        f"⏳ Matures in 24 hours — no card needed as collateral.\n"
        f"🎲 Possible payout: 💀{int(cost*0.7):,} · ➖{int(cost*1.1):,} · 🔥{int(cost*1.75):,} · ⭐{int(cost*2.5):,}\n"
        f"🔢 Contract ID: `#{cid}`\n\n"
        f"Use `/contract` anytime to check on it.",
        parse_mode="Markdown"
    )


async def contract_claim_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles con_claim_<contract_id> button taps."""
    query = update.callback_query
    if not query or not query.data:
        return
    user_id = query.from_user.id

    if is_banned(user_id):
        await query.answer("🚫 You're banned from using this bot.", show_alert=True)
        return

    try:
        cid = int(query.data.rsplit("_", 1)[1])
    except Exception:
        await query.answer("❌ Malformed contract button.", show_alert=True)
        return

    cursor.execute(
        "SELECT id, user_id, card_name, rarity, cost, ends_at, status FROM shinobi_contracts WHERE id=?",
        (cid,)
    )
    row = cursor.fetchone()
    if not row:
        await query.answer("❌ This contract no longer exists.", show_alert=True)
        return
    _id, owner_id, card_name, rarity, cost, ends_at, status = row

    if owner_id != user_id:
        await query.answer("❌ This isn't your contract.", show_alert=True)
        return
    if status != "active":
        await query.answer("✅ Already resolved.", show_alert=True)
        return
    now = int(time.time())
    if ends_at > now:
        remaining = ends_at - now
        hrs, mins = remaining // 3600, (remaining % 3600) // 60
        await query.answer(f"⏳ Not ready yet — {hrs}h {mins}m left.", show_alert=True)
        return

    # No card/rarity is attached anymore (Issue 7 fix), so every contract
    # rolls against the flat default odds instead of a rarity-weighted table.
    tier = _contract_roll_tier(rarity)
    payout = int(cost * CONTRACT_MULTIPLIERS[tier])
    add_coins(user_id, payout)
    cursor.execute(
        "UPDATE shinobi_contracts SET status='claimed', tier=?, payout=? WHERE id=?",
        (tier, payout, cid)
    )
    conn.commit()

    net = payout - cost
    result_text = (
        f"📜 *CONTRACT RESOLVED*\n\n"
        f"🪙 Contract `#{cid}` ({cost:,} coins)\n"
        f"Outcome: {CONTRACT_TIER_LABEL[tier]}\n"
        f"🪙 Payout: *{payout:,}* coins ({'+' if net>=0 else ''}{net:,} net)"
    )
    await query.answer("📜 Resolved!")
    try:
        await query.edit_message_text(result_text, parse_mode="Markdown")
    except Exception:
        try:
            await context.bot.send_message(chat_id=user_id, text=result_text, parse_mode="Markdown")
        except Exception:
            pass


async def contract_notify_scheduler(bot):
    """Runs forever. Every 60s, auto-resolves every contract that has matured.

    BUG FIX (cards stuck in contracts): this used to only *notify* the user
    once (`notified=0 → 1`) and leave the contract sitting in status='active'
    until the user came back and tapped the "Resolve" button themselves. But
    a contract's card stays locked (see is_card_frozen()) for as long as its
    status is 'active' — and since the query only ever looked at rows with
    notified=0, a contract that had already sent its one notification was
    never checked again. Any user who missed/ignored/dismissed that single
    DM (or started a legacy contract with a card attached before contracts
    stopped requiring collateral) had their contract — and their card —
    stuck in limbo forever, with no automatic way out.
    Now the scheduler settles (claims) every matured contract itself: it
    rolls the outcome, pays out coins, flips status to 'claimed' (which
    immediately frees any locked card, since is_card_frozen only counts
    status='active' rows), and DMs the user the result. This fixes both new
    contracts going forward AND any already-stuck legacy contracts sitting
    in the database, since they'll all match `status='active' AND ends_at<=now`
    on the very next pass.
    """
    print("[CONTRACTS] Auto-resolve scheduler started (60s interval).")
    await asyncio.sleep(35)
    while True:
        try:
            now = int(time.time())
            cursor.execute(
                "SELECT id, user_id, card_name, rarity, cost, card_row_id FROM shinobi_contracts "
                "WHERE status='active' AND ends_at<=?",
                (now,)
            )
            due = cursor.fetchall()
            for cid, user_id, card_name, rarity, cost, card_row_id in due:
                try:
                    tier = _contract_roll_tier(rarity)
                    payout = int(cost * CONTRACT_MULTIPLIERS[tier])
                    add_coins(user_id, payout)
                    cursor.execute(
                        "UPDATE shinobi_contracts SET status='claimed', tier=?, payout=?, notified=1 WHERE id=?",
                        (tier, payout, cid)
                    )
                    conn.commit()
                except Exception as e:
                    print(f"[CONTRACTS] Failed to auto-resolve #{cid}: {e}")
                    continue

                net = payout - cost
                # Legacy contracts (created before the Issue 7 fix) locked a
                # card as collateral — let those users know it's freed now.
                card_note = (
                    f"\n🔓 Your *{card_name}* card has been unlocked and returned "
                    f"to your collection."
                ) if card_row_id else ""
                try:
                    await bot.send_message(
                        chat_id=user_id,
                        text=(
                            f"📜 *Contract Auto-Resolved!*\n\n"
                            f"🪙 Contract `#{cid}` ({cost:,} coins) has matured.\n"
                            f"Outcome: {CONTRACT_TIER_LABEL[tier]}\n"
                            f"🪙 Payout: *{payout:,}* coins ({'+' if net>=0 else ''}{net:,} net){card_note}"
                        ),
                        parse_mode="Markdown"
                    )
                except Exception:
                    pass
        except Exception as e:
            print(f"[CONTRACTS] Scheduler error: {e}")
        await asyncio.sleep(60)


