def _card_matches_event(card_id: int, filter_type: str, filter_value: str) -> bool:
    cursor.execute("SELECT name, rarity, COALESCE(series,'Naruto') FROM cards WHERE id=?", (card_id,))
    row = cursor.fetchone()
    if not row:
        return False
    name, rarity, series = row
    if filter_type == "all":
        return True
    if filter_type == "name_contains":
        return filter_value.lower() in (name or "").lower()
    if filter_type == "series":
        return (series or "").lower() == filter_value.lower()
    if filter_type == "rarity":
        return (rarity or "").lower() == filter_value.lower()
    return False


def _active_world_events():
    now = int(time.time())
    cursor.execute("SELECT id FROM shinobi_world_events WHERE status='active' AND ends_at<=?", (now,))
    expired = [r[0] for r in cursor.fetchall()]
    for eid in expired:
        cursor.execute("UPDATE shinobi_world_events SET status='ended' WHERE id=?", (eid,))
    if expired:
        conn.commit()
    cursor.execute("SELECT * FROM shinobi_world_events WHERE status='active' AND ends_at>?", (now,))
    return cursor.fetchall()


def _expedition_event_multiplier(card_id: int) -> float:
    mult = 1.0
    for ev in _active_world_events():
        (_id, _name, _desc, filter_type, filter_value, _market_mult, expedition_mult,
         _started_at, _ends_at, _status) = ev
        if _card_matches_event(card_id, filter_type, filter_value):
            mult *= expedition_mult
    return mult


def _apply_market_event_modifiers():
    """Recomputes event_modifier on every tracked Shinobi Market row based on
    currently active world events. Cards matching no active event fall back to 1.0."""
    events = _active_world_events()
    cursor.execute("SELECT card_id FROM shinobi_market_values")
    tracked = [r[0] for r in cursor.fetchall()]
    for card_id in tracked:
        mult = 1.0
        for ev in events:
            (_id, _name, _desc, filter_type, filter_value, market_mult, _expedition_mult,
             _started_at, _ends_at, _status) = ev
            if _card_matches_event(card_id, filter_type, filter_value):
                mult *= market_mult
        cursor.execute("UPDATE shinobi_market_values SET event_modifier=? WHERE card_id=?", (mult, card_id))
    conn.commit()


async def events_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/events — see currently active world events."""
    if not update.effective_user or not update.message:
        return
    active = _active_world_events()
    if not active:
        await update.message.reply_text(
            "🌎 *SHINOBI WORLD EVENTS*\n\nNo event is active right now. Check back soon!",
            parse_mode="Markdown"
        )
        return
    now = int(time.time())
    lines = ["🌎 *ACTIVE WORLD EVENTS*\n"]
    for ev in active:
        (eid, name, desc, filter_type, filter_value, market_mult, expedition_mult,
         started_at, ends_at, status) = ev
        remaining = ends_at - now
        hrs, mins = remaining // 3600, (remaining % 3600) // 60
        lines.append(
            f"{name}\n_{desc}_\n"
            f"📊 Market: x{market_mult:.2f} · 🗺️ Expeditions: x{expedition_mult:.2f}\n"
            f"⏳ Ends in {hrs}h {mins}m — `#{eid}`\n"
        )
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def startevent_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/startevent <preset_code> [hours] — OWNER ONLY. Launches a preset world event."""
    if not update.effective_user or not update.message:
        return
    if not _is_owner(update.effective_user.id) and not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 This command is for admins/owner only.")
        return

    args = context.args or []
    if not args:
        preset_list = "\n".join(f"• `{code}` — {p['name']}" for code, p in EVENT_PRESETS.items())
        await update.message.reply_text(
            f"🌎 *START A WORLD EVENT*\n\nUsage: `/startevent <code> [hours]`\n\n{preset_list}",
            parse_mode="Markdown"
        )
        return

    code = args[0].lower()
    preset = EVENT_PRESETS.get(code)
    if not preset:
        await update.message.reply_text(f"❌ Unknown event code `{code}`. Use `/startevent` with no args to see the list.", parse_mode="Markdown")
        return

    try:
        hours = float(args[1]) if len(args) > 1 else preset["default_hours"]
    except ValueError:
        await update.message.reply_text("❌ Hours must be a number.")
        return

    now = int(time.time())
    ends_at = now + int(hours * 3600)
    cursor.execute(
        "INSERT INTO shinobi_world_events (name, description, filter_type, filter_value, market_mult, "
        "expedition_mult, started_at, ends_at, status) VALUES (?,?,?,?,?,?,?,?, 'active')",
        (preset["name"], preset["desc"], preset["filter_type"], preset["filter_value"],
         preset["market_mult"], preset["expedition_mult"], now, ends_at)
    )
    conn.commit()
    _apply_market_event_modifiers()
    await update.message.reply_text(
        f"✅ *{preset['name']}* is now active for *{hours:g}h*!\n_{preset['desc']}_",
        parse_mode="Markdown"
    )


async def endevent_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/endevent <event_id> — OWNER ONLY. Ends an active event early."""
    if not update.effective_user or not update.message:
        return
    if not _is_owner(update.effective_user.id) and not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 This command is for admins/owner only.")
        return
    args = context.args or []
    if not args:
        await update.message.reply_text("Usage: `/endevent <event_id>`", parse_mode="Markdown")
        return
    try:
        eid = int(args[0])
    except ValueError:
        await update.message.reply_text("❌ Event ID must be a number.")
        return
    cursor.execute("UPDATE shinobi_world_events SET status='ended', ends_at=? WHERE id=? AND status='active'", (int(time.time()), eid))
    conn.commit()
    _apply_market_event_modifiers()
    await update.message.reply_text(f"✅ Event `#{eid}` ended.", parse_mode="Markdown")


async def world_event_scheduler(bot):
    """Runs forever. Every 5 minutes, expires stale events and reapplies
    market event modifiers to reflect whatever's currently active."""
    print("[WORLD EVENTS] Scheduler started (300s interval).")
    await asyncio.sleep(45)
    while True:
        try:
            _apply_market_event_modifiers()
        except Exception as e:
            print(f"[WORLD EVENTS] Scheduler error: {e}")
        await asyncio.sleep(300)


# ═══════════════════════════════════════════════════════════════════
#     🏘️ SHINOBI VILLAGE — pick a village, donate coins, level it up
# ═══════════════════════════════════════════════════════════════════
# Users join one of five villages and contribute coins to its shared
# treasury. Every VILLAGE_LEVEL_THRESHOLD coins donated levels the village
# up, which grants all of its members a permanent % bonus to their
# Expedition coin rewards (applied in expedition_claim_callback).

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_villages (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    name       TEXT UNIQUE,
    emoji      TEXT,
    treasury   INTEGER DEFAULT 0
)
""")
conn.commit()

cursor.execute("""
CREATE TABLE IF NOT EXISTS shinobi_village_members (
    user_id    INTEGER PRIMARY KEY,
    village_id INTEGER,
    joined_at  INTEGER
)
""")
conn.commit()

VILLAGE_LEVEL_THRESHOLD = 250000   # coins of cumulative treasury per level
VILLAGE_MAX_BONUS_PCT = 50         # cap on expedition reward bonus

VILLAGE_SEEDS = [
    ("Hidden Leaf", "🍃"),
    ("Hidden Sand", "🌪️"),
    ("Hidden Mist", "🌫️"),
    ("Hidden Cloud", "⚡"),
    ("Hidden Stone", "🪨"),
]
for _vname, _vemoji in VILLAGE_SEEDS:
    cursor.execute("INSERT OR IGNORE INTO shinobi_villages (name, emoji, treasury) VALUES (?,?,0)", (_vname, _vemoji))
conn.commit()


def _village_level(treasury: int) -> int:
    return 1 + (treasury // VILLAGE_LEVEL_THRESHOLD)


def _village_bonus_pct(treasury: int) -> int:
    return min(VILLAGE_MAX_BONUS_PCT, (_village_level(treasury) - 1) * 5)


def _user_village(user_id: int):
    """Returns (village_id, name, emoji, treasury) or None if the user hasn't joined one."""
    cursor.execute(
        "SELECT v.id, v.name, v.emoji, v.treasury FROM shinobi_village_members m "
        "JOIN shinobi_villages v ON v.id = m.village_id WHERE m.user_id=?",
        (user_id,)
    )
    return cursor.fetchone()


def _village_expedition_multiplier(user_id: int) -> float:
    village = _user_village(user_id)
    if not village:
        return 1.0
    _vid, _name, _emoji, treasury = village
    return 1.0 + (_village_bonus_pct(treasury) / 100.0)


async def village_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/village — status + village list, /village join <name>, /village donate <amount>."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    args = context.args or []

    if not args:
        cursor.execute("SELECT id, name, emoji, treasury FROM shinobi_villages ORDER BY treasury DESC")
        villages = cursor.fetchall()
        my_village = _user_village(user_id)
        my_village_id = my_village[0] if my_village else None

        lines = ["🏘️ *SHINOBI VILLAGES*\n"]
        if my_village:
            vid, vname, vemoji, vtreasury = my_village
            level = _village_level(vtreasury)
            bonus = _village_bonus_pct(vtreasury)
            progress = vtreasury % VILLAGE_LEVEL_THRESHOLD
            lines.append(
                f"{vemoji} Your village: *{vname}* — Level *{level}*\n"
                f"💰 Treasury: {vtreasury:,} ({progress:,}/{VILLAGE_LEVEL_THRESHOLD:,} to next level)\n"
                f"🎁 Your expedition reward bonus: *+{bonus}%*\n"
            )
        else:
            lines.append("You haven't joined a village yet — tap one below!\n")

        lines.append("*All villages:*")
        for vid, vname, vemoji, vtreasury in villages:
            level = _village_level(vtreasury)
            tag = " ✅ (yours)" if vid == my_village_id else ""
            lines.append(f"{vemoji} {vname} — Level {level} — 💰{vtreasury:,}{tag}")
        lines.append("\nTap a village below to join it, or use a quick-donate button.")

        keyboard_rows = []
        row = []
        for vid, vname, vemoji, vtreasury in villages:
            label = f"{vemoji} {vname}" + (" ✅" if vid == my_village_id else "")
            row.append(InlineKeyboardButton(label, callback_data=f"vjoin_{vid}"))
            if len(row) == 2:
                keyboard_rows.append(row)
                row = []
        if row:
            keyboard_rows.append(row)

        if my_village_id:
            keyboard_rows.append([
                InlineKeyboardButton("💰 Donate 500", callback_data="vdonate_500"),
                InlineKeyboardButton("💰 1,000", callback_data="vdonate_1000"),
            ])
            keyboard_rows.append([
                InlineKeyboardButton("💰 5,000", callback_data="vdonate_5000"),
                InlineKeyboardButton("💰 10,000", callback_data="vdonate_10000"),
            ])

        await update.message.reply_text("\n".join(lines), parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(keyboard_rows))
        return

    sub = args[0].lower()

    if sub == "join":
        if len(args) < 2:
            await update.message.reply_text("Usage: `/village join <name>` (e.g. `/village join leaf`)", parse_mode="Markdown")
            return
        query_name = " ".join(args[1:]).lower()
        cursor.execute("SELECT id, name, emoji FROM shinobi_villages")
        villages = cursor.fetchall()
        match = None
        for vid, vname, vemoji in villages:
            if query_name in vname.lower():
                match = (vid, vname, vemoji)
                break
        if not match:
            names = ", ".join(v[1] for v in villages)
            await update.message.reply_text(f"❌ No village matches `{query_name}`. Choose from: {names}", parse_mode="Markdown")
            return
        vid, vname, vemoji = match
        cursor.execute(
            "INSERT INTO shinobi_village_members (user_id, village_id, joined_at) VALUES (?,?,?) "
            "ON CONFLICT(user_id) DO UPDATE SET village_id=excluded.village_id, joined_at=excluded.joined_at",
            (user_id, vid, int(time.time()))
        )
        conn.commit()
        await update.message.reply_text(f"✅ You've joined *{vemoji} {vname}*!", parse_mode="Markdown")
        return

    if sub == "donate":
        if len(args) < 2:
            await update.message.reply_text("Usage: `/village donate <amount>`", parse_mode="Markdown")
            return
        my_village = _user_village(user_id)
        if not my_village:
            await update.message.reply_text("❌ Join a village first with `/village join <name>`.", parse_mode="Markdown")
            return
        try:
            amount = int(args[1])
        except ValueError:
            await update.message.reply_text("❌ Amount must be a number.")
            return
        if amount <= 0:
            await update.message.reply_text("❌ Amount must be greater than 0.")
            return
        if not deduct_coins(user_id, amount):
            await update.message.reply_text(f"❌ You don't have 🪙{amount:,} coins — check /balance.", parse_mode="Markdown")
            return

        vid, vname, vemoji, old_treasury = my_village
        old_level = _village_level(old_treasury)
        new_treasury = old_treasury + amount
        cursor.execute("UPDATE shinobi_villages SET treasury=treasury+? WHERE id=?", (amount, vid))
        conn.commit()
        new_level = _village_level(new_treasury)

        text = f"✅ Donated 🪙{amount:,} to *{vemoji} {vname}*!\n💰 Treasury: {new_treasury:,}"
        if new_level > old_level:
            new_bonus = _village_bonus_pct(new_treasury)
            text += f"\n\n🎉 *{vname} reached Level {new_level}!*\nAll members now get *+{new_bonus}%* expedition rewards!"
        await update.message.reply_text(text, parse_mode="Markdown")
        return

    await update.message.reply_text("Usage: `/village`, `/village join <name>`, or `/village donate <amount>`", parse_mode="Markdown")


async def village_button_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles vjoin_<village_id> and vdonate_<amount> button taps from /village."""
    query = update.callback_query
    if not query or not query.data:
        return
    user_id = query.from_user.id

    if is_banned(user_id):
        await query.answer("🚫 You're banned from using this bot.", show_alert=True)
        return

    data = query.data

    if data.startswith("vjoin_"):
        try:
            vid = int(data.split("_", 1)[1])
        except Exception:
            await query.answer("❌ Malformed button.", show_alert=True)
            return
        cursor.execute("SELECT id, name, emoji FROM shinobi_villages WHERE id=?", (vid,))
        row = cursor.fetchone()
        if not row:
            await query.answer("❌ That village no longer exists.", show_alert=True)
            return
        _vid, vname, vemoji = row
        cursor.execute(
            "INSERT INTO shinobi_village_members (user_id, village_id, joined_at) VALUES (?,?,?) "
            "ON CONFLICT(user_id) DO UPDATE SET village_id=excluded.village_id, joined_at=excluded.joined_at",
            (user_id, vid, int(time.time()))
        )
        conn.commit()
        await query.answer(f"✅ Joined {vname}!", show_alert=True)

    elif data.startswith("vdonate_"):
        try:
            amount = int(data.split("_", 1)[1])
        except Exception:
            await query.answer("❌ Malformed button.", show_alert=True)
            return
        my_village = _user_village(user_id)
        if not my_village:
            await query.answer("❌ Join a village first!", show_alert=True)
            return
        if not deduct_coins(user_id, amount):
            await query.answer(f"❌ You don't have 🪙{amount:,} coins.", show_alert=True)
            return
        vid, vname, vemoji, old_treasury = my_village
        old_level = _village_level(old_treasury)
        new_treasury = old_treasury + amount
        cursor.execute("UPDATE shinobi_villages SET treasury=treasury+? WHERE id=?", (amount, vid))
        conn.commit()
        new_level = _village_level(new_treasury)
        alert = f"✅ Donated 🪙{amount:,} to {vname}!"
        if new_level > old_level:
            alert += f" 🎉 Level {new_level}!"
        await query.answer(alert, show_alert=True)

    else:
        await query.answer()
        return

    # Refresh the dashboard in place so the user sees the updated state.
    cursor.execute("SELECT id, name, emoji, treasury FROM shinobi_villages ORDER BY treasury DESC")
    villages = cursor.fetchall()
    my_village = _user_village(user_id)
    my_village_id = my_village[0] if my_village else None

    lines = ["🏘️ *SHINOBI VILLAGES*\n"]
    if my_village:
        vid, vname, vemoji, vtreasury = my_village
        level = _village_level(vtreasury)
        bonus = _village_bonus_pct(vtreasury)
        progress = vtreasury % VILLAGE_LEVEL_THRESHOLD
        lines.append(
            f"{vemoji} Your village: *{vname}* — Level *{level}*\n"
            f"💰 Treasury: {vtreasury:,} ({progress:,}/{VILLAGE_LEVEL_THRESHOLD:,} to next level)\n"
            f"🎁 Your expedition reward bonus: *+{bonus}%*\n"
        )
    else:
        lines.append("You haven't joined a village yet — tap one below!\n")

    lines.append("*All villages:*")
    for vid, vname, vemoji, vtreasury in villages:
        level = _village_level(vtreasury)
        tag = " ✅ (yours)" if vid == my_village_id else ""
        lines.append(f"{vemoji} {vname} — Level {level} — 💰{vtreasury:,}{tag}")
    lines.append("\nTap a village below to join it, or use a quick-donate button.")

    keyboard_rows = []
    row = []
    for vid, vname, vemoji, vtreasury in villages:
        label = f"{vemoji} {vname}" + (" ✅" if vid == my_village_id else "")
        row.append(InlineKeyboardButton(label, callback_data=f"vjoin_{vid}"))
        if len(row) == 2:
            keyboard_rows.append(row)
            row = []
    if row:
        keyboard_rows.append(row)
    if my_village_id:
        keyboard_rows.append([
            InlineKeyboardButton("💰 Donate 500", callback_data="vdonate_500"),
            InlineKeyboardButton("💰 1,000", callback_data="vdonate_1000"),
        ])
        keyboard_rows.append([
            InlineKeyboardButton("💰 5,000", callback_data="vdonate_5000"),
            InlineKeyboardButton("💰 10,000", callback_data="vdonate_10000"),
        ])

    try:
        await query.edit_message_text("\n".join(lines), parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(keyboard_rows))
    except Exception:
        pass


# ═══════════════════════════════════════════════════════════════════
#     🏆 SHINOBI RANKINGS — multiple leaderboards for the new systems
# ═══════════════════════════════════════════════════════════════════
# Separate from the bot's existing /top_shinobi_coins etc. This adds
# leaderboards specific to the new economy systems: expeditions completed,
# prediction profit, contract profit, and collection size.

RANKINGS_MEDALS = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]


def _rankings_menu_keyboard():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("💰 Wealthiest", callback_data="rank_wealth"),
         InlineKeyboardButton("💎 Collection Size", callback_data="rank_collection")],
        [InlineKeyboardButton("🗺️ Expedition Master", callback_data="rank_expedition"),
         InlineKeyboardButton("🔮 Market Genius", callback_data="rank_prediction")],
        [InlineKeyboardButton("📜 Contract Baron", callback_data="rank_contract")],
    ])


async def _rankings_render(rank_type: str) -> str:
    if rank_type == "wealth":
        cursor.execute("""
            SELECT sc.user_id, sc.coins, COALESCE(bu.first_name, CAST(sc.user_id AS TEXT)) AS name
            FROM shinobi_coins sc LEFT JOIN bot_users bu ON bu.user_id = sc.user_id
            WHERE sc.coins > 0 ORDER BY sc.coins DESC LIMIT 10
        """)
        rows = cursor.fetchall()
        title = "💰 WEALTHIEST SHINOBI"
        lines = [f"{RANKINGS_MEDALS[i]} *{safe_name(name)}* — 🪙{coins:,}" for i, (uid, coins, name) in enumerate(rows)]

    elif rank_type == "collection":
        cursor.execute("""
            SELECT uc.user_id, COUNT(*) AS n, COALESCE(bu.first_name, CAST(uc.user_id AS TEXT)) AS name
            FROM user_cards uc LEFT JOIN bot_users bu ON bu.user_id = uc.user_id
            GROUP BY uc.user_id ORDER BY n DESC LIMIT 10
        """)
        rows = cursor.fetchall()
        title = "💎 BIGGEST COLLECTIONS"
        lines = [f"{RANKINGS_MEDALS[i]} *{safe_name(name)}* — {n:,} cards" for i, (uid, n, name) in enumerate(rows)]

    elif rank_type == "expedition":
        cursor.execute("""
            SELECT se.user_id, COUNT(*) AS n, COALESCE(bu.first_name, CAST(se.user_id AS TEXT)) AS name
            FROM shinobi_expeditions se LEFT JOIN bot_users bu ON bu.user_id = se.user_id
            WHERE se.status='claimed' GROUP BY se.user_id ORDER BY n DESC LIMIT 10
        """)
        rows = cursor.fetchall()
        title = "🗺️ EXPEDITION MASTERS"
        lines = [f"{RANKINGS_MEDALS[i]} *{safe_name(name)}* — {n:,} completed" for i, (uid, n, name) in enumerate(rows)]

    elif rank_type == "prediction":
        cursor.execute("""
            SELECT pe.user_id, SUM(pe.payout - pe.entry_amount) AS profit,
                   COALESCE(bu.first_name, CAST(pe.user_id AS TEXT)) AS name
            FROM shinobi_prediction_entries pe LEFT JOIN bot_users bu ON bu.user_id = pe.user_id
            WHERE pe.paid_out=1 GROUP BY pe.user_id ORDER BY profit DESC LIMIT 10
        """)
        rows = cursor.fetchall()
        title = "🔮 MARKET GENIUSES (prediction profit)"
        lines = [f"{RANKINGS_MEDALS[i]} *{safe_name(name)}* — {'+' if p>=0 else ''}{p:,} 🪙" for i, (uid, p, name) in enumerate(rows)]

    elif rank_type == "contract":
        cursor.execute("""
            SELECT sc2.user_id, SUM(sc2.payout - sc2.cost) AS profit,
                   COALESCE(bu.first_name, CAST(sc2.user_id AS TEXT)) AS name
            FROM shinobi_contracts sc2 LEFT JOIN bot_users bu ON bu.user_id = sc2.user_id
            WHERE sc2.status='claimed' GROUP BY sc2.user_id ORDER BY profit DESC LIMIT 10
        """)
        rows = cursor.fetchall()
        title = "📜 CONTRACT BARONS (net profit)"
        lines = [f"{RANKINGS_MEDALS[i]} *{safe_name(name)}* — {'+' if p>=0 else ''}{p:,} 🪙" for i, (uid, p, name) in enumerate(rows)]

    else:
        return "❌ Unknown ranking."

    if not lines:
        return f"🏆 *{title}*\n\nNo data yet — be the first!"
    return f"🏆 *{title}*\n\n" + "\n".join(lines)


async def rankings_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/rankings — menu of leaderboards for the new economy systems."""
    if not update.effective_user or not update.message:
        return
    await update.message.reply_text(
        "🏆 *SHINOBI RANKINGS*\n\nPick a leaderboard:",
        parse_mode="Markdown",
        reply_markup=_rankings_menu_keyboard()
    )


async def rankings_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles rank_<type> button taps from the /rankings menu."""
    query = update.callback_query
    if not query or not query.data:
        return
    rank_type = query.data.split("_", 1)[1]
    text = await _rankings_render(rank_type)
    await query.answer()
    try:
        await query.edit_message_text(text, parse_mode="Markdown", reply_markup=_rankings_menu_keyboard())
    except Exception:
        pass



# ═══════════════════════════════════════════════════════════════════
#     🎰 SHINOBI CASINO — mini-games
# ═══════════════════════════════════════════════════════════════════
# 🪙 All betting games now run entirely on Ryo: /bowl /football
# /basketball /multiplier /roulette /mines
# (Bug 8: Dart has been removed completely, and every game listed
# above now shares one combined cap of 30 bets/day per user.)
#
# Bowling, Football and Basketball use Telegram's own animated
# dice (context.bot.send_dice) so the outcome shown to the group is a
# REAL Telegram-rolled result, not a simulated one.

# ── ⏳ Betting cooldown — keeps the tables fast & fair under heavy load ────────
# A lightweight in-memory check (no DB hit) so it costs virtually nothing even
# with many users betting at once. Applies to placing a NEW bet on any game
# (/bet, /bowl, /football, /basketball, /multiplier, /roulette, /mines)
# — it does NOT apply to in-game actions on an already-placed bet (choosing a
# side, firing a roulette chamber, picking a mines cell, cashing out).
BET_COOLDOWN_SECONDS = 5
_last_bet_time = {}   # user_id -> unix timestamp of their last placed bet


def check_bet_cooldown(user_id: int):
    """Returns None if the user may place a bet right now, otherwise a
    ready-to-send warning string with the remaining wait time."""
    now = time.time()
    elapsed = now - _last_bet_time.get(user_id, 0)
    if elapsed < BET_COOLDOWN_SECONDS:
        remaining = BET_COOLDOWN_SECONDS - elapsed
        return (
            f"⏳ *Slow down, shinobi!*\n\n"
            f"You're betting too fast — please wait *{remaining:.1f}s* before your next bet.\n"
            f"🎯 This keeps the tables fast & fair for everyone!"
        )
    return None


