_GAME_BANNER_CACHE = {}

GAME_BANNERS = {
    "bowl":       ("🎳 BOWLING STRIKE",   "Guess the pin count!",        (86, 170, 255)),
    "football":   ("⚽ PENALTY SHOOTOUT", "Goal or no goal?",            (86, 220, 130)),
    "basketball": ("🏀 SLAM DUNK",        "Swish or brick?",             (255, 150, 60)),
    "multiplier": ("🎰 MULTIPLIER",       "Pick your risk, spin big!",   (200, 120, 255)),
    "roulette":   ("🔫 SHINOBI ROULETTE", "6 chambers. How many bullets?", (235, 71, 90)),
    "mines":      ("💣 GEM MINES",        "Clear the field, cash out!",  (56, 209, 120)),
}


def render_game_banner(title: str, subtitle: str, accent: tuple):
    W, H = 900, 300
    img = Image.new("RGB", (W, H), (12, 16, 28))
    draw = ImageDraw.Draw(img, "RGBA")
    for i in range(0, W + H, 24):
        draw.line([(i, 0), (0, i)], fill=(*accent, 16), width=8)
    draw.rectangle([0, H - 8, W, H], fill=accent)
    draw.rectangle([0, 0, 8, H], fill=accent)
    try:
        font_title = ImageFont.truetype("DejaVuSans-Bold.ttf", 50)
        font_sub = ImageFont.truetype("DejaVuSans.ttf", 22)
        font_tag = ImageFont.truetype("DejaVuSans.ttf", 18)
    except Exception:
        try:
            font_title = ImageFont.load_default(size=50)
            font_sub = ImageFont.load_default(size=22)
            font_tag = ImageFont.load_default(size=18)
        except Exception:
            font_title = ImageFont.load_default()
            font_sub = font_title
            font_tag = font_title
    draw.text((48, 36), "NARUTO TCG CARDS  •  SHINOBI CASINO", font=font_tag, fill=accent)
    draw.text((46, 110), title, font=font_title, fill=(255, 255, 255))
    draw.text((50, 178), subtitle, font=font_sub, fill=(195, 200, 212))
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    return buf


def get_game_banner(key: str):
    if not PIL_AVAILABLE:
        return None
    if key not in _GAME_BANNER_CACHE:
        title, subtitle, accent = GAME_BANNERS[key]
        _GAME_BANNER_CACHE[key] = render_game_banner(title, subtitle, accent).getvalue()
    return io.BytesIO(_GAME_BANNER_CACHE[key])


async def _game_send(message, key: str, caption: str, reply_markup=None):
    """Sends the game's banner image with the caption/buttons attached (one message,
    image on top like every other feature). Falls back to plain text if Pillow is
    unavailable."""
    banner = get_game_banner(key)
    if banner:
        return await message.reply_photo(photo=banner, caption=caption, parse_mode="Markdown", reply_markup=reply_markup)
    return await message.reply_text(caption, parse_mode="Markdown", reply_markup=reply_markup)


async def _game_edit(query, caption: str, reply_markup=None):
    try:
        if query.message and query.message.photo:
            await query.edit_message_caption(caption=caption, parse_mode="Markdown", reply_markup=reply_markup)
        else:
            await query.edit_message_text(caption, parse_mode="Markdown", reply_markup=reply_markup)
    except Exception:
        try:
            await query.message.reply_text(caption, parse_mode="Markdown", reply_markup=reply_markup)
        except Exception:
            pass


def _parse_bet_ryo(update, args, min_amount=1):
    """Shared validation for the shinobi-coin dice games. Returns (amount, error_text)."""
    if len(args) < 1:
        return None, "usage"
    try:
        amount = int(args[0])
    except ValueError:
        return None, "❌ Bet amount must be a whole number."
    if amount < min_amount:
        return None, f"❌ Minimum bet is {min_amount:,} Ryo."
    current = get_ryo(update.effective_user.id)
    if current < amount:
        return None, f"😔 Not enough Ryo! You have *{current:,}*, need *{amount:,}*."
    return amount, None


