async def multiplier_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass
    parts = (query.data or "").split("_")
    if len(parts) != 4:
        return
    _, uid_s, amt_s, diff = parts
    uid, amount = int(uid_s), int(amt_s)
    if query.from_user.id != uid:
        await query.answer("❌ This isn't your bet!", show_alert=True)
        return
    if diff not in MULTIPLIER_DIFFICULTIES:
        return

    current = get_ryo(uid)
    if current < amount:
        await _game_edit(query, f"❌ Not enough coins anymore! You have {current:,}, need {amount:,}.")
        return
    deduct_ryo(uid, amount)

    win_chance, cap, label = MULTIPLIER_DIFFICULTIES[diff]
    await _game_edit(query, f"🎰 *MULTIPLIER*\n\n💰 Bet: *{amount:,}* 🪙 — {label}\n\n🎰 Spinning...")
    await asyncio.sleep(2)

    if random.random() < win_chance:
        mult = round(random.uniform(1.0, cap), 2)
    else:
        mult = round(random.uniform(0.0, 1.0), 2)

    payout = round(amount * mult)
    if payout > 0:
        add_ryo(uid, payout)

    if mult >= 1.0:
        result = f"🎉 *{mult}x!* — WIN! +{payout:,} 🪙"
    elif mult > 0:
        result = f"😬 *{mult}x* — small return, {payout:,} 🪙 back (net loss)"
    else:
        result = f"💥 *0.00x* — Total Loss. -{amount:,} 🪙"

    new_bal = get_ryo(uid)
    await _game_edit(
        query,
        f"🎰 *MULTIPLIER*\n\n💰 Bet: *{amount:,}* 🪙 — {label}\n\n{result}\n\n💼 New Balance: *{new_bal:,}* 🪙"
    )
    await log_bet(context.bot, f"🎰 *Multiplier* — bet {amount:,}, diff={diff}, mult={mult}x")


# ═══════════════════ 🔫 ROULETTE — /roulette <bet> <bullets> (Ryo) ═══════════════════

ROULETTE_CAPS = {1: 2.0, 2: 2.5, 3: 3.0, 4: 4.0, 5: 5.0}


def _roulette_keyboard(state):
    row1, row2 = [], []
    for i in range(1, 7):
        if i in state["used"]:
            label = "💥" if i == state.get("bullet_chamber_hit") else "✅"
        else:
            label = f"🔫{i}"
        btn = InlineKeyboardButton(label, callback_data="groul_noop" if i in state["used"] else f"groul_fire_{i}")
        (row1 if i <= 3 else row2).append(btn)
    rows = [row1, row2]
    if not state["game_over"]:
        rows.append([InlineKeyboardButton(f"💰 Cash Out ({state['mult']:.2f}x)", callback_data="groul_payout")])
    return InlineKeyboardMarkup(rows)


