#                       🎁 AIRDROP SYSTEM
# ═══════════════════════════════════════════════════════════════════

cursor.execute("""
CREATE TABLE IF NOT EXISTS airdrop_data (
    user_id          INTEGER PRIMARY KEY,
    last_free        INTEGER DEFAULT 0,   -- epoch of last free box open
    last_ad          INTEGER DEFAULT 0,   -- epoch of last ad box open
    streak           INTEGER DEFAULT 0,   -- consecutive daily opens
    total_opens      INTEGER DEFAULT 0,   -- all-time opens
    last_streak_day  INTEGER DEFAULT 0    -- IST day number of last open (for streak)
)
""")
conn.commit()

# ── Airdrop cooldowns ─────────────────────────────────────────────────────────
AIRDROP_FREE_COOLDOWN = 86400   # 24h  — one free box per day
AIRDROP_AD_COOLDOWN   = 600     # 10min — ad box cooldown
AIRDROP_STREAK_BONUS  = 5       # every 5 opens  → bonus reward
AIRDROP_SPRING_OPEN   = 20      # every 20 opens → guaranteed Spring card

# ── Drop rates ────────────────────────────────────────────────────────────────
AIRDROP_COIN_WEIGHT    = 60
AIRDROP_VOUCHER_WEIGHT = 35
AIRDROP_SPRING_WEIGHT  = 5

def _get_airdrop_row(user_id: int):
    cursor.execute(
        "SELECT last_free, last_ad, streak, total_opens, last_streak_day "
        "FROM airdrop_data WHERE user_id=?", (user_id,)
    )
    row = cursor.fetchone()
    if not row:
        cursor.execute(
            "INSERT OR IGNORE INTO airdrop_data "
            "(user_id, last_free, last_ad, streak, total_opens, last_streak_day) "
            "VALUES (?,0,0,0,0,0)", (user_id,)
        )
        conn.commit()
        return 0, 0, 0, 0, 0
    return row


def _generate_airdrop_reward(user_id: int, total_opens: int):
    """
    Returns (reward_type, value, display_text)
    reward_type: 'coins' | 'voucher' | 'spring'
    """
    # Guaranteed Spring on 20th open (or multiples)
    if total_opens > 0 and total_opens % AIRDROP_SPRING_OPEN == 0:
        cursor.execute(
            "SELECT name, rarity, file_id, COALESCE(file_type,'photo') "
            "FROM cards WHERE rarity='Spring' ORDER BY RANDOM() LIMIT 1"
        )
        card = cursor.fetchone()
        if card:
            return "spring", card, f"🌸 *SPRING CARD: {card[0].title()}!*"
        # fallback to coins if no spring cards
    else:
        roll = random.random() * 100
        if roll < AIRDROP_SPRING_WEIGHT:
            cursor.execute(
                "SELECT name, rarity, file_id, COALESCE(file_type,'photo') "
                "FROM cards WHERE rarity='Spring' ORDER BY RANDOM() LIMIT 1"
            )
            card = cursor.fetchone()
            if card:
                return "spring", card, f"🌸 *SPRING CARD: {card[0].title()}!*"
        if roll < (AIRDROP_SPRING_WEIGHT + AIRDROP_VOUCHER_WEIGHT):
            amount = random.randint(2, 20)
            return "voucher", amount, f"🎟️ *{amount} Draft Vouchers!*"

    # Coins (default)
    amount = random.randint(500, 5000)
    return "coins", amount, f"💰 *{amount:,} Shinobi Coins!*"


async def _announce_spring_drop(bot, user_name: str, card_name: str, chat_id: int):
    """Announce a Spring pull to the group."""
    try:
        await bot.send_message(
            chat_id=AIRDROP_ANNOUNCE_ID,
            text=(
                f"🌍 *GLOBAL AIRDROP DROP!*\n\n"
                f"🔥 *{user_name}* just pulled a\n"
                f"🌸 *SPRING CARD: {card_name.title()}!!*\n\n"
                f"from the 🎁 Airdrop Box!\n\n"
                f"⚔️ Will you be next? Use /airdrop now!"
            ),
            parse_mode="Markdown"
        )
    except Exception:
        pass


async def airdrop_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/airdrop — Open the daily airdrop box."""
    if not update.effective_user or not update.message:
        return
    user_id   = update.effective_user.id
    user_name = update.effective_user.first_name or "Shinobi"

    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    now           = int(time.time())
    last_free, last_ad, streak, total_opens, last_streak_day = _get_airdrop_row(user_id)

    # Work out if free box is available
    free_available = (now - last_free) >= AIRDROP_FREE_COOLDOWN
    ad_available   = (now - last_ad)   >= AIRDROP_AD_COOLDOWN

    # Time until next free box
    if not free_available:
        rem      = AIRDROP_FREE_COOLDOWN - (now - last_free)
        hrs, mn  = rem // 3600, (rem % 3600) // 60
        free_txt = f"⏳ Free box in: *{hrs}h {mn}m*"
    else:
        free_txt = "✅ *Free box available!*"

    if not ad_available:
        rem_ad   = AIRDROP_AD_COOLDOWN - (now - last_ad)
        ad_txt   = f"⏳ Ad box in: *{rem_ad // 60}m {rem_ad % 60}s*"
    else:
        ad_txt   = "📺 *Watch Ad available!*"

    # Streak display
    streak_bar = "🔥" * min(streak, 5)
    next_streak = AIRDROP_STREAK_BONUS - (streak % AIRDROP_STREAK_BONUS) if streak % AIRDROP_STREAK_BONUS != 0 else AIRDROP_STREAK_BONUS

    # Build inline keyboard
    buttons = []
    if free_available:
        buttons.append(InlineKeyboardButton("🎁 Open Free Box", callback_data="airdrop_free"))
    if ad_available:
        # Opens the Mini App WebApp (real AdsGram ad inside)
        buttons.append(InlineKeyboardButton(
            "📺 Watch Ad & Open",
            web_app=WebAppInfo(url=WEBAPP_URL)
        ))

    if not buttons:
        await update.message.reply_text(
            f"🎁 *AIRDROP BOX*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"😴 *All boxes on cooldown!*\n\n"
            f"{free_txt}\n"
            f"{ad_txt}\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"🔥 Streak: *{streak}* opens {streak_bar}\n"
            f"📦 Total opened: *{total_opens}*\n\n"
            f"Come back soon, shinobi! 🥷",
            parse_mode="Markdown"
        )
        return

    keyboard = InlineKeyboardMarkup([buttons])

    await update.message.reply_text(
        f"🎁 *SHINOBI AIRDROP BOX!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"✨ Mystery rewards await inside!\n\n"
        f"🪙 *Coins* — 60% chance (500–5,000)\n"
        f"🎟️ *Draft Vouchers* — 35% chance (2–20)\n"
        f"🌸 *Spring Card* — 5% chance\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"{free_txt}\n"
        f"{ad_txt}\n\n"
        f"🔥 Streak: *{streak}* {streak_bar}\n"
        f"⚡ *{next_streak} more* opens for streak bonus!\n"
        f"🌸 *{AIRDROP_SPRING_OPEN - (total_opens % AIRDROP_SPRING_OPEN)}* opens until guaranteed Spring!\n\n"
        f"👇 *Tap to open your box!*",
        parse_mode="Markdown",
        reply_markup=keyboard
    )


async def airdrop_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Free Box and Watch Ad & Open buttons."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass

    user_id   = query.from_user.id
    user_name = query.from_user.first_name or "Shinobi"
    data      = query.data
    now       = int(time.time())

    if not has_started_bot(user_id):
        await query.answer("❌ Please /start the bot first!", show_alert=True)
        return

    last_free, last_ad, streak, total_opens, last_streak_day = _get_airdrop_row(user_id)

    if data == "airdrop_free":
        if (now - last_free) < AIRDROP_FREE_COOLDOWN:
            rem     = AIRDROP_FREE_COOLDOWN - (now - last_free)
            hrs, mn = rem // 3600, (rem % 3600) // 60
            await query.answer(f"⏳ Free box resets in {hrs}h {mn}m!", show_alert=True)
            return
        box_type   = "free"
        last_free  = now

    elif data == "airdrop_ad":
        if (now - last_ad) < AIRDROP_AD_COOLDOWN:
            rem_ad = AIRDROP_AD_COOLDOWN - (now - last_ad)
            await query.answer(f"⏳ Ad box resets in {rem_ad // 60}m {rem_ad % 60}s!", show_alert=True)
            return
        # AdsGram — fire verification and proceed
        # (AdsGram webhook validates the token server-side; here we optimistically
        #  grant reward after the user taps "Watch Ad"; server callback at /adsgram_callback
        #  can be used for extra validation)
        box_type = "ad"
        last_ad  = now

    else:
        return

    # ── Update streak ─────────────────────────────────────────────────────────
    now_ist         = now + IST_OFFSET_SEC
    today_ist_day   = now_ist // 86400
    if today_ist_day == last_streak_day + 1:
        streak += 1          # consecutive day
    elif today_ist_day > last_streak_day + 1:
        streak = 1           # streak broken, reset to 1
    # same day → don't change streak

    total_opens += 1

    # ── Generate reward ───────────────────────────────────────────────────────
    reward_type, reward_value, reward_text = _generate_airdrop_reward(user_id, total_opens)

    # ── Apply reward ──────────────────────────────────────────────────────────
    streak_bonus_msg = ""
    if total_opens % AIRDROP_STREAK_BONUS == 0:
        # Streak milestone bonus: +500 coins
        add_coins(user_id, 500)
        streak_bonus_msg = f"\n\n🎊 *STREAK BONUS!* +500 coins for opening *{total_opens}* boxes!"

    if reward_type == "coins":
        add_coins(user_id, reward_value)
        new_bal = get_coins(user_id)
        result_detail = f"💰 *+{reward_value:,} Shinobi Coins!*\n💼 Balance: *{new_bal:,}*"

    elif reward_type == "voucher":
        add_vouchers(user_id, reward_value)
        new_v = get_user_vouchers(user_id)
        result_detail = f"🎟️ *+{reward_value} Draft Vouchers!*\n💼 Total: *{new_v}*"

    elif reward_type == "spring":
        cname, crarity, cfile, cfile_type = reward_value
        insert_user_card(user_id, cname, crarity, cfile)
        result_detail = f"🌸 *SPRING CARD!*\n🥷 {cname.title()}\n{RARITY_EMOJI.get(crarity,'🌸')} {crarity}"
        # Global announcement
        await _announce_spring_drop(context.bot, user_name, cname, query.message.chat_id)

    # ── Save DB ───────────────────────────────────────────────────────────────
    cursor.execute("""
        INSERT OR REPLACE INTO airdrop_data
        (user_id, last_free, last_ad, streak, total_opens, last_streak_day)
        VALUES (?,?,?,?,?,?)
    """, (user_id, last_free, last_ad, streak, total_opens, today_ist_day))
    conn.commit()

    # ── Animation-style reveal ────────────────────────────────────────────────
    open_label = "🆓 Free Box" if box_type == "free" else "📺 Ad Box"
    streak_bar = "🔥" * min(streak, 5)
    next_spring = AIRDROP_SPRING_OPEN - (total_opens % AIRDROP_SPRING_OPEN)

    await query.edit_message_text(
        f"🎁 *OPENING BOX...*\n\n"
        f"✨ ...\n"
        f"💥 *YOU GOT:*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"{result_detail}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"{streak_bonus_msg}\n\n"
        f"🎯 *{open_label}* opened!\n"
        f"🔥 Streak: *{streak}* {streak_bar}\n"
        f"📦 Total opens: *{total_opens}*\n"
        f"🌸 Guaranteed Spring in: *{next_spring}* opens\n\n"
        f"Use /airdrop to open again!",
        parse_mode="Markdown"
    )

    # If it was a Spring card, also send the card image
    if reward_type == "spring":
        cname, crarity, cfile, cfile_type = reward_value
        cap = (
            f"🌸 *AIRDROP SPRING CARD!*\n\n"
            f"🥷 *{cname.title()}*\n"
            f"{RARITY_EMOJI.get(crarity,'🌸')} *{crarity}*\n\n"
            f"⚔️ Congratulations, *{user_name}*! 🔥"
        )
        try:
            await send_card_media(context.bot, cfile, file_type=cfile_type, caption=cap, parse_mode="Markdown", chat_id=query.message.chat_id)
        except Exception:
            pass


pending_battles: dict = {}

# ── Naruto XO (Tic-Tac-Toe) — in-memory live state ────────────────────────────
pending_xo_challenges: dict = {}   # challenge_id -> challenge info (pre-accept)
active_xo_games: dict = {}         # match_id -> live board/turn state (post-accept)

# ── Naruto RPS (Rock Paper Scissors) — in-memory live state ───────────────────
pending_rps_challenges: dict = {}  # challenge_id -> challenge info (pre-accept)
active_rps_games: dict = {}        # match_id -> live picks state (post-accept)

GAME_CHALLENGE_EXPIRY_SECONDS = 120  # 2 minutes to accept/decline a challenge

def add_game_xp(user_id: int, amount: int):
    cursor.execute("INSERT OR IGNORE INTO game_xp (user_id, xp) VALUES (?,0)", (user_id,))
    cursor.execute("UPDATE game_xp SET xp = xp + ? WHERE user_id=?", (amount, user_id))
    conn.commit()


def get_game_xp(user_id: int) -> int:
    cursor.execute("SELECT xp FROM game_xp WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    return row[0] if row else 0


def _ensure_xo_stats_row(user_id: int):
    cursor.execute(
        "INSERT OR IGNORE INTO xo_stats (user_id, wins, losses, draws, current_streak, highest_streak, total_game_seconds, total_moves) "
        "VALUES (?,0,0,0,0,0,0,0)",
        (user_id,)
    )


def _ensure_rps_stats_row(user_id: int):
    cursor.execute(
        "INSERT OR IGNORE INTO rps_stats (user_id, wins, losses, draws, current_streak, highest_streak) VALUES (?,0,0,0,0,0)",
        (user_id,)
    )


def _resolve_game_target(update, context):
    """
    Shared target-resolution for /xo and /rps — reply-to-message, @mention
    entity, or @username arg. Returns (target_id, target_name) or (None, None).
    Mirrors the exact resolution style already used by /battle.
    """
    target_id, target_name = None, None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        t = update.message.reply_to_message.from_user
        target_id, target_name = t.id, t.first_name or "Shinobi"
        return target_id, target_name
    for ent in (update.message.entities or []):
        if ent.type == "mention":
            uname = update.message.text[ent.offset:ent.offset + ent.length].lstrip("@")
            cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (uname,))
            r = cursor.fetchone()
            if r:
                target_id, target_name = r
            return target_id, target_name
    if context.args:
        for a in context.args:
            if a.startswith("@"):
                uname = a.lstrip("@")
                cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (uname,))
                r = cursor.fetchone()
                if r:
                    target_id, target_name = r
                return target_id, target_name
    return None, None



# =====================================================================
# 🎮  NARUTO XO (TIC-TAC-TOE) — premium 1v1 challenge game
# =====================================================================

def _render_xo_board(board: list, match_id: str) -> InlineKeyboardMarkup:
    """board is a flat list of 9 cells: '' empty, 'X', or 'O'."""
    symbols = {"": "⬜", "X": "❌", "O": "⭕"}
    rows = []
    for r in range(3):
        row = []
        for c in range(3):
            idx = r * 3 + c
            row.append(InlineKeyboardButton(symbols[board[idx]], callback_data=f"xomv_{match_id}_{idx}"))
        rows.append(row)
    return InlineKeyboardMarkup(rows)


def _check_xo_winner(board: list):
    """Returns 'X', 'O', 'draw', or None (game continues)."""
    lines = [
        (0,1,2),(3,4,5),(6,7,8),
        (0,3,6),(1,4,7),(2,5,8),
        (0,4,8),(2,4,6),
    ]
    for a, b, c in lines:
        if board[a] and board[a] == board[b] == board[c]:
            return board[a]
    if all(cell for cell in board):
        return "draw"
    return None


async def xo_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/xo @username — Challenge someone to a premium Naruto-themed XO (Tic-Tac-Toe) match."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    user_name = update.effective_user.first_name or "Shinobi"
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    target_id, target_name = _resolve_game_target(update, context)
    if not target_id:
        await update.message.reply_text(
            "❌ *Usage:* `/xo @username`\nOr reply to someone's message.",
            parse_mode="Markdown"
        )
        return
    if target_id == user_id:
        await update.message.reply_text("❌ You can't challenge yourself!", parse_mode="Markdown")
        return

    challenge_id = f"xo_{user_id}_{target_id}_{int(time.time())}"
    pending_xo_challenges[challenge_id] = {
        "challenger_id": user_id, "challenger_name": user_name,
        "opponent_id": target_id, "opponent_name": target_name,
        "expires": int(time.time()) + GAME_CHALLENGE_EXPIRY_SECONDS,
    }

    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ Accept", callback_data=f"xoacc_{challenge_id}"),
        InlineKeyboardButton("❌ Decline", callback_data=f"xodec_{challenge_id}"),
    ]])

    await update.message.reply_text(
        f"🎮 *Naruto XO Challenge*\n\n"
        f"🍥 *{user_name}*\n\n"
        f"VS\n\n"
        f"🌙 *{target_name}*\n\n"
        f"⏳ Waiting for *{target_name}* to Accept...",
        parse_mode="Markdown",
        reply_markup=keyboard
    )


async def xo_challenge_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle XO challenge accept/decline."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass

    data = query.data or ""
    parts = data.split("_", 1)
    action = parts[0]  # "xoacc" or "xodec"
    challenge_id = parts[1] if len(parts) > 1 else ""

    challenge = pending_xo_challenges.get(challenge_id)
    if not challenge:
        await query.edit_message_text("❌ This XO challenge has expired.")
        return

    responder = query.from_user.id
    if responder != challenge["opponent_id"]:
        await query.answer("Only the challenged player can respond.", show_alert=True)
        return

    if action == "xodec":
        pending_xo_challenges.pop(challenge_id, None)
        await query.edit_message_text(
            f"❌ *{challenge['opponent_name']}* declined the XO challenge.",
            parse_mode="Markdown"
        )
        return

    if int(time.time()) > challenge["expires"]:
        pending_xo_challenges.pop(challenge_id, None)
        await query.edit_message_text("⏰ XO challenge expired.")
        return

    pending_xo_challenges.pop(challenge_id, None)

    ch_id, ch_name = challenge["challenger_id"], challenge["challenger_name"]
    op_id, op_name = challenge["opponent_id"], challenge["opponent_name"]

    # Randomly assign X/O and who starts
    players = [(ch_id, ch_name), (op_id, op_name)]
    random.shuffle(players)
    (first_id, first_name), (second_id, second_name) = players

    match_id = f"{ch_id}_{op_id}_{int(time.time())}"
    active_xo_games[match_id] = {
        "board": [""] * 9,
        "x_id": first_id, "x_name": first_name,
        "o_id": second_id, "o_name": second_name,
        "turn": first_id,
        "started_at": int(time.time()),
        "moves": 0,
        "chat_id": query.message.chat_id,
    }

    text = (
        f"🎮 *Naruto XO*\n\n"
        f"🍥 *{first_name}* (❌)\n"
        f"🌙 *{second_name}* (⭕)\n\n"
        f"➡️ Turn: *{first_name}*"
    )
    await query.edit_message_text(
        text, parse_mode="Markdown",
        reply_markup=_render_xo_board(active_xo_games[match_id]["board"], match_id)
    )


async def xo_move_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle a single XO cell tap."""
    query = update.callback_query
    data = query.data or ""
    parts = data.split("_")
    if len(parts) < 3:
        try:
            await query.answer()
        except Exception:
            pass
        return
    match_id = "_".join(parts[1:-1])
    try:
        idx = int(parts[-1])
    except ValueError:
        await query.answer()
        return

    game = active_xo_games.get(match_id)
    if not game:
        await query.answer("This match has ended or expired.", show_alert=True)
        return

    mover = query.from_user.id
    if mover not in (game["x_id"], game["o_id"]):
        await query.answer("You're not part of this match.", show_alert=True)
        return
    if mover != game["turn"]:
        await query.answer("⏳ It's not your turn yet!", show_alert=True)
        return
    if game["board"][idx]:
        await query.answer("❌ That cell is already taken!", show_alert=True)
        return

    try:
        await query.answer()
    except Exception:
        pass

    symbol = "X" if mover == game["x_id"] else "O"
    game["board"][idx] = symbol
    game["moves"] += 1

    result = _check_xo_winner(game["board"])

    if result is None:
        # Game continues — switch turn
        game["turn"] = game["o_id"] if mover == game["x_id"] else game["x_id"]
        next_name = game["x_name"] if game["turn"] == game["x_id"] else game["o_name"]
        text = (
            f"🎮 *Naruto XO*\n\n"
            f"🍥 *{game['x_name']}* (❌)\n"
            f"🌙 *{game['o_name']}* (⭕)\n\n"
            f"➡️ Turn: *{next_name}*"
        )
        try:
            await query.edit_message_text(text, parse_mode="Markdown", reply_markup=_render_xo_board(game["board"], match_id))
        except Exception:
            pass
        return

    # ── Match over — resolve result, stats, streaks, rewards ──────────────────
    duration = int(time.time()) - game["started_at"]
    x_id, x_name = game["x_id"], game["x_name"]
    o_id, o_name = game["o_id"], game["o_name"]

    _ensure_xo_stats_row(x_id)
    _ensure_xo_stats_row(o_id)
    for pid in (x_id, o_id):
        cursor.execute(
            "UPDATE xo_stats SET total_game_seconds = total_game_seconds + ?, total_moves = total_moves + ? WHERE user_id=?",
            (duration, game["moves"], pid)
        )

    XO_WIN_COINS = 100
    XO_WIN_XP = 25

    if result == "draw":
        cursor.execute("UPDATE xo_stats SET draws = draws + 1, current_streak = 0 WHERE user_id IN (?,?)", (x_id, o_id))
        conn.commit()
        text = (
            f"🤝 *Match Draw*\n\n"
            f"🍥 {x_name} vs 🌙 {o_name}\n\n"
            f"No rewards this time — better luck next battle!"
        )
        try:
            await query.edit_message_text(text, parse_mode="Markdown")
        except Exception:
            pass
        active_xo_games.pop(match_id, None)
        return

    winner_symbol = result
    winner_id, winner_name = (x_id, x_name) if winner_symbol == "X" else (o_id, o_name)
    loser_id, loser_name = (o_id, o_name) if winner_symbol == "X" else (x_id, x_name)

    cursor.execute("UPDATE xo_stats SET wins = wins + 1, current_streak = current_streak + 1 WHERE user_id=?", (winner_id,))
    cursor.execute("UPDATE xo_stats SET highest_streak = current_streak WHERE user_id=? AND current_streak > highest_streak", (winner_id,))
    cursor.execute("UPDATE xo_stats SET losses = losses + 1, current_streak = 0 WHERE user_id=?", (loser_id,))
    conn.commit()

    add_coins(winner_id, XO_WIN_COINS)
    add_game_xp(winner_id, XO_WIN_XP)

    cursor.execute("SELECT wins, losses, draws, current_streak FROM xo_stats WHERE user_id=?", (winner_id,))
    w_wins, w_losses, w_draws, w_streak = cursor.fetchone()
    total_games = w_wins + w_losses + w_draws
    win_rate = (w_wins / total_games * 100) if total_games else 0.0

    text = (
        f"🏆 *Naruto XO*\n\n"
        f"*Winner*\n🥇 {winner_name}\n\n"
        f"⭐ +{XO_WIN_XP} XP\n"
        f"🪙 +{XO_WIN_COINS} Coins\n\n"
        f"🔥 Win Streak: *{w_streak}*\n"
        f"📊 Current WR: *{win_rate:.0f}%*"
    )
    try:
        await query.edit_message_text(text, parse_mode="Markdown")
    except Exception:
        pass
    active_xo_games.pop(match_id, None)


async def xo_stats_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/stats_xo — Show your (or a replied-to user's) Naruto XO stats."""
    if not update.effective_user or not update.message:
        return
    target_id = update.effective_user.id
    target_name = update.effective_user.first_name or "Shinobi"
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        t = update.message.reply_to_message.from_user
        target_id, target_name = t.id, t.first_name or "Shinobi"

    _ensure_xo_stats_row(target_id)
    conn.commit()
    cursor.execute(
        "SELECT wins, losses, draws, current_streak, highest_streak, total_game_seconds, total_moves "
        "FROM xo_stats WHERE user_id=?",
        (target_id,)
    )
    wins, losses, draws, streak, high_streak, total_secs, total_moves = cursor.fetchone()
    total_games = wins + losses + draws
    win_rate = (wins / total_games * 100) if total_games else 0.0
    avg_secs = (total_secs / total_games) if total_games else 0
    avg_min, avg_sec = divmod(int(avg_secs), 60)

    cursor.execute("SELECT COUNT(*)+1 FROM xo_stats WHERE wins > (SELECT wins FROM xo_stats WHERE user_id=?)", (target_id,))
    rank = cursor.fetchone()[0]

    await update.message.reply_text(
        f"🎮 *Naruto XO Stats*\n\n"
        f"Player\n🍥 *{target_name}*\n\n"
        f"━━━━━━━━━━━━━━\n"
        f"🏆 Wins\n*{wins}*\n\n"
        f"❌ Losses\n*{losses}*\n\n"
        f"🤝 Draws\n*{draws}*\n\n"
        f"🎮 Total Games\n*{total_games}*\n\n"
        f"🔥 Current Streak\n*{streak}*\n\n"
        f"⚡ Highest Streak\n*{high_streak}*\n\n"
        f"📊 Win Rate\n*{win_rate:.2f}%*\n\n"
        f"⏱ Average Match\n*{avg_min}m {avg_sec}s*\n\n"
        f"⭐ Rank\n*#{rank}*\n"
        f"━━━━━━━━━━━━━━",
        parse_mode="Markdown"
    )


async def xo_top_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/top_xo — Naruto XO leaderboard, ranked by wins."""
    if not update.effective_user or not update.message:
        return
    cursor.execute(
        "SELECT xs.user_id, bu.first_name, xs.wins, xs.losses, xs.draws "
        "FROM xo_stats xs LEFT JOIN bot_users bu ON bu.user_id = xs.user_id "
        "WHERE xs.wins > 0 ORDER BY xs.wins DESC LIMIT 10"
    )
    rows = cursor.fetchall()
    if not rows:
        await update.message.reply_text("🎮 *No Naruto XO wins yet!* Be the first — try /xo!", parse_mode="Markdown")
        return
    medals = ["🥇", "🥈", "🥉"]
    lines = ["🏆 *Naruto XO Rankings*\n"]
    for i, (uid, fname, wins, losses, draws) in enumerate(rows):
        display = fname or str(uid)
        total = wins + losses + draws
        rate = (wins / total * 100) if total else 0.0
        medal = medals[i] if i < 3 else f"{i+1}️⃣"
        lines.append(f"{medal} *{display}*\nWins {wins} | WR {rate:.0f}%\n")
    await send_leaderboard(update.message, "xo", "\n".join(lines), parse_mode="Markdown")


