def _get_my_shinobis(user_id: int):
    """Return list of up to 3 (card_id, card_name, rarity, file_id, file_type) tuples for user's battle deck."""
    cursor.execute(
        "SELECT card1_id, card2_id, card3_id FROM my_shinobis WHERE user_id=?",
        (user_id,)
    )
    row = cursor.fetchone()
    if not row:
        return []
    cards = []
    for cid in row:
        if cid is None:
            continue
        cursor.execute(
            "SELECT id, card_name, rarity, file_id, COALESCE(file_type,'photo') FROM user_cards WHERE id=? AND user_id=?",
            (cid, user_id)
        )
        cr = cursor.fetchone()
        if cr:
            cards.append(cr)
    return cards


async def my_shinobis(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/my_shinobis [id1] [id2] [id3] — Set or view your 3-card battle deck."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    args = context.args or []

    # View current deck if no args
    if not args:
        cards = _get_my_shinobis(user_id)
        if not cards:
            await update.message.reply_text(
                "⚔️ *Your Battle Deck is Empty!*\n\n"
                "Set 3 cards using:\n`/my_shinobis <id1> <id2> <id3>`\n\n"
                "Find your card IDs with /collection",
                parse_mode="Markdown"
            )
            return
        lines = ["⚔️ *YOUR BATTLE DECK*\n", "━━━━━━━━━━━━━━━━━━━━━━"]
        for i, c in enumerate(cards):
            emoji = RARITY_EMOJI.get(c[2], "⭐")
            lines.append(f"*Slot {i+1}:* {emoji} {c[1].title()} [{c[2]}] (ID: {c[0]})")
        lines.append("━━━━━━━━━━━━━━━━━━━━━━")
        lines.append("\nUse `/battle @username` to fight!")
        await update.message.reply_text("\n".join(lines), parse_mode="Markdown")
        return

    # Set deck
    if len(args) != 3:
        await update.message.reply_text(
            "❌ *Usage:* `/my_shinobis <id1> <id2> <id3>`\n\n"
            "Provide exactly 3 card IDs.\n"
            "Find your card IDs with /collection",
            parse_mode="Markdown"
        )
        return

    try:
        id1, id2, id3 = int(args[0]), int(args[1]), int(args[2])
    except ValueError:
        await update.message.reply_text("❌ Card IDs must be numbers!", parse_mode="Markdown")
        return

    if len({id1, id2, id3}) != 3:
        await update.message.reply_text("❌ All 3 card IDs must be different!", parse_mode="Markdown")
        return

    # Verify all cards belong to user — try card_id (master/collection ID) first, fallback to row id
    card_info = {}
    resolved_ids = {}  # map user-entered id → actual user_cards.id (row id) for storage
    for cid in [id1, id2, id3]:
        # Try by master card_id (the #ID shown in /collection)
        cursor.execute(
            "SELECT id, card_name, rarity FROM user_cards WHERE card_id=? AND user_id=? LIMIT 1",
            (cid, user_id)
        )
        row = cursor.fetchone()
        if row:
            resolved_ids[cid] = row[0]   # actual user_cards row id
            card_info[cid] = (row[1], row[2])
        else:
            # Fallback: try by user_cards row id directly
            cursor.execute(
                "SELECT id, card_name, rarity FROM user_cards WHERE id=? AND user_id=?",
                (cid, user_id)
            )
            row = cursor.fetchone()
            if row:
                resolved_ids[cid] = row[0]
                card_info[cid] = (row[1], row[2])
            else:
                await update.message.reply_text(
                    f"❌ Card ID *#{cid}* not found in your collection!\n\n"
                    f"Use /collection to see your card IDs.",
                    parse_mode="Markdown"
                )
                return

    rid1, rid2, rid3 = resolved_ids[id1], resolved_ids[id2], resolved_ids[id3]

    cursor.execute(
        "INSERT OR REPLACE INTO my_shinobis (user_id, card1_id, card2_id, card3_id) VALUES (?,?,?,?)",
        (user_id, rid1, rid2, rid3)
    )
    conn.commit()

    lines = ["✅ *Battle Deck Set!*\n", "━━━━━━━━━━━━━━━━━━━━━━"]
    for i, cid in enumerate([id1, id2, id3]):
        cname, crarity = card_info[cid]
        emoji = RARITY_EMOJI.get(crarity, "⭐")
        lines.append(f"*Slot {i+1}:* {emoji} {cname.title()} [{crarity}]")
    lines.append("━━━━━━━━━━━━━━━━━━━━━━")
    lines.append("\n⚔️ Use `/battle @username` to fight!")

    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


