async def clan_deposits_cmd(update, context):
    """/clan_deposits — View clan treasury and deposit breakdown."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    my_clan = _get_user_clan(user_id)
    if not my_clan:
        await update.message.reply_text("❌ You are not in a clan.", parse_mode="Markdown")
        return
    clan_id, clan_name, role = my_clan

    # Apply interest before showing
    _apply_clan_deposit_interest()

    cursor.execute(
        "SELECT cd.user_id, cd.amount, bu.first_name, bu.username "
        "FROM clan_deposits cd LEFT JOIN bot_users bu ON bu.user_id=cd.user_id "
        "WHERE cd.clan_id=? AND cd.amount > 0 ORDER BY cd.amount DESC",
        (clan_id,)
    )
    rows = cursor.fetchall()

    cursor.execute("SELECT COALESCE(SUM(amount),0) FROM clan_deposits WHERE clan_id=?", (clan_id,))
    total = cursor.fetchone()[0]

    lines = [
        f"🏦 *{clan_name} — Clan Treasury*",
        f"━━━━━━━━━━━━━━━━━━━━━━",
        f"💰 Total: *{total:,} Shinobi Coins*",
        f"📈 Earns *1% interest* daily at 5:30 AM IST",
        f"━━━━━━━━━━━━━━━━━━━━━━\n",
        f"📋 *Member Deposits:*"
    ]

    if not rows:
        lines.append("  _No deposits yet._")
    else:
        for uid, amount, fname, uname in rows:
            display = fname or str(uid)
            tag = f" (@{uname})" if uname else f" [`{uid}`]"
            lines.append(f"  🥷 *{display}*{tag} — `{amount:,}` 🪙")

    can_withdraw = role in ("leader", "assistant")
    lines.append(f"\n━━━━━━━━━━━━━━━━━━━━━━")
    lines.append(f"💡 Deposit: `/deposit <amount>`")
    if can_withdraw:
        lines.append(f"💡 Withdraw: `/withdraw <amount>` _(Leader/Vice Leader only)_")

    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def leave_clan(update, context):
    """/leave_clan — Leave your current clan (non-leaders only)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    my_clan = _get_user_clan(user_id)
    if not my_clan:
        await update.message.reply_text("❌ You are not in a clan.", parse_mode="Markdown")
        return
    clan_id, clan_name, role = my_clan
    if role == "leader":
        await update.message.reply_text(
            "❌ *Leaders cannot leave.*\n\n"
            "You must use `/disband_clan` to disband, or transfer leadership first.",
            parse_mode="Markdown"
        )
        return
    cursor.execute("DELETE FROM clan_members WHERE user_id=? AND clan_id=?", (user_id, clan_id))
    # Remove officer/assistant role records in clans table if applicable
    cursor.execute(
        "UPDATE clans SET assistant_leader_id=NULL WHERE id=? AND assistant_leader_id=?",
        (clan_id, user_id)
    )
    conn.commit()
    user_name = update.effective_user.first_name or "Shinobi"
    await update.message.reply_text(
        f"✅ *{user_name}* has left *{clan_name}*. 👋\n\n"
        f"Browse other clans: /join_clan",
        parse_mode="Markdown"
    )
    # Notify clan leader
    cursor.execute("SELECT leader_id FROM clans WHERE id=?", (clan_id,))
    lr = cursor.fetchone()
    if lr:
        try:
            await context.bot.send_message(
                chat_id=lr[0],
                text=f"📢 *{user_name}* has left *{clan_name}*.",
                parse_mode="Markdown"
            )
        except Exception:
            pass


MAX_CLAN_OFFICERS = 4

async def promote_officer(update, context):
    """/promote_officer @user — Promote a member to Officer (leader or vice captain only, max 4 officers)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    my_clan = _get_user_clan(user_id)
    if not my_clan:
        await update.message.reply_text("❌ You are not in a clan.", parse_mode="Markdown")
        return
    clan_id, clan_name, role = my_clan
    if role not in ("leader", "assistant"):
        await update.message.reply_text(
            "❌ Only the *Leader* or *Vice Captain* can promote officers.",
            parse_mode="Markdown"
        )
        return

    # Check officer cap
    cursor.execute(
        "SELECT COUNT(*) FROM clan_members WHERE clan_id=? AND role='officer'",
        (clan_id,)
    )
    officer_count = cursor.fetchone()[0]
    if officer_count >= MAX_CLAN_OFFICERS:
        await update.message.reply_text(
            f"❌ Max *{MAX_CLAN_OFFICERS}* officers allowed per clan. Demote one first.",
            parse_mode="Markdown"
        )
        return

    # Resolve target
    target_id, target_name = None, None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        t = update.message.reply_to_message.from_user
        target_id, target_name = t.id, t.first_name or "Shinobi"
    else:
        for ent in (update.message.entities or []):
            if ent.type == "mention":
                uname = update.message.text[ent.offset:ent.offset + ent.length].lstrip("@")
                cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (uname,))
                r = cursor.fetchone()
                if r:
                    target_id, target_name = r
                break

    if not target_id:
        await update.message.reply_text(
            "❌ Reply to a message or use `/promote_officer @username`",
            parse_mode="Markdown"
        )
        return

    cursor.execute(
        "SELECT role FROM clan_members WHERE user_id=? AND clan_id=?",
        (target_id, clan_id)
    )
    row = cursor.fetchone()
    if not row:
        await update.message.reply_text(
            f"❌ *{target_name}* is not in your clan.", parse_mode="Markdown"
        )
        return
    if row[0] in ("leader", "assistant"):
        await update.message.reply_text(
            f"❌ *{target_name}* already has a higher role.", parse_mode="Markdown"
        )
        return
    if row[0] == "officer":
        await update.message.reply_text(
            f"ℹ️ *{target_name}* is already an Officer.", parse_mode="Markdown"
        )
        return

    cursor.execute(
        "UPDATE clan_members SET role='officer' WHERE user_id=? AND clan_id=?",
        (target_id, clan_id)
    )
    conn.commit()
    await update.message.reply_text(
        f"⚔️ *{target_name}* has been promoted to *Officer* of *{clan_name}*!",
        parse_mode="Markdown"
    )
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=f"⚔️ You have been promoted to *Officer* in *{clan_name}*! You can now invite members.",
            parse_mode="Markdown"
        )
    except Exception:
        pass


