async def top_rarity_cmd(update, context):
    """Generic handler for /top_<rarity> — shows top 10 collectors of that rarity."""
    if not update.effective_user or not update.message:
        return
    cmd = update.message.text.split("@")[0].lstrip("/").lower()
    rarity = RARITY_TOP_COMMANDS.get(cmd)
    if not rarity:
        return

    emoji = RARITY_EMOJI.get(rarity, "⭐")
    cursor.execute(
        """
        SELECT uc.user_id, bu.first_name, bu.username, COUNT(uc.id) as cnt
        FROM user_cards uc
        LEFT JOIN bot_users bu ON bu.user_id = uc.user_id
        WHERE uc.rarity = ?
        GROUP BY uc.user_id
        ORDER BY cnt DESC
        LIMIT 10
        """,
        (rarity,)
    )
    rows = cursor.fetchall()
    if not rows:
        await update.message.reply_text(
            f"{emoji} *No {rarity} cards collected yet!*", parse_mode="Markdown"
        )
        return

    medals = ["🥇", "🥈", "🥉"]
    lines = [f"{emoji} *TOP {rarity.upper()} COLLECTORS*\n", "━━━━━━━━━━━━━━━━━━━━"]
    for i, (uid, fname, uname, cnt) in enumerate(rows):
        display = fname or uname or str(uid)
        medal = medals[i] if i < 3 else f"{i+1}."
        lines.append(f"{medal} *{display}* — {cnt} {rarity} card(s)")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


