def _get_char_stats(card_name: str, rarity: str) -> dict:
    """Get battle stats for a card by name, falling back to rarity-based defaults."""
    name_lower = card_name.lower().strip()
    stats = CHAR_STATS_DB.get(name_lower)
    if stats:
        return dict(stats)
    # Rarity-based fallback
    base = {
        "Common":   {"hp": 120, "atk": 30, "def": 20, "spd": 30, "chakra": 100, "element": "Wind"},
        "Rare": {"hp": 180, "atk": 50, "def": 35, "spd": 50, "chakra": 150, "element": "Fire"},
        "Epic":     {"hp": 260, "atk": 75, "def": 50, "spd": 65, "chakra": 200, "element": "Lightning"},
        "Legendary":     {"hp": 370, "atk": 105, "def": 65, "spd": 75, "chakra": 250, "element": "Earth"},
        "Mythic":  {"hp": 460, "atk": 135, "def": 75, "spd": 85, "chakra": 280, "element": "Water"},
        "Spring":   {"hp": 520, "atk": 155, "def": 85, "spd": 90, "chakra": 295, "element": "Wind"},
    }
    return dict(base.get(rarity, base["Common"]))

def _calc_round_damage(attacker_stats: dict, defender_stats: dict, crit_chance: float = 0.15) -> tuple:
    """Return (damage, is_crit, element_bonus)."""
    atk = attacker_stats["atk"]
    def_ = defender_stats["def"]
    spd = attacker_stats["spd"]
    # Element advantage
    elem_bonus = 1.0
    att_elem = attacker_stats.get("element", "Wind")
    def_elem = defender_stats.get("element", "Wind")
    if ELEMENT_ADVANTAGE.get(att_elem) == def_elem:
        elem_bonus = 1.20  # +20% element advantage
    # Speed affects damage slightly
    spd_bonus = 1.0 + (spd - 50) * 0.002  # ±10% range
    # Base damage
    raw = max(5, int((atk * spd_bonus * elem_bonus) - def_ * 0.5))
    # Random variance ±15%
    variance = random.uniform(0.85, 1.15)
    damage = int(raw * variance)
    # Critical hit
    is_crit = random.random() < crit_chance
    if is_crit:
        damage = int(damage * 1.5)
    return max(1, damage), is_crit, elem_bonus > 1.0


# Active battles stored in memory: {battle_id: battle_state}
active_battles: dict = {}


async def battle(update, context):
    """/battle @username — Challenge someone to a 3-round card battle."""
    if not update.effective_user or not update.message:
        return
    user_id   = update.effective_user.id
    user_name = update.effective_user.first_name or "Shinobi"
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    # Resolve target
    target_id, target_name = None, None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        t = update.message.reply_to_message.from_user
        target_id, target_name = t.id, t.first_name or "Shinobi"
    else:
        for ent in (update.message.entities or []):
            if ent.type == "mention":
                uname = update.message.text[ent.offset:ent.offset + ent.length].lstrip("@")
                cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (uname,))
                r = cursor.fetchone()
                if r:
                    target_id, target_name = r
                break
        if not target_id and context.args:
            for a in context.args:
                if a.startswith("@"):
                    uname = a.lstrip("@")
                    cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (uname,))
                    r = cursor.fetchone()
                    if r:
                        target_id, target_name = r
                    break

    if not target_id:
        await update.message.reply_text(
            "❌ *Usage:* `/battle @username`\nOr reply to someone's message.",
            parse_mode="Markdown"
        )
        return
    if target_id == user_id:
        await update.message.reply_text("❌ You can't battle yourself!", parse_mode="Markdown")
        return

    ch_cards = _get_my_shinobis(user_id)
    if not ch_cards or len(ch_cards) < 3:
        await update.message.reply_text(
            "❌ *You need exactly 3 cards in your battle deck!*\n\n"
            "Set 3 cards: `/my_shinobis <id1> <id2> <id3>`",
            parse_mode="Markdown"
        )
        return
    op_cards = _get_my_shinobis(target_id)
    if not op_cards or len(op_cards) < 3:
        await update.message.reply_text(
            f"❌ *{target_name}* needs 3 cards in their battle deck!\n\n"
            f"They must use `/my_shinobis <id1> <id2> <id3>` first.",
            parse_mode="Markdown"
        )
        return

    challenge_id = f"btl_{user_id}_{target_id}_{int(time.time())}"
    pending_battles[challenge_id] = {
        "challenger_id":   user_id,
        "challenger_name": user_name,
        "opponent_id":     target_id,
        "opponent_name":   target_name,
        "expires":         int(time.time()) + 120,
    }

    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("⚔️ Accept Battle", callback_data=f"battle_accept_{challenge_id}"),
        InlineKeyboardButton("🏳️ Decline",        callback_data=f"battle_decline_{challenge_id}"),
    ]])

    ch_card_names = " | ".join(f"{RARITY_EMOJI.get(c[2],'⭐')}{c[1].title()}" for c in ch_cards)
    await update.message.reply_text(
        f"⚔️ *BATTLE CHALLENGE!*\n\n"
        f"🥷 *{user_name}* challenges *{target_name}*!\n\n"
        f"🃏 *{user_name}'s Deck:* _[Hidden - 3 Shinobis ready]_\n\n"
        f"⏳ *{target_name}*, accept within 2 minutes!\n"
        f"⚠️ Both decks are secret until the battle begins!",
        parse_mode="Markdown",
        reply_markup=keyboard
    )


async def battle_callback(update, context):
    """Handle battle accept/decline and run the 3-round battle."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass

    data  = query.data or ""
    parts = data.split("_", 2)
    if len(parts) < 3:
        return
    action       = parts[1]
    challenge_id = parts[2]

    challenge = pending_battles.get(challenge_id)
    if not challenge:
        await query.edit_message_text("❌ This battle challenge has expired.")
        return

    responder = query.from_user.id

    if action == "decline":
        if responder != challenge["opponent_id"]:
            await query.answer("Only the challenged player can respond.", show_alert=True)
            return
        pending_battles.pop(challenge_id, None)
        await query.edit_message_text(
            f"🏳️ *{challenge['opponent_name']}* declined the battle.",
            parse_mode="Markdown"
        )
        return

    if action != "accept":
        return
    if responder != challenge["opponent_id"]:
        await query.answer("Only the challenged player can respond.", show_alert=True)
        return
    if int(time.time()) > challenge["expires"]:
        pending_battles.pop(challenge_id, None)
        await query.edit_message_text("⏰ Battle challenge expired.")
        return

    pending_battles.pop(challenge_id, None)

    ch_id,   ch_name = challenge["challenger_id"],  challenge["challenger_name"]
    op_id,   op_name = challenge["opponent_id"],    challenge["opponent_name"]

    ch_cards = _get_my_shinobis(ch_id)
    op_cards = _get_my_shinobis(op_id)

    if not ch_cards or len(ch_cards) < 3 or not op_cards or len(op_cards) < 3:
        await query.edit_message_text("❌ One of the players no longer has 3 cards in their deck.")
        return

    # ── Run 3 rounds ───────────────────────────────────────────────
    ch_wins = 0
    op_wins = 0
    draws   = 0
    round_logs = []

    elem_labels = {True: " 🌪️ ELEMENT ADV!", False: ""}
    crit_labels  = {True: " 💥 CRIT!", False: ""}

    for rnd in range(3):
        ch_card = ch_cards[rnd]  # (id, name, rarity, file_id, file_type)
        op_card = op_cards[rnd]

        ch_name_card  = ch_card[1]
        op_name_card  = op_card[1]
        ch_rarity     = ch_card[2]
        op_rarity     = op_card[2]
        ch_emoji      = RARITY_EMOJI.get(ch_rarity, "⭐")
        op_emoji      = RARITY_EMOJI.get(op_rarity, "⭐")

        # DRAW check — same card name and same rarity
        if ch_name_card.lower().strip() == op_name_card.lower().strip() and ch_rarity == op_rarity:
            draws += 1
            round_logs.append(
                f"🔄 *Round {rnd+1}:* DRAW!\n"
                f"   Both: {ch_emoji} *{ch_name_card.title()}* [{ch_rarity}]\n"
                f"   ⚖️ Same card — round is a draw!"
            )
            continue

        ch_stats = _get_char_stats(ch_name_card, ch_rarity)
        op_stats = _get_char_stats(op_name_card, op_rarity)

        # Apply rarity HP/ATK scaling on top of base
        rarity_hp_scale = {
            "Common": 1.0, "Rare": 1.2, "Epic": 1.5, "Legendary": 1.9, "Mythic": 2.4, "Spring": 3.0
        }
        ch_stats["hp"]  = int(ch_stats["hp"]  * rarity_hp_scale.get(ch_rarity, 1.0))
        ch_stats["atk"] = int(ch_stats["atk"] * rarity_hp_scale.get(ch_rarity, 1.0))
        op_stats["hp"]  = int(op_stats["hp"]  * rarity_hp_scale.get(op_rarity, 1.0))
        op_stats["atk"] = int(op_stats["atk"] * rarity_hp_scale.get(op_rarity, 1.0))

        # Simulate round combat: alternate attacks until one HP hits 0
        ch_hp = ch_stats["hp"]
        op_hp = op_stats["hp"]
        first = ch_stats if ch_stats["spd"] >= op_stats["spd"] else op_stats
        round_detail = []
        turn = 0
        while ch_hp > 0 and op_hp > 0 and turn < 20:
            turn += 1
            if first is ch_stats:  # ch attacks first
                dmg, crit, elem = _calc_round_damage(ch_stats, op_stats)
                op_hp -= dmg
                round_detail.append(f"   ⚔️ {ch_emoji}{ch_name_card.title()} → {dmg} DMG{crit_labels[crit]}{elem_labels[elem]}")
                if op_hp > 0:
                    dmg2, crit2, elem2 = _calc_round_damage(op_stats, ch_stats)
                    ch_hp -= dmg2
                    round_detail.append(f"   ⚔️ {op_emoji}{op_name_card.title()} → {dmg2} DMG{crit_labels[crit2]}{elem_labels[elem2]}")
            else:
                dmg, crit, elem = _calc_round_damage(op_stats, ch_stats)
                ch_hp -= dmg
                round_detail.append(f"   ⚔️ {op_emoji}{op_name_card.title()} → {dmg} DMG{crit_labels[crit]}{elem_labels[elem]}")
                if ch_hp > 0:
                    dmg2, crit2, elem2 = _calc_round_damage(ch_stats, op_stats)
                    op_hp -= dmg2
                    round_detail.append(f"   ⚔️ {ch_emoji}{ch_name_card.title()} → {dmg2} DMG{crit_labels[crit2]}{elem_labels[elem2]}")

        # Limit detail lines to keep message short
        shown_detail = round_detail[:4]
        if len(round_detail) > 4:
            shown_detail.append(f"   ... {len(round_detail)-4} more exchange(s)")

        if ch_hp > op_hp:
            ch_wins += 1
            winner_tag = f"🏆 *{ch_name}* wins Round {rnd+1}!"
        elif op_hp > ch_hp:
            op_wins += 1
            winner_tag = f"🏆 *{op_name}* wins Round {rnd+1}!"
        else:
            draws += 1
            winner_tag = f"⚖️ Round {rnd+1} is a DRAW!"

        round_logs.append(
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"⚔️ *Round {rnd+1}*\n"
            f"  🥷 *{ch_name}*: {ch_emoji} *{ch_name_card.title()}* [{ch_rarity}] HP:{ch_stats['hp']}\n"
            f"  🥷 *{op_name}*: {op_emoji} *{op_name_card.title()}* [{op_rarity}] HP:{op_stats['hp']}\n"
            + "\n".join(shown_detail) + "\n"
            f"  ❤️ Remaining — {ch_name}: {max(0,ch_hp)} | {op_name}: {max(0,op_hp)}\n"
            f"  {winner_tag}"
        )

    # ── Final result ─────────────────────────────────────────────
    if ch_wins > op_wins:
        overall_winner_id   = ch_id
        overall_winner_name = ch_name
        overall_loser_name  = op_name
    elif op_wins > ch_wins:
        overall_winner_id   = op_id
        overall_winner_name = op_name
        overall_loser_name  = ch_name
    else:
        overall_winner_id   = None
        overall_winner_name = None
        overall_loser_name  = None

    win_coins  = 300
    draw_coins = 100
    lose_coins = 75

    if overall_winner_id:
        add_coins(overall_winner_id, win_coins)
        add_coins(ch_id if overall_winner_id == op_id else op_id, lose_coins)
    else:
        add_coins(ch_id, draw_coins)
        add_coins(op_id, draw_coins)

    cursor.execute(
        "INSERT INTO battle_history (challenger_id, opponent_id, winner_id, challenger_power, opponent_power, battle_at) "
        "VALUES (?,?,?,?,?,?)",
        (ch_id, op_id, overall_winner_id or 0, ch_wins, op_wins, int(time.time()))
    )
    conn.commit()

    result_header = (
        f"⚔️ *3-ROUND BATTLE RESULT!*\n\n"
        f"🥷 *{ch_name}* VS 🥷 *{op_name}*\n\n"
    )
    rounds_text = "\n\n".join(round_logs)
    scoreline = (
        f"\n\n━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📊 *Final Score:* {ch_name} *{ch_wins}* — *{op_wins}* {op_name}"
        + (f" (⚖️ {draws} draw(s))" if draws else "") + "\n"
    )
    if overall_winner_name:
        final = (
            f"🏆 *WINNER: {overall_winner_name}!*\n\n"
            f"💰 {overall_winner_name}: *+{win_coins}* coins\n"
            f"💰 {overall_loser_name}: *+{lose_coins}* coins"
        )
    else:
        final = (
            f"⚖️ *IT'S A DRAW!*\n\n"
            f"💰 Both players: *+{draw_coins}* coins"
        )

    full_text = result_header + rounds_text + scoreline + final
    # Telegram message limit — truncate if too long
    if len(full_text) > 4000:
        full_text = full_text[:3950] + "\n..._(truncated)_"

    await query.edit_message_text(full_text, parse_mode="Markdown")



# =====================================================================
# 🏯  CLAN SYSTEM  🏯
# =====================================================================

MAX_CLAN_MEMBERS = 10


def _get_user_clan(user_id: int):
    """Return (clan_id, clan_name, role) or None."""
    cursor.execute(
        "SELECT cm.clan_id, c.name, cm.role FROM clan_members cm "
        "JOIN clans c ON c.id=cm.clan_id WHERE cm.user_id=?",
        (user_id,)
    )
    return cursor.fetchone()


def _get_clan_member_count(clan_id: int) -> int:
    cursor.execute("SELECT COUNT(*) FROM clan_members WHERE clan_id=?", (clan_id,))
    row = cursor.fetchone()
    return row[0] if row else 0


def _clan_total_coins(clan_id: int) -> int:
    """Sum of all members' wallet coins PLUS coins deposited into the clan treasury."""
    # Wallet coins held by members
    cursor.execute(
        "SELECT COALESCE(SUM(sc.coins), 0) FROM clan_members cm "
        "LEFT JOIN shinobi_coins sc ON sc.user_id=cm.user_id "
        "WHERE cm.clan_id=?",
        (clan_id,)
    )
    row = cursor.fetchone()
    wallet_total = row[0] if row else 0

    # Deposited coins sitting in the clan treasury
    cursor.execute(
        "SELECT COALESCE(SUM(amount), 0) FROM clan_deposits WHERE clan_id=?",
        (clan_id,)
    )
    dep_row = cursor.fetchone()
    treasury_total = dep_row[0] if dep_row else 0

    return wallet_total + treasury_total


async def create_clan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/create_clan <clan name>"""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    existing = _get_user_clan(user_id)
    if existing:
        await update.message.reply_text(
            f"❌ You are already in clan *{existing[1]}*.\nLeave or disband it first.",
            parse_mode="Markdown"
        )
        return

    name = " ".join(context.args).strip() if context.args else ""
    if not name:
        await update.message.reply_text("❌ Usage: `/create_clan <clan name>`", parse_mode="Markdown")
        return
    if len(name) > 30:
        await update.message.reply_text("❌ Clan name must be 30 characters or less.", parse_mode="Markdown")
        return

    # Check name taken
    cursor.execute("SELECT id FROM clans WHERE LOWER(name)=LOWER(?)", (name,))
    if cursor.fetchone():
        await update.message.reply_text(f"❌ A clan named *{name}* already exists!", parse_mode="Markdown")
        return

    now = int(time.time())
    cursor.execute(
        "INSERT INTO clans (name, leader_id, created_at) VALUES (?,?,?)",
        (name, user_id, now)
    )
    clan_id = cursor.lastrowid
    cursor.execute(
        "INSERT INTO clan_members (user_id, clan_id, role, joined_at) VALUES (?,?,?,?)",
        (user_id, clan_id, "leader", now)
    )
    conn.commit()

    await update.message.reply_text(
        f"🏯 *Clan Created!*\n\n"
        f"🔥 *{name}* is now your clan!\n"
        f"👑 You are the *Leader*.\n\n"
        f"📢 Use `/add_member @user` to invite members.\n"
        f"🖼️ Use `/set_clanlogo` (reply to an image) to set your clan logo.",
        parse_mode="Markdown"
    )


async def add_member(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/add_member — invite a user to clan (leader or assistant leader only)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    my_clan = _get_user_clan(user_id)
    if not my_clan:
        await update.message.reply_text("❌ You are not in a clan.", parse_mode="Markdown")
        return
    clan_id, clan_name, role = my_clan
    if role not in ("leader", "assistant", "officer"):
        await update.message.reply_text(
            "❌ Only the *Leader*, *Vice Captain* or *Officer* can invite members.",
            parse_mode="Markdown"
        )
        return

    # Check member cap
    if _get_clan_member_count(clan_id) >= MAX_CLAN_MEMBERS:
        await update.message.reply_text(
            f"❌ Clan is full! Maximum *{MAX_CLAN_MEMBERS}* members allowed.",
            parse_mode="Markdown"
        )
        return

    # Resolve target
    target_id = None
    target_name = None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        t = update.message.reply_to_message.from_user
        target_id = t.id
        target_name = t.first_name or "Shinobi"
    else:
        for ent in (update.message.entities or []):
            if ent.type == "mention":
                uname = update.message.text[ent.offset:ent.offset + ent.length].lstrip("@")
                cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (uname,))
                r = cursor.fetchone()
                if r:
                    target_id, target_name = r
                break
        if not target_id and context.args:
            for a in context.args:
                try:
                    tid = int(a)
                    cursor.execute("SELECT user_id, first_name FROM bot_users WHERE user_id=? LIMIT 1", (tid,))
                    r = cursor.fetchone()
                    if r:
                        target_id, target_name = r
                    break
                except ValueError:
                    if a.startswith("@"):
                        uname = a.lstrip("@")
                        cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (uname,))
                        r = cursor.fetchone()
                        if r:
                            target_id, target_name = r
                        break

    if not target_id:
        await update.message.reply_text(
            "❌ *Usage:* Reply to a user's message or `/add_member @username` or `/add_member <user_id>`",
            parse_mode="Markdown"
        )
        return
    if target_id == user_id:
        await update.message.reply_text("❌ You can't invite yourself.", parse_mode="Markdown")
        return

    # Check already in a clan
    existing = _get_user_clan(target_id)
    if existing:
        await update.message.reply_text(
            f"❌ *{target_name}* is already in clan *{existing[1]}*.",
            parse_mode="Markdown"
        )
        return

    # Check pending invite
    cursor.execute(
        "SELECT id FROM clan_invitations WHERE clan_id=? AND invitee_id=? AND status='pending'",
        (clan_id, target_id)
    )
    if cursor.fetchone():
        await update.message.reply_text(
            f"⏳ *{target_name}* already has a pending invitation to your clan.",
            parse_mode="Markdown"
        )
        return

    now = int(time.time())
    cursor.execute(
        "INSERT INTO clan_invitations (clan_id, inviter_id, invitee_id, status, created_at) VALUES (?,?,?,?,?)",
        (clan_id, user_id, target_id, "pending", now)
    )
    inv_id = cursor.lastrowid
    conn.commit()

    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ Accept", callback_data=f"claninv_accept_{inv_id}"),
        InlineKeyboardButton("❌ Decline", callback_data=f"claninv_decline_{inv_id}"),
    ]])

    inviter_name = update.effective_user.first_name or "Leader"
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=(
                f"🏯 *Clan Invitation!*\n\n"
                f"👑 *{inviter_name}* invites you to join\n"
                f"🔥 *{clan_name}*!\n\n"
                f"Accept or decline below 👇"
            ),
            parse_mode="Markdown",
            reply_markup=keyboard
        )
        await update.message.reply_text(
            f"📨 Invitation sent to *{target_name}*!",
            parse_mode="Markdown"
        )
    except Exception:
        await update.message.reply_text(
            f"⚠️ Could not send DM to *{target_name}*. They must start the bot first.",
            parse_mode="Markdown"
        )


async def clan_invitation_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle clan invite accept/decline."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass

    data = query.data or ""
    parts = data.split("_", 2)
    if len(parts) < 3:
        return

    action = parts[1]
    try:
        inv_id = int(parts[2])
    except ValueError:
        return

    cursor.execute(
        "SELECT clan_id, inviter_id, invitee_id, status FROM clan_invitations WHERE id=?",
        (inv_id,)
    )
    inv = cursor.fetchone()
    if not inv:
        await query.edit_message_text("❌ Invitation not found or already handled.")
        return

    clan_id, inviter_id, invitee_id, status = inv
    if status != "pending":
        await query.edit_message_text("ℹ️ This invitation has already been handled.")
        return

    responder = query.from_user.id
    if responder != invitee_id:
        await query.answer("This invitation is not for you.", show_alert=True)
        return

    if action == "decline":
        cursor.execute("UPDATE clan_invitations SET status='declined' WHERE id=?", (inv_id,))
        conn.commit()
        await query.edit_message_text("❌ You declined the clan invitation.")
        return

    # Accept
    existing = _get_user_clan(invitee_id)
    if existing:
        cursor.execute("UPDATE clan_invitations SET status='expired' WHERE id=?", (inv_id,))
        conn.commit()
        await query.edit_message_text(
            f"❌ You are already in clan *{existing[1]}*. Leave first.",
            parse_mode="Markdown"
        )
        return

    if _get_clan_member_count(clan_id) >= MAX_CLAN_MEMBERS:
        cursor.execute("UPDATE clan_invitations SET status='expired' WHERE id=?", (inv_id,))
        conn.commit()
        await query.edit_message_text("❌ Clan is now full. Sorry!")
        return

    cursor.execute("SELECT name FROM clans WHERE id=?", (clan_id,))
    clan_row = cursor.fetchone()
    clan_name = clan_row[0] if clan_row else "Unknown"

    cursor.execute(
        "INSERT OR REPLACE INTO clan_members (user_id, clan_id, role, joined_at) VALUES (?,?,?,?)",
        (invitee_id, clan_id, "member", int(time.time()))
    )
    cursor.execute("UPDATE clan_invitations SET status='accepted' WHERE id=?", (inv_id,))
    conn.commit()

    user_name = query.from_user.first_name or "Shinobi"
    await query.edit_message_text(
        f"✅ *Welcome to {clan_name}!* 🏯\n\nYou are now a member of this clan!",
        parse_mode="Markdown"
    )
    try:
        await context.bot.send_message(
            chat_id=inviter_id,
            text=f"✅ *{user_name}* has joined your clan *{clan_name}*! 🏯",
            parse_mode="Markdown"
        )
    except Exception:
        pass


async def kick_member(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/kick_member @user — remove a member (leader only)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    my_clan = _get_user_clan(user_id)
    if not my_clan:
        await update.message.reply_text("❌ You are not in a clan.", parse_mode="Markdown")
        return
    clan_id, clan_name, role = my_clan
    if role != "leader":
        await update.message.reply_text("❌ Only the *Leader* can kick members.", parse_mode="Markdown")
        return

    # Resolve target
    target_id = None
    target_name = None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        t = update.message.reply_to_message.from_user
        target_id = t.id
        target_name = t.first_name or "Shinobi"
    else:
        for ent in (update.message.entities or []):
            if ent.type == "mention":
                uname = update.message.text[ent.offset:ent.offset + ent.length].lstrip("@")
                cursor.execute("SELECT user_id, first_name FROM bot_users WHERE username=? LIMIT 1", (uname,))
                r = cursor.fetchone()
                if r:
                    target_id, target_name = r
                break
        if not target_id and context.args:
            for a in context.args:
                try:
                    tid = int(a)
                    cursor.execute("SELECT user_id, first_name FROM bot_users WHERE user_id=? LIMIT 1", (tid,))
                    r = cursor.fetchone()
                    if r:
                        target_id, target_name = r
                    break
                except ValueError:
                    pass

    if not target_id:
        await update.message.reply_text(
            "❌ Reply to a message or use `/kick_member @username`",
            parse_mode="Markdown"
        )
        return
    if target_id == user_id:
        await update.message.reply_text("❌ You can't kick yourself. Use `/disband_clan` to disband.", parse_mode="Markdown")
        return

    cursor.execute(
        "SELECT role FROM clan_members WHERE user_id=? AND clan_id=?",
        (target_id, clan_id)
    )
    row = cursor.fetchone()
    if not row:
        await update.message.reply_text(f"❌ *{target_name}* is not in your clan.", parse_mode="Markdown")
        return

    cursor.execute("DELETE FROM clan_members WHERE user_id=? AND clan_id=?", (target_id, clan_id))
    conn.commit()

    await update.message.reply_text(
        f"✅ *{target_name}* has been kicked from *{clan_name}*.",
        parse_mode="Markdown"
    )
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=f"⚠️ You have been kicked from clan *{clan_name}*.",
            parse_mode="Markdown"
        )
    except Exception:
        pass


async def disband_clan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/disband_clan — leader disbands the clan."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    my_clan = _get_user_clan(user_id)
    if not my_clan:
        await update.message.reply_text("❌ You are not in a clan.", parse_mode="Markdown")
        return
    clan_id, clan_name, role = my_clan
    if role != "leader":
        await update.message.reply_text("❌ Only the *Leader* can disband the clan.", parse_mode="Markdown")
        return

    # Get all members to notify
    cursor.execute("SELECT user_id FROM clan_members WHERE clan_id=? AND user_id!=?", (clan_id, user_id))
    members = [r[0] for r in cursor.fetchall()]

    cursor.execute("DELETE FROM clan_members WHERE clan_id=?", (clan_id,))
    cursor.execute("DELETE FROM clan_invitations WHERE clan_id=?", (clan_id,))
    cursor.execute("DELETE FROM clans WHERE id=?", (clan_id,))
    conn.commit()

    await update.message.reply_text(
        f"💥 *Clan {clan_name} has been disbanded!*",
        parse_mode="Markdown"
    )
    for mid in members:
        try:
            await context.bot.send_message(
                chat_id=mid,
                text=f"💥 Clan *{clan_name}* has been disbanded by the leader.",
                parse_mode="Markdown"
            )
        except Exception:
            pass


async def set_clanlogo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/set_clanlogo — reply to an image to set clan logo (leader only)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    my_clan = _get_user_clan(user_id)
    if not my_clan:
        await update.message.reply_text("❌ You are not in a clan.", parse_mode="Markdown")
        return
    clan_id, clan_name, role = my_clan
    if role != "leader":
        await update.message.reply_text("❌ Only the *Leader* can set the clan logo.", parse_mode="Markdown")
        return

    # Must reply to a photo
    photo = None
    if update.message.reply_to_message:
        if update.message.reply_to_message.photo:
            photo = update.message.reply_to_message.photo[-1].file_id
        elif update.message.reply_to_message.document and update.message.reply_to_message.document.mime_type and "image" in update.message.reply_to_message.document.mime_type:
            photo = update.message.reply_to_message.document.file_id
    elif update.message.photo:
        photo = update.message.photo[-1].file_id

    if not photo:
        await update.message.reply_text(
            "❌ Please reply to an image to set the clan logo.\n"
            "Example: Reply to a photo and use `/set_clanlogo`",
            parse_mode="Markdown"
        )
        return

    cursor.execute("UPDATE clans SET logo_file_id=? WHERE id=?", (photo, clan_id))
    conn.commit()

    await update.message.reply_text(
        f"✅ *Clan logo updated for {clan_name}!* 🖼️",
        parse_mode="Markdown"
    )


async def add_vicecaptain(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/add_vicecaptain @user — set vice captain/assistant leader (leader only)."""
