async def clan_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/clan — show current clan info with logo, leader, members and pending invites."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    # Use a fresh connection to avoid stale global cursor issues
    try:
        _conn = sqlite3.connect(DB_PATH, check_same_thread=False)
        _conn.execute("PRAGMA busy_timeout=5000")
        _cur = _conn.cursor()

        _cur.execute(
            "SELECT cm.clan_id, c.name, cm.role FROM clan_members cm "
            "JOIN clans c ON c.id=cm.clan_id WHERE cm.user_id=?",
            (user_id,)
        )
        my_clan = _cur.fetchone()

        if not my_clan:
            await update.message.reply_text(
                "🏯 *You are not in a clan!*\n\n"
                "🔍 Browse clans: `/join_clan`\n"
                "🆕 Create one: `/create_clan <name>`",
                parse_mode="Markdown"
            )
            return

        clan_id, clan_name, my_role = my_clan

        _cur.execute(
            "SELECT leader_id, assistant_leader_id, logo_file_id FROM clans WHERE id=?",
            (clan_id,)
        )
        clan_row = _cur.fetchone()
        if not clan_row:
            await update.message.reply_text("❌ Clan data not found.", parse_mode="Markdown")
            return
        leader_id, asst_id, logo_fid = clan_row

        # Get members
        _cur.execute(
            "SELECT cm.user_id, cm.role, bu.first_name, bu.username "
            "FROM clan_members cm LEFT JOIN bot_users bu ON bu.user_id=cm.user_id "
            "WHERE cm.clan_id=? ORDER BY CASE cm.role WHEN 'leader' THEN 0 WHEN 'assistant' THEN 1 ELSE 2 END",
            (clan_id,)
        )
        members = _cur.fetchall()
        member_count = len(members)

        # Wallet coins (sum of all members)
        _cur.execute(
            "SELECT COALESCE(SUM(sc.coins), 0) FROM clan_members cm "
            "LEFT JOIN shinobi_coins sc ON sc.user_id=cm.user_id "
            "WHERE cm.clan_id=?",
            (clan_id,)
        )
        wallet_coins = (_cur.fetchone() or [0])[0]

        # Treasury coins (deposited funds)
        _cur.execute(
            "SELECT COALESCE(SUM(amount), 0) FROM clan_deposits WHERE clan_id=?",
            (clan_id,)
        )
        treasury_coins = (_cur.fetchone() or [0])[0]

        total_coins = wallet_coins + treasury_coins

        lines = [f"🏯 *{clan_name}*\n"]
        lines.append(f"👥 Members: *{member_count}/{MAX_CLAN_MEMBERS}*")
        lines.append(f"💰 Clan Power: *{total_coins:,}* Shinobi Coins")
        lines.append(f"🏦 Treasury: *{treasury_coins:,}* coins\n")
        lines.append("━━━━━━━━━━━━━━━━━━━━")

        for m_uid, m_role, m_fname, m_uname in members:
            def _esc(s):
                for ch in ("_", "*", "[", "]", "`"):
                    s = s.replace(ch, "\\" + ch)
                return s
            display = _esc(m_fname if m_fname else str(m_uid))
            tag_display = f" (@{_esc(m_uname)})" if m_uname else f" (`{m_uid}`)"
            if m_role == "leader":
                role_label = "👑 Leader"
            elif m_role == "assistant":
                role_label = "🥷 Vice Captain"
            elif m_role == "officer":
                role_label = "⚔️ Officer"
            else:
                role_label = "🍥 Member"
            lines.append(f"{role_label}: *{display}*{tag_display}")

        # Pending invitations (shown to leader/assistant/officer)
        if my_role in ("leader", "assistant", "officer"):
            _cur.execute(
                "SELECT ci.invitee_id, bu.first_name FROM clan_invitations ci "
                "LEFT JOIN bot_users bu ON bu.user_id=ci.invitee_id "
                "WHERE ci.clan_id=? AND ci.status='pending'",
                (clan_id,)
            )
            pending_invs = _cur.fetchall()
            if pending_invs:
                lines.append("\n━━━━━━━━━━━━━━━━━━━━")
                lines.append("📨 *Pending Invitations:*")
                for inv_uid, inv_fname in pending_invs:
                    lines.append(f"  ⏳ {inv_fname or str(inv_uid)}")

        text = "\n".join(lines)

    except Exception as e:
        await update.message.reply_text(f"❌ Error loading clan data: {e}", parse_mode="Markdown")
        return
    finally:
        try:
            _conn.close()
        except Exception:
            pass

    if logo_fid:
        try:
            await update.message.reply_photo(photo=logo_fid, caption=text, parse_mode="Markdown")
            return
        except Exception:
            pass
    await update.message.reply_text(text, parse_mode="Markdown")


# Pagination state for /join_clan
_join_clan_pages: dict = {}
CLANS_PER_PAGE = 7


async def join_clan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/join_clan — browse all clans in a paginated button list."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    existing = _get_user_clan(user_id)
    if existing:
        await update.message.reply_text(
            f"❌ You are already in clan *{existing[1]}*.",
            parse_mode="Markdown"
        )
        return

    await _show_clan_page(update.message, user_id, page=0, context=context)


async def _show_clan_page(message, user_id: int, page: int, context, edit=False):
    """Build paginated clan list with inline buttons."""
    cursor.execute(
        "SELECT c.id, c.name, COUNT(cm.user_id) as mc "
        "FROM clans c LEFT JOIN clan_members cm ON cm.clan_id=c.id "
        "GROUP BY c.id ORDER BY mc DESC"
    )
    all_clans = cursor.fetchall()

    if not all_clans:
        text = "🏯 *No clans exist yet!*\n\nCreate one with `/create_clan <name>`"
        if edit:
            await message.edit_text(text, parse_mode="Markdown")
        else:
            await message.reply_text(text, parse_mode="Markdown")
        return

    total_pages = max(1, math.ceil(len(all_clans) / CLANS_PER_PAGE))
    page = max(0, min(page, total_pages - 1))
    start = page * CLANS_PER_PAGE
    page_clans = all_clans[start:start + CLANS_PER_PAGE]

    buttons = []
    for cid, cname, mc in page_clans:
        buttons.append([InlineKeyboardButton(
            f"🏯 {cname} ({mc}/{MAX_CLAN_MEMBERS})",
            callback_data=f"clanview_{cid}"
        )])

    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️ Previous", callback_data=f"clanpage_{page - 1}_{user_id}"))
    if page < total_pages - 1:
        nav.append(InlineKeyboardButton("Next ➡️", callback_data=f"clanpage_{page + 1}_{user_id}"))
    if nav:
        buttons.append(nav)

    keyboard = InlineKeyboardMarkup(buttons)
    text = f"🏯 *All Clans* — Page {page + 1}/{total_pages}\n\nTap a clan to view details & send a join request:"

    if edit:
        await message.edit_text(text, parse_mode="Markdown", reply_markup=keyboard)
    else:
        await message.reply_text(text, parse_mode="Markdown", reply_markup=keyboard)


async def clan_browser_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle clan page navigation and clan view buttons."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass

    data = query.data or ""
    user_id = query.from_user.id

    if data.startswith("clanpage_"):
        parts = data.split("_")
        try:
            page = int(parts[1])
            # only the user who opened /join_clan can navigate
            if len(parts) > 2 and int(parts[2]) != user_id:
                await query.answer("Use /join_clan to browse clans.", show_alert=True)
                return
        except (ValueError, IndexError):
            return
        await _show_clan_page(query.message, user_id, page, context, edit=True)

    elif data.startswith("clanview_"):
        try:
            clan_id = int(data.split("_")[1])
        except (ValueError, IndexError):
            return

        cursor.execute(
            "SELECT c.name, c.logo_file_id, c.leader_id, "
            "COUNT(cm.user_id) as mc "
            "FROM clans c LEFT JOIN clan_members cm ON cm.clan_id=c.id "
            "WHERE c.id=?",
            (clan_id,)
        )
        row = cursor.fetchone()
        if not row:
            await query.edit_message_text("❌ Clan not found.")
            return

        cname, logo_fid, leader_id, mc = row
        total_coins = _clan_total_coins(clan_id)

        # Get leader name
        cursor.execute("SELECT first_name FROM bot_users WHERE user_id=? LIMIT 1", (leader_id,))
        lr = cursor.fetchone()
        leader_display = lr[0] if lr else str(leader_id)

        text = (
            f"🏯 *{cname}*\n\n"
            f"👑 Leader: *{leader_display}*\n"
            f"👥 Members: *{mc}/{MAX_CLAN_MEMBERS}*\n"
            f"💰 Clan Power: *{total_coins:,}* coins\n\n"
            f"Send a join request?"
        )

        buttons = [[
            InlineKeyboardButton("📨 Send Join Request", callback_data=f"clanreq_{clan_id}"),
            InlineKeyboardButton("⬅️ Back", callback_data=f"clanpage_0_{user_id}"),
        ]]
        keyboard = InlineKeyboardMarkup(buttons)
        await query.edit_message_text(text, parse_mode="Markdown", reply_markup=keyboard)

    elif data.startswith("clanreq_"):
        try:
            clan_id = int(data.split("_")[1])
        except (ValueError, IndexError):
            return

        existing = _get_user_clan(user_id)
        if existing:
            await query.answer(f"You are already in clan {existing[1]}!", show_alert=True)
            return

        if _get_clan_member_count(clan_id) >= MAX_CLAN_MEMBERS:
            await query.answer("This clan is full!", show_alert=True)
            return

        # Check existing pending invite
        cursor.execute(
            "SELECT id FROM clan_invitations WHERE clan_id=? AND invitee_id=? AND status='pending'",
            (clan_id, user_id)
        )
        if cursor.fetchone():
            await query.answer("You already sent a request to this clan!", show_alert=True)
            return

        cursor.execute("SELECT name, leader_id FROM clans WHERE id=?", (clan_id,))
        clan_row = cursor.fetchone()
        if not clan_row:
            await query.answer("Clan not found.", show_alert=True)
            return
        clan_name, leader_id = clan_row

        now = int(time.time())
        cursor.execute(
            "INSERT INTO clan_invitations (clan_id, inviter_id, invitee_id, status, created_at) VALUES (?,?,?,?,?)",
            (clan_id, user_id, user_id, "join_request", now)
        )
        req_id = cursor.lastrowid
        conn.commit()

        user_fname = query.from_user.first_name or "Shinobi"

        # Notify leader
        keyboard = InlineKeyboardMarkup([[
            InlineKeyboardButton("✅ Accept", callback_data=f"clanaccept_{req_id}_{user_id}"),
            InlineKeyboardButton("❌ Decline", callback_data=f"clandardecline_{req_id}"),
        ]])
        try:
            await context.bot.send_message(
                chat_id=leader_id,
                text=(
                    f"📨 *Join Request!*\n\n"
                    f"🥷 *{user_fname}* wants to join *{clan_name}*!\n\n"
                    f"Accept or decline below 👇"
                ),
                parse_mode="Markdown",
                reply_markup=keyboard
            )
        except Exception:
            pass

        await query.edit_message_text(
            f"✅ *Join request sent to {clan_name}!*\n\nWait for the leader to respond.",
            parse_mode="Markdown"
        )

    elif data.startswith("clanaccept_"):
        parts = data.split("_")
        try:
            req_id = int(parts[1])
            applicant_id = int(parts[2])
        except (ValueError, IndexError):
            return

        # Check responder is leader/assistant of that clan
        cursor.execute(
            "SELECT clan_id FROM clan_invitations WHERE id=? AND status='join_request'",
            (req_id,)
        )
        r = cursor.fetchone()
        if not r:
            await query.edit_message_text("❌ Request no longer active.")
            return
        clan_id = r[0]

        cursor.execute("SELECT role FROM clan_members WHERE user_id=? AND clan_id=?", (user_id, clan_id))
        rr = cursor.fetchone()
        if not rr or rr[0] not in ("leader", "assistant", "officer"):
            await query.answer("Only leader/vice captain/officer can accept requests.", show_alert=True)
            return

        existing = _get_user_clan(applicant_id)
        if existing:
            cursor.execute("UPDATE clan_invitations SET status='expired' WHERE id=?", (req_id,))
            conn.commit()
            await query.edit_message_text("❌ User is already in another clan.")
            return

        if _get_clan_member_count(clan_id) >= MAX_CLAN_MEMBERS:
            cursor.execute("UPDATE clan_invitations SET status='expired' WHERE id=?", (req_id,))
            conn.commit()
            await query.edit_message_text("❌ Clan is full!")
            return

        cursor.execute(
            "INSERT OR REPLACE INTO clan_members (user_id, clan_id, role, joined_at) VALUES (?,?,?,?)",
            (applicant_id, clan_id, "member", int(time.time()))
        )
        cursor.execute("UPDATE clan_invitations SET status='accepted' WHERE id=?", (req_id,))
        conn.commit()

        cursor.execute("SELECT name FROM clans WHERE id=?", (clan_id,))
        cn = cursor.fetchone()
        clan_name = cn[0] if cn else "Clan"

        await query.edit_message_text(
            f"✅ *Join request accepted!* {clan_name} has a new member!",
            parse_mode="Markdown"
        )
        try:
            await context.bot.send_message(
                chat_id=applicant_id,
                text=f"✅ *Your request was accepted!* Welcome to *{clan_name}*! 🏯",
                parse_mode="Markdown"
            )
        except Exception:
            pass

    elif data.startswith("clandardecline_"):
        parts = data.split("_")
        try:
            req_id = int(parts[1])
        except (ValueError, IndexError):
            return
        cursor.execute("UPDATE clan_invitations SET status='declined' WHERE id=?", (req_id,))
        conn.commit()
        await query.edit_message_text("❌ Join request declined.")


async def top_clans(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/top_clans — leaderboard of clans by total member coins."""
    if not update.effective_user or not update.message:
        return

    cursor.execute("SELECT id, name FROM clans")
    all_clans = cursor.fetchall()

    if not all_clans:
        await update.message.reply_text("🏯 *No clans yet!* Create one with `/create_clan`", parse_mode="Markdown")
        return

    clan_scores = []
    for cid, cname in all_clans:
        total = _clan_total_coins(cid)
        mc = _get_clan_member_count(cid)
        clan_scores.append((cid, cname, total, mc))

    clan_scores.sort(key=lambda x: x[2], reverse=True)

    lines = ["🏆 *TOP CLANS LEADERBOARD*\n", "_(Clan Power = member wallets + clan treasury)_\n", "━━━━━━━━━━━━━━━━━━━━"]
    medals = ["🥇", "🥈", "🥉"]
    for i, (cid, cname, total, mc) in enumerate(clan_scores[:10]):
        medal = medals[i] if i < 3 else f"{i+1}."
        # Show treasury breakdown
        cursor.execute("SELECT COALESCE(SUM(amount),0) FROM clan_deposits WHERE clan_id=?", (cid,))
        treasury = (cursor.fetchone() or [0])[0]
        lines.append(f"{medal} *{cname}* — 💰 {total:,} coins | 🏦 {treasury:,} treasury | 👥 {mc} members")

    await send_leaderboard(update.message, "clans", "\n".join(lines), parse_mode="Markdown")


