# ── In-memory raid state (per-chat) ──────────────────────────────────────────
# Structure: {chat_id: { beast, participants, phase, spawn_msg_id, ... }}
active_raids: dict = {}

# Random spawn scheduler task handle per chat
raid_spawn_tasks: dict = {}

# ── Raid reward rarity weights ─────────────────────────────────────────────
RAID_REWARD_RARITIES = ["Common", "Rare", "Epic", "Legendary", "Mythic"]
RAID_REWARD_WEIGHTS  = [30, 25, 20, 15, 10]  # % — common:30, rare:25, epic:20, legendary:15, mythic:10

# ── Tailed beast power scale by participant count ────────────────────────────
# beast_power = sum of (top N-1 players' 3-spring equivalent) to make it tough
# Each "spring-level" power = 520 (Spring card HP fallback)
SPRING_CARD_POWER = 520

def _raid_beast_power(num_players: int) -> int:
    """Scale beast HP: use (num_players - 1) × 3-spring equivalent, min 3 players."""
    effective = max(2, num_players - 1)
    return effective * 3 * SPRING_CARD_POWER


def _get_player_raid_power(user_id: int) -> int:
    """Sum of the 3 battle deck cards' ATK stats (or fallback) for raid damage."""
    cursor.execute(
        "SELECT card1_id, card2_id, card3_id FROM my_shinobis WHERE user_id=?",
        (user_id,)
    )
    row = cursor.fetchone()
    if not row:
        return 60  # base fallback
    total_atk = 0
    for cid in row:
        if cid is None:
            total_atk += 30
            continue
        cursor.execute(
            "SELECT card_name, rarity FROM user_cards WHERE id=? AND user_id=?",
            (cid, user_id)
        )
        cr = cursor.fetchone()
        if not cr:
            total_atk += 30
            continue
        stats = _get_char_stats(cr[0], cr[1])
        total_atk += stats.get("atk", 30)
    return max(10, total_atk)


def _get_raid_pass_count(user_id: int) -> int:
    cursor.execute("SELECT passes FROM raid_passes WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    return row[0] if row else 0


def _set_raid_passes(user_id: int, passes: int, day: int = None):
    if day is None:
        day = int(time.time()) // 86400
    cursor.execute(
        "INSERT OR REPLACE INTO raid_passes (user_id, passes, last_claim_day) VALUES (?,?,?)",
        (user_id, passes, day)
    )
    conn.commit()


def _ist_day() -> int:
    """Return current IST day-epoch (seconds // 86400 in IST)."""
    return (int(time.time()) + IST_OFFSET_SEC) // 86400


def _ist_weekday() -> int:
    """0=Mon … 6=Sun in IST."""
    from datetime import datetime, timezone, timedelta
    now_ist = datetime.now(timezone.utc) + timedelta(seconds=IST_OFFSET_SEC)
    return now_ist.weekday()


# ── /claim_raidpass ───────────────────────────────────────────────────────────
async def claim_raidpass(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/claim_raidpass — Claim 1 daily raid pass (2 on Sunday)."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return

    today = _ist_day()
    cursor.execute(
        "SELECT passes, last_claim_day FROM raid_passes WHERE user_id=?",
        (user_id,)
    )
    row = cursor.fetchone()
    passes = row[0] if row else 0
    last_day = row[1] if row else 0

    if last_day >= today:
        await update.message.reply_text(
            "⏳ *Already claimed today!*\n\n"
            f"🎟️ Your passes: *{passes}*\n\n"
            "🔄 Come back tomorrow for a new pass!",
            parse_mode="Markdown"
        )
        return

    is_sunday = (_ist_weekday() == 6)
    gained = 2 if is_sunday else 1
    passes += gained
    _set_raid_passes(user_id, passes, today)

    sunday_bonus = " 🎉 *Sunday Bonus — 2 passes!*" if is_sunday else ""
    await update.message.reply_text(
        f"🎟️ *RAID PASS CLAIMED!*{sunday_bonus}\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"✅ *+{gained} Raid Pass* added!\n"
        f"🎟️ Total passes: *{passes}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"⚔️ Use your pass to join a *Tailed Beast Raid!*\n"
        f"🐉 Raids spawn randomly *7–9 PM IST* daily!\n"
        f"🏆 Win to earn a random rarity *Beast Card!*",
        parse_mode="Markdown"
    )


# ── /raid_pass — check pass balance ─────────────────────────────────────────
async def raid_pass_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/raid_pass — Check your raid pass balance."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return
    passes = _get_raid_pass_count(user_id)
    today = _ist_day()
    cursor.execute("SELECT last_claim_day FROM raid_passes WHERE user_id=?", (user_id,))
    row = cursor.fetchone()
    claimed_today = row and row[0] >= today if row else False
    is_sunday = (_ist_weekday() == 6)
    daily_earn = 2 if is_sunday else 1
    await update.message.reply_text(
        f"🎟️ *YOUR RAID PASSES*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🎫 Passes: *{passes}*\n"
        f"📅 Daily earn: *{daily_earn}* {'(Sunday Bonus!)' if is_sunday else ''}\n"
        f"✅ Claimed today: *{'Yes' if claimed_today else 'No'}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
        f"{'⏳ Already claimed today. Come back tomorrow!' if claimed_today else '📩 Use /claim_raidpass to get your pass!'}\n"
        f"🐉 Tailed Beast Raids spawn *7–9 PM IST* daily!",
        parse_mode="Markdown"
    )


# ── /addbeast — Admin: add a tailed beast ─────────────────────────────────────
async def addbeast(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/addbeast <name> <rarity> — Reply to a photo/video to add a tailed beast."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only.")
        return

    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            "❌ Usage: `/addbeast <name> <rarity>`\n"
            "Reply to a photo/video with this command.\n"
            "Example: `/addbeast Nine Tails rare`",
            parse_mode="Markdown"
        )
        return

    # Last arg is rarity, everything else is beast name
    rarity_input = args[-1].strip().title()
    beast_name = " ".join(args[:-1]).strip()

    # Normalize rarity
    rarity_map = {
        "Common": "Common",
        "Rare": "Rare",
        "Epic": "Epic",
        "Legendary": "Legendary",
        "Mythic": "Mythic",
        "Spring": "Spring",
        "Uncommon": "Rare",
        "Mythical": "Mythic",
    }
    rarity = rarity_map.get(rarity_input, rarity_input)
    if rarity not in RARITY_EMOJI:
        await update.message.reply_text(
            f"❌ Unknown rarity *{rarity_input}*.\n"
            "Valid: Common, Rare, Epic, Legendary, Mythic, Spring",
            parse_mode="Markdown"
        )
        return

    # Get file from replied message
    replied = update.message.reply_to_message
    file_id = None
    file_type = "photo"
    if replied:
        if replied.photo:
            file_id = replied.photo[-1].file_id
            file_type = "photo"
        elif replied.video:
            file_id = replied.video.file_id
            file_type = "video"
        elif replied.animation:
            file_id = replied.animation.file_id
            file_type = "video"
    elif update.message.photo:
        file_id = update.message.photo[-1].file_id
        file_type = "photo"

    if not file_id:
        await update.message.reply_text(
            "❌ Please reply to a photo or video with `/addbeast <name> <rarity>`",
            parse_mode="Markdown"
        )
        return

    now = int(time.time())
    try:
        # Allow multiple entries per beast name (one per rarity)
        cursor.execute(
            "SELECT id FROM tailed_beasts WHERE LOWER(name)=? AND rarity=?",
            (beast_name.lower(), rarity)
        )
        existing_row = cursor.fetchone()
        if existing_row:
            # Update existing rarity entry
            cursor.execute(
                "UPDATE tailed_beasts SET file_id=?, file_type=?, added_by=?, added_at=? WHERE id=?",
                (file_id, file_type, update.effective_user.id, now, existing_row[0])
            )
        else:
            # Insert new rarity entry for this beast
            cursor.execute(
                "INSERT INTO tailed_beasts (name, rarity, file_id, file_type, added_by, added_at) "
                "VALUES (?,?,?,?,?,?)",
                (beast_name.lower(), rarity, file_id, file_type, update.effective_user.id, now)
            )
        conn.commit()
    except Exception as e:
        await update.message.reply_text(f"❌ DB Error: {e}")
        return

    emoji = RARITY_EMOJI.get(rarity, "🐉")
    await update.message.reply_text(
        f"✅ *Tailed Beast Added!*\n\n"
        f"🐉 *{beast_name.title()}*\n"
        f"{emoji} Rarity: *{rarity}*\n\n"
        f"It can now be spawned in raids!",
        parse_mode="Markdown"
    )


# ── Spawn a raid in a chat ────────────────────────────────────────────────────
async def _spawn_raid(bot, chat_id: int, beast_row: tuple = None):
    """Spawn a tailed beast raid in the given chat."""
    global active_raids

    if chat_id in active_raids:
        return  # Already an active raid

    if beast_row is None:
        cursor.execute(
            "SELECT id, name, rarity, file_id, file_type FROM tailed_beasts ORDER BY RANDOM() LIMIT 1"
        )
        beast_row = cursor.fetchone()

    if not beast_row:
        return  # No beasts in DB

    bid, bname, brarity, bfile, bfile_type = beast_row

    raid_id = f"raid_{chat_id}_{int(time.time())}"
    active_raids[chat_id] = {
        "raid_id": raid_id,
        "beast_id": bid,
        "beast_name": bname,
        "beast_rarity": brarity,
        "beast_file": bfile,
        "beast_file_type": bfile_type or "photo",
        "participants": {},          # {user_id: {"name": ..., "power": ...}}
        "phase": "waiting",          # waiting → active → ended
        "spawn_time": int(time.time()),
        "battle_started_at": None,
        "spawn_msg_id": None,
        "chat_id": chat_id,
        "countdown_task": None,
    }

    beast_emoji = RARITY_EMOJI.get(brarity, "🐉")
    num_players = len(active_raids[chat_id]["participants"])

    # Try to use a random raid_beast_image if available for this beast
    cursor.execute(
        "SELECT file_id, file_type FROM raid_beast_images WHERE beast_name=? ORDER BY RANDOM() LIMIT 1",
        (bname.lower(),)
    )
    img_row = cursor.fetchone()
    if img_row:
        bfile, bfile_type = img_row[0], img_row[1] or "photo"
        active_raids[chat_id]["beast_file"] = bfile
        active_raids[chat_id]["beast_file_type"] = bfile_type

    # Destroyer animation text
    animation_lines = [
        "🌑 *The sky darkens...*",
        "⚡ *Chakra trembles across the land...*",
        "🔥 *The seal is breaking!*",
        "💥 *THE TAILED BEAST AWAKENS!* 💥",
    ]

    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("⚔️ JOIN RAID", callback_data=f"raid_join_{chat_id}")
    ]])

    caption = (
        f"{'━'*22}\n"
        f"{animation_lines[0]}\n"
        f"{animation_lines[1]}\n"
        f"{animation_lines[2]}\n"
        f"{animation_lines[3]}\n"
        f"{'━'*22}\n\n"
        f"🐉 *{bname.title()}* has appeared!\n"
        f"{beast_emoji} Rarity: *{brarity}*\n\n"
        f"👥 *0/10* raiders joined\n"
        f"⏳ Raid opens for *10 minutes!*\n\n"
        f"🎟️ Need a *Raid Pass* to join!\n"
        f"📩 Get one with /claim\\_raidpass\n\n"
        f"👇 *Tap JOIN RAID to battle!*"
    )

    try:
        msg = await send_card_media(
            bot, bfile, file_type=bfile_type, caption=caption,
            parse_mode="Markdown", reply_markup=keyboard, chat_id=chat_id
        )
        active_raids[chat_id]["spawn_msg_id"] = msg.message_id
    except Exception as e:
        print(f"[RAID] Spawn error in {chat_id}: {e}")
        active_raids.pop(chat_id, None)
        return

    # Schedule auto-close after 10 minutes if <3 players
    async def _auto_close():
        await asyncio.sleep(600)  # 10 minutes
        raid = active_raids.get(chat_id)
        if not raid or raid["phase"] != "waiting":
            return
        n = len(raid["participants"])
        if n < 3:
            active_raids.pop(chat_id, None)
            try:
                await bot.send_message(
                    chat_id=chat_id,
                    text=(
                        f"💨 *The {bname.title()} retreated...*\n\n"
                        f"Not enough raiders joined (need at least 3).\n"
                        f"⏰ Raid expired! Your raid passes were *not consumed*."
                    ),
                    parse_mode="Markdown"
                )
                # Refund passes
                for uid in list(raid["participants"].keys()):
                    cur_passes = _get_raid_pass_count(uid)
                    _set_raid_passes(uid, cur_passes + 1)
            except Exception:
                pass
        else:
            # Enough players — start battle
            await _start_raid_battle(bot, chat_id)

    task = asyncio.ensure_future(_auto_close())
    active_raids[chat_id]["countdown_task"] = task


async def _update_raid_message(bot, chat_id: int):
    """Refresh the raid spawn message with current participant count."""
    raid = active_raids.get(chat_id)
    if not raid:
        return
    n = len(raid["participants"])
    bname = raid["beast_name"]
    brarity = raid["beast_rarity"]
    beast_emoji = RARITY_EMOJI.get(brarity, "🐉")

    names_list = "\n".join(
        f"  {i+1}. 🥷 {v['name']}" for i, (uid, v) in enumerate(raid["participants"].items())
    ) or "  _No raiders yet..._"

    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("⚔️ JOIN RAID", callback_data=f"raid_join_{chat_id}")
    ]])

    status = f"⚔️ *{n}/10 raiders joined!*" if n >= 3 else f"⚠️ *{n}/10 — Need 3+ to start!*"

    new_caption = (
        f"🐉 *{bname.title()}* — Active Raid!\n"
        f"{beast_emoji} Rarity: *{brarity}*\n\n"
        f"{status}\n\n"
        f"*Raiders:*\n{names_list}\n\n"
        f"{'🟢 *3+ players! Raid starts in 30s!*' if n >= 3 else '⏳ Waiting for raiders...'}\n"
        f"🎟️ Need a *Raid Pass* to join!"
    )
    try:
        msg_id = raid.get("spawn_msg_id")
        if msg_id:
            if raid["beast_file_type"] == "video":
                await bot.edit_message_caption(
                    chat_id=chat_id, message_id=msg_id,
                    caption=new_caption, parse_mode="Markdown",
                    reply_markup=keyboard
                )
            else:
                await bot.edit_message_caption(
                    chat_id=chat_id, message_id=msg_id,
                    caption=new_caption, parse_mode="Markdown",
                    reply_markup=keyboard
                )
    except Exception:
        pass


async def _countdown_and_start(bot, chat_id: int):
    """30-second countdown then start battle."""
    await asyncio.sleep(30)
    raid = active_raids.get(chat_id)
    if not raid or raid["phase"] != "waiting":
        return
    await _start_raid_battle(bot, chat_id)


async def _start_raid_battle(bot, chat_id: int):
    """Run the raid battle and distribute rewards."""
    raid = active_raids.get(chat_id)
    if not raid or raid["phase"] == "ended":
        return
    raid["phase"] = "active"

    participants = raid["participants"]
    n = len(participants)
    bname = raid["beast_name"]
    brarity = raid["beast_rarity"]
    beast_emoji = RARITY_EMOJI.get(brarity, "🐉")

    if n < 3:
        active_raids.pop(chat_id, None)
        return

    beast_max_hp = _raid_beast_power(n)
    beast_hp = beast_max_hp

    # Calculate each player's attack contribution
    player_dmg = {}
    for uid, pdata in participants.items():
        base_atk = _get_player_raid_power(uid)
        # Add random variance ±20%
        variance = random.uniform(0.80, 1.20)
        crit = random.random() < 0.20
        dmg = int(base_atk * variance * (1.5 if crit else 1.0))
        player_dmg[uid] = {"dmg": max(5, dmg), "crit": crit, "name": pdata["name"]}

    total_dmg = sum(v["dmg"] for v in player_dmg.values())

    # Determine if raid is won
    raid_won = total_dmg >= beast_hp

    # Build battle log
    battle_lines = [
        f"⚔️ *TAILED BEAST RAID BATTLE!*\n",
        f"🐉 *{bname.title()}* [{brarity}]\n",
        f"❤️ Beast HP: *{beast_hp:,}*\n",
        f"━━━━━━━━━━━━━━━━━━━━━━\n",
        f"*⚡ Player Attacks:*\n",
    ]

    for uid, ddata in player_dmg.items():
        crit_tag = " 🔥 *CRIT!*" if ddata["crit"] else ""
        battle_lines.append(f"  ⚔️ *{ddata['name']}*: `{ddata['dmg']:,}` DMG{crit_tag}")

    battle_lines.append(f"\n━━━━━━━━━━━━━━━━━━━━━━")
    battle_lines.append(f"💥 *Total Damage:* `{total_dmg:,}` / `{beast_hp:,}`")

    if raid_won:
        battle_lines.append(f"\n\n🎉 *RAID VICTORY!* 🎉")
        battle_lines.append(f"🐉 *{bname.title()}* has been defeated!")
    else:
        shortage = beast_hp - total_dmg
        battle_lines.append(f"\n\n💀 *RAID FAILED!*")
        battle_lines.append(f"The beast was too powerful by `{shortage:,}` HP!")

    try:
        await bot.send_message(
            chat_id=chat_id,
            text="\n".join(battle_lines),
            parse_mode="Markdown"
        )
    except Exception:
        pass

    # ── Distribute rewards ────────────────────────────────────────────────────
    if raid_won:
        now = int(time.time())
        reward_lines = [f"🏆 *RAID REWARDS — {bname.title()}*\n", "━━━━━━━━━━━━━━━━━━━━━━\n"]

        # Log raid in DB
        cursor.execute(
            "INSERT INTO raid_history (beast_name, beast_rarity, chat_id, started_at, ended_at, result) "
            "VALUES (?,?,?,?,?,?)",
            (bname, brarity, chat_id, raid["spawn_time"], now, "win")
        )
        raid_row_id = cursor.lastrowid

        for uid, pdata in participants.items():
            # Random rarity for reward card
            reward_rarity = random.choices(RAID_REWARD_RARITIES, weights=RAID_REWARD_WEIGHTS, k=1)[0]
            # Try to give the actual beast card (from tailed_beasts table) OR fallback to random normal card
            cursor.execute(
                "SELECT name, rarity, file_id, COALESCE(file_type,'photo') FROM tailed_beasts "
                "WHERE LOWER(name)=? AND rarity=? LIMIT 1",
                (bname.lower(), reward_rarity)
            )
            card_row = cursor.fetchone()
            if not card_row:
                # Fallback: pick the beast card at any rarity, then use the rewarded rarity label
                cursor.execute(
                    "SELECT name, rarity, file_id, COALESCE(file_type,'photo') FROM tailed_beasts "
                    "WHERE LOWER(name)=? LIMIT 1",
                    (bname.lower(),)
                )
                card_row = cursor.fetchone()
            if not card_row:
                # Final fallback: normal card pool
                cursor.execute(
                    "SELECT name, rarity, file_id, COALESCE(file_type,'photo') FROM cards "
                    "WHERE rarity=? ORDER BY RANDOM() LIMIT 1",
                    (reward_rarity,)
                )
                card_row = cursor.fetchone()

            if card_row:
                cname, crarity, cfile, cft = card_row
                # Beast reward cards go to user_beast_cards (separate from normal collection)
                cursor.execute(
                    "INSERT INTO user_beast_cards (user_id, beast_name, beast_rarity, file_id, file_type, earned_at) "
                    "VALUES (?,?,?,?,?,?)",
                    (uid, cname, reward_rarity, cfile, cft, now)
                )
                # Also log in raid_rewards
                cursor.execute(
                    "INSERT INTO raid_rewards (raid_id, user_id, card_name, card_rarity, file_id, rewarded_at) "
                    "VALUES (?,?,?,?,?,?)",
                    (raid_row_id, uid, cname, reward_rarity, cfile, now)
                )
                r_emoji = RARITY_EMOJI.get(reward_rarity, "⭐")
                reward_lines.append(
                    f"🥷 *{pdata['name']}*\n"
                    f"  {r_emoji} Got: *{cname.title()}* [{reward_rarity}]\n"
                )
                # DM the winner
                try:
                    await bot.send_message(
                        chat_id=uid,
                        text=(
                            f"🎉 *TAILED BEAST RAID REWARD!*\n\n"
                            f"🐉 You defeated *{bname.title()}*!\n"
                            f"{r_emoji} Beast Card: *{cname.title()}* [{reward_rarity}]\n\n"
                            f"🐉 Added to your *Beast Collection!*\n"
                            f"Use /my_beast to view it!"
                        ),
                        parse_mode="Markdown"
                    )
                except Exception:
                    pass
            else:
                reward_lines.append(f"🥷 *{pdata['name']}*: ⭐ No beast card available — coins rewarded instead!\n")
                add_coins(uid, 500)

        conn.commit()
        reward_lines.append("\n━━━━━━━━━━━━━━━━━━━━━━")
        reward_lines.append("💎 *Rarity is random — everyone gets a surprise!*")

        try:
            await bot.send_message(
                chat_id=chat_id,
                text="\n".join(reward_lines),
                parse_mode="Markdown"
            )
        except Exception:
            pass
    else:
        # Failed raid — refund passes
        try:
            cursor.execute(
                "INSERT INTO raid_history (beast_name, beast_rarity, chat_id, started_at, ended_at, result) "
                "VALUES (?,?,?,?,?,?)",
                (bname, brarity, chat_id, raid["spawn_time"], int(time.time()), "fail")
            )
            conn.commit()
        except Exception:
            pass
        try:
            await bot.send_message(
                chat_id=chat_id,
                text=(
                    f"💀 *Raid Failed!*\n\n"
                    f"🐉 *{bname.title()}* was too strong!\n"
                    f"🎟️ Raid passes have been *refunded* to all participants.\n\n"
                    f"💪 Train harder and try again!"
                ),
                parse_mode="Markdown"
            )
        except Exception:
            pass
        # Refund passes
        for uid in participants:
            cur_p = _get_raid_pass_count(uid)
            _set_raid_passes(uid, cur_p + 1)

    raid["phase"] = "ended"
    active_raids.pop(chat_id, None)


# ── raid_join callback ────────────────────────────────────────────────────────
async def raid_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle the JOIN RAID button."""
    query = update.callback_query
    try:
        await query.answer()
    except Exception:
        pass

    user_id = query.from_user.id
    user_name = query.from_user.first_name or "Shinobi"

    if is_banned(user_id):
        await query.answer("🚫 You are banned!", show_alert=True)
        return
    if not has_started_bot(user_id):
        await query.answer("❌ Start the bot in DM first: /start", show_alert=True)
        return

    data = query.data or ""
    try:
        chat_id = int(data.split("_")[-1])
    except Exception:
        return

    raid = active_raids.get(chat_id)
    if not raid or raid["phase"] != "waiting":
        await query.answer("❌ This raid is no longer active!", show_alert=True)
        return

    if user_id in raid["participants"]:
        await query.answer("✅ You already joined this raid!", show_alert=True)
        return

    if len(raid["participants"]) >= 10:
        await query.answer("❌ Raid is full (max 10 players)!", show_alert=True)
        return

    # Check raid pass
    passes = _get_raid_pass_count(user_id)
    if passes <= 0:
        await query.answer(
            "🎟️ You don't have a Raid Pass!\nUse /claim_raidpass to get one.",
            show_alert=True
        )
        return

    # Deduct pass
    _set_raid_passes(user_id, passes - 1)

    # Add to raid
    raid["participants"][user_id] = {
        "name": user_name,
        "power": _get_player_raid_power(user_id)
    }

    n = len(raid["participants"])
    await query.answer(f"⚔️ Joined raid! {n}/10 raiders", show_alert=False)

    # Update the spawn message
    await _update_raid_message(context.bot, chat_id)

    # If we just hit 3 players, start 30s countdown
    if n == 3:
        asyncio.ensure_future(_countdown_and_start(context.bot, chat_id))
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=(
                    f"⚡ *3 RAIDERS READY!*\n\n"
                    f"⏳ Raid starts in *30 seconds!*\n"
                    f"👥 More players can still join (up to 10)."
                ),
                parse_mode="Markdown"
            )
        except Exception:
            pass

    # If full at 10, start immediately
    elif n >= 10:
        asyncio.ensure_future(_start_raid_battle(context.bot, chat_id))


# ── /forcespawn_beast — Owner spawns a specific beast ────────────────────────
async def forcespawn_beast(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/forcespawn_beast <name> — Force-spawn a tailed beast raid."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only.")
        return

    chat_id = update.effective_chat.id

    if chat_id in active_raids:
        await update.message.reply_text("❌ A raid is already active in this chat!")
        return

    beast_name = " ".join(context.args).strip().lower() if context.args else ""

    if beast_name:
        cursor.execute(
            "SELECT id, name, rarity, file_id, file_type FROM tailed_beasts WHERE LOWER(name)=?",
            (beast_name,)
        )
        row = cursor.fetchone()
        if not row:
            # Try partial match
            cursor.execute(
                "SELECT id, name, rarity, file_id, file_type FROM tailed_beasts WHERE LOWER(name) LIKE ?",
                (f"%{beast_name}%",)
            )
            row = cursor.fetchone()
        if not row:
            cursor.execute("SELECT name FROM tailed_beasts ORDER BY name")
            available = [r[0].title() for r in cursor.fetchall()]
            beast_list = "\n".join(f"• {b}" for b in available) or "None added yet."
            await update.message.reply_text(
                f"❌ Beast *{beast_name.title()}* not found!\n\n"
                f"*Available beasts:*\n{beast_list}",
                parse_mode="Markdown"
            )
            return
    else:
        cursor.execute(
            "SELECT id, name, rarity, file_id, file_type FROM tailed_beasts ORDER BY RANDOM() LIMIT 1"
        )
        row = cursor.fetchone()
        if not row:
            await update.message.reply_text("❌ No tailed beasts added yet! Use /addbeast first.")
            return

    await update.message.reply_text(
        f"🐉 *Force-spawning {row[1].title()}...*",
        parse_mode="Markdown"
    )
    await _spawn_raid(context.bot, chat_id, beast_row=row)


# ── Random raid scheduler ─────────────────────────────────────────────────────
async def _raid_random_scheduler(bot, chat_id: int):
    """Randomly spawn a raid between 7–9 PM IST in the given chat."""
    while True:
        # Calculate seconds until next 7–9 PM IST window
        from datetime import datetime, timezone, timedelta
        now_utc = datetime.now(timezone.utc)
        now_ist = now_utc + timedelta(seconds=IST_OFFSET_SEC)

        # Next 7 PM IST today or tomorrow
        target_hour = random.randint(19, 20)   # 7 PM or 8 PM IST
        target_min  = random.randint(0, 59)

        next_spawn = now_ist.replace(hour=target_hour, minute=target_min, second=0, microsecond=0)
        if next_spawn <= now_ist:
            next_spawn += timedelta(days=1)

        wait_secs = (next_spawn - now_ist).total_seconds()
        await asyncio.sleep(wait_secs)

        # Spawn if no active raid
        if chat_id not in active_raids:
            cursor.execute(
                "SELECT id, name, rarity, file_id, file_type FROM tailed_beasts ORDER BY RANDOM() LIMIT 1"
            )
            row = cursor.fetchone()
            if row:
                await _spawn_raid(bot, chat_id, beast_row=row)

        # Wait at least 23h before scheduling again
        await asyncio.sleep(82800)


# ── /start_raid_scheduler — Owner: enable random raid spawns for this chat ───
async def start_raid_scheduler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/start_raid_scheduler — Enable automatic tailed beast raid spawning in this chat."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only.")
        return

    chat_id = update.effective_chat.id
    if chat_id in raid_spawn_tasks:
        await update.message.reply_text("✅ Raid scheduler already running in this chat!")
        return

    task = asyncio.ensure_future(_raid_random_scheduler(context.bot, chat_id))
    raid_spawn_tasks[chat_id] = task

    # Save setting
    cursor.execute(
        "INSERT OR REPLACE INTO bot_settings (key, value) VALUES (?,?)",
        (f"raid_scheduler_{chat_id}", "1")
    )
    conn.commit()

    await update.message.reply_text(
        f"🐉 *Tailed Beast Raid Scheduler Started!*\n\n"
        f"🕖 Raids will spawn randomly between *7–9 PM IST* daily.\n"
        f"🎟️ Players need /claim\\_raidpass to join!\n"
        f"👥 Minimum *3* players, maximum *10* players.",
        parse_mode="Markdown"
    )


