# ═══════════════════════════════════════════════════════════════════
#   🐉  ADD RAID BEAST IMAGE — /add_raidbeast <name> (reply to image)
# ═══════════════════════════════════════════════════════════════════

async def add_raidbeast(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/add_raidbeast <beast_name> — Reply to a photo/video to add a random appearance image for a beast."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only.")
        return

    beast_name = " ".join(context.args).strip() if context.args else ""
    if not beast_name:
        await update.message.reply_text(
            "❌ *Usage:* `/add_raidbeast <beast name>`\n"
            "Reply to a photo or video with this command.\n\n"
            "Example: `/add_raidbeast Nine Tails`\n\n"
            "This adds a *random appearance image* for the beast that shows when it spawns in raids.",
            parse_mode="Markdown"
        )
        return

    # Get file from replied message or direct attachment
    replied = update.message.reply_to_message
    file_id = None
    file_type = "photo"
    if replied:
        if replied.photo:
            file_id = replied.photo[-1].file_id
            file_type = "photo"
        elif replied.video:
            file_id = replied.video.file_id
            file_type = "video"
        elif replied.animation:
            file_id = replied.animation.file_id
            file_type = "video"
    elif update.message.photo:
        file_id = update.message.photo[-1].file_id
        file_type = "photo"
    elif update.message.video:
        file_id = update.message.video.file_id
        file_type = "video"

    if not file_id:
        await update.message.reply_text(
            "❌ Please reply to a photo or video with `/add_raidbeast <name>`",
            parse_mode="Markdown"
        )
        return

    now = int(time.time())
    cursor.execute(
        "INSERT INTO raid_beast_images (beast_name, file_id, file_type, added_by, added_at) VALUES (?,?,?,?,?)",
        (beast_name.lower().strip(), file_id, file_type, update.effective_user.id, now)
    )
    conn.commit()

    # Count how many images this beast now has
    cursor.execute("SELECT COUNT(*) FROM raid_beast_images WHERE beast_name=?", (beast_name.lower().strip(),))
    count = cursor.fetchone()[0]

    await update.message.reply_text(
        f"✅ *Raid Beast Image Added!*\n\n"
        f"🐉 Beast: *{beast_name.title()}*\n"
        f"🖼️ Total images for this beast: *{count}*\n\n"
        f"_A random image will be shown when *{beast_name.title()}* spawns in a raid!_",
        parse_mode="Markdown"
    )


# ═══════════════════════════════════════════════════════════════════
#   🐉  MY BEAST COLLECTION — /my_beast
# ═══════════════════════════════════════════════════════════════════

async def my_beast(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/my_beast — View your collected beast cards from raids."""
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    if not has_started_bot(user_id) and not is_admin(user_id):
        await update.message.reply_text(NOT_STARTED_MSG, parse_mode="Markdown", disable_web_page_preview=True)
        return
    if is_banned(user_id):
        await update.message.reply_text(get_ban_message(user_id), parse_mode="Markdown")
        return

    user_name = update.effective_user.first_name or "Shinobi"

    cursor.execute(
        "SELECT id, beast_name, beast_rarity, file_id, file_type, earned_at "
        "FROM user_beast_cards WHERE user_id=? ORDER BY earned_at DESC",
        (user_id,)
    )
    rows = cursor.fetchall()

    if not rows:
        await update.message.reply_text(
            f"🐉 *{user_name}'s Beast Collection*\n\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"📭 *No beast cards yet!*\n\n"
            f"Participate in Tailed Beast Raids to earn beast cards!\n"
            f"🎟️ Use /claim_raidpass to get a raid pass.\n"
            f"🐉 Raids spawn between *7–9 PM IST* daily.",
            parse_mode="Markdown"
        )
        return

    # Group by beast name + rarity
    from collections import Counter
    beast_counts = Counter((r[1], r[2]) for r in rows)

    lines = [f"🐉 *{user_name}'s Beast Collection*", f"━━━━━━━━━━━━━━━━━━━━━━"]
    total = len(rows)
    for (bname, brarity), cnt in sorted(beast_counts.items(), key=lambda x: -x[1]):
        emoji = RARITY_EMOJI.get(brarity, "🐉")
        lines.append(f"{emoji} *{bname.title()}* [{brarity}] × {cnt}")
    lines.append("━━━━━━━━━━━━━━━━━━━━━━")
    lines.append(f"🏆 Total Beast Cards: *{total}*")

    # Show the most recent beast card as thumbnail
    recent = rows[0]
    r_file_id, r_file_type = recent[3], recent[4] or "photo"

    try:
        await send_card_media(update.message, r_file_id, file_type=r_file_type, caption="\n".join(lines), parse_mode="Markdown")
    except Exception:
        await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


# ═══════════════════════════════════════════════════════════════════
#   🗑️  DELETE CARD BY NAME — /delcard_name <name>  (Admin)
# ═══════════════════════════════════════════════════════════════════

async def delcard_by_name(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/delcard_name <name> — Delete ALL cards matching that name across ALL rarities from DB and all user collections."""
    if not update.effective_user or not update.message:
        return
    if not is_admin(update.effective_user.id):
        await update.message.reply_text("🚫 Admin only.")
        return

    name_input = " ".join(context.args).strip() if context.args else ""
    if not name_input:
        await update.message.reply_text(
            "❌ *Usage:* `/delcard_name <card name>`\n\n"
            "Deletes ALL cards with that name across every rarity from the master DB "
            "and removes them from every user's collection too.\n\n"
            "Example: `/delcard_name Nine Tails`",
            parse_mode="Markdown"
        )
        return

    name_lower = normalize(name_input)

    # Find all matching master cards
    cursor.execute("SELECT id, name, rarity FROM cards")
    all_cards = cursor.fetchall()
    matched = [(cid, cname, crarity) for cid, cname, crarity in all_cards if normalize(str(cname)) == name_lower]

    if not matched:
        await update.message.reply_text(
            f"❌ *No cards found with name:* `{name_input}`\n\n"
            f"Use /list_cards to check exact names.",
            parse_mode="Markdown"
        )
        return

    master_ids = [c[0] for c in matched]
    card_names = list({c[1] for c in matched})
    rarities_deleted = [f"{RARITY_EMOJI.get(c[2],'⭐')} {c[2]}" for c in matched]

    # Delete from user_cards (by card_id or card_name match)
    user_cards_deleted = 0
    for cid, cname, crarity in matched:
        cursor.execute("SELECT COUNT(*) FROM user_cards WHERE card_id=?", (cid,))
        user_cards_deleted += cursor.fetchone()[0]
        cursor.execute("DELETE FROM user_cards WHERE card_id=?", (cid,))
    # Also catch any orphaned rows by name
    for cname in card_names:
        cursor.execute("SELECT COUNT(*) FROM user_cards WHERE card_name=? COLLATE NOCASE", (cname,))
        user_cards_deleted += cursor.fetchone()[0]
        cursor.execute("DELETE FROM user_cards WHERE card_name=? COLLATE NOCASE", (cname,))

    # Delete from master cards table
    for cid in master_ids:
        cursor.execute("DELETE FROM cards WHERE id=?", (cid,))

    conn.commit()

    display_name = card_names[0].title() if card_names else name_input.title()
    rarity_list = "\n".join(f"  {r}" for r in rarities_deleted)

    await update.message.reply_text(
        f"🗑️ *Card Fully Deleted!*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🥷 Name: *{display_name}*\n"
        f"📋 Rarities removed:\n{rarity_list}\n\n"
        f"👥 Removed from *{user_cards_deleted}* user collection(s)\n"
        f"━━━━━━━━━━━━━━━━━━━━━━",
        parse_mode="Markdown"
    )
    await log_to_group(
        context.bot,
        f"🗑️ *FULL CARD DELETE by Name*\n\n"
        f"🥷 Name: {display_name}\n"
        f"📋 Rarities: {', '.join(c[2] for c in matched)}\n"
        f"👥 User copies removed: {user_cards_deleted}\n"
        f"👤 By: {update.effective_user.first_name} (`{update.effective_user.id}`)"
    )


