def _install_crash_visibility_hooks():
    """Makes sure that if this process ever stops unexpectedly, the reason
    is ALWAYS printed to the log before it happens, instead of the process
    just going silent (which is what makes "bot stopped, no idea why" bugs
    so hard to track down). Covers three separate failure classes:

      1. An uncaught exception anywhere on the main thread — normally
         Python prints this to stderr, but on some hosts stderr isn't
         captured the same way stdout is, so this explicitly logs it via
         print() (which the bot already uses for all its own logging) too.
      2. An uncaught exception inside a background asyncio task (e.g. the
         auto-backup/quiz/auction schedulers, started via
         asyncio.create_task in post_init). These do NOT crash the process
         by default — they just die silently and asyncio quietly drops the
         exception — so without this hook a scheduler could be dead for
         hours with nothing in the logs to show it.
      3. The process receiving SIGTERM/SIGINT — this is what almost every
         hosting platform (StackHost included) sends before stopping,
         restarting, or redeploying a container. If the bot "stops working"
         because the PLATFORM is restarting it (health check, memory limit,
         redeploy, etc.) rather than because of a bug in this file, this is
         the only way to tell — the process itself has no other way to know
         WHY it's being stopped.
    """
    def _log_uncaught_exception(exc_type, exc_value, exc_tb):
        if issubclass(exc_type, KeyboardInterrupt):
            sys.__excepthook__(exc_type, exc_value, exc_tb)
            return
        print("=" * 70)
        print("[FATAL] Uncaught exception on main thread — process is about to die:")
        traceback.print_exception(exc_type, exc_value, exc_tb)
        print("=" * 70)
    sys.excepthook = _log_uncaught_exception

    def _log_asyncio_exception(loop, context):
        exc = context.get("exception")
        print("=" * 70)
        print(f"[FATAL] Unhandled exception in a background asyncio task: {context.get('message')}")
        if exc is not None:
            traceback.print_exception(type(exc), exc, exc.__traceback__)
        else:
            print(context)
        print("=" * 70)
    try:
        asyncio.get_event_loop().set_exception_handler(_log_asyncio_exception)
    except Exception:
        pass  # event loop isn't created yet on some platforms — set again in post_init

    def _log_signal(signum, frame):
        name = signal.Signals(signum).name
        print("=" * 70)
        print(f"[SHUTDOWN] Process received {name} ({signum}) — this is almost always the "
              f"HOSTING PLATFORM telling the process to stop (redeploy, health-check "
              f"restart, memory/CPU limit, manual stop), not a bug in this file. "
              f"Exiting now.")
        print("=" * 70)
        sys.exit(0)
    try:
        signal.signal(signal.SIGTERM, _log_signal)
        signal.signal(signal.SIGINT, _log_signal)
    except Exception as _sige:
        print(f"[SHUTDOWN] Could not install signal handlers (non-fatal): {_sige}")


_LOOP_HEARTBEAT_TS = time.monotonic()
_HARD_WATCHDOG_STARTED = False

def _cgroup_memory_limit_mb():
    """Best-effort Linux cgroup memory limit in MB."""
    for path in ("/sys/fs/cgroup/memory.max", "/sys/fs/cgroup/memory/memory.limit_in_bytes"):
        try:
            raw = open(path, "r").read().strip()
            if raw and raw != "max":
                value = int(raw)
                if value > 0:
                    return value / (1024 * 1024)
        except Exception:
            pass
    return None

def _hard_watchdog_loop():
    """Out-of-band self-healing watchdog.

    This runs in a real OS thread, not the asyncio loop. If a synchronous DB
    call, image operation, network call, or other bug blocks the event loop for
    too long, the normal heartbeat cannot report it and the bot appears dead.
    This thread can still see the stale heartbeat and replaces the process. It
    also detects sustained RSS pressure before the host reaches a hard OOM
    kill. A SIGKILL/OOM kill itself is impossible to catch from inside Python;
    StackHost must still be configured to restart the app/container.
    """
    global _HARD_WATCHDOG_STARTED
    if _HARD_WATCHDOG_STARTED:
        return
    _HARD_WATCHDOG_STARTED = True
    stall_limit = float(os.environ.get("HARD_WATCHDOG_STALL_SEC", "90"))
    check_sec = float(os.environ.get("HARD_WATCHDOG_CHECK_SEC", "15"))
    mem_limit = _cgroup_memory_limit_mb()
    mem_ratio = float(os.environ.get("HARD_WATCHDOG_MEMORY_RATIO", "0.85"))
    high_mem_hits = 0
    print(f"[WATCHDOG] hard watchdog online | stall>{stall_limit:.0f}s | cgroup_memory={mem_limit or 'unknown'}MB")
    while True:
        time.sleep(check_sec)
        try:
            stale = time.monotonic() - _LOOP_HEARTBEAT_TS
            rss = _get_memory_mb() if "_get_memory_mb" in globals() else -1
            if stale > stall_limit:
                print(f"[WATCHDOG] EVENT LOOP STALL detected ({stale:.1f}s). Restarting process now.")
                os.execv(sys.executable, [sys.executable] + sys.argv)
                return
            if mem_limit and rss >= 0 and rss > mem_limit * mem_ratio:
                high_mem_hits += 1
                print(f"[WATCHDOG] high RSS {rss:.1f}MB / limit {mem_limit:.1f}MB ({rss/mem_limit:.0%}), hit={high_mem_hits}")
                if high_mem_hits >= 3:
                    print("[WATCHDOG] sustained memory pressure — replacing process before OOM.")
                    os.execv(sys.executable, [sys.executable] + sys.argv)
                    return
            else:
                high_mem_hits = 0
        except Exception as exc:
            print(f"[WATCHDOG] monitor error: {exc}")

def main():
    _install_crash_visibility_hooks()
    threading.Thread(target=_hard_watchdog_loop, name="hard-watchdog", daemon=True).start()

    # Apply saved owner panel settings on startup
    apply_panel_settings()
    load_draft_rarity_weights()

    # ── DB-ready lock: initialize on first boot after this update ──────────────
    # panel_get("db_ready") only comes back None the very first time this runs
    # (either a genuinely fresh/empty DB after a redeploy, OR the first boot
    # right after upgrading to this version on an EXISTING, already-populated
    # database). Don't lock out an existing bot just because this key never
    # existed before — only start locked if the DB actually looks empty.
    if panel_get("db_ready") is None:
        try:
            cursor.execute("SELECT COUNT(*) FROM bot_users")
            existing_users = cursor.fetchone()[0]
        except Exception:
            existing_users = 0
        panel_set("db_ready", "1" if existing_users > 0 else "0")
        print(f"[DB_READY] Initialized db_ready={'1' if existing_users > 0 else '0'} "
              f"(existing bot_users rows: {existing_users})")

    # Initialize MongoDB and run one-time migration
    init_mongo_and_migrate()

    # 🔥 START FLASK SERVER (no reload issue)
    def run_web():
        app.run(
            host="0.0.0.0",
            port=int(os.environ.get("PORT", 5000)),
            use_reloader=False
        )

    threading.Thread(target=run_web, daemon=True).start()

    # 🔥 TELEGRAM BOT SETUP
    # NOTE (Bug fix — "Pool timeout: All connections in the connection pool
    # are occupied. Request was *not* sent to Telegram."):
    # python-telegram-bot's HTTPXRequest defaults to connection_pool_size=1,
    # meaning only ONE outgoing HTTP request (any sendMessage/sendSticker/etc,
    # in ANY chat) could be in flight at a time. With concurrent_updates(True)
    # and many active groups sending messages/stickers at once, every other
    # outgoing request just queued up waiting for that single connection, and
    # once pool_timeout (30s) was exceeded it was dropped with "Request was
    # *not* sent to Telegram" — exactly the error spam seen in the logs.
    # Raising connection_pool_size lets many requests be in flight at the same
    # time so they stop starving each other out. pool_timeout is also raised
    # as a safety margin in case of a genuine burst.
    # RIGHT-SIZED FOR A 512MB STACKHOST FREE CONTAINER:
    # 256 simultaneous HTTP connections was sized for the "never starve" case
    # but each open connection/buffer costs real memory on a container that
    # only has 512MB total, shared with SQLite's page cache, PIL image
    # buffers, and everything else. 32 is still far more than a single-bot
    # process realistically has in flight at once (message send/edit calls
    # are quick), while leaving headroom. Raise via HTTP_POOL_SIZE env var if
    # you genuinely start seeing "Pool timeout: All connections ... occupied"
    # in the logs again.
    request = HTTPXRequest(
        connect_timeout=20,
        read_timeout=30,
        write_timeout=30,
        pool_timeout=30,
        connection_pool_size=int(os.environ.get("HTTP_POOL_SIZE", 32)),
    )

    get_updates_request = HTTPXRequest(
        connect_timeout=20,
        read_timeout=60,
        write_timeout=30,
        pool_timeout=30,
        connection_pool_size=int(os.environ.get("GETUPDATES_POOL_SIZE", 4)),
    )

    # NOTE: concurrent_updates(True) processes up to 256 updates at once (PTB
    # default), each as its own asyncio task. Most of this bot's handlers do
    # CPU-bound work directly on the event loop (PIL image rendering for
    # spawns/banners/cards is NOT offloaded to a thread in most call sites),
    # so a burst of simultaneous activity across many active groups can pile
    # up a large number of these tasks all competing for the SAME single
    # thread that also has to keep polling Telegram for new updates. On a
    # resource-limited host this can starve the event loop badly enough that
    # the bot appears to "hang"/stop responding under load without ever
    # actually crashing. Capping this to a much lower, still-generous number
    # keeps genuine concurrency (multiple users at once) while preventing
    # any single burst from monopolizing the loop. Tune via the
    # MAX_CONCURRENT_UPDATES env var if needed.
    # PERF FIX: lowered default 32 -> 8. With message_tracker's DB/Mongo work
    # now offloaded (see above), the event loop itself is far less likely to
    # be the bottleneck, but PIL rendering and other still-synchronous work
    # in other handlers (spawn_card, /collection, etc.) can still pile up.
    # 8 keeps real concurrency while capping how much can pile onto the loop
    # in one burst. Raise via MAX_CONCURRENT_UPDATES env var once the rest of
    # the DB access is migrated to _db_run() and this is confirmed stable.
    # RIGHT-SIZED FOR 512MB: lowered further from the earlier 8 -> 4. With
    # message_tracker/sticker_tracker's DB work now fully offloaded, the
    # remaining event-loop cost per update is mostly PIL rendering on spawns
    # — capping in-flight updates to 4 keeps memory pressure predictable on
    # a container this small while still allowing real concurrency. Raise
    # via MAX_CONCURRENT_UPDATES once you've confirmed RAM headroom in the
    # heartbeat logs.
    _max_concurrent_updates = int(os.environ.get("MAX_CONCURRENT_UPDATES", 4))

    telegram_app = (
        ApplicationBuilder()
        .token(BOT_TOKEN)
        .request(request)
        .get_updates_request(get_updates_request)
        .concurrent_updates(_max_concurrent_updates)
        .build()
    )

    telegram_app.add_handler(CommandHandler("start", start))

    # ── ⚔️ ARENA WARS — new deterministic team-battle mode (self-contained) ────
    import arena_game
    arena_game.setup(telegram_app, DB_PATH, is_admin)

    # ── Universal DM-registration + verify gate ───────────────────────────────
    # Fires in group -1 BEFORE all other handlers.
    # ApplicationHandlerStop stops ALL subsequent handler groups.
    EXEMPT_COMMANDS = {"start", "join", "forcestart"}  # always allowed

    async def require_dm_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
        if not update.effective_user or not update.message:
            return
        if not update.message.text or not update.message.text.startswith("/"):
            return
        user_id = update.effective_user.id
        cmd = update.message.text.split()[0].lower().lstrip("/").split("@")[0]

        # ── Bot-wide ON/OFF + database-ready lock (owner controls) ─────────────
        # Checked BEFORE the EXEMPT_COMMANDS/admin bypass below so that when the
        # owner turns the bot OFF, or the DB is not marked ready yet (fresh
        # deploy pending /restore), truly NOTHING works for non-admins in any
        # group or DM — including /start. This is also what closes the "user
        # /starts before /restore and gets a 0-collection row" bug: nobody can
        # even register as a user while db_ready is false.
        # A small allowlist of read-only/self-service commands still works even
        # while OFF/locked, so admins can still be reached and users aren't left
        # totally confused.
        _ALWAYS_ALLOWED_WHEN_OFF = {"live", "lock", "on", "off", "freeze", "unfreeze", "frozen", "restore", "backup"}
        if not is_admin(user_id) and cmd not in _ALWAYS_ALLOWED_WHEN_OFF:
            if not is_bot_enabled():
                try:
                    await update.message.reply_text(BOT_OFF_MSG, parse_mode="Markdown")
                except Exception:
                    pass
                from telegram.ext import ApplicationHandlerStop
                raise ApplicationHandlerStop
            if not is_db_ready():
                try:
                    await update.message.reply_text(DB_NOT_READY_MSG, parse_mode="Markdown")
                except Exception:
                    pass
                from telegram.ext import ApplicationHandlerStop
                raise ApplicationHandlerStop

        if cmd in EXEMPT_COMMANDS:
            return
        if is_admin(user_id):
            return

        # ── Global command spam protection ──────────────────────────────────────
        # Reuses the same record_message/is_blocked system already protecting
        # plain messages, stickers, and /catch — now applied to EVERY command so
        # rapid-fire command spam (e.g. mashing /wordle, /shop, etc.) is muted
        # the same way, instead of only being caught for plain text.
        record_message(user_id)
        if is_blocked(user_id):
            if user_id not in block_notified:
                block_notified[user_id] = True
                remaining = int(blocked_users[user_id] - time.time())
                mins, secs = remaining // 60, remaining % 60
                try:
                    await update.message.reply_text(
                        f"🚫 *Spam Detected!*\n\n"
                        f"⛔ You're sending commands too quickly and have been muted.\n"
                        f"⏳ Try again in: *{mins}m {secs}s*",
                        parse_mode="Markdown"
                    )
                except Exception:
                    pass
            from telegram.ext import ApplicationHandlerStop
            raise ApplicationHandlerStop

        if not has_started_bot(user_id):
            await update.message.reply_text(
                NOT_STARTED_MSG,
                parse_mode="Markdown",
                disable_web_page_preview=True
            )
            from telegram.ext import ApplicationHandlerStop
            raise ApplicationHandlerStop

        # ── Verify gate: only enforced in DM (group commands like /catch, /forcespawn
        # are unaffected since the gate is about full bot/DM feature access) ─────────
        is_dm = update.effective_chat and update.effective_chat.type == "private"
        if is_dm and not is_verified_user(user_id):
            user_name = update.effective_user.first_name or "Shinobi"
            await _send_join_gate(context.bot, update.effective_chat.id, user_name)
            from telegram.ext import ApplicationHandlerStop
            raise ApplicationHandlerStop

    telegram_app.add_handler(
        MessageHandler(filters.COMMAND, require_dm_start),
        group=-1
    )

    # ── Bot-wide OFF / DB-not-ready lock for inline button taps ────────────────
    # Mirrors the command-level gate above but for CallbackQueryHandler
    # (inline buttons: market buy/sell, draft spins, battle moves, etc.).
    # Registered in group=-1 so it runs before every other callback handler.
    async def require_bot_live_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
        query = update.callback_query
        if not query or not query.from_user:
            return
        user_id = query.from_user.id
        if is_admin(user_id):
            return
        if not is_bot_enabled():
            try:
                await query.answer("🔴 The bot is currently turned OFF by the owner.", show_alert=True)
            except Exception:
                pass
            from telegram.ext import ApplicationHandlerStop
            raise ApplicationHandlerStop
        if not is_db_ready():
            try:
                await query.answer("⏳ The bot is starting up / syncing its database. Try again shortly.", show_alert=True)
            except Exception:
                pass
            from telegram.ext import ApplicationHandlerStop
            raise ApplicationHandlerStop

    telegram_app.add_handler(CallbackQueryHandler(require_bot_live_callback), group=-1)
